INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89499, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "言论自由是每个人都可以说出自己想法的权利。", "primary_collocate": null, "pronunciation": "yán lùn zì yóu", "ipa": "jɛn˧˥ lwən˥˩ tsɨ˥˩ joʊ˧˥", "syllable_count": 4, "sentences": [{"text": "每个人都有言论自由，可以说出自己的想法。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们国家，言论自由受到法律保护。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了言论自由，大家才敢说真话。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，言论自由不等于可以乱说。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为争取言论自由努力了很多年。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上常常讨论言论自由的问题。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有言论自由，人们就不敢表达想法。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "言论自由让每个人都能说出不同的看法。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该尊重别人的言论自由。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的学生也有言论自由。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "言論自由", "label": "繁体"}], "register": "书面", "sense_fingerprint": "每个人说出自己想法的权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f31afe75-cf81-4a37-a9d7-9dd37dc90485') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89499, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言论自由", "is_correct": true, "explanation": "言论自由就是每个人说出自己想法的权利，填入后语义吻合。"}, {"text": "财产", "is_correct": false, "explanation": "语义：财产与说出自己的想法无关，句子逻辑不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不是人人都可以拥有、用来表达想法的权利。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体特征，不能作为说出想法的权利。"}], "explanations": {"言论自由": "言论自由就是每个人说出自己想法的权利，填入后语义吻合。", "财产": "语义：财产与说出自己的想法无关，句子逻辑不通。", "饭菜": "语义：饭菜不是人人都可以拥有、用来表达想法的权利。", "身高": "体貌：身高是身体特征，不能作为说出想法的权利。"}, "sentence_index": 0, "correct_answer": "言论自由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的言论自由很有道理。", "explanation": "这里应该用〈观点〉。言论自由指发表意见的权利，不能用来评价某段说法有没有道理；“有道理”形容的是观点、说法。"}, {"text": "这个周末我想去看言论自由。", "explanation": "这里应该用〈电影〉。言论自由是权利，不能被观看；“看”的对象应是电影、演出等。"}, {"text": "他把言论自由煮熟了再吃。", "explanation": "这里应该用〈鸡蛋〉。言论自由是权利，不能被煮、被吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89499, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言论自由", "is_correct": true, "explanation": "言论自由是人们敢于表达想法的前提，填入后语义吻合。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“没有”后接的应是制度、权利类词，“地铁”不能作为引出“不敢表达想法”的条件。"}, {"text": "食盐", "is_correct": false, "explanation": "语义：食盐与表达想法无关，句子逻辑不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能作为“不敢表达想法”的条件。"}], "explanations": {"言论自由": "言论自由是人们敢于表达想法的前提，填入后语义吻合。", "地铁": "搭配：“没有”后接的应是制度、权利类词，“地铁”不能作为引出“不敢表达想法”的条件。", "食盐": "语义：食盐与表达想法无关，句子逻辑不通。", "垃圾": "语义：垃圾不能作为“不敢表达想法”的条件。"}, "sentence_index": 6, "correct_answer": "言论自由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校里的学生也接受言论自由。", "explanation": "这里应该用〈教育〉。“接受”搭配教育、训练，言论自由是权利，不能被“接受”。"}, {"text": "这个路口的言论自由很拥挤。", "explanation": "这里应该用〈交通〉。“拥挤”形容道路、人群，不能用于权利。"}, {"text": "学生们认真完成了言论自由。", "explanation": "这里应该用〈作业〉。“完成”的对象是任务，言论自由是权利，不能被完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人都享用言论自由，可以说出自己的想法。", "corrected_sentence": "每个人都享有言论自由，可以说出自己的想法。", "error_description": "错误：“享用”，应为“享有”。“享用”多用于饮食、服务等具体事物，表示权利应用“享有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89499, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校里的学生也享用言论自由。", "corrected_sentence": "学校里的学生也享有言论自由。", "error_description": "错误：“享用”，应为“享有”。“享用”用于饮食、服务等，表示拥有权利应用“享有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
