INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89500, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公民依法享有的发表意见、表达思想而不受非法干涉的权利。", "primary_collocate": null, "pronunciation": "yán lùn zì yóu", "ipa": "jɛn˧˥ lwən˥˩ tsɨ˥˩ joʊ˧˥", "syllable_count": 4, "sentences": [{"text": "宪法规定公民享有言论自由。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "言论自由是公民的基本权利之一。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律保护公民的言论自由。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民行使言论自由时，不能伤害别人。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的言论自由有明确的法律规定。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师认为这件事没有影响他的言论自由。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民依法行使言论自由，不能破坏社会的安全。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓依法享有言论自由。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络上的言论自由也要遵守法律。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院认为这个人没有侵犯他人的言论自由。", "target_word": "言论自由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "言論自由", "label": "繁体"}], "register": "书面", "sense_fingerprint": "公民依法发表意见的法定权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f31afe75-cf81-4a37-a9d7-9dd37dc90485') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言论自由", "is_correct": true, "explanation": "宪法规定公民享有的正是言论自由，填入后语义吻合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是宪法规定的公民权利。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“享有”后接权利、待遇，“汽车”不说“享有汽车”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体特征，不能作为宪法规定的权利。"}], "explanations": {"言论自由": "宪法规定公民享有的正是言论自由，填入后语义吻合。", "天气": "语义：天气不是宪法规定的公民权利。", "汽车": "搭配：“享有”后接权利、待遇，“汽车”不说“享有汽车”。", "体重": "体貌：体重是身体特征，不能作为宪法规定的权利。"}, "sentence_index": 0, "correct_answer": "言论自由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在报纸上发表了言论自由。", "explanation": "这里应该用〈观点〉。“发表”的对象是观点、文章等，言论自由是权利，不能被发表。"}, {"text": "他每天都在吃言论自由。", "explanation": "这里应该用〈饭〉。“吃”的对象是饭菜等，言论自由是权利，不能被吃。"}, {"text": "他用言论自由洗了衣服。", "explanation": "这里应该用〈洗衣粉〉。言论自由是权利，不能用来洗衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言论自由", "is_correct": true, "explanation": "“行使”的对象是权利，言论自由是权利，填入后语义吻合。"}, {"text": "农田", "is_correct": false, "explanation": "搭配：“行使”的对象是权利，“农田”不能被行使。"}, {"text": "诗歌", "is_correct": false, "explanation": "搭配：“行使”的对象是权利，“诗歌”不能被行使。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“行使”的对象是权利，“食堂”不能被行使。"}], "explanations": {"言论自由": "“行使”的对象是权利，言论自由是权利，填入后语义吻合。", "农田": "搭配：“行使”的对象是权利，“农田”不能被行使。", "诗歌": "搭配：“行使”的对象是权利，“诗歌”不能被行使。", "食堂": "搭配：“行使”的对象是权利，“食堂”不能被行使。"}, "sentence_index": 6, "correct_answer": "言论自由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都练习言论自由一个小时。", "explanation": "这里应该用〈书法〉。“练习”的对象是技能，言论自由是权利，不能被练习。"}, {"text": "这座城市的言论自由很繁华。", "explanation": "这里应该用〈街道〉。“繁华”形容地方的热闹，不能用来形容权利。"}, {"text": "他把言论自由放进了书包。", "explanation": "这里应该用〈书〉。言论自由是抽象权利，不能被放进物体中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法律规定老百姓享有一个言论自由。", "corrected_sentence": "法律规定老百姓享有言论自由。", "error_description": "错误：多出“一个”。“言论自由”是抽象的权利，不能用量词“个”计数，应直接说“享有言论自由”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民依法享有言论自由的。", "corrected_sentence": "农民依法享有言论自由。", "error_description": "错误：句末多出“的”。“享有言论自由”是完整的动宾结构，句末不能加“的”，应为“农民依法享有言论自由。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
