INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89503, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "入时是穿的和用的，和现在大家喜欢的一样。", "primary_collocate": null, "pronunciation": "rù shí", "ipa": "ɻu˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "她今天穿得很入时。", "target_word": "入时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服的样子不太入时。", "target_word": "入时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶的打扮一点也不老，很入时。", "target_word": "入时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的帽子和鞋都很入时。", "target_word": "入时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包看起来很入时，年轻人都喜欢。", "target_word": "入时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一条入时的裙子。", "target_word": "入时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的衣服又好看又入时。", "target_word": "入时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她打扮得入时，走在街上很显眼。", "target_word": "入时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在这种颜色已经不入时了。", "target_word": "入时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿着入时的外套去上班。", "target_word": "入时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "穿戴用品合乎当下流行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89503, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "入时", "is_correct": true, "explanation": "正确：入时 rù shí，意思是合乎当下流行、时髦。"}, {"text": "入市", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是进入市场。"}, {"text": "入室", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是进入房间。"}, {"text": "如实", "is_correct": false, "explanation": "rú（第二声）与 rù（第四声）声调不同，意思是如实、真实。"}], "explanations": {"入时": "正确：入时 rù shí，意思是合乎当下流行、时髦。", "入市": "shì（第四声）与 shí（第二声）声调不同，意思是进入市场。", "入室": "shì（第四声）与 shí（第二声）声调不同，意思是进入房间。", "如实": "rú（第二声）与 rù（第四声）声调不同，意思是如实、真实。"}, "sentence_index": null, "correct_answer": "入时"}, "level_3": {"options": [{"text": "入时", "is_correct": true, "explanation": "正确：「穿得很入时」说衣着合乎当下流行，与句意相合。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：「高兴」形容心情，不能用来描述穿着的样式，「穿得很高兴」说不通。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：「沙哑」形容声音粗而不清亮，不能用来形容穿着，「穿得很沙哑」说不通。"}, {"text": "热情", "is_correct": false, "explanation": "语义：「热情」形容待人接物的态度，「穿得很热情」不能说明衣着的样式。"}], "explanations": {"入时": "正确：「穿得很入时」说衣着合乎当下流行，与句意相合。", "高兴": "语义：「高兴」形容心情，不能用来描述穿着的样式，「穿得很高兴」说不通。", "沙哑": "语义：「沙哑」形容声音粗而不清亮，不能用来形容穿着，「穿得很沙哑」说不通。", "热情": "语义：「热情」形容待人接物的态度，「穿得很热情」不能说明衣着的样式。"}, "sentence_index": 0, "correct_answer": "入时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方案想得很入时。", "explanation": "这里应该用〈周到〉。「入时」只形容衣着、用品合乎当下流行，不用于形容想法或方案；想得全面要用〈周到〉。"}, {"text": "这碗面条很入时。", "explanation": "这里应该用〈好吃〉。「入时」只形容衣着、用品，不用于形容食物。"}, {"text": "他说话很入时。", "explanation": "这里应该用〈得体〉。「入时」只形容衣着、用品合乎当下流行，不用于形容说话的方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89503, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "入时", "is_correct": true, "explanation": "正确：入时 rù shí，意思是合乎当下流行、时髦。"}, {"text": "入世", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是投身社会、参与世事。"}, {"text": "日食", "is_correct": false, "explanation": "rì 与 rù 的韵母不同（i 与 u），意思是日食。"}, {"text": "入室", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是进入房间。"}], "explanations": {"入时": "正确：入时 rù shí，意思是合乎当下流行、时髦。", "入世": "shì（第四声）与 shí（第二声）声调不同，意思是投身社会、参与世事。", "日食": "rì 与 rù 的韵母不同（i 与 u），意思是日食。", "入室": "shì（第四声）与 shí（第二声）声调不同，意思是进入房间。"}, "sentence_index": null, "correct_answer": "入时"}, "level_3": {"options": [{"text": "入时", "is_correct": true, "explanation": "正确：「又好看又入时」说衣服既美观又合乎当下流行，与句意相合。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：「陈旧」指过时，与后半句「入时」的含义相反，「又好看又陈旧」前后矛盾。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：「严肃」形容神情或态度，不能用来形容衣服的样式，「又好看又严肃」说不通。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：「沙哑」形容声音粗而不清亮，不能用来形容衣服，「又好看又沙哑」说不通。"}], "explanations": {"入时": "正确：「又好看又入时」说衣服既美观又合乎当下流行，与句意相合。", "陈旧": "语义：「陈旧」指过时，与后半句「入时」的含义相反，「又好看又陈旧」前后矛盾。", "严肃": "语义：「严肃」形容神情或态度，不能用来形容衣服的样式，「又好看又严肃」说不通。", "沙哑": "语义：「沙哑」形容声音粗而不清亮，不能用来形容衣服，「又好看又沙哑」说不通。"}, "sentence_index": 6, "correct_answer": "入时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的性格很入时。", "explanation": "这里应该用〈随和〉。「入时」只形容衣着、用品合乎当下流行，不用于形容性格。"}, {"text": "这份报告的页数很入时。", "explanation": "这里是把〈入时〉用在了页数上；「入时」只形容衣着、用品，不用于描述报告的篇幅，应说〈适中〉。"}, {"text": "这盏灯的亮度很入时。", "explanation": "这里是把〈入时〉用在了亮度上；「入时」只形容衣着、用品，不用于灯光，应说〈明亮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.p