INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师的穿着很入时地，学生都喜欢她。", "corrected_sentence": "这位老师的穿着很入时，学生都喜欢她。", "error_description": "「入时」在句中作谓语，后面不加「地」，应说「很入时」；「地」只用于修饰动词，「很入时地」中多出的「地」是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
