INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89504, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "合乎时尚，时髦。", "primary_collocate": null, "pronunciation": "rù shí", "ipa": "ɻu˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这位歌手的打扮十分入时。", "target_word": "入时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的发型既简单又入时。", "target_word": "入时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这身衣服太不入时了，换一件吧。", "target_word": "入时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志里的模特个个都穿得入时。", "target_word": "入时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢入时的眼镜。", "target_word": "入时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老李虽然年纪大，穿衣服却很入时。", "target_word": "入时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条围巾的花样很入时。", "target_word": "入时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐今天的裙子配得很入时，大家都夸她。", "target_word": "入时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是把自己打扮得很入时。", "target_word": "入时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "入时的打扮让她看起来很年轻。", "target_word": "入时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "合乎时尚、时髦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89504, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "入时", "is_correct": true, "explanation": "正确：入时 rù shí，意思是合乎时尚、时髦。"}, {"text": "入市", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是进入市场。"}, {"text": "如实", "is_correct": false, "explanation": "rú（第二声）与 rù（第四声）声调不同，意思是如实、真实。"}, {"text": "入室", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是进入房间。"}], "explanations": {"入时": "正确：入时 rù shí，意思是合乎时尚、时髦。", "入市": "shì（第四声）与 shí（第二声）声调不同，意思是进入市场。", "如实": "rú（第二声）与 rù（第四声）声调不同，意思是如实、真实。", "入室": "shì（第四声）与 shí（第二声）声调不同，意思是进入房间。"}, "sentence_index": null, "correct_answer": "入时"}, "level_3": {"options": [{"text": "入时", "is_correct": true, "explanation": "正确：「打扮十分入时」说打扮合乎时尚，与句意相合。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：「清楚」形容明白、分明，不能用来形容打扮，「打扮十分清楚」说不通。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：「寒冷」形容温度低，与描述打扮的句子不符，「打扮十分寒冷」说不通。"}, {"text": "饱满", "is_correct": false, "explanation": "搭配：「饱满」多形容精神、果实等，不用于形容打扮，搭配不当。"}], "explanations": {"入时": "正确：「打扮十分入时」说打扮合乎时尚，与句意相合。", "清楚": "语义：「清楚」形容明白、分明，不能用来形容打扮，「打扮十分清楚」说不通。", "寒冷": "语义：「寒冷」形容温度低，与描述打扮的句子不符，「打扮十分寒冷」说不通。", "饱满": "搭配：「饱满」多形容精神、果实等，不用于形容打扮，搭配不当。"}, "sentence_index": 0, "correct_answer": "入时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的声音很入时。", "explanation": "这里应该用〈动听〉。「入时」指合乎时尚，不用于形容声音。"}, {"text": "书架上的书排得很入时。", "explanation": "这里应该用〈整齐〉。「入时」不用于形容物品摆放得是否整齐。"}, {"text": "这块蛋糕做得很入时。", "explanation": "这里应该用〈精致〉。「入时」不用于形容食物的做工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89504, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "入时", "is_correct": true, "explanation": "正确：入时 rù shí，意思是合乎时尚、时髦。"}, {"text": "入世", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是投身社会、参与世事。"}, {"text": "日食", "is_correct": false, "explanation": "rì 与 rù 的韵母不同（i 与 u），意思是日食。"}, {"text": "入室", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是进入房间。"}], "explanations": {"入时": "正确：入时 rù shí，意思是合乎时尚、时髦。", "入世": "shì（第四声）与 shí（第二声）声调不同，意思是投身社会、参与世事。", "日食": "rì 与 rù 的韵母不同（i 与 u），意思是日食。", "入室": "shì（第四声）与 shí（第二声）声调不同，意思是进入房间。"}, "sentence_index": null, "correct_answer": "入时"}, "level_3": {"options": [{"text": "入时", "is_correct": true, "explanation": "正确：「这条围巾的花样很入时」说花样合乎当下流行，与句意相合。"}, {"text": "伤心", "is_correct": false, "explanation": "语义：「伤心」形容心情，不能用来形容围巾的花样，「花样很伤心」说不通。"}, {"text": "高大", "is_correct": false, "explanation": "语义：「高大」形容体积或身材，不能用来形容花样，「花样很高大」说不通。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：「清脆」多形容声音，不用于形容花样，搭配不当。"}], "explanations": {"入时": "正确：「这条围巾的花样很入时」说花样合乎当下流行，与句意相合。", "伤心": "语义：「伤心」形容心情，不能用来形容围巾的花样，「花样很伤心」说不通。", "高大": "语义：「高大」形容体积或身材，不能用来形容花样，「花样很高大」说不通。", "清脆": "搭配：「清脆」多形容声音，不用于形容花样，搭配不当。"}, "sentence_index": 6, "correct_answer": "入时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的心情很入时。", "explanation": "这里应该用〈愉快〉。「入时」只形容打扮、用品合乎流行，不用于形容心情。"}, {"text": "这次会议的内容很入时。", "explanation": "这里是把〈入时〉用在了会议内容上，表示〈内容切合时事〉的意思；「入时」不用于文字或会议内容。"}, {"text": "这场比赛的结果很入时。", "explanation": "这里应该用〈理想〉。「入时」指合乎流行的衣着、用品，不用于比赛结果；说结果好要用〈理想〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
