INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89505, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "很喜欢，心里觉得它很好。", "primary_collocate": null, "pronunciation": "xǐ ài", "ipa": "ɕi˨˩ ai˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们都喜爱这只小狗。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就喜爱音乐。", "target_word": "喜爱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很喜爱这本书，看了三次。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种水果很受大家喜爱。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷一直喜爱京剧，常常去听。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜爱春天，因为花开了。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他十分喜爱自己的家乡。", "target_word": "喜爱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个孩子喜爱读书，从不看电视。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都很喜爱这位老师的课。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜爱着这座城市，每天都想念它。", "target_word": "喜爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喜爱着", "label": "体标"}, {"form": "喜爱过", "label": "体标"}, {"form": "喜愛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对事物、活动或地方很喜欢，觉得它好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62cc808b-1d77-4da2-a098-96e4506bf48a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89505, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喜爱", "is_correct": true, "explanation": "正确：「喜爱」表示对小狗有好感，符合「孩子们都……这只小狗」的语境。"}, {"text": "批准", "is_correct": false, "explanation": "语义：「批准」的对象是计划、申请等，不能用来指小狗。"}, {"text": "编写", "is_correct": false, "explanation": "搭配：「编写」多跟书、程序、教材搭配，不能说「编写这只小狗」。"}, {"text": "举办", "is_correct": false, "explanation": "语义：「举办」的对象是活动、比赛，不能用于小狗。"}], "explanations": {"喜爱": "正确：「喜爱」表示对小狗有好感，符合「孩子们都……这只小狗」的语境。", "批准": "语义：「批准」的对象是计划、申请等，不能用来指小狗。", "编写": "搭配：「编写」多跟书、程序、教材搭配，不能说「编写这只小狗」。", "举办": "语义：「举办」的对象是活动、比赛，不能用于小狗。"}, "sentence_index": 0, "correct_answer": "喜爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这个结果很喜爱，心里很高兴。", "explanation": "这里应该用〈满意〉。「喜爱」表示对人或事物本身有好感，不用来表示对结果的满意。"}, {"text": "我很喜爱他的帮助，他帮了我很多次。", "explanation": "这里应该用〈感激〉。「喜爱」针对人或事物本身，对别人的帮助表示谢意要用「感激」。"}, {"text": "我喜爱了一下这幅画，就转身走了。", "explanation": "这里应该用〈看〉。「喜爱」表示长期稳定的好感，不能加「了一下」表示短暂的动作，应说「我看了一下这幅画」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89505, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喜爱", "is_correct": true, "explanation": "正确：「喜爱」表示对家乡的深厚感情，符合「他十分……自己的家乡」的语境。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：「烹饪」的对象是食物，不能用来指家乡。"}, {"text": "统计", "is_correct": false, "explanation": "搭配：「统计」多跟数字、人数、数据搭配，不能说「统计自己的家乡」。"}, {"text": "打印", "is_correct": false, "explanation": "语义：「打印」的对象是文件、材料，不能用于家乡。"}], "explanations": {"喜爱": "正确：「喜爱」表示对家乡的深厚感情，符合「他十分……自己的家乡」的语境。", "烹饪": "语义：「烹饪」的对象是食物，不能用来指家乡。", "统计": "搭配：「统计」多跟数字、人数、数据搭配，不能说「统计自己的家乡」。", "打印": "语义：「打印」的对象是文件、材料，不能用于家乡。"}, "sentence_index": 6, "correct_answer": "喜爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他搬走了，我却很喜爱这件事。", "explanation": "这里应该用〈遗憾〉。「喜爱」表示对人或事物的好感，不能用来表达对别人离开的惋惜。"}, {"text": "他很喜爱女儿的身体，常常为此操心。", "explanation": "这里应该用〈担心〉。「喜爱」的对象是人或事物本身，不能用来表示对身体状况的担忧。"}, {"text": "我对他的回答感到喜爱，心里很平静。", "explanation": "这里应该用〈满意〉。「喜爱」表示对人或事物本身的好感，不用于对别人回答的满意或认可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
