INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从小就喜爱了这片海。", "corrected_sentence": "我从小就喜爱这片海。", "error_description": "「了」误用：「喜爱」表示持续的好感，不接「了」表示完成，应说「我从小就喜爱这片海」，去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
