INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89506, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "对人或事物有好感，感到喜欢。", "primary_collocate": null, "pronunciation": "xǐ ài", "ipa": "ɕi˨˩ ai˥˩", "syllable_count": 2, "sentences": [{"text": "同学们都很喜爱新来的老师。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他善良，所以大家都喜爱他。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一次见面，我就喜爱这个女孩。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生很受病人喜爱。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明喜爱他的同桌，常常帮她。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师喜爱努力的学生。", "target_word": "喜爱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的笑容让每个人都喜爱她。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们喜爱这位幽默的邻居。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都喜爱这个有礼貌的孩子。", "target_word": "喜爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜爱着那位帮过她的老人。", "target_word": "喜爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喜爱着", "label": "体标"}, {"form": "喜爱过", "label": "体标"}, {"form": "喜愛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对某个人有好感，感到喜欢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62cc808b-1d77-4da2-a098-96e4506bf48a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喜爱", "is_correct": true, "explanation": "正确：「喜爱」表示同学对老师的好感，符合「同学们都很……新来的老师」的语境。"}, {"text": "修理", "is_correct": false, "explanation": "语义：「修理」的对象是机器、物件，不能用来指老师。"}, {"text": "运输", "is_correct": false, "explanation": "语义：「运输」的对象是货物，不能用来指老师。"}, {"text": "编写", "is_correct": false, "explanation": "搭配：「编写」多跟书、程序、教材搭配，不能说「编写新来的老师」。"}], "explanations": {"喜爱": "正确：「喜爱」表示同学对老师的好感，符合「同学们都很……新来的老师」的语境。", "修理": "语义：「修理」的对象是机器、物件，不能用来指老师。", "运输": "语义：「运输」的对象是货物，不能用来指老师。", "编写": "搭配：「编写」多跟书、程序、教材搭配，不能说「编写新来的老师」。"}, "sentence_index": 0, "correct_answer": "喜爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我为他的遭遇感到喜爱。", "explanation": "这里应该用〈同情〉。「喜爱」表示对人或事物的好感，不能用于对别人不幸遭遇的怜悯。"}, {"text": "我喜爱了他一会儿，就走了。", "explanation": "这里应该用〈看〉。「喜爱」表示持久的好感，不能用「了一会儿」表示短暂动作，应说「我看了他一会儿，就走了」。"}, {"text": "我很喜爱他的帮助，他帮了我很多。", "explanation": "这里应该用〈感谢〉。「喜爱」针对人或事物本身，对别人的帮助表示谢意要用「感谢」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喜爱", "is_correct": true, "explanation": "正确：「喜爱」表示对人的好感，符合「她的笑容让每个人都……她」的语境。"}, {"text": "统计", "is_correct": false, "explanation": "搭配：「统计」多跟数字、人数、数据搭配，不能说「统计她」。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：「搬运」的对象是物品，不能用来指人的笑容所引起的情感。"}, {"text": "发明", "is_correct": false, "explanation": "语义：「发明」的对象是物品或方法，不能用来指人。"}], "explanations": {"喜爱": "正确：「喜爱」表示对人的好感，符合「她的笑容让每个人都……她」的语境。", "统计": "搭配：「统计」多跟数字、人数、数据搭配，不能说「统计她」。", "搬运": "语义：「搬运」的对象是物品，不能用来指人的笑容所引起的情感。", "发明": "语义：「发明」的对象是物品或方法，不能用来指人。"}, "sentence_index": 6, "correct_answer": "喜爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈很喜爱我的身体，常常为此操心。", "explanation": "这里应该用〈担心〉。「喜爱」的对象是人本身，不能用来表示对身体状况的担忧。"}, {"text": "我很喜爱那场比赛的失利。", "explanation": "这里应该用〈遗憾〉。「喜爱」表达好感，不能用于对比赛失利表示惋惜。"}, {"text": "我对他的回答感到喜爱。", "explanation": "这里应该用〈赞赏〉。「喜爱」表示对人或事物本身的好感，不用于对别人回答的肯定与赞赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很喜爱了那个邻居。", "corrected_sentence": "我很喜爱那个邻居。", "error_description": "「了」误用：「喜爱」表示持续的好感，不接「了」，应说「我很喜爱那个邻居」，去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都把很喜爱那位老师。", "corrected_sentence": "我们都很喜爱那位老师。", "error_description": "「把」字句错误：「把」不能放在状语「很」前面，应说「我们都很喜爱那位老师」，去掉「把」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
