INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89507, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "证人是看到事情经过，能站出来说清楚的人。", "primary_collocate": null, "pronunciation": "zhèng rén", "ipa": "ʈʂɤŋ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "小明打碎了玻璃，只有我是证人。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故发生时，很多路人都是证人。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在街上找看见事故的证人。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不敢当证人，怕别人找他麻烦。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事没有证人，谁也说不清楚。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我愿意做证人，把看到的都说出来。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天他在现场，所以大家请他当证人。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说东西不是他拿的，可是有三个证人。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想知道谁打了架，就找来了证人。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证人说，他听到了很大的一声响。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "证人证言", "label": "复合"}], "register": "中性", "sense_fingerprint": "亲眼看到事情经过并能说清楚的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89507, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证人", "is_correct": true, "explanation": "证人：亲眼看到事情经过、能站出来说清楚的人，读作 zhèng rén。"}, {"text": "整人", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，整人是捉弄、折磨别人的意思。"}, {"text": "众人", "is_correct": false, "explanation": "zhòng 与 zhèng 韵母元音不同（o 与 e），众人指许多人。"}, {"text": "圣人", "is_correct": false, "explanation": "shèng 与 zhèng 声母不同（sh 与 zh），圣人指品德高尚、有智慧的人。"}], "explanations": {"证人": "证人：亲眼看到事情经过、能站出来说清楚的人，读作 zhèng rén。", "整人": "zhěng（第三声）与 zhèng（第四声）声调不同，整人是捉弄、折磨别人的意思。", "众人": "zhòng 与 zhèng 韵母元音不同（o 与 e），众人指许多人。", "圣人": "shèng 与 zhèng 声母不同（sh 与 zh），圣人指品德高尚、有智慧的人。"}, "sentence_index": null, "correct_answer": "证人"}, "level_3": {"options": [{"text": "证人", "is_correct": true, "explanation": "证人：指亲眼看到事情经过、能说清楚的人，与“只有我是”前文的语境相符。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不是人，不能亲眼看到事情经过。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：句中已有“打碎了玻璃”，“只有我是玻璃”与前文矛盾，搭配不当。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，不能作为亲眼看到事情的人。"}], "explanations": {"证人": "证人：指亲眼看到事情经过、能说清楚的人，与“只有我是”前文的语境相符。", "窗帘": "语义：窗帘不是人，不能亲眼看到事情经过。", "玻璃": "搭配：句中已有“打碎了玻璃”，“只有我是玻璃”与前文矛盾，搭配不当。", "花瓶": "语义：花瓶是器物，不能作为亲眼看到事情的人。"}, "sentence_index": 0, "correct_answer": "证人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把证人写在纸上，交给了警察。", "explanation": "这里应该用〈证词〉。写在纸上交出去的是证词，证人指看见事情经过的人，不能写在纸上。"}, {"text": "他去医院开了证人。", "explanation": "这里应该用〈证明〉。开的是证明，证人指看见事情经过的人，不能用“开”来说。"}, {"text": "他喝了一杯证人。", "explanation": "这里应该用〈茶〉。喝的是茶水，证人是人，不能当饮品来喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "证人", "is_correct": true, "explanation": "证人：指在现场、能站出来说明情况的人，与“在现场”的语境相符。"}, {"text": "箱子", "is_correct": false, "explanation": "语义：箱子不是人，不能在现场亲眼看见事情，也不能担任证人。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“当”要求带表示角色的名词，天气不能充当被请去担任角色的对象。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是家电，不能在现场亲眼看到事情经过。"}], "explanations": {"证人": "证人：指在现场、能站出来说明情况的人，与“在现场”的语境相符。", "箱子": "语义：箱子不是人，不能在现场亲眼看见事情，也不能担任证人。", "天气": "配价：“当”要求带表示角色的名词，天气不能充当被请去担任角色的对象。", "电视": "语义：电视是家电，不能在现场亲眼看到事情经过。"}, "sentence_index": 6, "correct_answer": "证人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "证人下令把他带走了。", "explanation": "这里应该用〈法官〉。下令的是法官，证人只陈述所见，不能下令拘押。"}, {"text": "证人起诉了他的邻居。", "explanation": "这里应该用〈原告〉。起诉的是原告，证人不是诉讼的当事人。"}, {"text": "证人承认了这次抢劫。", "explanation": "这里应该用〈嫌疑人〉。承认作案的是嫌疑人，证人不是涉案的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只证人看见了事故的经过。", "corrected_sentence": "这位证人看见了事故的经过。", "error_description": "量词错误：“只”用于动物，证人是人，应把量词“只”改为“位”，写作“这位证人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位看见事故证人很诚实。", "corrected_sentence": "那位看见事故的证人很诚实。", "error_description": "修饰语错误：“看见事故”修饰“证人”时要加“的”，应写作“看见事故的证人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
