INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在诉讼中就所知案件事实向司法机关作证的人。", "primary_collocate": null, "pronunciation": "zhèng rén", "ipa": "ʈʂɤŋ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "法官请证人站起来，说说当时的情况。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子有两位证人，他们都愿意出庭。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证人在法庭上说，他那天晚上看见了嫌疑人。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师向证人问了几个问题。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开庭前，律师又见了一次证人。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证人的话让法官改变了看法。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为没有证人，这件案子很难判。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个案子的重要证人。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证人签了字，然后离开了法庭。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院通知证人明天上午九点出庭。", "target_word": "证人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "证人席", "label": "复合"}], "register": "正式", "sense_fingerprint": "诉讼中向法院或司法机关作证的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89508, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证人", "is_correct": true, "explanation": "证人：在诉讼中就所知案件事实作证的人，读作 zhèng rén。"}, {"text": "整人", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，整人是捉弄、折磨别人的意思。"}, {"text": "众人", "is_correct": false, "explanation": "zhòng 与 zhèng 韵母元音不同（o 与 e），众人指许多人。"}, {"text": "圣人", "is_correct": false, "explanation": "shèng 与 zhèng 声母不同（sh 与 zh），圣人指品德高尚、有智慧的人。"}], "explanations": {"证人": "证人：在诉讼中就所知案件事实作证的人，读作 zhèng rén。", "整人": "zhěng（第三声）与 zhèng（第四声）声调不同，整人是捉弄、折磨别人的意思。", "众人": "zhòng 与 zhèng 韵母元音不同（o 与 e），众人指许多人。", "圣人": "shèng 与 zhèng 声母不同（sh 与 zh），圣人指品德高尚、有智慧的人。"}, "sentence_index": null, "correct_answer": "证人"}, "level_3": {"options": [{"text": "证人", "is_correct": true, "explanation": "证人：指在法庭上陈述所知案情的人，符合“请……站起来，说说当时的情况”的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会站起来，也不能讲述当时的情况。"}, {"text": "婴儿", "is_correct": false, "explanation": "体貌：婴儿还不会站立，也无法陈述案件经过。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“说”需要有生命的说话者，书包不能充当说话的主语。"}], "explanations": {"证人": "证人：指在法庭上陈述所知案情的人，符合“请……站起来，说说当时的情况”的语境。", "石头": "语义：石头不会站起来，也不能讲述当时的情况。", "婴儿": "体貌：婴儿还不会站立，也无法陈述案件经过。", "书包": "配价：“说”需要有生命的说话者，书包不能充当说话的主语。"}, "sentence_index": 0, "correct_answer": "证人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海关检查时，他出示了一位证人。", "explanation": "这里应该用〈证件〉。出示的是证件，证人指在诉讼中作证的人，不能拿出来给人查验。"}, {"text": "法庭上，他播放了一位证人。", "explanation": "这里应该用〈录音〉。播放的是录音，证人是人，不能被播放。"}, {"text": "他买了两斤证人。", "explanation": "这里应该用〈苹果〉。买的是苹果，证人是人，不能用斤来称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "证人", "is_correct": true, "explanation": "证人：没有人出来作证，案件就难以认定，符合“很难判”的因果关系。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果与案件无关，“没有苹果，这件案子很难判”说不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，“没有椅子，这件案子很难判”说不通。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，与案件能否判决没有关系，句子说不通。"}], "explanations": {"证人": "证人：没有人出来作证，案件就难以认定，符合“很难判”的因果关系。", "苹果": "语义：苹果与案件无关，“没有苹果，这件案子很难判”说不通。", "椅子": "语义：椅子是家具，“没有椅子，这件案子很难判”说不通。", "春天": "语义：春天是季节，与案件能否判决没有关系，句子说不通。"}, "sentence_index": 6, "correct_answer": "证人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "证人宣布了今天的判决。", "explanation": "这里应该用〈法官〉。宣布判决的是法官，证人只陈述自己所知的事实，不做裁决。"}, {"text": "证人在法庭上替被告做了手术。", "explanation": "这里应该用〈医生〉。做手术的是医生，证人只陈述所知的事实，不能替人做手术。"}, {"text": "证人向法院起诉了他的邻居。", "explanation": "这里应该用〈原告〉。起诉的是原告，证人不是诉讼当事人，不能提起诉讼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只证人很诚实。", "corrected_sentence": "这位证人很诚实。", "error_description": "量词错误：“只”用于动物，证人是人，应把量词“只”改为“位”，写作“这位证人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看见站在门口证人。", "corrected_sentence": "我看见站在门口的证人。", "error_description": "修饰语错误：“站在门口”修饰“证人”时要加“的”，应写作“站在门口的证人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
