INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89509, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "双是两个合成一对,数东西时用。", "primary_collocate": null, "pronunciation": "shuāng", "ipa": "ʂuɑŋ˥", "syllable_count": 1, "sentences": [{"text": "冬天我需要一双厚手套。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双皮鞋多少钱?", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一双巧手做了个小木船。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你拿三双筷子来。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一双白色的运动鞋。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睁着一双大眼睛看我。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双拖鞋是我在家穿的。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她送了我一双红袜子。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一双旧鞋放在门口。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有四双拖鞋。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "雙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "双:量词,两个合成一对的东西,数鞋、手套、拖鞋、眼睛等时用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cbc0dd4-f7ee-4093-b4cd-555297c3b1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89509, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "双", "is_correct": true, "explanation": "双是两个合成一对，数东西时用，如手套、鞋、拖鞋。"}, {"text": "装", "is_correct": false, "explanation": "zhuāng（第一声）与 shuāng 声母不同（zh 与 sh），意思是装（装东西）。"}, {"text": "爽", "is_correct": false, "explanation": "shuǎng（第三声）与 shuāng（第一声）声调不同，意思是爽快、舒服。"}, {"text": "拴", "is_correct": false, "explanation": "shuān（第一声）与 shuāng 韵母不同（an 与 ang），意思是拴住。"}], "explanations": {"双": "双是两个合成一对，数东西时用，如手套、鞋、拖鞋。", "装": "zhuāng（第一声）与 shuāng 声母不同（zh 与 sh），意思是装（装东西）。", "爽": "shuǎng（第三声）与 shuāng（第一声）声调不同，意思是爽快、舒服。", "拴": "shuān（第一声）与 shuāng 韵母不同（an 与 ang），意思是拴住。"}, "sentence_index": null, "correct_answer": "双"}, "level_3": {"options": [{"text": "双", "is_correct": true, "explanation": "“双”是量词，手套成对计量，“一双厚手套”符合句意。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，手套不用“张”计量。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄的东西，不用于手套。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，不能用于手套。"}], "explanations": {"双": "“双”是量词，手套成对计量，“一双厚手套”符合句意。", "张": "搭配：“张”用于平面的东西，手套不用“张”计量。", "把": "搭配：“把”用于有柄的东西，不用于手套。", "本": "搭配：“本”用于书册，不能用于手套。"}, "sentence_index": 0, "correct_answer": "双"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你拿三双碗来。", "explanation": "这里应该用〈只〉。“双”用于成对的东西，碗不成对，要说“三只碗”。"}, {"text": "请你拿三双扑克牌来。", "explanation": "这里应该用〈副〉。扑克牌用“副”计量，不用“双”。"}, {"text": "这双盘子是我在家用的。", "explanation": "这里应该用〈个〉。盘子是单件，用“个”计量，“双”只用于成对的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89509, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "双", "is_correct": true, "explanation": "双是两个合成一对，数东西时用，如手套、鞋、拖鞋。"}, {"text": "窗", "is_correct": false, "explanation": "chuāng（第一声）与 shuāng 声母不同（ch 与 sh），意思是窗户。"}, {"text": "庄", "is_correct": false, "explanation": "zhuāng（第一声）与 shuāng 声母不同（zh 与 sh），意思是村庄或庄重。"}, {"text": "疮", "is_correct": false, "explanation": "chuāng（第一声）与 shuāng 声母不同（ch 与 sh），意思是皮肤上的疮。"}], "explanations": {"双": "双是两个合成一对，数东西时用，如手套、鞋、拖鞋。", "窗": "chuāng（第一声）与 shuāng 声母不同（ch 与 sh），意思是窗户。", "庄": "zhuāng（第一声）与 shuāng 声母不同（zh 与 sh），意思是村庄或庄重。", "疮": "chuāng（第一声）与 shuāng 声母不同（ch 与 sh），意思是皮肤上的疮。"}, "sentence_index": null, "correct_answer": "双"}, "level_3": {"options": [{"text": "双", "is_correct": true, "explanation": "“双”是量词，拖鞋成对计量，“这双拖鞋”符合句意。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，不用于拖鞋。"}, {"text": "件", "is_correct": false, "explanation": "搭配：“件”用于衣物等单件东西，拖鞋不用“件”计量。"}, {"text": "辆", "is_correct": false, "explanation": "语义：“辆”用于车辆，与拖鞋无关，句意不通。"}], "explanations": {"双": "“双”是量词，拖鞋成对计量，“这双拖鞋”符合句意。", "条": "搭配：“条”用于细长的东西，不用于拖鞋。", "件": "搭配：“件”用于衣物等单件东西，拖鞋不用“件”计量。", "辆": "语义：“辆”用于车辆，与拖鞋无关，句意不通。"}, "sentence_index": 6, "correct_answer": "双"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家有四双房子。", "explanation": "这里应该用〈套〉。“双”用于成对的东西，房子不成对，要说“四套房子”。"}, {"text": "我家有四双小猫。", "explanation": "这里应该用〈只〉。小猫不成对，“双”只用于成对的东西，应说“四只小猫”。"}, {"text": "我配了两双眼镜。", "explanation": "这里应该用〈副〉。眼镜用“副”计量，“双”只用于成对的东西，不能说“两双眼镜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我要戴一双帽子出门。", "corrected_sentence": "我要戴一顶帽子出门。", "error_description": "量词错误：“双”只用于成对的东西，帽子是单件的，不能说“一双帽子”，应该用“顶”，说“一顶帽子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有三个双运动鞋。", "corrected_sentence": "他有三双运动鞋。", "error_description": "量词重复：“三双”中的“双”已是量词，前面不能再加“个”，应说“三双运动鞋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
