INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89510, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词,用于成对的东西。", "primary_collocate": null, "pronunciation": "shuāng", "ipa": "ʂuɑŋ˥", "syllable_count": 1, "sentences": [{"text": "我买了一双新鞋。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有一双大眼睛。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一双筷子。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双袜子是妈妈送的。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他戴着一双黑手套。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做了一双布鞋给我。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋太小了,我穿不下。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那双手很大,也很暖和。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着两双筷子。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一双会弹钢琴的手。", "target_word": "双", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "雙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "双:量词,用于成对的东西,如鞋、袜子、筷子、手、眼睛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cbc0dd4-f7ee-4093-b4cd-555297c3b1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89510, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "双", "is_correct": true, "explanation": "双是量词，用于成对的东西，如鞋、袜子、手套。"}, {"text": "窗", "is_correct": false, "explanation": "chuāng（第一声）与 shuāng 声母不同（ch 与 sh），意思是窗户。"}, {"text": "装", "is_correct": false, "explanation": "zhuāng（第一声）与 shuāng 声母不同（zh 与 sh），意思是装（装东西）。"}, {"text": "爽", "is_correct": false, "explanation": "shuǎng（第三声）与 shuāng（第一声）声调不同，意思是爽快、舒服。"}], "explanations": {"双": "双是量词，用于成对的东西，如鞋、袜子、手套。", "窗": "chuāng（第一声）与 shuāng 声母不同（ch 与 sh），意思是窗户。", "装": "zhuāng（第一声）与 shuāng 声母不同（zh 与 sh），意思是装（装东西）。", "爽": "shuǎng（第三声）与 shuāng（第一声）声调不同，意思是爽快、舒服。"}, "sentence_index": null, "correct_answer": "双"}, "level_3": {"options": [{"text": "双", "is_correct": true, "explanation": "“双”是量词，鞋成对计量，“一双新鞋”符合句意。"}, {"text": "件", "is_correct": false, "explanation": "搭配：“件”用于衣物等单件东西，鞋不用“件”计量。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，不用于鞋。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，鞋不用“张”计量。"}], "explanations": {"双": "“双”是量词，鞋成对计量，“一双新鞋”符合句意。", "件": "搭配：“件”用于衣物等单件东西，鞋不用“件”计量。", "条": "搭配：“条”用于细长的东西，不用于鞋。", "张": "搭配：“张”用于平面的东西，鞋不用“张”计量。"}, "sentence_index": 0, "correct_answer": "双"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双书是妈妈送的。", "explanation": "这里应该用〈本〉。“双”只用于成对的东西，书不成对，要说“这本书”。"}, {"text": "这双眼镜是妈妈送的。", "explanation": "这里应该用〈副〉。眼镜用“副”计量，不用“双”。"}, {"text": "这双扑克牌是我的生日礼物。", "explanation": "这里应该用〈副〉。扑克牌成套，用“副”计量，“双”只用于成对的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warni