INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89510, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "双", "is_correct": true, "explanation": "双是量词，用于成对的东西，如鞋、袜子、手套。"}, {"text": "拴", "is_correct": false, "explanation": "shuān（第一声）与 shuāng 韵母不同（an 与 ang），意思是拴住。"}, {"text": "庄", "is_correct": false, "explanation": "zhuāng（第一声）与 shuāng 声母不同（zh 与 sh），意思是村庄或庄重。"}, {"text": "疮", "is_correct": false, "explanation": "chuāng（第一声）与 shuāng 声母不同（ch 与 sh），意思是皮肤上的疮。"}], "explanations": {"双": "双是量词，用于成对的东西，如鞋、袜子、手套。", "拴": "shuān（第一声）与 shuāng 韵母不同（an 与 ang），意思是拴住。", "庄": "zhuāng（第一声）与 shuāng 声母不同（zh 与 sh），意思是村庄或庄重。", "疮": "chuāng（第一声）与 shuāng 声母不同（ch 与 sh），意思是皮肤上的疮。"}, "sentence_index": null, "correct_answer": "双"}, "level_3": {"options": [{"text": "双", "is_correct": true, "explanation": "“双”是量词，鞋成对计量，“这双鞋”符合句意。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车辆，不能用于鞋。"}, {"text": "杯", "is_correct": false, "explanation": "搭配：“杯”用于盛饮料的容器，不能计量鞋。"}, {"text": "块", "is_correct": false, "explanation": "语义：“块”指块状物，不表示成对，句意不通。"}], "explanations": {"双": "“双”是量词，鞋成对计量，“这双鞋”符合句意。", "辆": "搭配：“辆”用于车辆，不能用于鞋。", "杯": "搭配：“杯”用于盛饮料的容器，不能计量鞋。", "块": "语义：“块”指块状物，不表示成对，句意不通。"}, "sentence_index": 6, "correct_answer": "双"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一双会弹钢琴的老师。", "explanation": "这里应该用〈位〉。“双”用于成对的东西，老师是人，要用“位”计量。"}, {"text": "他买了一双项链送妈妈。", "explanation": "这里应该用〈条〉。项链是单件，用“条”计量，“双”只用于成对的东西。"}, {"text": "他昨天写了一双信给妈妈。", "explanation": "这里应该用〈封〉。信用“封”计量，“双”只用于成对的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了一双黑裙子。", "corrected_sentence": "我昨天买了一条黑裙子。", "error_description": "量词错误：“双”只用于成对的东西，裙子是单件的，不能说“一双裙子”，应该用“条”，说“一条黑裙子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她买了双两靴子。", "corrected_sentence": "她买了两双靴子。", "error_description": "数量词语序错误：应说“两双”，数词在前、量词在后，不能说“双两”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82cbe1-8246-4716-b102-f7925d595486') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
