INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89511, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "内幕是藏在里面、别人不知道的事。", "primary_collocate": null, "pronunciation": "nèi mù", "ipa": "neɪ˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "记者想知道这件事的内幕。", "target_word": "内幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的内幕，外人一点也不知道。", "target_word": "内幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说出了比赛的内幕。", "target_word": "内幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上写着这件事的内幕。", "target_word": "内幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有他自己知道这件事的内幕。", "target_word": "内幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个内幕太大，没有人敢说。", "target_word": "内幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这里面有什么内幕吗？", "target_word": "内幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想告诉我们内幕。", "target_word": "内幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个记者把内幕写成了一本书。", "target_word": "内幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了朋友的话，我才知道内幕。", "target_word": "内幕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "內幕", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "内幕消息", "label": "复合"}], "register": "中性", "sense_fingerprint": "藏在里面、别人不知道的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60eb8d25-3940-4b37-9ab8-c3a913d8c431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89511, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "内幕", "is_correct": true, "explanation": "正确：内幕 nèi mù 指藏在里面、别人不知道的事。"}, {"text": "类目", "is_correct": false, "explanation": "lèi（第四声）与 nèi 声母不同（l／n），意思是类别条目。"}, {"text": "内膜", "is_correct": false, "explanation": "mó（第二声）与 mù（第四声）声调不同，意思是内层的薄膜。"}, {"text": "内部", "is_correct": false, "explanation": "bù 与 mù 声母不同（b／m），意思是里面、内部。"}, {"text": "内务", "is_correct": false, "explanation": "wù 与 mù 声母不同（w／m），意思是机关或家庭内部的事务。"}], "explanations": {"内幕": "正确：内幕 nèi mù 指藏在里面、别人不知道的事。", "类目": "lèi（第四声）与 nèi 声母不同（l／n），意思是类别条目。", "内膜": "mó（第二声）与 mù（第四声）声调不同，意思是内层的薄膜。", "内部": "bù 与 mù 声母不同（b／m），意思是里面、内部。", "内务": "wù 与 mù 声母不同（w／m），意思是机关或家庭内部的事务。"}, "sentence_index": null, "correct_answer": "内幕"}, "level_3": {"options": [{"text": "内幕", "is_correct": true, "explanation": "正确：内幕指不为外人所知的内情，与“想知道”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是可以打听的事件内情。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“这件事的价格”不成立，事件没有价钱可谈。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：外貌指人或物的外表，不是事件中别人不知道的内情。"}], "explanations": {"内幕": "正确：内幕指不为外人所知的内情，与“想知道”搭配。", "天气": "语义：天气是自然现象，不是可以打听的事件内情。", "价格": "搭配：“这件事的价格”不成立，事件没有价钱可谈。", "外貌": "语义：外貌指人或物的外表，不是事件中别人不知道的内情。"}, "sentence_index": 0, "correct_answer": "内幕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "原子的内幕很小。", "explanation": "这里应该用〈内核〉。内幕指事件或机构里外人不知道的内情，原子中心的部分要说内核。"}, {"text": "报纸上写着这件事的一位内幕。", "explanation": "量词错误：“位”用于人，内幕是事情的内情，应该用〈个〉。"}, {"text": "这个房间的内幕很干净。", "explanation": "内幕只用于事件或机构里外人不知道的内情，不能用来说房间的内部状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内幕", "is_correct": true, "explanation": "正确：内幕是藏在里面、别人不知道的事，与“你知道”搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不是藏在里面的事情。"}, {"text": "房租", "is_correct": false, "explanation": "搭配：“这里面有什么房租”不成立，房租是付给房东的钱。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是可以藏在里面让人打听的隐情。"}], "explanations": {"内幕": "正确：内幕是藏在里面、别人不知道的事，与“你知道”搭配。", "体重": "语义：体重是身体的重量，不是藏在里面的事情。", "房租": "搭配：“这里面有什么房租”不成立，房租是付给房东的钱。", "年龄": "语义：年龄不是可以藏在里面让人打听的隐情。"}, "sentence_index": 6, "correct_answer": "内幕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我住在内幕里，很少出门。", "explanation": "内幕是抽象的内情，不是可以居住的地方。"}, {"text": "他的内幕很痛苦。", "explanation": "内幕指事件里的内情，不能指人的内心感受。"}, {"text": "他把这个内幕煮了。", "explanation": "这里应该用〈食物〉。内幕是事件里外人不知道的内情，不能拿来煮；能煮的东西要说食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他透露了一本内幕。", "corrected_sentence": "他透露了一个内幕。", "error_description": "量词错误：“本”用于书籍，内幕不是书，应该用“个”，正确是「一个内幕」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于听说了公司的内幕们。", "corrected_sentence": "他终于听说了公司的内幕。", "error_description": "后缀错误：内幕是抽象名词，不能加“们”表示复数，正确是「内幕」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
