INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89513, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89513, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变道是开车时，从一条路转到旁边另一条路上。", "primary_collocate": null, "pronunciation": "biàn dào", "ipa": "pjɛn˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "红灯前，那辆车突然变道了。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我学开车时，老师说变道要慢。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去左边，所以先打灯再变道。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路口不能变道，会很危险。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆白车一直变道，太危险了。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到前面有人修路，司机马上变道。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变道前要先看一看旁边。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他变道后，速度慢了下来。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈开车很小心，很少变道。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的车要变道去右边的路。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变了道", "label": "体标（了）"}, {"form": "变过道", "label": "体标（过）"}, {"form": "變道", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开车时从一条车道转到旁边的车道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94079a68-bf10-4746-bd88-8d31e031ef14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89513, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变道", "is_correct": true, "explanation": "正确。“突然变道了”指车辆在红灯前转入相邻车道，符合语境。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：车辆不会唱歌，“突然唱歌了”与红灯前的驾驶情境不符。"}, {"text": "变瘦", "is_correct": false, "explanation": "语义：“变瘦”指人的体型改变，车辆不能“变瘦”。"}, {"text": "睡着", "is_correct": false, "explanation": "语义：车辆不会睡着，与红灯前需要专注驾驶的情境矛盾。"}], "explanations": {"变道": "正确。“突然变道了”指车辆在红灯前转入相邻车道，符合语境。", "唱歌": "语义：车辆不会唱歌，“突然唱歌了”与红灯前的驾驶情境不符。", "变瘦": "语义：“变瘦”指人的体型改变，车辆不能“变瘦”。", "睡着": "语义：车辆不会睡着，与红灯前需要专注驾驶的情境矛盾。"}, "sentence_index": 0, "correct_answer": "变道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话时常常变道，一会儿说东一会儿说西。", "explanation": "这里应该用〈变话题〉。说话内容的改变不能说变道，变道只用于车辆转入相邻车道。"}, {"text": "车停在家门口，爸爸下车变道进了屋。", "explanation": "这里应该用〈走〉。人下车后走进屋要说走，变道是车辆转入相邻车道。"}, {"text": "天气突然变道，雨下得很大。", "explanation": "这里应该用〈变化〉。天气的改变要说变化，变道只用于车辆转入相邻车道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变道", "is_correct": true, "explanation": "正确。“变道”前要先看旁边的车，确保安全，符合语境。"}, {"text": "红色", "is_correct": false, "explanation": "词性：“红色”是颜色词，不是动作，“红色前要先看一看旁边”不通。"}, {"text": "司机", "is_correct": false, "explanation": "词性：“司机”是人，不是动作，“司机前要先看一看旁边”不通。"}, {"text": "变瘦", "is_correct": false, "explanation": "体貌：“变瘦”说的是人的体型，与驾驶前的观察无关。"}], "explanations": {"变道": "正确。“变道”前要先看旁边的车，确保安全，符合语境。", "红色": "词性：“红色”是颜色词，不是动作，“红色前要先看一看旁边”不通。", "司机": "词性：“司机”是人，不是动作，“司机前要先看一看旁边”不通。", "变瘦": "体貌：“变瘦”说的是人的体型，与驾驶前的观察无关。"}, "sentence_index": 6, "correct_answer": "变道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里变道，走到了冰箱前。", "explanation": "这里应该用〈移动〉。在厨房里换个位置要说移动；变道是车辆转入相邻车道。"}, {"text": "孩子在操场上变道，躲开了篮球。", "explanation": "这里应该用〈跑〉。在操场上奔跑要说跑；变道是车辆转入相邻车道。"}, {"text": "老人在电梯里变道，让出了位置。", "explanation": "这里应该用〈挪〉。在电梯里挪动位置要说挪；变道是车辆转入相邻车道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89513, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他突然了变道，躲开了前面的坑。", "corrected_sentence": "他突然变了道，躲开了前面的坑。", "error_description": "“了”位置错误：“了”不能放在动词“变道”前面，应说“变了道”或“变道了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89513, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前在这里变道过，知道要早点打灯。", "corrected_sentence": "我们以前在这里变过道，知道要早点打灯。", "error_description": "“过”位置错误：离合词“变道”带“过”时，“过”一般放在“变”和“道”之间，说“变过道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
