INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89514, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "车辆由所在车道转入相邻车道行驶。", "primary_collocate": null, "pronunciation": "biàn dào", "ipa": "pjɛn˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "前面有车，你先别变道。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没打灯就变道了。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时不要随便变道。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出口快到了，我要变道。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他变道太快，差点撞到我。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机看到前面堵车，马上变道。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高速路上变道要看后面的车。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先看后视镜，再变道。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面堵车了，很多人都在变道。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚才变道的时候没看后面。", "target_word": "变道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变了道", "label": "体标（了）"}, {"form": "变过道", "label": "体标（过）"}, {"form": "變道", "label": "繁体"}], "register": "中性", "sense_fingerprint": "车辆从当前车道转入相邻车道行驶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94079a68-bf10-4746-bd88-8d31e031ef14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变道", "is_correct": true, "explanation": "正确。“变道”指转入相邻车道，与“前面有车，你先别”的劝阻语境相符。"}, {"text": "变形", "is_correct": false, "explanation": "语义：“变形”指形体改变，与“前面有车，你先别”的劝阻语境不符。"}, {"text": "变色", "is_correct": false, "explanation": "语义：“变色”指颜色改变，与前面有车、需要谨慎的情境无关。"}, {"text": "变卖", "is_correct": false, "explanation": "语义：“变卖”指把东西卖掉换钱，与“前面有车”的驾驶语境无关。"}], "explanations": {"变道": "正确。“变道”指转入相邻车道，与“前面有车，你先别”的劝阻语境相符。", "变形": "语义：“变形”指形体改变，与“前面有车，你先别”的劝阻语境不符。", "变色": "语义：“变色”指颜色改变，与前面有车、需要谨慎的情境无关。", "变卖": "语义：“变卖”指把东西卖掉换钱，与“前面有车”的驾驶语境无关。"}, "sentence_index": 0, "correct_answer": "变道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下了车，变道走进了商店。", "explanation": "这里应该用〈走〉。人步行进商店要说走，变道是车辆转入相邻车道。"}, {"text": "他在车位里慢慢往后变道，怕撞到后面的车。", "explanation": "这里应该用〈倒车〉。车辆往后退要说倒车，变道是转入相邻车道，不能用来描述后退。"}, {"text": "他在车站变道去市区。", "explanation": "这里应该用〈换车〉。在车站转乘另一辆车要说换车，变道是车辆转入相邻车道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变道", "is_correct": true, "explanation": "正确。“变道”是车辆在高速路上转入相邻车道，转前要看后面的车。"}, {"text": "散步", "is_correct": false, "explanation": "语义：高速路上散步十分危险，与“要看后面的车”的交通语境矛盾。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与车辆行驶无关，与“要看后面的车”不搭。"}, {"text": "变胖", "is_correct": false, "explanation": "体貌：“变胖”说的是人的体型变化，与道路上的行为不相关。"}], "explanations": {"变道": "正确。“变道”是车辆在高速路上转入相邻车道，转前要看后面的车。", "散步": "语义：高速路上散步十分危险，与“要看后面的车”的交通语境矛盾。", "唱歌": "语义：唱歌与车辆行驶无关，与“要看后面的车”不搭。", "变胖": "体貌：“变胖”说的是人的体型变化，与道路上的行为不相关。"}, "sentence_index": 6, "correct_answer": "变道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在人行道上变道，绕过了前面的人。", "explanation": "这里应该用〈走〉。在人行道上从旁边走过、避开别人要说走；变道是车辆转入相邻车道。"}, {"text": "这只猫在树上变道，跳到了另一根树枝。", "explanation": "这里应该用〈爬〉。猫在树上攀爬要说爬；变道是车辆转入相邻车道。"}, {"text": "地铁乘客在车厢里变道，给老人让了座。", "explanation": "这里应该用〈挪〉或〈走〉。车厢里移动要说挪或走；变道是车辆转入相邻车道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚才了变道，没有打灯。", "corrected_sentence": "他刚才变了道，没有打灯。", "error_description": "“了”位置错误：“了”不能放在动词“变道”前面，应说“变了道”或“变道了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们以前变道过。", "corrected_sentence": "他们以前变过道。", "error_description": "“过”位置错误：离合词“变道”带“过”时，“过”一般放在“变”和“道”之间，说“变过道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
