INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89516, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词,用于书册中的一张纸(一面)。", "primary_collocate": null, "pronunciation": "yè", "ipa": "jɛ˥˩", "syllable_count": 1, "sentences": [{"text": "他写了三页日记。", "target_word": "页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本画册的每一页都有一张照片。", "target_word": "页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这页的字太小，我看不清。", "target_word": "页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告一共有二十页。", "target_word": "页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的笔记本已经写了二十页。", "target_word": "页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的第一页有作者的名字。", "target_word": "页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我读了一页书。", "target_word": "页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本相册有三十页，每页都有照片。", "target_word": "页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在最后一页写了一句话。", "target_word": "页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要我们每天抄两页字。", "target_word": "页", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "頁", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用于书册、本子中一张纸或一面的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe847b-453c-49ae-ad59-f1b51c9b852b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89516, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "页", "is_correct": true, "explanation": "正确。页（yè），书册中一张纸或一面，数纸张时用。"}, {"text": "爷", "is_correct": false, "explanation": "页（yè）与爷（yé）声调不同，爷读第二声，意思是爷爷。"}, {"text": "椰", "is_correct": false, "explanation": "页（yè）与椰（yē）声调不同，椰读第一声，意思是椰子。"}, {"text": "饿", "is_correct": false, "explanation": "页（yè）与饿（è）只差前面的 y 音，饿读 è，意思是饥饿。"}], "explanations": {"页": "正确。页（yè），书册中一张纸或一面，数纸张时用。", "爷": "页（yè）与爷（yé）声调不同，爷读第二声，意思是爷爷。", "椰": "页（yè）与椰（yē）声调不同，椰读第一声，意思是椰子。", "饿": "页（yè）与饿（è）只差前面的 y 音，饿读 è，意思是饥饿。"}, "sentence_index": null, "correct_answer": "页"}, "level_3": {"options": [{"text": "页", "is_correct": true, "explanation": "正确。“页”用来数日记的页数。"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗歌或歌曲，日记不能用“首”来数。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄或可握的东西，不用于数日记。"}, {"text": "辆", "is_correct": false, "explanation": "语义：“辆”用于车，日记不是车，不能用“辆”来数。"}], "explanations": {"页": "正确。“页”用来数日记的页数。", "首": "语义：“首”用于诗歌或歌曲，日记不能用“首”来数。", "把": "搭配：“把”用于有柄或可握的东西，不用于数日记。", "辆": "语义：“辆”用于车，日记不是车，不能用“辆”来数。"}, "sentence_index": 0, "correct_answer": "页"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他送了我一页礼物。", "explanation": "这里应该用〈份〉或〈件〉。“页”只用于书册中的纸张，礼物不能用“页”来数。"}, {"text": "这棵树掉了三页。", "explanation": "这里应该说〈叶子〉，并用〈片〉来数。“页”指书册中的纸，不指树叶。"}, {"text": "窗户上有两页玻璃。", "explanation": "这里应该用〈块〉。“页”不能用来数玻璃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89516, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "页", "is_correct": true, "explanation": "正确。页（yè），书册中一张纸或一面，数纸张时用。"}, {"text": "也", "is_correct": false, "explanation": "页（yè）与也（yě）声调不同，也读第三声，意思是“也”。"}, {"text": "乐", "is_correct": false, "explanation": "页（yè）与乐（lè）声母不同，乐读 lè，意思是快乐。"}, {"text": "耶", "is_correct": false, "explanation": "页（yè）与耶（yē）声调不同，耶读第一声，如耶稣。"}], "explanations": {"页": "正确。页（yè），书册中一张纸或一面，数纸张时用。", "也": "页（yè）与也（yě）声调不同，也读第三声，意思是“也”。", "乐": "页（yè）与乐（lè）声母不同，乐读 lè，意思是快乐。", "耶": "页（yè）与耶（yē）声调不同，耶读第一声，如耶稣。"}, "sentence_index": null, "correct_answer": "页"}, "level_3": {"options": [{"text": "页", "is_correct": true, "explanation": "正确。“页”用来数书的页数。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”用于山、建筑等大型固定的东西，书不能用“座”来数。"}, {"text": "颗", "is_correct": false, "explanation": "语义：“颗”用于小而圆的东西，书不能用“颗”来数。"}, {"text": "盏", "is_correct": false, "explanation": "搭配：“盏”用于灯，不用于数书。"}], "explanations": {"页": "正确。“页”用来数书的页数。", "座": "语义：“座”用于山、建筑等大型固定的东西，书不能用“座”来数。", "颗": "语义：“颗”用于小而圆的东西，书不能用“颗”来数。", "盏": "搭配：“盏”用于灯，不用于数书。"}, "sentence_index": 6, "correct_answer": "页"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一页饼干。", "explanation": "这里应该用〈块〉或〈片〉。“页”不能用来数饼干。"}, {"text": "我家有一页椅子。", "explanation": "这里应该用〈把〉。“页”不能用来数椅子。"}, {"text": "我家来了一页客人。", "explanation": "这里应该用〈位〉。“页”不用于数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇作文写了五个页。", "corrected_sentence": "这篇作文写了五页。", "error_description": "“页”前面不能加“个”，应说“这篇作文写了五页”。“个”不能直接与“页”搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天读了页一书。", "corrected_sentence": "我今天读了一页书。", "error_description": "语序错误：量词“页”要放在数词“一”后面、名词“书”前面，应说“一页书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
