INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89517, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "刻意是特别用心，故意这样做。", "primary_collocate": null, "pronunciation": "kè yì", "ipa": "kʰɤ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "他刻意保持安静，不想吵醒孩子。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王刻意避开这个话题。", "target_word": "刻意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刻意把房间收拾得很干净，等客人来。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刻意笑了笑，想让气氛轻松一点。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做菜时，他刻意少放了盐。", "target_word": "刻意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刻意和我保持距离。", "target_word": "刻意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事是作者刻意写成这样的，好让读者去猜。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刻意穿得很正式，因为今天要面试。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刻意放慢脚步，等着她跟上来。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们刻意不看对方，好像不认识。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：故意地、有意识地这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89517, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "刻意", "is_correct": true, "explanation": "正确：刻意，有意识地用心去做某事，即故意、有意地这样做。"}, {"text": "可以", "is_correct": false, "explanation": "两个音节的声调都与“刻意”不同（kě 第三声、yǐ 第三声），意思是“可以”。"}, {"text": "可疑", "is_correct": false, "explanation": "两个音节的声调与“刻意”不同（kě 第三声、yí 第二声），意思是“令人怀疑”。"}, {"text": "课业", "is_correct": false, "explanation": "第一个音节相同，第二个音节的韵母不同（yè 与 yì），意思是“学业、功课”。"}, {"text": "可译", "is_correct": false, "explanation": "第一个音节只有声调不同（kě 第三声与 kè 第四声），第二个音节相同，意思是“可以翻译的”。"}], "explanations": {"刻意": "正确：刻意，有意识地用心去做某事，即故意、有意地这样做。", "可以": "两个音节的声调都与“刻意”不同（kě 第三声、yǐ 第三声），意思是“可以”。", "可疑": "两个音节的声调与“刻意”不同（kě 第三声、yí 第二声），意思是“令人怀疑”。", "课业": "第一个音节相同，第二个音节的韵母不同（yè 与 yì），意思是“学业、功课”。", "可译": "第一个音节只有声调不同（kě 第三声与 kè 第四声），第二个音节相同，意思是“可以翻译的”。"}, "sentence_index": null, "correct_answer": "刻意"}, "level_3": {"options": [{"text": "刻意", "is_correct": true, "explanation": "正确：“刻意”表示有意去做，与“不想吵醒孩子”的意图相合。"}, {"text": "毫不", "is_correct": false, "explanation": "语义：“毫不”表示完全不，与“不想吵醒孩子”的意图矛盾。"}, {"text": "尽情", "is_correct": false, "explanation": "搭配：“尽情”多用于尽兴地做某事，不能与“保持安静”搭配。"}, {"text": "乱", "is_correct": false, "explanation": "搭配：“乱”多修饰“乱说”“乱动”这类行为，不能与“保持安静”搭配。"}], "explanations": {"刻意": "正确：“刻意”表示有意去做，与“不想吵醒孩子”的意图相合。", "毫不": "语义：“毫不”表示完全不，与“不想吵醒孩子”的意图矛盾。", "尽情": "搭配：“尽情”多用于尽兴地做某事，不能与“保持安静”搭配。", "乱": "搭配：“乱”多修饰“乱说”“乱动”这类行为，不能与“保持安静”搭配。"}, "sentence_index": 0, "correct_answer": "刻意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刻意很累，一直靠在椅子上不动。", "explanation": "“刻意”修饰有意识的行为，“很累”是身体的感受，不能刻意做到；应说“他故意装得很累”。"}, {"text": "他刻意拾到了一张旧照片。", "explanation": "这里“刻意”被误用为〈偶然〉的意思：“拾到”是偶然得到的结果，不能刻意完成。"}, {"text": "我刻意听见了远处的敲门声。", "explanation": "这里“刻意”被误用为〈无意〉的意思：“听见”是无意中产生的结果，不能刻意完成；要表达有意去听，应说“刻意去听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刻意", "is_correct": true, "explanation": "正确：“刻意”表示有意去做，与“作者有意写成这样”的安排相合。"}, {"text": "恰巧", "is_correct": false, "explanation": "语义：“恰巧”表示碰巧，与“作者有意写成这样”的安排矛盾。"}, {"text": "随口", "is_correct": false, "explanation": "搭配：“随口”多修饰说话，不能修饰“写成”这类有计划的创作。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”表示没有计划，与“作者有意写成这样”的安排矛盾。"}], "explanations": {"刻意": "正确：“刻意”表示有意去做，与“作者有意写成这样”的安排相合。", "恰巧": "语义：“恰巧”表示碰巧，与“作者有意写成这样”的安排矛盾。", "随口": "搭配：“随口”多修饰说话，不能修饰“写成”这类有计划的创作。", "偶然": "语义：“偶然”表示没有计划，与“作者有意写成这样”的安排矛盾。"}, "sentence_index": 6, "correct_answer": "刻意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她刻意在不知不觉中把杯子打碎了。", "explanation": "这里“刻意”被误用为〈无意〉的意思：“刻意”是有意识地去做，而“不知不觉”表示没有意识，二者矛盾。"}, {"text": "我刻意梦见了小时候的老房子。", "explanation": "这里“刻意”被误用为〈不由自主〉的意思：“梦见”是睡眠中自然出现的情景，不能刻意做到。"}, {"text": "我刻意在一夜之间白了头发。", "explanation": "“白头发”是自然出现的变化，不能刻意在一夜之间做到；这里“刻意”被误用为〈不由自主〉的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹刻意了把书放在最上面，好让我一眼看见。", "corrected_sentence": "妹妹刻意把书放在最上面，好让我一眼看见。", "error_description": "“刻意”是副词，后面不能直接加动态助词“了”；这里的“了”应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板刻意了避开这个问题，大家都注意到了。", "corrected_sentence": "老板刻意避开这个问题，大家都注意到了。", "error_description": "“刻意”是副词，后面不能直接加动态助词“了”；这里的“了”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
