INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89518, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89518, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用尽心思，特意。", "primary_collocate": null, "pronunciation": "kè yì", "ipa": "kʰɤ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "她刻意打扮了一下，想给大家留下好印象。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刻意早到半小时，想先看看会场。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师刻意放慢语速，让大家听清楚。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刻意不提这件事，怕他难过。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片不是刻意拍的，只是碰巧拍到了。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刻意躲开我，我很快就发现了。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让孩子睡好，妈妈刻意把灯关了。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话时刻意压低了声音。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刻意穿了一件红衣服，好让朋友一眼找到他。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有刻意学，只是听多了就会说了。", "target_word": "刻意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：特意地用心去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89518, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "刻意", "is_correct": true, "explanation": "正确：刻意，有意识地用心去做某事，即特意、故意。"}, {"text": "可以", "is_correct": false, "explanation": "两个音节的声调都与“刻意”不同（kě 第三声、yǐ 第三声），意思是“可以”。"}, {"text": "可疑", "is_correct": false, "explanation": "两个音节的声调与“刻意”不同（kě 第三声、yí 第二声），意思是“令人怀疑”。"}, {"text": "课业", "is_correct": false, "explanation": "第一个音节相同，第二个音节的韵母不同（yè 与 yì），意思是“学业、功课”。"}, {"text": "可译", "is_correct": false, "explanation": "第一个音节只有声调不同（kě 第三声与 kè 第四声），第二个音节相同，意思是“可以翻译的”。"}], "explanations": {"刻意": "正确：刻意，有意识地用心去做某事，即特意、故意。", "可以": "两个音节的声调都与“刻意”不同（kě 第三声、yǐ 第三声），意思是“可以”。", "可疑": "两个音节的声调与“刻意”不同（kě 第三声、yí 第二声），意思是“令人怀疑”。", "课业": "第一个音节相同，第二个音节的韵母不同（yè 与 yì），意思是“学业、功课”。", "可译": "第一个音节只有声调不同（kě 第三声与 kè 第四声），第二个音节相同，意思是“可以翻译的”。"}, "sentence_index": null, "correct_answer": "刻意"}, "level_3": {"options": [{"text": "刻意", "is_correct": true, "explanation": "正确：“刻意”表示有意用心，与“想给大家留下好印象”的意图相合。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示一直没有这样做过，与“打扮了一下”这种一次性的动作矛盾。"}, {"text": "无意", "is_correct": false, "explanation": "语义：“无意”表示没有故意，与“想给大家留下好印象”的目的矛盾。"}, {"text": "一概", "is_correct": false, "explanation": "搭配：“一概”多与“不”“没”等否定词连用，不能与“打扮了一下”这样的肯定动作搭配。"}], "explanations": {"刻意": "正确：“刻意”表示有意用心，与“想给大家留下好印象”的意图相合。", "从不": "语义：“从不”表示一直没有这样做过，与“打扮了一下”这种一次性的动作矛盾。", "无意": "语义：“无意”表示没有故意，与“想给大家留下好印象”的目的矛盾。", "一概": "搭配：“一概”多与“不”“没”等否定词连用，不能与“打扮了一下”这样的肯定动作搭配。"}, "sentence_index": 0, "correct_answer": "刻意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她刻意很伤心，眼泪一直往下流。", "explanation": "“刻意”修饰有意识的行为，“伤心”是内心感受，不能刻意做到；应说“她故意装得很伤心”。"}, {"text": "我刻意捡到了一百块钱，高兴极了。", "explanation": "“刻意”表示有意识地去做，“捡到”是偶然得到的结果，不能刻意完成；这里被误用为〈偶然〉的意思。"}, {"text": "我刻意看见了一只飞过的鸟。", "explanation": "这里“刻意”被误用为〈无意〉的意思：“看见”是无意中产生的结果，不能刻意完成；要表达有意去看，应说“刻意去看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刻意", "is_correct": true, "explanation": "正确：“刻意”表示有意去做，与“为了让孩子睡好”的目的相合。"}, {"text": "无意", "is_correct": false, "explanation": "语义：“无意”表示没有故意，与“为了让孩子睡好”这一明确目的矛盾。"}, {"text": "随口", "is_correct": false, "explanation": "搭配：“随口”多修饰说话，不能修饰“把灯关了”这类有目的的动作。"}, {"text": "碰巧", "is_correct": false, "explanation": "语义：“碰巧”表示偶然、没有计划，与“为了让孩子睡好”这一明确目的矛盾。"}], "explanations": {"刻意": "正确：“刻意”表示有意去做，与“为了让孩子睡好”的目的相合。", "无意": "语义：“无意”表示没有故意，与“为了让孩子睡好”这一明确目的矛盾。", "随口": "搭配：“随口”多修饰说话，不能修饰“把灯关了”这类有目的的动作。", "碰巧": "语义：“碰巧”表示偶然、没有计划，与“为了让孩子睡好”这一明确目的矛盾。"}, "sentence_index": 6, "correct_answer": "刻意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刻意不知不觉地走出了房间，我完全没有察觉。", "explanation": "这里“刻意”被误用为〈无意〉的意思：“刻意”表示有意识地去做，“不知不觉”表示没有意识，二者矛盾。"}, {"text": "我刻意梦见了已经去世的爷爷。", "explanation": "这里“刻意”被误用为〈不由自主〉的意思：“梦见”是睡眠中自然出现的情景，“刻意”表示有意识地去做，二者矛盾。"}, {"text": "他刻意一夜之间长高了十厘米。", "explanation": "“长高”是身体自然生长的结果，不能刻意做到，更不可能在一夜之间完成；这里“刻意”被误用为〈不由自主〉的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刻意了绕开那条路，怕遇到熟人。", "corrected_sentence": "他刻意绕开那条路，怕遇到熟人。", "error_description": "“刻意”是副词，后面不能直接加动态助词“了”；这里的“了”应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刻意了避开我，不想让我尴尬。", "corrected_sentence": "他刻意避开我，不想让我尴尬。", "error_description": "“刻意”是副词，后面不能直接加动态助词“了”；这里的“了”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
