INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89519, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "起手是开始动手做一件事。", "primary_collocate": null, "pronunciation": "qǐ shǒu", "ipa": "tɕʰi˨˩ ʂoʊ˨˩", "syllable_count": 2, "sentences": [{"text": "这件事太多了，我不知道从哪里起手。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先起手做，我马上来帮你。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一起手就做得很快。", "target_word": "起手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子这么乱，该从哪儿起手呢？", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿起笔，起手写信。", "target_word": "起手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作太大，大家不知从何起手。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事一起手，就得坚持做到底。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭要从洗菜起手。", "target_word": "起手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你先起手，我们再慢慢商量。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他起手修车，一个小时就好了。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起了手", "label": "体标"}], "register": "口语", "sense_fingerprint": "开始动手做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed153e7-0a2c-4ca6-9ac2-d5bcdbc4229a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89519, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起手", "is_correct": true, "explanation": "起手指开始动手做事，与“不知道从哪里做”的语境相符。"}, {"text": "下班", "is_correct": false, "explanation": "语义：下班指结束工作，与“不知道从哪里开始”的语境相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“这件事太多了”需要决定的处理顺序无关，句意不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“从哪里”后接“吃饭”不通，且与“这件事太多了”的语境不合。"}], "explanations": {"起手": "起手指开始动手做事，与“不知道从哪里做”的语境相符。", "下班": "语义：下班指结束工作，与“不知道从哪里开始”的语境相反。", "睡觉": "语义：睡觉与“这件事太多了”需要决定的处理顺序无关，句意不通。", "吃饭": "搭配：“从哪里”后接“吃饭”不通，且与“这件事太多了”的语境不合。"}, "sentence_index": 0, "correct_answer": "起手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他觉得太危险，于是起手了。", "explanation": "这里应该用〈收手〉。收手指停止、罢手，与起手“开始动手”的意思相反，句意自相矛盾。"}, {"text": "快起手，别再打了！", "explanation": "这里应该用〈住手〉。住手表示停止动作，起手表示开始动手，与“别再打了”矛盾。"}, {"text": "他见大家都反对，就起手不干了。", "explanation": "这里应该用〈罢手〉。罢手指停止，起手指开始动手，与“不干了”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89519, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起手", "is_correct": true, "explanation": "起手指开始动手做事，与“坚持做到底”的前提相符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃与“就得坚持做到底”的要求直接矛盾。"}, {"text": "停止", "is_correct": false, "explanation": "语义：停止与“就得坚持做到底”的要求相矛盾。"}, {"text": "结束", "is_correct": false, "explanation": "搭配：“一结束，就得坚持做到底”搭配不通，事情结束后不存在继续坚持的对象。"}], "explanations": {"起手": "起手指开始动手做事，与“坚持做到底”的前提相符。", "放弃": "语义：放弃与“就得坚持做到底”的要求直接矛盾。", "停止": "语义：停止与“就得坚持做到底”的要求相矛盾。", "结束": "搭配：“一结束，就得坚持做到底”搭配不通，事情结束后不存在继续坚持的对象。"}, "sentence_index": 6, "correct_answer": "起手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器一按按钮就起手运转。", "explanation": "这里应该用〈启动〉。起手指人开始动手做事，不用于机器。"}, {"text": "他从椅子上起手，走出了教室。", "explanation": "这里应该用〈起身〉。起手指开始动手做事，不表示从座位上站起。"}, {"text": "他每天七点起手，吃完早饭就出门。", "explanation": "这里应该用〈起床〉。起手指开始动手做事，不表示从床上起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一起手就停不住来。", "corrected_sentence": "他一起手就停不下来。", "error_description": "趋向补语错误：“停不住”后不能接“来”，应说“停不下来”，把“住”改为“下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这活儿他一起手了，就不肯停下来。", "corrected_sentence": "这活儿他一起手，就不肯停下来。", "error_description": "体标误用：在“一……就……”结构中，“起手”后面不加“了”。应说“一起手，就不肯停下来”，不能说“一起手了，就……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
