INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "下棋、武术等活动的开头动作。", "primary_collocate": null, "pronunciation": "qǐ shǒu", "ipa": "tɕʰi˨˩ ʂoʊ˨˩", "syllable_count": 2, "sentences": [{"text": "下棋时，他的起手很特别。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套拳的起手是一个抱拳礼。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们打太极拳时先练起手。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的起手是中炮，攻击性很强。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起手要慢，后面才能快。", "target_word": "起手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位师傅的起手很稳。", "target_word": "起手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛开始，他的起手很大胆。", "target_word": "起手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学武术先要练好起手。", "target_word": "起手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的起手能让你在棋局中占先。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的起手太慢，被我躲开了。", "target_word": "起手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起手式", "label": "复合"}], "register": "口语", "sense_fingerprint": "下棋、武术等的开头动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed153e7-0a2c-4ca6-9ac2-d5bcdbc4229a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起手", "is_correct": true, "explanation": "起手指下棋或武术的开头动作，与“下棋时，他的……很特别”的语境相符。"}, {"text": "拳法", "is_correct": false, "explanation": "语义：拳法属于武术，与“下棋时”的情境不符。"}, {"text": "拳头", "is_correct": false, "explanation": "语义：拳头与下棋无关，“下棋时，他的拳头很特别”句意不通。"}, {"text": "步伐", "is_correct": false, "explanation": "搭配：“步伐”指走路或舞蹈的动作，不与“下棋”搭配。"}], "explanations": {"起手": "起手指下棋或武术的开头动作，与“下棋时，他的……很特别”的语境相符。", "拳法": "语义：拳法属于武术，与“下棋时”的情境不符。", "拳头": "语义：拳头与下棋无关，“下棋时，他的拳头很特别”句意不通。", "步伐": "搭配：“步伐”指走路或舞蹈的动作，不与“下棋”搭配。"}, "sentence_index": 0, "correct_answer": "起手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套拳的收尾动作正是起手，很有气势。", "explanation": "这里应该用〈收势〉。收势指武术收尾的动作，起手指开头动作，“收尾动作正是起手”自相矛盾。"}, {"text": "这盘棋已经终局，双方都在起手。", "explanation": "这里应该用〈收官〉。起手指下棋的开局走法，不指终局阶段。"}, {"text": "他练完整套拳，才起手抱拳行礼。", "explanation": "这里应该用〈收功〉。收功指练完后的收式，起手指开头动作，“练完才起手”自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起手", "is_correct": true, "explanation": "起手指比赛开局的开头动作，“他的起手很大胆”符合“比赛开始”的语境。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘是器物，不能说“棋盘很大胆”。"}, {"text": "观众", "is_correct": false, "explanation": "语义：“他的观众很大胆”与“比赛开始”时的动作无关，句意不通。"}, {"text": "奖杯", "is_correct": false, "explanation": "语义：奖杯是物品，比赛刚开始也没有奖杯，“奖杯很大胆”不通。"}], "explanations": {"起手": "起手指比赛开局的开头动作，“他的起手很大胆”符合“比赛开始”的语境。", "棋盘": "语义：棋盘是器物，不能说“棋盘很大胆”。", "观众": "语义：“他的观众很大胆”与“比赛开始”时的动作无关，句意不通。", "奖杯": "语义：奖杯是物品，比赛刚开始也没有奖杯，“奖杯很大胆”不通。"}, "sentence_index": 6, "correct_answer": "起手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盘棋的最后一步是他的起手，一子定胜负。", "explanation": "这里应该用〈收官〉。起手指开局的第一步，不指棋局最后阶段。"}, {"text": "这套拳的最后一个动作叫起手。", "explanation": "这里应该用〈收势〉。收势是武术收尾的动作，起手是开头动作。"}, {"text": "他的起手是一把很长的剑。", "explanation": "这里应该用〈兵器〉。起手指开头的动作，不指器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的这只起手很妙。", "corrected_sentence": "他的这步起手很妙。", "error_description": "量词错误：“起手”指下棋或武术的开头动作，应用“步”来数，不能用“只”。“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师让我先起手练熟。", "corrected_sentence": "老师让我先把起手练熟。", "error_description": "处置式漏用“把”：“练熟”要求把“起手”作为处置对象，应说“先把起手练熟”，不能省略“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
