INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89521, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "显然是很容易就看得出来。", "primary_collocate": null, "pronunciation": "xiǎn rán", "ipa": "ɕjɛn˨˩˦ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "事情已经很显然了。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个道理很显然，不用多解释。", "target_word": "显然", "complexity_tier": "T3", "furigana": "zhè ge dào lǐ hěn xiǎn rán, bú yòng duō jiě shì", "sentence_source": "generated"}, {"text": "这一点很显然，他是想帮我们。", "target_word": "显然", "complexity_tier": "T3", "furigana": "zhè yì diǎn hěn xiǎn rán, tā shì xiǎng bāng wǒ men", "sentence_source": "generated"}, {"text": "他的错误十分显然。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结果很显然,我们赢了。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题的答案很显然。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的意思再显然不过了。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的理由很显然站不住。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "答案已经很显然了，大家都知道。", "target_word": "显然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上写着要往左走，这一点很显然。", "target_word": "显然", "complexity_tier": "T3", "furigana": "dì tú shàng xiě zhe yào wǎng zuǒ zǒu, zhè yì diǎn hěn xiǎn rán", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情一看就明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b6d23d-90ac-4dc8-9c4e-4b812c474339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "显然", "is_correct": true, "explanation": "「显然」表示情况已经很明白，与「事情已经很……了」搭配，句意通顺。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：「安静」描述环境或人的状态，「事情」不能安静。"}, {"text": "饿", "is_correct": false, "explanation": "语义：「饿」指想吃东西的感觉，与「事情」的情况无关，句子不通。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：「胖」描述人或动物的体形，不能用来形容「事情」。"}], "explanations": {"显然": "「显然」表示情况已经很明白，与「事情已经很……了」搭配，句意通顺。", "安静": "搭配：「安静」描述环境或人的状态，「事情」不能安静。", "饿": "语义：「饿」指想吃东西的感觉，与「事情」的情况无关，句子不通。", "胖": "体貌：「胖」描述人或动物的体形，不能用来形容「事情」。"}, "sentence_index": 0, "correct_answer": "显然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的想法十分显然，我很难猜到。", "explanation": "这里应该用〈含蓄〉。「显然」指很容易看出来，与「很难猜到」的意思相反，表示不易看出应用「含蓄」。"}, {"text": "请你把他的错误十分显然地说出来。", "explanation": "这里应该用〈清楚地〉。「显然」不作方式状语，描述说的方式应用「清楚地」。"}, {"text": "他的错误十分显然，我却还是不确定。", "explanation": "这里应该用〈隐晦〉。「显然」指很容易看出来，与「还是不确定」矛盾，不易看出的情况应说「隐晦」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "显然", "is_correct": true, "explanation": "「显然」表示明显，与「他的意思再……不过了」搭配，句意通顺。"}, {"text": "幸福", "is_correct": false, "explanation": "搭配：「幸福」描述人的感受，「意思」不能幸福。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：「矮」描述人或物的高度，不能用来形容「意思」。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：「辣」描述食物的味道，不能用来形容「意思」。"}], "explanations": {"显然": "「显然」表示明显，与「他的意思再……不过了」搭配，句意通顺。", "幸福": "搭配：「幸福」描述人的感受，「意思」不能幸福。", "矮": "体貌：「矮」描述人或物的高度，不能用来形容「意思」。", "辣": "搭配：「辣」描述食物的味道，不能用来形容「意思」。"}, "sentence_index": 6, "correct_answer": "显然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地图上写着要往左走，这一点显然很难看出来。", "explanation": "这里应该用〈隐蔽〉。「显然」表示很容易看出来，与「很难看出来」的意思相反。"}, {"text": "地图上写着要往左走，但这一点我显然看不出来。", "explanation": "这里应该用〈始终〉。「显然」表示很容易看出来，与「看不出来」矛盾；应说「始终」，表示一直如此。"}, {"text": "地图上写着要往左走，但是这一点显然不明显。", "explanation": "这里应该用〈模糊〉。「显然」指很容易看出，与「不明显」自相矛盾，表示不清楚应用「模糊」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个道理是很显然。", "corrected_sentence": "这个道理是很显然的。", "error_description": "错误：用「是」强调「很显然」时要构成「是……的」，句末缺少「的」，应说「是很显然的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的心意很显然不过了。", "corrected_sentence": "她的心意再显然不过了。", "error_description": "错误：「……不过了」格式要用「再」，应说「再显然不过了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
