INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89523, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89523, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "加总是把几个数加在一起，得出总共有多少。", "primary_collocate": null, "pronunciation": "jiā zǒng", "ipa": "tɕi̯a˥ tsʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "请把这几个数加总，看看一共是多少。", "target_word": "加总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把三天的分数加总，得到了二百分。", "target_word": "加总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先加总每个人的票数。", "target_word": "加总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让学生把这些数字加总起来。", "target_word": "加总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加总以后，总数是一百五十。", "target_word": "加总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你加总过这一列数字吗？", "target_word": "加总", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这五个数加总一下，一共是二十。", "target_word": "加总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他算得很快，一下子就加总好了。", "target_word": "加总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先加总男生的人数，再加总女生的人数。", "target_word": "加总", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子正在用手指加总两个数。", "target_word": "加总", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "加总了", "label": "体标"}, {"form": "加总过", "label": "体标"}, {"form": "加總", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把几个数字加在一起，算出总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd548b280-89df-4fe8-9d81-fedf7fde6e45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排列", "is_correct": false, "explanation": "搭配：“排列”说的是次序，不能用来求总数。"}, {"text": "加总", "is_correct": true, "explanation": "正确：“加总”表示把几个数加在一起求总数，与“看看一共是多少”相合。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”表示使分离，与后面“看看一共是多少”要求的合计意思冲突。"}, {"text": "减去", "is_correct": false, "explanation": "语义：“减去”表示从总数中扣除，与句子要求的求和方向相反，不能用来求“一共是多少”。"}], "explanations": {"排列": "搭配：“排列”说的是次序，不能用来求总数。", "加总": "正确：“加总”表示把几个数加在一起求总数，与“看看一共是多少”相合。", "分开": "语义：“分开”表示使分离，与后面“看看一共是多少”要求的合计意思冲突。", "减去": "语义：“减去”表示从总数中扣除，与句子要求的求和方向相反，不能用来求“一共是多少”。"}, "sentence_index": 0, "correct_answer": "加总"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让学生把两篇作文加总起来。", "explanation": "这里应该用〈合并〉。加总是把数字相加求和，两篇作文不是数，应说合并两篇作文。"}, {"text": "这个月我的体重加总了三公斤。", "explanation": "这里应该用〈增加〉。加总表示把数量相加求和，说体重变多要用增加，体重也不能加总。"}, {"text": "雨水在池子里慢慢加总起来。", "explanation": "这里应该用〈累积〉。加总只用于数字的求和，雨水逐渐聚集要用累积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切割", "is_correct": false, "explanation": "搭配：“切割”的对象是实物，不能用于“这五个数”的求和。"}, {"text": "加总", "is_correct": true, "explanation": "正确：“加总”表示把五个数相加，得到一共二十，与句子相合。"}, {"text": "抽烟", "is_correct": false, "explanation": "配价：“抽烟”是动宾结构，已带宾语“烟”，不能再处理“这五个数”。"}, {"text": "问候", "is_correct": false, "explanation": "搭配：“问候”的对象是人，不能用于“这五个数”。"}], "explanations": {"切割": "搭配：“切割”的对象是实物，不能用于“这五个数”的求和。", "加总": "正确：“加总”表示把五个数相加，得到一共二十，与句子相合。", "抽烟": "配价：“抽烟”是动宾结构，已带宾语“烟”，不能再处理“这五个数”。", "问候": "搭配：“问候”的对象是人，不能用于“这五个数”。"}, "sentence_index": 6, "correct_answer": "加总"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教练每天加总运动员的体能。", "explanation": "这里应该用〈训练〉。加总是把数字相加求和，体能不是数，锻炼体能要用训练。"}, {"text": "我们在假期加总了美好的时光。", "explanation": "这里应该用〈享受〉。加总只用于数量的合计，度过美好时光要用享受。"}, {"text": "他终于加总了大家的信任。", "explanation": "这里应该用〈赢得〉。加总指把数字相加求总和，信任不是数，赢得信任要用赢得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会计把这些账单加总出去。", "corrected_sentence": "会计把这些账单加总起来。", "error_description": "“加总”后的趋向补语用错了：应说“加总起来”，“出去”不能表示把几项数字合并求总数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很快就把全部发票的金额加总去了。", "corrected_sentence": "她很快就把全部发票的金额加总好了。", "error_description": "“加总”后的结果补语用错了：应说“加总好”，“去”不能表示加总完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89525, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89525, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "车带是车轮里面装气的圆圈。", "primary_collocate": null, "pronunciation": "chē dài", "ipa": "tʂʰɤ⁵⁵ taɪ⁵¹", "syllable_count": 2, "sentences": [{"text": "钉子扎破了自行车的车带，漏气了。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给车带打了点儿气。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车带里的气太足，容易爆。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅正在补车带上的小洞。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条车带用了三年，该换了。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车带拿出来了。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车带没气了，车骑不动。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车带放进水里，冒出了小气泡。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩把旧车带当成游泳圈玩。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里新买的车带又黑又软。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "口语", "sense_fingerprint": "车轮里面装气的圆圈，即内胎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a716b1e6-c5ce-40f3-a6a3-7a805e3ea816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89525, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "车带", "is_correct": true, "explanation": "正确。车带指车轮里面装气的圆圈，即内胎。"}, {"text": "车道", "is_correct": false, "explanation": "dào（第四声）与 dài 韵母不同（ao / ai），意思是车道，即车辆行驶的路线。"}, {"text": "车载", "is_correct": false, "explanation": "zài 与 dài 声母不同（z / d），意思是装在车上的，如车载导航。"}, {"text": "车盖", "is_correct": false, "explanation": "gài 与 dài 声母不同（g / d），意思是车的盖子。"}, {"text": "车队", "is_correct": false, "explanation": "duì 与 dài 韵母不同（uei / ai），意思是一队车辆。"}], "explanations": {"车带": "正确。车带指车轮里面装气的圆圈，即内胎。", "车道": "dào（第四声）与 dài 韵母不同（ao / ai），意思是车道，即车辆行驶的路线。", "车载": "zài 与 dài 声母不同（z / d），意思是装在车上的，如车载导航。", "车盖": "gài 与 dài 声母不同（g / d），意思是车的盖子。", "车队": "duì 与 dài 韵母不同（uei / ai），意思是一队车辆。"}, "sentence_index": null, "correct_answer": "车带"}, "level_3": {"options": [{"text": "车带", "is_correct": true, "explanation": "正确。车带是装气的圆圈，扎破后会漏气。"}, {"text": "车铃", "is_correct": false, "explanation": "语义：车铃是发声的部件，不装气，与“扎破”“漏气”矛盾。"}, {"text": "车灯", "is_correct": false, "explanation": "语义：车灯是发光的部件，不存在漏气的问题，与“漏气”矛盾。"}, {"text": "车把", "is_correct": false, "explanation": "搭配：“扎破”和“漏气”只用于充了气的东西，不说扎破车把。"}], "explanations": {"车带": "正确。车带是装气的圆圈，扎破后会漏气。", "车铃": "语义：车铃是发声的部件，不装气，与“扎破”“漏气”矛盾。", "车灯": "语义：车灯是发光的部件，不存在漏气的问题，与“漏气”矛盾。", "车把": "搭配：“扎破”和“漏气”只用于充了气的东西，不说扎破车把。"}, "sentence_index": 0, "correct_answer": "车带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨天，车带能挡住轮子甩起来的泥水。", "explanation": "这里应该用〈挡泥板〉。车带在轮胎里面，挡不住泥水。"}, {"text": "车带上装着一个小灯，晚上很亮。", "explanation": "这里应该用〈车把〉。车带是轮胎里装气的圆圈，上面不能装灯。"}, {"text": "他系上了车带，裤子就不会掉了。", "explanation": "这里应该用〈皮带〉。车带是轮胎里的橡胶管，不是用来系裤子的腰带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车带", "is_correct": true, "explanation": "正确。车带是装气的圆圈，没气了车就骑不动。"}, {"text": "车闸", "is_correct": false, "explanation": "语义：车闸是用来刹车的，不装气，不会“没气”。"}, {"text": "车链", "is_correct": false, "explanation": "搭配：“没气”只用于充了气的东西，不说车链没气。"}, {"text": "车座", "is_correct": false, "explanation": "语义：车座是坐垫，不装气，与“没气”矛盾。"}], "explanations": {"车带": "正确。车带是装气的圆圈，没气了车就骑不动。", "车闸": "语义：车闸是用来刹车的，不装气，不会“没气”。", "车链": "搭配：“没气”只用于充了气的东西，不说车链没气。", "车座": "语义：车座是坐垫，不装气，与“没气”矛盾。"}, "sentence_index": 6, "correct_answer": "车带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按了一下车带，前面的人就让开了。", "explanation": "这里应该用〈车铃〉。车带是装气的圆圈，按了不会响。"}, {"text": "把车带接到水龙头上，就能浇花了。", "explanation": "这里应该用〈水管〉。车带是充气的橡胶圈，不能用来输水。"}, {"text": "他戴上了车带，准备出门。", "explanation": "这里应该用〈手套〉。车带是轮胎里的管子，不能戴在手上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只车带。", "corrected_sentence": "我买了一条车带。", "error_description": "量词错误：车带应该用量词“条”，不能用“只”。正确的说法是“一条车带”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给车带充了电。", "corrected_sentence": "他给车带充了气。", "error_description": "搭配错误：车带是充气的橡胶管，应与“充气”搭配，不能说“充电”。正确的说法是“他给车带充了气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
