INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自行车或汽车轮胎里面充气的橡胶管。", "primary_collocate": null, "pronunciation": "chē dài", "ipa": "tʂʰɤ⁵⁵ taɪ⁵¹", "syllable_count": 2, "sentences": [{"text": "汽车的车带坏了，只能换新的。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根车带是橡胶做的，很有弹性。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路边的修车铺买了一条车带。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钉子扎穿了轮胎和车带。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摩托车的车带也要定期检查。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把新车带装进了轮胎里。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条车带太小，装不进大轮胎。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车带破了，他只好推着车走。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车的车带又粗又厚。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在车带上贴了一块胶皮。", "target_word": "车带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "口语", "sense_fingerprint": "自行车或汽车轮胎里面充气的橡胶管", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a716b1e6-c5ce-40f3-a6a3-7a805e3ea816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89526, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "车带", "is_correct": true, "explanation": "正确。车带指自行车或汽车轮胎里面充气的橡胶管。"}, {"text": "车道", "is_correct": false, "explanation": "dào（第四声）与 dài 韵母不同（ao / ai），意思是车道，即车辆行驶的路线。"}, {"text": "车载", "is_correct": false, "explanation": "zài 与 dài 声母不同（z / d），意思是装在车上的，如车载导航。"}, {"text": "车盖", "is_correct": false, "explanation": "gài 与 dài 声母不同（g / d），意思是车的盖子。"}, {"text": "车队", "is_correct": false, "explanation": "duì 与 dài 韵母不同（uei / ai），意思是一队车辆。"}], "explanations": {"车带": "正确。车带指自行车或汽车轮胎里面充气的橡胶管。", "车道": "dào（第四声）与 dài 韵母不同（ao / ai），意思是车道，即车辆行驶的路线。", "车载": "zài 与 dài 声母不同（z / d），意思是装在车上的，如车载导航。", "车盖": "gài 与 dài 声母不同（g / d），意思是车的盖子。", "车队": "duì 与 dài 韵母不同（uei / ai），意思是一队车辆。"}, "sentence_index": null, "correct_answer": "车带"}, "level_3": {"options": [{"text": "车带", "is_correct": true, "explanation": "正确。汽车轮胎里的车带坏了，只能换新的。"}, {"text": "车速", "is_correct": false, "explanation": "搭配：“坏了”一般用于部件，不说车速坏了。"}, {"text": "车龄", "is_correct": false, "explanation": "语义：车龄指车辆使用的年限，不是会坏的部件。"}, {"text": "车费", "is_correct": false, "explanation": "语义：车费是乘车的钱，不是车的部件，不会“坏了”。"}], "explanations": {"车带": "正确。汽车轮胎里的车带坏了，只能换新的。", "车速": "搭配：“坏了”一般用于部件，不说车速坏了。", "车龄": "语义：车龄指车辆使用的年限，不是会坏的部件。", "车费": "语义：车费是乘车的钱，不是车的部件，不会“坏了”。"}, "sentence_index": 0, "correct_answer": "车带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把车带夹在耳朵上听音乐。", "explanation": "这里应该用〈耳机〉。车带是轮胎里的充气橡胶管，不能用来听音乐。"}, {"text": "他用车带在纸上写字。", "explanation": "这里应该用〈铅笔〉。车带是轮胎里的橡胶管，不能用来写字。"}, {"text": "他把车带系在腰上，裤子就不会掉了。", "explanation": "这里应该用〈皮带〉。车带是轮胎里的橡胶管，不是用来系在腰上的腰带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车带", "is_correct": true, "explanation": "正确。这条车带太小，装不进大轮胎。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是天然的水体，不能装进轮胎，与语境矛盾。"}, {"text": "项链", "is_correct": false, "explanation": "语义：项链是首饰，不可能装进轮胎，与“装不进大轮胎”的语境矛盾。"}, {"text": "公路", "is_correct": false, "explanation": "搭配：“装进”不搭配公路，公路是道路，不能被装进东西。"}], "explanations": {"车带": "正确。这条车带太小，装不进大轮胎。", "河流": "语义：河流是天然的水体，不能装进轮胎，与语境矛盾。", "项链": "语义：项链是首饰，不可能装进轮胎，与“装不进大轮胎”的语境矛盾。", "公路": "搭配：“装进”不搭配公路，公路是道路，不能被装进东西。"}, "sentence_index": 6, "correct_answer": "车带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根车带漏水了，得换新的。", "explanation": "这里应该用〈水管〉。车带是充气的橡胶管，装的是气，不装水，所以漏的是气，不说漏水。"}, {"text": "医生用车带给孩子量体温。", "explanation": "这里应该用〈体温计〉。车带是轮胎里的充气橡胶管，不能量体温。"}, {"text": "这个孩子戴上了车带当手镯。", "explanation": "这里应该用〈首饰〉。车带是轮胎里的橡胶管，不是首饰，不能戴在身上当装饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一只旧车带。", "corrected_sentence": "他买了一条旧车带。", "error_description": "量词错误：车带应该用量词“条”，不用“只”。正确的说法是“一条旧车带”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车带破了，他又买了两张新车带。", "corrected_sentence": "车带破了，他又买了两条新车带。", "error_description": "量词错误：车带是长条形的东西，用量词“条”，不用“张”。正确的说法是“两条新车带”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
