INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89527, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "下一个是排在后面,紧接着的那一个。", "primary_collocate": null, "pronunciation": "xià yí gè", "ipa": "ɕja˥˩ i˧˥ kɤ˥˩", "syllable_count": 3, "sentences": [{"text": "前面的人走了,下一个是你。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我唱完了,下一个轮到谁?", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说:“下一个请进来。”", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我会了,下一个是什么?", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天只有三个人,你是下一个。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚做完,下一个该我了。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹跳完舞,下一个是哥哥。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排队的时候,我看了看下一个是谁。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏我玩完了,让下一个玩吧。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师叫完我的名字,下一个就是小明。", "target_word": "下一个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下一位", "label": "复合"}, {"form": "上一个", "label": "复合"}, {"form": "下一個", "label": "繁体"}], "register": "口语", "sense_fingerprint": "下一个:紧接着的那个人或事物(单独指代)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb4c8f47-f9b5-4427-b6c0-3ded0add6b63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89527, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下一个", "is_correct": true, "explanation": "下一个：紧接着的那个人，即排在后面轮到的人。"}, {"text": "前一个", "is_correct": false, "explanation": "语义：“前一个”指已经走了的那位，与“排在后面”的意思相反。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话人本人，不能表示排在后面的那一位，“自己是你”说不通。"}, {"text": "谁", "is_correct": false, "explanation": "配价：“谁”是疑问代词，陈述句中“谁是你”不成立，且与“前面的人走了”的语境不符。"}], "explanations": {"下一个": "下一个：紧接着的那个人，即排在后面轮到的人。", "前一个": "语义：“前一个”指已经走了的那位，与“排在后面”的意思相反。", "自己": "语义：“自己”指说话人本人，不能表示排在后面的那一位，“自己是你”说不通。", "谁": "配价：“谁”是疑问代词，陈述句中“谁是你”不成立，且与“前面的人走了”的语境不符。"}, "sentence_index": 0, "correct_answer": "下一个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把作业写完，下一个才去睡觉。", "explanation": "这里应该用〈之后〉。表示事情的先后要用之后，“下一个”不能作时间副词，只指排在后面的人或事物。"}, {"text": "会议开始了，下一个我们讨论预算。", "explanation": "这里应该用〈接下来〉。“下一个”只能单独指代人或事物，不能表示接着做某事的时间顺序。"}, {"text": "我把碗洗完，下一个去洗衣服。", "explanation": "这里应该用〈然后〉。表示先后相接的动作要用然后，“下一个”不能引出后续的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下一个", "is_correct": true, "explanation": "下一个：紧接着的那个人，指排在后面的人。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指他人，妹妹跳完舞后接的是哥哥，“别人是哥哥”与句意不符。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指全体，不能与单指的“哥哥”构成“是”字句，且与顺序义不符。"}, {"text": "其他人", "is_correct": false, "explanation": "语义：“其他人”指除此以外的人群，与“接着的哥哥”不符，“其他人是哥哥”说不通。"}], "explanations": {"下一个": "下一个：紧接着的那个人，指排在后面的人。", "别人": "语义：“别人”指他人，妹妹跳完舞后接的是哥哥，“别人是哥哥”与句意不符。", "大家": "搭配：“大家”指全体，不能与单指的“哥哥”构成“是”字句，且与顺序义不符。", "其他人": "语义：“其他人”指除此以外的人群，与“接着的哥哥”不符，“其他人是哥哥”说不通。"}, "sentence_index": 6, "correct_answer": "下一个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们吃完饭，下一个出发去车站。", "explanation": "这里应该用〈随后〉。表示紧接着某事之后要用随后，“下一个”只指排在后面的人或事物，不能表示动作的先后。"}, {"text": "下一个人都到了，我们开始吧。", "explanation": "这里应该用〈每个〉。表示全体的人要用每个或全部，“下一个”只指紧接着的那一个，不能表示全体。"}, {"text": "他在国外住了三年，下一个回国了。", "explanation": "这里应该用〈后来〉。表示时间上的先后要用后来，“下一个”不能作时间副词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生说：“下一个们请进来。”", "corrected_sentence": "医生说：“下一个请进来。”", "error_description": "错误：“下一个们”，“下一个”已指单独的一个人，不能再加复数后缀“们”；正确：“下一个请进来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们三个人，你是下一个的。", "corrected_sentence": "我们三个人，你是下一个。", "error_description": "错误：“下一个的”，“下一个”作代词时句末不能再加“的”；正确：“你是下一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
