INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89530, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有用;能起作用。", "primary_collocate": null, "pronunciation": "zhōng yòng", "ipa": "ʈʂʊŋ˥˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个办法真中用。", "target_word": "中用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在说也不中用。", "target_word": "中用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药很中用,我吃了就好了。", "target_word": "中用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哭了不中用,我们得想办法。", "target_word": "中用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪大了,干活不中用了。", "target_word": "中用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧书对我还中用。", "target_word": "中用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这个方法很中用。", "target_word": "中用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光着急不中用。", "target_word": "中用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教的这个记单词的办法很中用。", "target_word": "中用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草药在我们这儿很中用。", "target_word": "中用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不中用", "label": "否定式"}], "register": "口语", "sense_fingerprint": "办法、话、药等有用、能起作用，如“这个办法真中用”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41030cd8-5d0c-42f5-9a15-c95cff6bf5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89530, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中用", "is_correct": true, "explanation": "“中用”表示能起作用，放在“这个办法真___”中意思通顺。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”是人的感觉，办法不会饿。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描述人或动物的体形，办法没有体形可言。"}, {"text": "伤心", "is_correct": false, "explanation": "语义：“伤心”是人的情绪，办法不会伤心。"}], "explanations": {"中用": "“中用”表示能起作用，放在“这个办法真___”中意思通顺。", "饿": "语义：“饿”是人的感觉，办法不会饿。", "瘦": "体貌：“瘦”描述人或动物的体形，办法没有体形可言。", "伤心": "语义：“伤心”是人的情绪，办法不会伤心。"}, "sentence_index": 0, "correct_answer": "中用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气很中用，适合出去玩。", "explanation": "这里应该用〈好〉。“中用”说办法或东西能起作用，天气不能说“中用”。"}, {"text": "这个假期很中用，我们去海边玩了两天。", "explanation": "这里应该用〈愉快〉。“中用”说的是有用、能起作用，假期不是能起作用的事物，应说“愉快”。"}, {"text": "这件衣服的颜色很中用，我很喜欢。", "explanation": "这里应该用〈好看〉。颜色是看的，要说好看，不说“中用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中用", "is_correct": true, "explanation": "“中用”表示能起作用，放在“听说这个方法很___”中意思通顺。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”是人的情绪，方法不会害羞。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描述人或动物的体形，方法没有体形可言。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”是人的心情，方法不会高兴。"}], "explanations": {"中用": "“中用”表示能起作用，放在“听说这个方法很___”中意思通顺。", "害羞": "语义：“害羞”是人的情绪，方法不会害羞。", "胖": "体貌：“胖”描述人或动物的体形，方法没有体形可言。", "高兴": "语义：“高兴”是人的心情，方法不会高兴。"}, "sentence_index": 6, "correct_answer": "中用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首诗很中用，读起来很动人。", "explanation": "这里应该用〈优美〉。“中用”说的是能起作用或有用，诗是欣赏的作品，不能说“中用”。"}, {"text": "她的声音很中用，大家都爱听她唱歌。", "explanation": "这里应该用〈好听〉。“中用”说办法、东西能起作用，声音要说好听。"}, {"text": "这个笑话很中用，大家都笑了。", "explanation": "这里应该用〈有趣〉。笑话的作用是有趣，不说“中用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方子很的中用，吃了就好。", "corrected_sentence": "这个方子很中用，吃了就好。", "error_description": "错误：「很」与「中用」之间误加结构助词「的」，程度副词「很」后不能直接加「的」。正确：删去「的」，即「这个方子很中用」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法很还中用，你试试吧。", "corrected_sentence": "这个办法还很中用，你试试吧。", "error_description": "错误：“很还中用”；正确：“还很中用”。副词“还”应放在“很”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1050a821-339f-44a3-ab99-2cddfa8e9e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
