INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89531, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古城是很久很久以前就有的城市。", "primary_collocate": null, "pronunciation": "gǔ chéng", "ipa": "ku˨˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这是一座有两千年历史的古城。", "target_word": "古城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们周末去古城玩了。", "target_word": "古城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古城里的房子都很旧。", "target_word": "古城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在一座安静的古城。", "target_word": "古城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古城的街道很窄，车不多。", "target_word": "古城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客在古城里走着，拍了很多照片。", "target_word": "古城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城有很长的城墙。", "target_word": "古城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢西安这座古城。", "target_word": "古城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上古城的灯很漂亮。", "target_word": "古城", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想带父母去古城看看。", "target_word": "古城", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "古城墙", "label": "复合"}], "register": "中性", "sense_fingerprint": "很久以前就有的城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60eb8d25-3940-4b37-9ab8-c3a913d8c431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89531, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "古城", "is_correct": true, "explanation": "正确：古城 gǔ chéng 指很久以前就有的城市。"}, {"text": "赌城", "is_correct": false, "explanation": "dǔ（第三声）与 gǔ 声母不同（d／g），意思是以赌博著称的城市。"}, {"text": "故城", "is_correct": false, "explanation": "gù（第四声）与 gǔ（第三声）声调不同，意思是古代遗留下来的旧城。"}, {"text": "土城", "is_correct": false, "explanation": "tǔ（第三声）与 gǔ 声母不同（t／g），意思是土筑的城墙。"}], "explanations": {"古城": "正确：古城 gǔ chéng 指很久以前就有的城市。", "赌城": "dǔ（第三声）与 gǔ 声母不同（d／g），意思是以赌博著称的城市。", "故城": "gù（第四声）与 gǔ（第三声）声调不同，意思是古代遗留下来的旧城。", "土城": "tǔ（第三声）与 gǔ 声母不同（t／g），意思是土筑的城墙。"}, "sentence_index": null, "correct_answer": "古城"}, "level_3": {"options": [{"text": "古城", "is_correct": true, "explanation": "正确：古城是有两千年历史的古代城市，与“这是一座”搭配。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机只有几十年历史，不可能有两千年历史。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：量词“座”不用于公司，公司也谈不上两千年历史。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球是运动项目，不能是有历史的城市。"}], "explanations": {"古城": "正确：古城是有两千年历史的古代城市，与“这是一座”搭配。", "手机": "语义：手机只有几十年历史，不可能有两千年历史。", "公司": "搭配：量词“座”不用于公司，公司也谈不上两千年历史。", "足球": "语义：足球是运动项目，不能是有历史的城市。"}, "sentence_index": 0, "correct_answer": "古城"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座古城有三斤重。", "explanation": "这里应该用〈鱼〉。古城是城市，没有重量可言；“三斤重”的对象要说鱼。"}, {"text": "他住在一只安静的古城。", "explanation": "量词错误：“只”用于动物，这里应该用〈座〉，城市要说“一座古城”。"}, {"text": "这个古城很好吃，我一口气吃了两碗。", "explanation": "这里应该用〈面条〉。古城是城市，不能吃，也不能用“碗”来计量；一口气吃两碗的对象要说面条。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古城", "is_correct": true, "explanation": "正确：古城是有城墙的古代城市，与“这座”搭配。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“座”用于建筑、山等大型固定物，不能修饰音乐。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会有城墙，句子的主语应是建筑或地方。"}, {"text": "外貌", "is_correct": false, "explanation": "搭配：“座”不能修饰外貌，外貌也不会有城墙。"}], "explanations": {"古城": "正确：古城是有城墙的古代城市，与“这座”搭配。", "音乐": "搭配：“座”用于建筑、山等大型固定物，不能修饰音乐。", "颜色": "语义：颜色不会有城墙，句子的主语应是建筑或地方。", "外貌": "搭配：“座”不能修饰外貌，外貌也不会有城墙。"}, "sentence_index": 6, "correct_answer": "古城"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿着一座古城。", "explanation": "这里应该用〈衣服〉。古城是城市，不能穿；能穿的东西要说衣服。"}, {"text": "他住在一颗古城里。", "explanation": "量词错误：“颗”用于圆小的东西，城市要用“座”。"}, {"text": "我一口气吃了两个古城。", "explanation": "这里应该用〈饺子〉。古城是城市，不能吃；能吃的东西要说饺子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去了一位很有名的古城。", "corrected_sentence": "我们去了一座很有名的古城。", "error_description": "量词错误：“位”用于人，城市应该用“座”，正确是「一座古城」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在古城的里住了一个晚上。", "corrected_sentence": "我们在古城里住了一个晚上。", "error_description": "结构错误：表示处所要说“古城里”，“的”不能插在“古城”和“里”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
