INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89533, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军马是给军队用的马。", "primary_collocate": null, "pronunciation": "jūn mǎ", "ipa": "tɕyn˥ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "这是一匹军马，不是普通的马。", "target_word": "军马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部队需要很多军马。", "target_word": "军马", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在部队里照顾军马。", "target_word": "军马", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这匹军马跟着战士走了很多年。", "target_word": "军马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军马每天吃很多草。", "target_word": "军马", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "战士们给军马洗了澡。", "target_word": "军马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里有一个养军马的地方。", "target_word": "军马", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷年轻时在军队里养过军马。", "target_word": "军马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，战士们把军马带回了马房。", "target_word": "军马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家为军队买了一百匹军马。", "target_word": "军马", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一匹军马", "label": "量词"}, {"form": "军马场", "label": "复合词"}], "register": "中性", "sense_fingerprint": "军队专用、由部队饲养使用的马", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc84aebc-8278-4ecb-bb1f-1683bde98033') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "军马", "is_correct": true, "explanation": "正确：「军马」指军队用的马，量词「匹」用于马，句意通顺。"}, {"text": "军人", "is_correct": false, "explanation": "搭配：量词「匹」用于马，不能用于人。"}, {"text": "军车", "is_correct": false, "explanation": "搭配：量词「匹」用于马，不用于车辆。"}, {"text": "军犬", "is_correct": false, "explanation": "语义：「军犬」是狗，与「不是普通的马」的对比不成立。"}], "explanations": {"军马": "正确：「军马」指军队用的马，量词「匹」用于马，句意通顺。", "军人": "搭配：量词「匹」用于马，不能用于人。", "军车": "搭配：量词「匹」用于马，不用于车辆。", "军犬": "语义：「军犬」是狗，与「不是普通的马」的对比不成立。"}, "sentence_index": 0, "correct_answer": "军马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "战士们骑着一只军马去巡逻。", "explanation": "这里应该用〈匹〉。马用量词「匹」，「只」多用于鸟、猫狗等动物，不用于马。"}, {"text": "训练场上站着一条军马。", "explanation": "这里应该用〈匹〉。「条」用于长条形的东西，不用于马。"}, {"text": "营地里站着一张军马。", "explanation": "这里应该用〈匹〉。「张」用于纸、桌子等扁平的东西，不用于马。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军马", "is_correct": true, "explanation": "正确：「养」的对象是「军马」这类牲畜，句意通顺。"}, {"text": "军粮", "is_correct": false, "explanation": "语义：粮食不能饲养，「养军粮」不通。"}, {"text": "军号", "is_correct": false, "explanation": "语义：「军号」是号角，不能饲养。"}, {"text": "军帽", "is_correct": false, "explanation": "搭配：「养」的对象是动物，不说「养军帽」。"}], "explanations": {"军马": "正确：「养」的对象是「军马」这类牲畜，句意通顺。", "军粮": "语义：粮食不能饲养，「养军粮」不通。", "军号": "语义：「军号」是号角，不能饲养。", "军帽": "搭配：「养」的对象是动物，不说「养军帽」。"}, "sentence_index": 6, "correct_answer": "军马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国家为军队买了一百台军马。", "explanation": "这里应该用〈匹〉。「台」用于机器，不用于马。"}, {"text": "国家为军队买了一百座军马。", "explanation": "这里应该用〈匹〉。「座」用于山、房屋等，不用于马。"}, {"text": "国家为军队买了一百朵军马。", "explanation": "这里应该用〈匹〉。「朵」用于花朵，不用于马。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只军马很老实，大家都喜欢它。", "corrected_sentence": "这匹军马很老实，大家都喜欢它。", "error_description": "量词错误：马应用量词「匹」，「只」不用于马。正确说法是「这匹军马」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国家去年为军队买了一只军马。", "corrected_sentence": "国家去年为军队买了一匹军马。", "error_description": "量词错误：马应用量词「匹」，「只」不用于马。正确说法是「买了一匹军马」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
