INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89534, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供军队骑乘或驮运的马。", "primary_collocate": null, "pronunciation": "jūn mǎ", "ipa": "tɕyn˥ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "战士骑着军马走在前面。", "target_word": "军马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军马驮着很重的货物上山。", "target_word": "军马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路太窄，军马驮着箱子慢慢走。", "target_word": "军马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军官骑上军马，向前跑去。", "target_word": "军马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过河的时候，军马驮着药品。", "target_word": "军马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那匹军马又高又壮，跑得很快。", "target_word": "军马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战士把东西放在军马的背上。", "target_word": "军马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪山上，军马帮部队运粮食。", "target_word": "军马", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑过军马，知道它们很聪明。", "target_word": "军马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军马听到命令，马上停了下来。", "target_word": "军马", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一匹军马", "label": "量词"}, {"form": "军马场", "label": "复合词"}], "register": "中性", "sense_fingerprint": "军队用来骑乘或驮运物资的马", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc84aebc-8278-4ecb-bb1f-1683bde98033') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "军马", "is_correct": true, "explanation": "正确：「骑着」的对象是可以骑的牲畜，「军马」指军队用的马，句意通顺。"}, {"text": "军鼓", "is_correct": false, "explanation": "语义：「军鼓」是打击乐器，不能骑。"}, {"text": "军帽", "is_correct": false, "explanation": "搭配：「骑」的对象是马、车等，不说「骑帽子」。"}, {"text": "军粮", "is_correct": false, "explanation": "语义：粮食不能骑，句意不通。"}], "explanations": {"军马": "正确：「骑着」的对象是可以骑的牲畜，「军马」指军队用的马，句意通顺。", "军鼓": "语义：「军鼓」是打击乐器，不能骑。", "军帽": "搭配：「骑」的对象是马、车等，不说「骑帽子」。", "军粮": "语义：粮食不能骑，句意不通。"}, "sentence_index": 0, "correct_answer": "军马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "军官骑上一只军马，向前跑去。", "explanation": "这里应该用〈匹〉。马用量词「匹」，「只」不用于马。"}, {"text": "军官骑上一辆军马，向前跑去。", "explanation": "这里应该用〈匹〉。「辆」用于车辆，不用于马。"}, {"text": "军官骑上一座军马，向前跑去。", "explanation": "这里应该用〈匹〉。「座」用于山、房屋等，不用于马。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军马", "is_correct": true, "explanation": "正确：「军马」有背，可以放东西，句意通顺。"}, {"text": "军歌", "is_correct": false, "explanation": "语义：歌曲没有背，「放在…的背上」不通。"}, {"text": "军号", "is_correct": false, "explanation": "语义：「军号」是号角，没有背，不能放东西。"}, {"text": "军旗", "is_correct": false, "explanation": "语义：旗子不能像马背那样承载东西，句意不通。"}], "explanations": {"军马": "正确：「军马」有背，可以放东西，句意通顺。", "军歌": "语义：歌曲没有背，「放在…的背上」不通。", "军号": "语义：「军号」是号角，没有背，不能放东西。", "军旗": "语义：旗子不能像马背那样承载东西，句意不通。"}, "sentence_index": 6, "correct_answer": "军马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一块军马听到命令，马上停了下来。", "explanation": "这里应该用〈匹〉。「块」用于片状的东西，不用于马。"}, {"text": "一朵军马听到命令，马上停了下来。", "explanation": "这里应该用〈匹〉。「朵」用于花朵，不用于马。"}, {"text": "一条军马听到命令，马上停了下来。", "explanation": "这里应该用〈匹〉。「条」用于长条形的东西，不用于马。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只军马驮着粮食走过了山谷。", "corrected_sentence": "一匹军马驮着粮食走过了山谷。", "error_description": "量词错误：马应用量词「匹」，「只」用于鸟、猫狗等动物，不用于马。正确说法是「一匹军马」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条军马驮着药品过了河。", "corrected_sentence": "一匹军马驮着药品过了河。", "error_description": "量词错误：马应用量词「匹」，「条」用于长条形的东西，不用于马。正确说法是「一匹军马驮着药品过了河」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
