INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89535, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "也就是表示换个说法，说的是同一件事。", "primary_collocate": null, "pronunciation": "yě jiù shì", "ipa": "jɛ˨˩ tɕjoʊ˥˩ ʂʅ˥˩", "syllable_count": 3, "sentences": [{"text": "他是我爸爸的哥哥，也就是我的伯父。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天是十月一日，也就是国庆节。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是我妈妈的妹妹，也就是我的阿姨。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家在中山路十号，也就是银行对面的那栋楼。", "target_word": "也就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的儿子的儿子，也就是他的孙子，今年三岁了。", "target_word": "也就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是星期天，也就是我们不上班的日子。", "target_word": "也就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路长三千米，也就是三公里。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈的爸爸，也就是我的外公，住在上海。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王老师是我们的班主任，也就是管我们班的老师。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我的同桌，也就是坐在我旁边的人。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "换一个说法，指的还是前面说的同一个人或事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b85a5fef-cf91-4887-8a4f-1d7906f0a58f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "也就是", "is_correct": true, "explanation": "“也就是”换一种说法解释前文，说的仍是同一个人：爸爸的哥哥就是我的伯父。"}, {"text": "却是", "is_correct": false, "explanation": "语义：“却是”表示转折，与前后指同一人的换说法不合。"}, {"text": "偏是", "is_correct": false, "explanation": "语义：“偏是”表示出乎意料，句子并没有这层意思，不合。"}, {"text": "可是", "is_correct": false, "explanation": "语义：“可是”表示转折，与前后指同一人的换说法不合。"}], "explanations": {"也就是": "“也就是”换一种说法解释前文，说的仍是同一个人：爸爸的哥哥就是我的伯父。", "却是": "语义：“却是”表示转折，与前后指同一人的换说法不合。", "偏是": "语义：“偏是”表示出乎意料，句子并没有这层意思，不合。", "可是": "语义：“可是”表示转折，与前后指同一人的换说法不合。"}, "sentence_index": 0, "correct_answer": "也就是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了两个苹果，也就是一个苹果。", "explanation": "〈也就是〉换说法要求前后指同一件事；“两个苹果”和“一个苹果”数量不同，不能用〈也就是〉连接。"}, {"text": "这个人是我的老师，也就是我的弟弟。", "explanation": "〈也就是〉换说法要求前后指同一个人；“老师”和“弟弟”不是同一个人，用法不成立。"}, {"text": "他是我的同学，也就是我的老师。", "explanation": "〈也就是〉换说法要求前后指同一人或事，这里“同学”和“老师”是两个人，用法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "也就是", "is_correct": true, "explanation": "“也就是”换一种说法，把“三千米”换算成“三公里”，指的是同一个长度。"}, {"text": "倒是", "is_correct": false, "explanation": "语义：“倒是”表示让步或转折，与前后同一数量的换算不合。"}, {"text": "又是", "is_correct": false, "explanation": "语义：“又是”表示重复或递进，与换算说明的意思不合。"}, {"text": "实是", "is_correct": false, "explanation": "语域：“实是”是书面语，与这句中性的换算说明不合。"}], "explanations": {"也就是": "“也就是”换一种说法，把“三千米”换算成“三公里”，指的是同一个长度。", "倒是": "语义：“倒是”表示让步或转折，与前后同一数量的换算不合。", "又是": "语义：“又是”表示重复或递进，与换算说明的意思不合。", "实是": "语域：“实是”是书面语，与这句中性的换算说明不合。"}, "sentence_index": 6, "correct_answer": "也就是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很聪明，也就是成绩很差。", "explanation": "〈也就是〉只用来换说法，不表示转折；这里表示转折应该用〈但是〉。"}, {"text": "这顿饭很贵，也就是我今天不想去了。", "explanation": "〈也就是〉不表示因果，这里表示结果应该用〈所以〉。"}, {"text": "我喜欢苹果，也就是我喜欢香蕉。", "explanation": "〈也就是〉前后要指同一件事，这里是两种不同的水果，应该用〈也〉或〈而且〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是我舅舅的女儿，也就是也就是我的表妹。", "corrected_sentence": "她是我舅舅的女儿，也就是我的表妹。", "error_description": "错误在于〈也就是〉多写了一遍，出现“也就是也就是”的重复。正确的说法只用一次〈也就是〉，引出换一种说法的解释。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是我的班长，也就是是班里管事的人。", "corrected_sentence": "她是我的班长，也就是班里管事的人。", "error_description": "错误在于〈是〉多写了一次，“也就是是”重复。正确的写法是只用一个〈是〉：“也就是班里管事的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
