INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89536, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89536, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示由前面的情况推出结论，相当于「就是说」。", "primary_collocate": null, "pronunciation": "yě jiù shì", "ipa": "jɛ˨˩ tɕjoʊ˥˩ ʂʅ˥˩", "syllable_count": 3, "sentences": [{"text": "他只考了三十分，也就是没有及格。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今年二十五岁，小王比我大三岁，也就是二十八岁。", "target_word": "也就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说周五不来，也就是周末才能见面。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议十点开始，路上要一个小时，也就是九点要出门。", "target_word": "也就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一共有六十个人，三个人一组，也就是二十组。", "target_word": "也就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没带钱包，也就是今天不能买东西。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生都走了，也就是教室里没有人了。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每天跑五公里，一周跑七天，也就是一周三十五公里。", "target_word": "也就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药一天吃三次，一次两片，也就是一天六片。", "target_word": "也就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "票卖完了，也就是我们今天看不了电影。", "target_word": "也就是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用另一种说法解释或推出前面的内容，相当于“就是说”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b85a5fef-cf91-4887-8a4f-1d7906f0a58f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "也就是", "is_correct": true, "explanation": "“也就是”用另一种说法推出前面的结论：只考了三十分，就意味着没有及格。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，前后并不是对立关系，不合。"}, {"text": "竟", "is_correct": false, "explanation": "语义：“竟”表示出乎意料，与由分数推出结论的语气不合。"}, {"text": "尚", "is_correct": false, "explanation": "语域：“尚”是书面语，与口语化的成绩叙述不合。"}], "explanations": {"也就是": "“也就是”用另一种说法推出前面的结论：只考了三十分，就意味着没有及格。", "却": "语义：“却”表示转折，前后并不是对立关系，不合。", "竟": "语义：“竟”表示出乎意料，与由分数推出结论的语气不合。", "尚": "语域：“尚”是书面语，与口语化的成绩叙述不合。"}, "sentence_index": 0, "correct_answer": "也就是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是老师，也就是他不会教书。", "explanation": "〈也就是〉用于由前面得出结论，但“是老师”推不出“不会教书”，这个推论不成立。"}, {"text": "我们都没有钱，也就是我们很有钱。", "explanation": "〈也就是〉用于由前面推出结论，“没有钱”推不出“很有钱”，前后意思相反，这里转折应该用〈但是〉，不能用〈也就是〉。"}, {"text": "他很努力，也就是他没有进步。", "explanation": "〈也就是〉用于推出结论或换说法，不表示转折；这里表示转折应该用〈可是〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "也就是", "is_correct": true, "explanation": "“也就是”用另一种说法推出前面的结论：学生都走了，教室里自然没有人了。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示庆幸，句子并没有这层意思，不合。"}, {"text": "偏", "is_correct": false, "explanation": "语义：“偏”表示出乎意料，与平实的推出关系不合。"}, {"text": "可", "is_correct": false, "explanation": "语义：“可”表示转折，前后并不是对立关系，不合。"}], "explanations": {"也就是": "“也就是”用另一种说法推出前面的结论：学生都走了，教室里自然没有人了。", "幸好": "语义：“幸好”表示庆幸，句子并没有这层意思，不合。", "偏": "语义：“偏”表示出乎意料，与平实的推出关系不合。", "可": "语义：“可”表示转折，前后并不是对立关系，不合。"}, "sentence_index": 6, "correct_answer": "也就是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我喜欢游泳，也就是我喜欢跑步。", "explanation": "推论不成立：“喜欢游泳”推不出“喜欢跑步”，前后是并列关系，应用〈也〉或〈还〉。"}, {"text": "今天下雨了，也就是我喜欢吃面条。", "explanation": "推论不成立：“下雨了”推不出“喜欢吃面条”，前后没有关系，不能用〈也就是〉。"}, {"text": "他是我的同学，也就是我的老师。", "explanation": "推论不成立：“他是我的同学”推不出“他是我的老师”，两者不是同一人，也无法由此推出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "苹果五块钱一斤，我买了两斤，也就是了十块钱。", "corrected_sentence": "苹果五块钱一斤，我买了两斤，也就是十块钱。", "error_description": "错误在于〈也就是〉后面多加了〈了〉。〈也就是〉后面直接接结论：“也就是十块钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她今天没来上课，也就是是她病了。", "corrected_sentence": "她今天没来上课，也就是她病了。", "error_description": "错误在于〈是〉重复，写成“也就是是”。正确的写法是只用一个〈是〉：“也就是她病了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
