INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89537, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "句子是一些字词合在一起，说清楚一个意思。", "primary_collocate": null, "pronunciation": "jù zi", "ipa": "tɕy˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "我会说几个简单的句子了。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的句子又短又清楚。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个词放在一起，就成了句子。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们用新词写句子。", "target_word": "句子", "complexity_tier": "T3", "furigana": "lǎo shī ràng wǒ men yòng xīn cí xiě jù zi", "sentence_source": "generated"}, {"text": "这个句子我听懂了。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在本子上抄了五个句子。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个句子的意思不一样。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子说出了第一个完整的句子。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再说一个句子。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的句子都很短。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "字词合在一起说清楚一个意思的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed30a35-9b40-419e-ba00-be7904a18ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89537, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "句子", "is_correct": true, "explanation": "正确：句子（jù zi）指字词合在一起、说清楚一个意思的话。"}, {"text": "桔子", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，桔子意思是一种水果。"}, {"text": "巨资", "is_correct": false, "explanation": "第二音节 zī（第一声）与轻声 zi 声调不同，巨资意思是巨额资金。"}, {"text": "肚子", "is_correct": false, "explanation": "dù 与 jù 声母不同（d 与 j），肚子意思是腹部。"}, {"text": "路子", "is_correct": false, "explanation": "lù 与 jù 声母不同（l 与 j），路子意思是门路、途径。"}], "explanations": {"句子": "正确：句子（jù zi）指字词合在一起、说清楚一个意思的话。", "桔子": "jú（第二声）与 jù（第四声）声调不同，桔子意思是一种水果。", "巨资": "第二音节 zī（第一声）与轻声 zi 声调不同，巨资意思是巨额资金。", "肚子": "dù 与 jù 声母不同（d 与 j），肚子意思是腹部。", "路子": "lù 与 jù 声母不同（l 与 j），路子意思是门路、途径。"}, "sentence_index": null, "correct_answer": "句子"}, "level_3": {"options": [{"text": "句子", "is_correct": true, "explanation": "正确：句子是说清楚一个意思的话，“说几个简单的句子”搭配自然。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“说”不能与“歌”搭配，说的对象只能是话语，应说“唱歌”。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭是食物，不能用“说”来表达，句中的“会说”指能说出语言。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，“会说房子”不成立，与“会说”的语言含义矛盾。"}], "explanations": {"句子": "正确：句子是说清楚一个意思的话，“说几个简单的句子”搭配自然。", "歌": "搭配：“说”不能与“歌”搭配，说的对象只能是话语，应说“唱歌”。", "饭": "语义：饭是食物，不能用“说”来表达，句中的“会说”指能说出语言。", "房子": "语义：房子是建筑，“会说房子”不成立，与“会说”的语言含义矛盾。"}, "sentence_index": 0, "correct_answer": "句子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个句子的封面很漂亮。", "explanation": "这里把〈句子〉当成了〈书〉。句子是语言单位，没有封面，封面是书的部分。"}, {"text": "这个句子有十画。", "explanation": "这里应该用〈汉字〉。笔画数只用于单个汉字，句子由多个词组成，不能按笔画计算。"}, {"text": "这个句子是第三声。", "explanation": "这里应该用〈声调〉。“第三声”描述的是音节的声调，句子不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "句子", "is_correct": true, "explanation": "正确：句子表示完整的意思，两个句子可以比较意思是否一样。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，没有“意思”，不能比较两者的意思是否一样。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是语言单位，谈不上“意思一样不一样”。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“……的意思”一般接语言单位，“窗户”不能与“意思”搭配。"}], "explanations": {"句子": "正确：句子表示完整的意思，两个句子可以比较意思是否一样。", "桌子": "语义：桌子是家具，没有“意思”，不能比较两者的意思是否一样。", "天气": "语义：天气是气象状况，不是语言单位，谈不上“意思一样不一样”。", "窗户": "搭配：“……的意思”一般接语言单位，“窗户”不能与“意思”搭配。"}, "sentence_index": 6, "correct_answer": "句子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个句子是叠词。", "explanation": "这里应该用〈词语〉。叠词是由重复的字构成的词，句子不是词，不能称为叠词。"}, {"text": "这个句子读轻声。", "explanation": "这里应该用〈音节〉。轻声是音节的读法，句子作为语言单位不读轻声。"}, {"text": "这个句子是三位数。", "explanation": "这里应该用〈数字〉。“三位数”只用来描述数字，不能用来形容句子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她背下了五张句子。", "corrected_sentence": "她背下了五个句子。", "error_description": "量词错误：句子应用“个”，不用“张”。“张”多用于纸张、桌子等平面的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几句子都很短。", "corrected_sentence": "这几个句子都很短。", "error_description": "量词漏掉：“这几”之后接名词要加量词“个”，应说“这几个句子”，不能说“这几句子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
