INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89538, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由词或短语构成、能表达完整意思的语言单位。", "primary_collocate": null, "pronunciation": "jù zi", "ipa": "tɕy˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "这个句子里有一个错别字。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用“喜欢”写一个句子。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "句子的最后要写上句号。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把句子写在了黑板上。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子有十个字。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子的意思我看不懂。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了一遍课文里的句子。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个句子读两遍。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "句子太长，我读不完。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子的主语是“我”。", "target_word": "句子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "由词或短语构成、表达完整意思的语言单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed30a35-9b40-419e-ba00-be7904a18ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89538, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "句子", "is_correct": true, "explanation": "正确：句子（jù zi）指由词或短语构成、能表达完整意思的语言单位。"}, {"text": "桔子", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，桔子意思是一种水果。"}, {"text": "巨资", "is_correct": false, "explanation": "第二音节 zī（第一声）与轻声 zi 声调不同，巨资意思是巨额资金。"}, {"text": "肚子", "is_correct": false, "explanation": "dù 与 jù 声母不同（d 与 j），肚子意思是腹部。"}, {"text": "路子", "is_correct": false, "explanation": "lù 与 jù 声母不同（l 与 j），路子意思是门路、途径。"}], "explanations": {"句子": "正确：句子（jù zi）指由词或短语构成、能表达完整意思的语言单位。", "桔子": "jú（第二声）与 jù（第四声）声调不同，桔子意思是一种水果。", "巨资": "第二音节 zī（第一声）与轻声 zi 声调不同，巨资意思是巨额资金。", "肚子": "dù 与 jù 声母不同（d 与 j），肚子意思是腹部。", "路子": "lù 与 jù 声母不同（l 与 j），路子意思是门路、途径。"}, "sentence_index": null, "correct_answer": "句子"}, "level_3": {"options": [{"text": "句子", "is_correct": true, "explanation": "正确：句子能表达完整意思，书面句子里可以出现错别字，与“这个……里”搭配自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是书面文字，“这个天气里有一个错别字”说不通。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉是水果，不含文字，不会有错别字。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“有错别字”说的是书面文字，“声音”不能与“错别字”搭配。"}], "explanations": {"句子": "正确：句子能表达完整意思，书面句子里可以出现错别字，与“这个……里”搭配自然。", "天气": "语义：天气是气象状况，不是书面文字，“这个天气里有一个错别字”说不通。", "香蕉": "语义：香蕉是水果，不含文字，不会有错别字。", "声音": "搭配：“有错别字”说的是书面文字，“声音”不能与“错别字”搭配。"}, "sentence_index": 0, "correct_answer": "句子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个句子是第四声。", "explanation": "这里应该用〈音节〉。声调是音节的属性，句子由多个词组成，不能说它是第四声。"}, {"text": "这个句子是独体字。", "explanation": "这里应该用〈字〉。独体字指只由一个部件构成的单个汉字，句子由多个词组成，不能说是独体字。"}, {"text": "这个句子有八画。", "explanation": "这里应该用〈汉字〉。笔画数只用于单个汉字，句子由多个词组成，不能按笔画计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "句子", "is_correct": true, "explanation": "正确：句子是能表达完整意思的语言单位，课文里的句子可以读一遍。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“读”的对象是文字类内容，颜色不能与“读一遍”搭配。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：硬币是金属货币，不是可以阅读的文字内容。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，课文里的桌子不能被“读一遍”。"}], "explanations": {"句子": "正确：句子是能表达完整意思的语言单位，课文里的句子可以读一遍。", "颜色": "搭配：“读”的对象是文字类内容，颜色不能与“读一遍”搭配。", "硬币": "语义：硬币是金属货币，不是可以阅读的文字内容。", "桌子": "语义：桌子是家具，课文里的桌子不能被“读一遍”。"}, "sentence_index": 6, "correct_answer": "句子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "句子是一种标点。", "explanation": "这里应该用〈句号〉。句号是标点符号，句子是由词或短语构成的语言单位，不是标点。"}, {"text": "这个句子是一个副词。", "explanation": "这里把〈句子〉当成了〈词类〉。句子是由词组成的语言单位，不属于副词这一类。"}, {"text": "这个句子是三位数。", "explanation": "这里应该用〈数字〉。“三位数”只用来描述数字，不能用来形容句子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天读了三句子。", "corrected_sentence": "我昨天读了三个句子。", "error_description": "量词漏掉：句子前面有数词时要加量词“个”，应说“三个句子”，不能直接说“三句子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我昨天写句子。", "corrected_sentence": "这是我昨天写的句子。", "error_description": "定语标记漏掉：“写”修饰名词“句子”时，中间要加“的”，应说“我昨天写的句子”，不能说“我昨天写句子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
