INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "轿车是人坐的小汽车，一般有四个轮子，有顶。", "primary_collocate": null, "pronunciation": "jiào chē", "ipa": "tɕjau˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "那辆红色轿车是我朋友的。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轿车有四个轮子，还有车顶。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，我们坐轿车回家。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天开轿车送我上学。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路上有很多轿车和公共汽车。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆轿车太旧了，该换新的。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的轿车里放着一瓶水。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轿车坐五个人，坐不下七个人。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一辆便宜的轿车。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车场里有三辆白色轿车。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "小轿车", "label": "复合词"}, {"form": "轎車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "载人的、有四个轮子和车顶的小汽车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94079a68-bf10-4746-bd88-8d31e031ef14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89539, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轿车", "is_correct": true, "explanation": "正确。轿车（jiào chē）指载人的小汽车。"}, {"text": "交车", "is_correct": false, "explanation": "jiāo（第一声）与 jiào（第四声）声调不同，意思是交付车辆，不是轿车。"}, {"text": "驾车", "is_correct": false, "explanation": "jià 与 jiào 韵母不同，意思是驾驶车辆。"}, {"text": "校车", "is_correct": false, "explanation": "xiào 与 jiào 声母不同（x 与 j），意思是学校的接送班车。"}], "explanations": {"轿车": "正确。轿车（jiào chē）指载人的小汽车。", "交车": "jiāo（第一声）与 jiào（第四声）声调不同，意思是交付车辆，不是轿车。", "驾车": "jià 与 jiào 韵母不同，意思是驾驶车辆。", "校车": "xiào 与 jiào 声母不同（x 与 j），意思是学校的接送班车。"}, "sentence_index": null, "correct_answer": "轿车"}, "level_3": {"options": [{"text": "轿车", "is_correct": true, "explanation": "正确。“那辆红色轿车”是朋友的私家车，符合语境。"}, {"text": "救护车", "is_correct": false, "explanation": "语义：救护车是医院的公用车，不会属于“我朋友”。"}, {"text": "垃圾车", "is_correct": false, "explanation": "语义：垃圾车属于环卫部门，不会是朋友私人的车。"}, {"text": "警车", "is_correct": false, "explanation": "语义：警车是公安部门的公务车，不会是朋友私人的车。"}], "explanations": {"轿车": "正确。“那辆红色轿车”是朋友的私家车，符合语境。", "救护车": "语义：救护车是医院的公用车，不会属于“我朋友”。", "垃圾车": "语义：垃圾车属于环卫部门，不会是朋友私人的车。", "警车": "语义：警车是公安部门的公务车，不会是朋友私人的车。"}, "sentence_index": 0, "correct_answer": "轿车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "清晨，轿车在街上缓缓地洒水。", "explanation": "这里应该用〈洒水车〉。洒水要用洒水车，轿车是供人乘坐的车。"}, {"text": "轿车把冷冻海鲜运到超市。", "explanation": "这里应该用〈冷藏车〉。运送需要低温保存的货物要用冷藏车，轿车供人乘坐。"}, {"text": "轿车每天早上来收垃圾。", "explanation": "这里应该用〈垃圾车〉。收垃圾要用垃圾车，轿车不这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89539, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轿车", "is_correct": true, "explanation": "正确。“他的轿车里放着一瓶水”指放在他私家车里，符合语境。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机太小，装不下一瓶水，“他的手机里放着一瓶水”不通。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵是器官，不能用来放东西，“他的耳朵里放着一瓶水”不通。"}, {"text": "地铁站", "is_correct": false, "explanation": "语义：地铁站是公共设施，说“他的地铁站里”不合常理。"}], "explanations": {"轿车": "正确。“他的轿车里放着一瓶水”指放在他私家车里，符合语境。", "手机": "语义：手机太小，装不下一瓶水，“他的手机里放着一瓶水”不通。", "耳朵": "语义：耳朵是器官，不能用来放东西，“他的耳朵里放着一瓶水”不通。", "地铁站": "语义：地铁站是公共设施，说“他的地铁站里”不合常理。"}, "sentence_index": 6, "correct_answer": "轿车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "轿车在轨道上缓缓前行，车铃叮叮作响。", "explanation": "这里应该用〈有轨电车〉。有轨电车沿轨道行驶并响铃，轿车是在公路上行驶的车。"}, {"text": "轿车在铁路上飞速前进，很快就到了。", "explanation": "这里应该用〈高铁〉。高铁沿铁路运行，轿车只在公路上行驶。"}, {"text": "轿车在大江上缓缓驶过，汽笛声很响。", "explanation": "这里应该用〈轮船〉。大江上航行的是船，会鸣汽笛；轿车是陆地上行驶的车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸开着一本新的轿车去上班。", "corrected_sentence": "爸爸开着一辆新的轿车去上班。", "error_description": "量词错误：“轿车”应使用量词“辆”，“本”用于书册，不能用于轿车。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家门口停着两轿车。", "corrected_sentence": "他家门口停着两辆轿车。", "error_description": "量词缺失：“两”后面的“轿车”需要量词“辆”，不能直接说“两轿车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
