INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89540, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人乘坐的小型汽车，一般有固定车顶，座位较舒适。", "primary_collocate": null, "pronunciation": "jiào chē", "ipa": "tɕjau˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "爸爸新买了一辆黑色的轿车。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆轿车坐起来很舒服。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一家人坐轿车去海边。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轿车的后座可以坐三个人。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开轿车上班，不坐地铁。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种轿车有四个门，也有车顶。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轿车停在楼下的车位上。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王的轿车是去年买的。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车太大，轿车比较小。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派轿车来机场接客人。", "target_word": "轿车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "小轿车", "label": "复合词"}, {"form": "轎車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "供人乘坐、有固定车顶、座位舒适的小型汽车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94079a68-bf10-4746-bd88-8d31e031ef14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89540, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "轿车", "is_correct": true, "explanation": "正确。轿车（jiào chē）指供人乘坐的小汽车。"}, {"text": "交车", "is_correct": false, "explanation": "jiāo（第一声）与 jiào（第四声）声调不同，意思是交付车辆，不是轿车。"}, {"text": "校车", "is_correct": false, "explanation": "xiào 与 jiào 声母不同（x 与 j），意思是学校的接送班车。"}, {"text": "借车", "is_correct": false, "explanation": "jiè 与 jiào 韵母不同，意思是借用车辆。"}, {"text": "旧车", "is_correct": false, "explanation": "jiù 与 jiào 韵母不同，意思是旧的车辆。"}], "explanations": {"轿车": "正确。轿车（jiào chē）指供人乘坐的小汽车。", "交车": "jiāo（第一声）与 jiào（第四声）声调不同，意思是交付车辆，不是轿车。", "校车": "xiào 与 jiào 声母不同（x 与 j），意思是学校的接送班车。", "借车": "jiè 与 jiào 韵母不同，意思是借用车辆。", "旧车": "jiù 与 jiào 韵母不同，意思是旧的车辆。"}, "sentence_index": null, "correct_answer": "轿车"}, "level_3": {"options": [{"text": "轿车", "is_correct": true, "explanation": "正确。“一辆黑色的轿车”指供人乘坐的私家小汽车，与“爸爸新买了”相符。"}, {"text": "救护车", "is_correct": false, "explanation": "语义：救护车是医院用来送病人的车，不会是爸爸私人买的。"}, {"text": "公交车", "is_correct": false, "explanation": "搭配：“买”的对象通常是私人用车，公交车多由公司或公共机构购置。"}, {"text": "消防车", "is_correct": false, "explanation": "语义：消防车是消防部门的专用车，普通人不会买来私用，与“爸爸新买了”不符。"}], "explanations": {"轿车": "正确。“一辆黑色的轿车”指供人乘坐的私家小汽车，与“爸爸新买了”相符。", "救护车": "语义：救护车是医院用来送病人的车，不会是爸爸私人买的。", "公交车": "搭配：“买”的对象通常是私人用车，公交车多由公司或公共机构购置。", "消防车": "语义：消防车是消防部门的专用车，普通人不会买来私用，与“爸爸新买了”不符。"}, "sentence_index": 0, "correct_answer": "轿车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们用轿车运了两吨水泥去工地。", "explanation": "这里应该用〈货车〉。轿车供人乘坐，运送大量货物要用货车。"}, {"text": "环卫工人每天早上开轿车收垃圾。", "explanation": "这里应该用〈垃圾车〉。收垃圾要用垃圾车，轿车供人乘坐，不这样用。"}, {"text": "起火后，消防员开着轿车赶到现场灭火。", "explanation": "这里应该用〈消防车〉。灭火需要消防车携带的设备，轿车不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轿车", "is_correct": true, "explanation": "正确。轿车可以停在楼下的车位上，符合语境。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不会自己开到楼下停进车位。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“停”的施事须是车辆，冰箱不能作为停放的主语。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是随身物品，不会停在车位上。"}], "explanations": {"轿车": "正确。轿车可以停在楼下的车位上，符合语境。", "沙发": "语义：沙发是家具，不会自己开到楼下停进车位。", "冰箱": "配价：“停”的施事须是车辆，冰箱不能作为停放的主语。", "行李": "语义：行李是随身物品，不会停在车位上。"}, "sentence_index": 6, "correct_answer": "轿车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "轿车在铁轨上飞快地驶向北京。", "explanation": "这里应该用〈火车〉。火车沿铁轨行驶，轿车是在公路上行驶的车，不能在铁轨上跑。"}, {"text": "轿车在江面上飞快地划过，溅起了一片水花。", "explanation": "这里应该用〈快艇〉。在水面上高速航行的是船，轿车是陆地上行驶的车。"}, {"text": "轿车在地下轨道上飞快地穿行，很快就到了站。", "explanation": "这里应该用〈地铁〉。地铁在地下轨道上运行，轿车在公路上行驶，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈昨天买了一个新的轿车。", "corrected_sentence": "妈妈昨天买了一辆新的轿车。", "error_description": "量词错误：“轿车”应使用量词“辆”，“个”不能用于轿车，应说“一辆新的轿车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车库里停着两轿车。", "corrected_sentence": "车库里停着两辆轿车。", "error_description": "量词缺失：“两”后面的名词“轿车”需要量词“辆”，不能直接说“两轿车”，应说“两辆轿车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
