INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89541, 1, 'prompt1_core', '{"pos": "结果补语", "semantic_class": "function", "definition": "尽是用完了,一点也不剩。", "primary_collocate": null, "pronunciation": "jìn", "ipa": "tɕin˥˩", "syllable_count": 1, "sentences": [{"text": "这口老井的水，用了几百年也用不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè kǒu lǎo jǐng de shuǐ, yòng le jǐ bǎi nián yě yòng bú jìn.", "sentence_source": "generated"}, {"text": "爸爸留下的钱，我一辈子也花不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "bà ba liú xià de qián, wǒ yí bèi zi yě huā bú jìn.", "sentence_source": "generated"}, {"text": "这片森林的木材，砍了几代人也砍不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè piàn sēn lín de mù cái, kǎn le jǐ dài rén yě kǎn bú jìn.", "sentence_source": "generated"}, {"text": "这座大山里的泉水，取了一年也取不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè zuò dà shān lǐ de quán shuǐ, qǔ le yì nián yě qǔ bú jìn.", "sentence_source": "generated"}, {"text": "他有花不尽的钱。", "target_word": "尽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子有用不尽的力气。", "target_word": "尽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座金矿的金子，挖一辈子也挖不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè zuò jīn kuàng de jīn zi, wā yí bèi zi yě wā bú jìn.", "sentence_source": "generated"}, {"text": "这片草原的牧草，牛羊吃一辈子也吃不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè piàn cǎo yuán de mù cǎo, niú yáng chī yí bèi zi yě chī bú jìn.", "sentence_source": "generated"}, {"text": "这片海里的鱼，捕了几十年也捕不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè piàn hǎi lǐ de yú, bǔ le jǐ shí nián yě bǔ bú jìn.", "sentence_source": "generated"}, {"text": "这笔遗产太多了，我们子孙三代也花不尽。", "target_word": "尽", "complexity_tier": "T3", "furigana": "zhè bǐ yí chǎn tài duō le, wǒ men zǐ sūn sān dài yě huā bú jìn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "盡", "label": "繁体"}, {"form": "用尽", "label": "复合"}, {"form": "无尽", "label": "复合"}], "register": "中性", "sense_fingerprint": "尽|结果补语|V不尽:用完、穷尽、一点不剩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fca3150-b75d-419f-a155-8fc7061e16d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89541, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尽", "is_correct": true, "explanation": "尽 jìn（第四声）：用完、一点不剩，是正确答案。"}, {"text": "金", "is_correct": false, "explanation": "金 jīn（第一声）与 jìn（第四声）声调不同，意思是金子。"}, {"text": "紧", "is_correct": false, "explanation": "紧 jǐn（第三声）与 jìn（第四声）声调不同，意思是紧张、不松。"}, {"text": "静", "is_correct": false, "explanation": "静 jìng 与 jìn 韵母不同（-ng 与 -n），意思是安静。"}, {"text": "今", "is_correct": false, "explanation": "今 jīn（第一声）与 jìn（第四声）声调不同，意思是今天。"}], "explanations": {"尽": "尽 jìn（第四声）：用完、一点不剩，是正确答案。", "金": "金 jīn（第一声）与 jìn（第四声）声调不同，意思是金子。", "紧": "紧 jǐn（第三声）与 jìn（第四声）声调不同，意思是紧张、不松。", "静": "静 jìng 与 jìn 韵母不同（-ng 与 -n），意思是安静。", "今": "今 jīn（第一声）与 jìn（第四声）声调不同，意思是今天。"}, "sentence_index": null, "correct_answer": "尽"}, "level_3": {"options": [{"text": "尽", "is_correct": true, "explanation": "“用不尽”即用到一点不剩，符合“用了几百年也用不尽”的语境。"}, {"text": "上", "is_correct": false, "explanation": "语义：“用不上”表示用不到、没有用处，与“用了几百年”的语境矛盾。"}, {"text": "起", "is_correct": false, "explanation": "语义：“用不起”表示负担不起费用，与老井之水取用无需花钱的语境不合。"}, {"text": "动", "is_correct": false, "explanation": "搭配：“用不动”说物体无法挪动，不能用来形容用水，搭配不当。"}], "explanations": {"尽": "“用不尽”即用到一点不剩，符合“用了几百年也用不尽”的语境。", "上": "语义：“用不上”表示用不到、没有用处，与“用了几百年”的语境矛盾。", "起": "语义：“用不起”表示负担不起费用，与老井之水取用无需花钱的语境不合。", "动": "搭配：“用不动”说物体无法挪动，不能用来形容用水，搭配不当。"}, "sentence_index": 0, "correct_answer": "尽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我终于把作业做尽了，可以去玩了。", "explanation": "这里应该用〈完〉。“尽”多用于钱财、粮食、力气等可以耗尽的东西，表示用到一点不剩；作业做完要说“做完”。"}, {"text": "我把厨房打扫尽了，你可以进来了。", "explanation": "这里应该用〈完〉。“尽”表示一点不剩，不用于打扫这类动作的结束；打扫完要说“打扫完”。"}, {"text": "这学期的课我上尽了，下周开始放假。", "explanation": "这里应该用〈完〉。“尽”表示用到一点不剩，不用于课程结束；课上完要说“上完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89541, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "尽", "is_correct": true, "explanation": "尽 jìn（第四声）：用完、一点不剩，是正确答案。"}, {"text": "筋", "is_correct": false, "explanation": "筋 jīn（第一声）与 jìn（第四声）声调不同，意思是筋骨、肌腱。"}, {"text": "斤", "is_correct": false, "explanation": "斤 jīn（第一声）与 jìn（第四声）声调不同，意思是重量单位“斤”。"}, {"text": "净", "is_correct": false, "explanation": "净 jìng 与 jìn 韵母不同（-ng 与 -n），意思是干净。"}, {"text": "竟", "is_correct": false, "explanation": "竟 jìng 与 jìn 韵母不同（-ng 与 -n），意思是竟然、居然。"}, {"text": "信", "is_correct": false, "explanation": "信 xìn（第四声）与 jìn 声母不同（x 与 j），意思是相信、信件。"}], "explanations": {"尽": "尽 jìn（第四声）：用完、一点不剩，是正确答案。", "筋": "筋 jīn（第一声）与 jìn（第四声）声调不同，意思是筋骨、肌腱。", "斤": "斤 jīn（第一声）与 jìn（第四声）声调不同，意思是重量单位“斤”。", "净": "净 jìng 与 jìn 韵母不同（-ng 与 -n），意思是干净。", "竟": "竟 jìng 与 jìn 韵母不同（-ng 与 -n），意思是竟然、居然。", "信": "信 xìn（第四声）与 jìn 声母不同（x 与 j），意思是相信、信件。"}, "sentence_index": null, "correct_answer": "尽"}, "level_3": {"options": [{"text": "尽", "is_correct": true, "explanation": "“挖不尽”即挖到一点不剩，符合“挖一辈子也挖不尽”的语境。"}, {"text": "通", "is_correct": false, "explanation": "语义：“挖不通”指挖不穿、挖不透，与金子数量多、挖不完的语境不合。"}, {"text": "下", "is_correct": false, "explanation": "搭配：“挖不下”不是常用的结果补语搭配，“下”不能表示挖到一点不剩。"}, {"text": "清", "is_correct": false, "explanation": "搭配：“挖不清”表示挖得不清楚，不能说明金子挖尽的结果。"}], "explanations": {"尽": "“挖不尽”即挖到一点不剩，符合“挖一辈子也挖不尽”的语境。", "通": "语义：“挖不通”指挖不穿、挖不透，与金子数量多、挖不完的语境不合。", "下": "搭配：“挖不下”不是常用的结果补语搭配，“下”不能表示挖到一点不剩。", "清": "搭配：“挖不清”表示挖得不清楚，不能说明金子挖尽的结果。"}, "sentence_index": 6, "correct_answer": "尽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议终于开尽了，大家都松了一口气。", "explanation": "这里应该用〈完〉。“尽”表示用到一点不剩，多用于钱财、粮食、力气等可以耗尽的东西；会议结束要用“完”。"}, {"text": "这封信我写尽了，马上寄出去。", "explanation": "这里应该用〈完〉。“尽”表示用到一点不剩，多用于钱财、粮食、力气等；写信写完要说“写完”。"}, {"text": "这张桌子我擦尽了，你可以坐了。", "explanation": "这里应该用〈干净〉。擦到干干净净要说“擦干净”；“尽”表示一点不剩，不用于擦桌子这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些粮食，吃一辈子也吃尽不了。", "corrected_sentence": "这些粮食，吃一辈子也吃不尽。", "error_description": "错误形式“吃尽不了”，应为“吃不尽”。可能补语的否定式是“V不尽”，“不”要放在动词和“尽”之间，不能写成“V尽不了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这口井的水，抽一个月也抽得不尽。", "corrected_sentence": "这口井的水，抽一个月也抽不尽。", "error_description": "错误形式“抽得不尽”，应为“抽不尽”。可能补语的否定式是“V不尽”，“得”不能插在动词和“不”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf3a36d-cbb1-4a72-99b6-d89bfb624757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89543, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
