INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89543, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "另加是在原来的东西以外，再多放一些。", "primary_collocate": null, "pronunciation": "lìng jiā", "ipa": "liŋ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "菜做好了，另加一点盐。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要一碗面，另加一个蛋。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在咖啡里另加了两勺糖。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在汤里另加一些水。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯咖啡要另加奶吗？", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕上另加了一些水果。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在饺子里另加了点肉。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶里另加点蜂蜜会更甜。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗粥里另加一些红枣吧。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炒菜时另加一点糖，味道更好。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "另加了", "label": "体标"}], "register": "中性", "sense_fingerprint": "在原有的东西之外再放入一些", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd51ad7a1-a286-491d-9bbd-bb1f05a74ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89543, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戴", "is_correct": false, "explanation": "搭配：「戴」用于头、手等身体部位或饰物，不能与「盐」搭配。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：盐不能被「洗」，「洗」不与「盐」搭配。"}, {"text": "另加", "is_correct": true, "explanation": "正确。「另加」指在原有的东西以外再放入一些，菜做好后再加一点盐。"}, {"text": "读", "is_correct": false, "explanation": "搭配：「读」的对象是文字、书，不能与「盐」搭配。"}], "explanations": {"戴": "搭配：「戴」用于头、手等身体部位或饰物，不能与「盐」搭配。", "洗": "搭配：盐不能被「洗」，「洗」不与「盐」搭配。", "另加": "正确。「另加」指在原有的东西以外再放入一些，菜做好后再加一点盐。", "读": "搭配：「读」的对象是文字、书，不能与「盐」搭配。"}, "sentence_index": 0, "correct_answer": "另加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想请我另加他们的音乐社团。", "explanation": "应该用〈加入〉。另加表示在原有的东西上再放一些，不用于加入团体。"}, {"text": "他把桌子从客厅另加到了卧室。", "explanation": "应该用〈搬〉。另加表示在原有东西之外再多放一些，不表示把东西从一处挪到另一处。"}, {"text": "我把书另加卖掉了。", "explanation": "应该删去〈另加〉，说「我把书卖掉了」。另加表示在原有东西上再放入一些，不表示售出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89543, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剥", "is_correct": false, "explanation": "搭配：「剥」用于去掉皮壳，不用于在饺子里处理肉。"}, {"text": "删", "is_correct": false, "explanation": "语义：「删」是删去，与句中加肉的意思相反。"}, {"text": "另加", "is_correct": true, "explanation": "正确。「另加」指在饺子馅原有的东西之外再放入肉。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是吃下的食物，「在饺子里吃」这个位置说不通。"}], "explanations": {"剥": "搭配：「剥」用于去掉皮壳，不用于在饺子里处理肉。", "删": "语义：「删」是删去，与句中加肉的意思相反。", "另加": "正确。「另加」指在饺子馅原有的东西之外再放入肉。", "吃": "搭配：「吃」的对象是吃下的食物，「在饺子里吃」这个位置说不通。"}, "sentence_index": 6, "correct_answer": "另加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这本书另加扔了。", "explanation": "应该删去〈另加〉，说「他把这本书扔了」。另加表示在原有东西之外再放入，不表示丢弃。"}, {"text": "我想把红茶另加成绿茶。", "explanation": "应该用〈换〉。另加是在原有东西之外再加入，不表示用一样东西替换另一样。"}, {"text": "他每天早上都另加跑步。", "explanation": "另加要带上被放入的东西，表示再放入一些，不能用来修饰「跑步」这样的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汤里另加一只盐。", "corrected_sentence": "汤里另加一勺盐。", "error_description": "量词错误：「盐」不能用量词「只」，应说「另加一勺盐」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在茶里另加一本柠檬。", "corrected_sentence": "我在茶里另加一片柠檬。", "error_description": "量词错误：「本」用于书，柠檬片应用量词「片」，应说「另加一片柠檬」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
