INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89544, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89544, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在原有的基础上再增加。", "primary_collocate": null, "pronunciation": "lìng jiā", "ipa": "liŋ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "车费是十元，另加五元服务费。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租之外，另加水电费。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资之外，公司另加了奖金。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门票五十元，另加保险费十元。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个价格不含运费，要另加。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在作业里另加了一道题。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛另加了一场。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这周老师另加了两节课。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基本工资另加奖金，一共六千。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学费之外，还要另加书本费。", "target_word": "另加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "另加了", "label": "体标"}], "register": "中性", "sense_fingerprint": "在原有数目或项目的基础上再增加", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd51ad7a1-a286-491d-9bbd-bb1f05a74ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能与「服务费」搭配。"}, {"text": "丢", "is_correct": false, "explanation": "语义：「丢」是遗失，与句中加收费用的意思相反。"}, {"text": "看", "is_correct": false, "explanation": "搭配：「看」不能与「服务费」搭配，句中要表示再加收的费用。"}, {"text": "另加", "is_correct": true, "explanation": "正确。「另加」指在原有的车费之外再增加五元服务费。"}], "explanations": {"吃": "搭配：「吃」的对象是食物，不能与「服务费」搭配。", "丢": "语义：「丢」是遗失，与句中加收费用的意思相反。", "看": "搭配：「看」不能与「服务费」搭配，句中要表示再加收的费用。", "另加": "正确。「另加」指在原有的车费之外再增加五元服务费。"}, "sentence_index": 0, "correct_answer": "另加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今年另加了三岁。", "explanation": "应该用〈长〉（长了三岁）。另加表示在原有数额上再加上同类的东西，不用于年龄增长。"}, {"text": "工资从六千另加到了五千。", "explanation": "应该用〈降〉。另加表示在原有数额上再增加，不表示数额减少。"}, {"text": "他把这笔钱另加花光了。", "explanation": "应该删去〈另加〉，说「他把这笔钱花光了」。另加表示增加数额，不表示把钱花掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "搭配：「喝」不能与「比赛」搭配，「喝了一场」说不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：「扔」是丢弃，与增加一场的意思相反。"}, {"text": "另加", "is_correct": true, "explanation": "正确。「另加了一场」指在原有比赛之外再增加一场。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」不用于「比赛」，「洗了一场」说不通。"}], "explanations": {"喝": "搭配：「喝」不能与「比赛」搭配，「喝了一场」说不通。", "扔": "语义：「扔」是丢弃，与增加一场的意思相反。", "另加": "正确。「另加了一场」指在原有比赛之外再增加一场。", "洗": "搭配：「洗」不用于「比赛」，「洗了一场」说不通。"}, "sentence_index": 6, "correct_answer": "另加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想把这支队伍另加到别的公司。", "explanation": "应该用〈调〉。另加表示在原有数目或项目上再增加，不表示把人调往别处。"}, {"text": "妈妈把门另加关上了。", "explanation": "应该删去〈另加〉，说「妈妈把门关上了」。另加表示在原有数目上再增加，不表示关门。"}, {"text": "他把钱另加扔了。", "explanation": "应该删去〈另加〉，说「他把钱扔了」。另加表示增加数额，不表示丢弃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个套餐另加了一只饮料。", "corrected_sentence": "这个套餐另加了一杯饮料。", "error_description": "量词错误：「饮料」应用量词「杯」，应说「另加了一杯饮料」，不能用「只」（「只」多用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个价格另加了五元了运费。", "corrected_sentence": "这个价格另加了五元运费。", "error_description": "了的位置错误：「了」只能紧跟动词「另加」，不能插在数量词「五元」和「运费」之间，应说「另加了五元运费」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
