INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89545, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89545, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通行是从一个地方走过去，没有被挡住。", "primary_collocate": null, "pronunciation": "tōng xíng", "ipa": "tʰʊŋ⁵⁵ ɕiŋ³⁵", "syllable_count": 2, "sentences": [{"text": "路修好了，大家可以放心通行。", "target_word": "通行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救护车来了，其他车都让开路让它通行。", "target_word": "通行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿灯亮了，车辆可以通行。", "target_word": "通行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条隧道今天开始通行。", "target_word": "通行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的雪扫干净了，车辆可以通行了。", "target_word": "通行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥太旧，卡车不能通行。", "target_word": "通行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察指挥车辆依次通行。", "target_word": "通行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面在修路，车子无法通行。", "target_word": "通行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路太窄，只能一辆一辆通行。", "target_word": "通行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问这条路现在能通行吗？", "target_word": "通行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "通行了", "label": "体标"}, {"form": "通行过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人或车从一处顺利走过去，没有阻挡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a716b1e6-c5ce-40f3-a6a3-7a805e3ea816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89545, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通行", "is_correct": true, "explanation": "正确。通行指人或车从一处顺利走过去，没有阻挡。"}, {"text": "同行", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，意思是同一行业的人，或一起走。"}, {"text": "通信", "is_correct": false, "explanation": "xìn（第四声）与 xíng 韵母不同（in / ing），意思是互相传递信件或消息。"}, {"text": "通性", "is_correct": false, "explanation": "xìng（第四声）与 xíng 声调不同，意思是普遍的性质。"}, {"text": "同姓", "is_correct": false, "explanation": "tóng 与 tōng 声调不同，xìng 与 xíng 声调不同，意思是姓氏相同。"}], "explanations": {"通行": "正确。通行指人或车从一处顺利走过去，没有阻挡。", "同行": "tóng（第二声）与 tōng（第一声）声调不同，意思是同一行业的人，或一起走。", "通信": "xìn（第四声）与 xíng 韵母不同（in / ing），意思是互相传递信件或消息。", "通性": "xìng（第四声）与 xíng 声调不同，意思是普遍的性质。", "同姓": "tóng 与 tōng 声调不同，xìng 与 xíng 声调不同，意思是姓氏相同。"}, "sentence_index": null, "correct_answer": "通行"}, "level_3": {"options": [{"text": "通行", "is_correct": true, "explanation": "正确。路修好了，大家可以放心通行。"}, {"text": "争吵", "is_correct": false, "explanation": "语义：“放心争吵”与“放心”的意思相矛盾，路修好了不会引起争吵。"}, {"text": "发愁", "is_correct": false, "explanation": "语义：“放心”与“发愁”语义相反，句子不通。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“放心”后面只接人可以放心去做的事，感冒不是可以放心去做的动作。"}], "explanations": {"通行": "正确。路修好了，大家可以放心通行。", "争吵": "语义：“放心争吵”与“放心”的意思相矛盾，路修好了不会引起争吵。", "发愁": "语义：“放心”与“发愁”语义相反，句子不通。", "感冒": "搭配：“放心”后面只接人可以放心去做的事，感冒不是可以放心去做的动作。"}, "sentence_index": 0, "correct_answer": "通行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们通行了这场比赛。", "explanation": "这里应该用〈参加〉。通行指人或车顺利走过去，不能带“比赛”作宾语。"}, {"text": "他每天在公园通行。", "explanation": "这里应该用〈散步〉。通行指通过，不指在公园里散步这类活动。"}, {"text": "他每天通行三本书。", "explanation": "这里应该用〈阅读〉。通行指人或车顺利走过去，不能带“书”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89545, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通行", "is_correct": true, "explanation": "正确。警察指挥车辆依次通行，车辆一辆接一辆地过去。"}, {"text": "演讲", "is_correct": false, "explanation": "配价：“演讲”的施事必须是人，车辆不能作“演讲”的主语。"}, {"text": "散步", "is_correct": false, "explanation": "语义：车辆不会散步，“车辆依次散步”与语境矛盾。"}, {"text": "生长", "is_correct": false, "explanation": "语义：车辆不会生长，“车辆依次生长”与语境完全不符。"}], "explanations": {"通行": "正确。警察指挥车辆依次通行，车辆一辆接一辆地过去。", "演讲": "配价：“演讲”的施事必须是人，车辆不能作“演讲”的主语。", "散步": "语义：车辆不会散步，“车辆依次散步”与语境矛盾。", "生长": "语义：车辆不会生长，“车辆依次生长”与语境完全不符。"}, "sentence_index": 6, "correct_answer": "通行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店每天通行到晚上十点。", "explanation": "这里应该用〈营业〉。通行指通过或被普遍使用，不指商店开门做生意。"}, {"text": "这个软件在电脑上通行得很快。", "explanation": "这里应该用〈运行〉。通行指人或车从一处顺利走过去，不指软件在电脑上工作。"}, {"text": "两家公司正在通行。", "explanation": "这里应该用〈合作〉。通行只指车辆或人在道路上通过，不用来说公司之间合作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路刚修好，车辆在正通行。", "corrected_sentence": "这条路刚修好，车辆正在通行。", "error_description": "副词错误：“正在”是一个词，不能拆开成“在正”，应说“正在通行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察指挥完以后，车辆就顺利了通行。", "corrected_sentence": "警察指挥完以后，车辆就顺利通行。", "error_description": "体标位置错误：“了”不应插在“顺利”和“通行”之间，删去后为“车辆就顺利通行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
