INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89547, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "光是让我们能看见东西的东西。太阳和灯都有。", "primary_collocate": null, "pronunciation": "guāng", "ipa": "kuɑŋ˥", "syllable_count": 1, "sentences": [{"text": "太阳给我们光和热。", "target_word": "光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天黑了，屋子里没有光。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯一开，屋里就有光了。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外有一道光照进来。", "target_word": "光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "晚上我看不见路，因为没有光。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小花需要水和光才能长大。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间的光太弱了，我看不清书。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月亮没有自己的光。", "target_word": "光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他关了灯，屋子里一点光也没有。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光从窗户照进来，房间很亮。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "束", "label": "量词"}, {"form": "灯光", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常生活中太阳、灯发出的光，让人看得见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89547, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "光", "is_correct": true, "explanation": "光（guāng）指能让人看见东西的光线，是正确答案。"}, {"text": "广", "is_correct": false, "explanation": "广（guǎng，第三声）与光（guāng，第一声）声调不同，意思是宽广、广场。"}, {"text": "逛", "is_correct": false, "explanation": "逛（guàng，第四声）与光（guāng，第一声）声调不同，意思是随意走走。"}, {"text": "官", "is_correct": false, "explanation": "官（guān）与光（guāng）韵母不同：an 与 ang，意思是官员。"}, {"text": "观", "is_correct": false, "explanation": "观（guān）与光（guāng）韵母不同：an 与 ang，意思是观看。"}], "explanations": {"光": "光（guāng）指能让人看见东西的光线，是正确答案。", "广": "广（guǎng，第三声）与光（guāng，第一声）声调不同，意思是宽广、广场。", "逛": "逛（guàng，第四声）与光（guāng，第一声）声调不同，意思是随意走走。", "官": "官（guān）与光（guāng）韵母不同：an 与 ang，意思是官员。", "观": "观（guān）与光（guāng）韵母不同：an 与 ang，意思是观看。"}, "sentence_index": null, "correct_answer": "光"}, "level_3": {"options": [{"text": "光", "is_correct": true, "explanation": "光：太阳给我们的是光和热，“光和热”是固定搭配。"}, {"text": "水", "is_correct": false, "explanation": "语义：太阳给我们的是光和热，不会给水。"}, {"text": "风", "is_correct": false, "explanation": "语义：风不是太阳给的，与“热”并列说不通。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“光和热”是固定说法，“雨和热”不成立。"}], "explanations": {"光": "光：太阳给我们的是光和热，“光和热”是固定搭配。", "水": "语义：太阳给我们的是光和热，不会给水。", "风": "语义：风不是太阳给的，与“热”并列说不通。", "雨": "搭配：“光和热”是固定说法，“雨和热”不成立。"}, "sentence_index": 0, "correct_answer": "光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窗外有一座光照进来。", "explanation": "量词错误：光不能用“座”（“座”用于山、房屋等大型固定的东西），这里应该用〈道〉或〈束〉。"}, {"text": "窗外有一首光照进来。", "explanation": "量词错误：光不能用“首”（“首”用于诗歌、歌曲等），这里应该用〈道〉或〈束〉。"}, {"text": "窗外有一场光照进来。", "explanation": "量词错误：光不能用“场”（“场”用于比赛、雨雪等事件），这里应该用〈道〉或〈束〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89547, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "光", "is_correct": true, "explanation": "光（guāng）指能让人看见东西的光线，是正确答案。"}, {"text": "关", "is_correct": false, "explanation": "关（guān）与光（guāng）韵母不同：an 与 ang，意思是关闭。"}, {"text": "冠", "is_correct": false, "explanation": "冠（guān）与光（guāng）韵母不同：an 与 ang，意思是冠军、帽子。"}, {"text": "框", "is_correct": false, "explanation": "框（kuāng）与光（guāng）声母不同：k 与 g，意思是框架。"}, {"text": "荒", "is_correct": false, "explanation": "荒（huāng）与光（guāng）声母不同：h 与 g，意思是荒地。"}], "explanations": {"光": "光（guāng）指能让人看见东西的光线，是正确答案。", "关": "关（guān）与光（guāng）韵母不同：an 与 ang，意思是关闭。", "冠": "冠（guān）与光（guāng）韵母不同：an 与 ang，意思是冠军、帽子。", "框": "框（kuāng）与光（guāng）声母不同：k 与 g，意思是框架。", "荒": "荒（huāng）与光（guāng）声母不同：h 与 g，意思是荒地。"}, "sentence_index": null, "correct_answer": "光"}, "level_3": {"options": [{"text": "光", "is_correct": true, "explanation": "光：照亮房间、让人看清书的正是光，与“我看不清书”相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音与“看不清书”无关，句子说的是看不见。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不影响看书，这里要的是能让人看见东西的东西。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“太弱了”一般不说温度，温度用“高”“低”来描述。"}], "explanations": {"光": "光：照亮房间、让人看清书的正是光，与“我看不清书”相符。", "声音": "语义：声音与“看不清书”无关，句子说的是看不见。", "味道": "语义：味道不影响看书，这里要的是能让人看见东西的东西。", "温度": "搭配：“太弱了”一般不说温度，温度用“高”“低”来描述。"}, "sentence_index": 6, "correct_answer": "光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗外有一张光照进来。", "explanation": "量词错误：光不能用“张”（“张”用于平面的东西）。这里应该用〈道〉或〈束〉。"}, {"text": "窗外有一棵光照进来。", "explanation": "量词错误：“棵”用于树木，光不能这样计量。这里应该用〈道〉或〈束〉。"}, {"text": "窗外有一把光照进来。", "explanation": "量词错误：“把”用于有柄的东西，光不能这样计量。这里应该用〈道〉或〈束〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗外照进来一只光。", "corrected_sentence": "窗外照进来一束光。", "error_description": "量词错误：“光”应搭配“束”或“道”，不能用“只”（“只”用于动物、成对的东西等）。正确说法是“窗外照进来一束光”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他关了光，屋里就没有光了。", "corrected_sentence": "他关了灯，屋里就没有光了。", "error_description": "搭配错误：“关”后面接的是灯这类光源，不能说“关光”。正确说法是“关了灯”，光是灯发出的，不能被“关”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
