INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89548, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "照在物体上，使人能看见东西的物质。", "primary_collocate": null, "pronunciation": "guāng", "ipa": "kuɑŋ˥", "syllable_count": 1, "sentences": [{"text": "光照在桌子上，桌子很亮。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了光，我们才能看见东西。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光比声音传得快。", "target_word": "光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一束光照在她的脸上。", "target_word": "光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "树叶挡住了光，地上很暗。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块玻璃能让光通过。", "target_word": "光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用手电筒的光照着路。", "target_word": "光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳的光要八分钟才能到地球。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们是因为有光才能看到颜色。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "黑暗里突然出现了一点光。", "target_word": "光", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "束", "label": "量词"}, {"form": "灯光", "label": "复合"}], "register": "中性", "sense_fingerprint": "物理意义上的光：照在物体上、传播、使人看见颜色和东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd86389b0-f4c1-4e9d-ad63-6659a36e1d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89548, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "光", "is_correct": true, "explanation": "光（guāng）指照在物体上、使人看见东西的光，是正确答案。"}, {"text": "广", "is_correct": false, "explanation": "广（guǎng，第三声）与光（guāng，第一声）声调不同，意思是宽广、广场。"}, {"text": "逛", "is_correct": false, "explanation": "逛（guàng，第四声）与光（guāng，第一声）声调不同，意思是随意走走。"}, {"text": "官", "is_correct": false, "explanation": "官（guān）与光（guāng）韵母不同：an 与 ang，意思是官员。"}, {"text": "观", "is_correct": false, "explanation": "观（guān）与光（guāng）韵母不同：an 与 ang，意思是观看。"}], "explanations": {"光": "光（guāng）指照在物体上、使人看见东西的光，是正确答案。", "广": "广（guǎng，第三声）与光（guāng，第一声）声调不同，意思是宽广、广场。", "逛": "逛（guàng，第四声）与光（guāng，第一声）声调不同，意思是随意走走。", "官": "官（guān）与光（guāng）韵母不同：an 与 ang，意思是官员。", "观": "观（guān）与光（guāng）韵母不同：an 与 ang，意思是观看。"}, "sentence_index": null, "correct_answer": "光"}, "level_3": {"options": [{"text": "光", "is_correct": true, "explanation": "光：照在桌子上使桌子变亮的正是光。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是挡住光后的暗处，不能让桌子变亮。"}, {"text": "灰尘", "is_correct": false, "explanation": "语义：灰尘不发光，句子说的是桌子变亮。"}, {"text": "烟", "is_correct": false, "explanation": "搭配：“照在桌子上”的主语应是光源，烟不能使桌子变亮。"}], "explanations": {"光": "光：照在桌子上使桌子变亮的正是光。", "影子": "语义：影子是挡住光后的暗处，不能让桌子变亮。", "灰尘": "语义：灰尘不发光，句子说的是桌子变亮。", "烟": "搭配：“照在桌子上”的主语应是光源，烟不能使桌子变亮。"}, "sentence_index": 0, "correct_answer": "光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一座光照在她的脸上。", "explanation": "量词错误：光不能用“座”（“座”用于山、房屋等大型固定的东西），这里应该用〈束〉或〈道〉。"}, {"text": "一场光照在她的脸上。", "explanation": "量词错误：光不能用“场”（“场”用于比赛、雨雪等事件），这里应该用〈束〉或〈道〉。"}, {"text": "一首光照在她的脸上。", "explanation": "量词错误：光不能用“首”（“首”用于诗歌、歌曲等），这里应该用〈束〉或〈道〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89548, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "光", "is_correct": true, "explanation": "光（guāng）指照在物体上、使人看见东西的光，是正确答案。"}, {"text": "关", "is_correct": false, "explanation": "关（guān）与光（guāng）韵母不同：an 与 ang，意思是关闭。"}, {"text": "冠", "is_correct": false, "explanation": "冠（guān）与光（guāng）韵母不同：an 与 ang，意思是冠军、帽子。"}, {"text": "框", "is_correct": false, "explanation": "框（kuāng）与光（guāng）声母不同：k 与 g，意思是框架。"}, {"text": "荒", "is_correct": false, "explanation": "荒（huāng）与光（guāng）声母不同：h 与 g，意思是荒地。"}], "explanations": {"光": "光（guāng）指照在物体上、使人看见东西的光，是正确答案。", "关": "关（guān）与光（guāng）韵母不同：an 与 ang，意思是关闭。", "冠": "冠（guān）与光（guāng）韵母不同：an 与 ang，意思是冠军、帽子。", "框": "框（kuāng）与光（guāng）声母不同：k 与 g，意思是框架。", "荒": "荒（huāng）与光（guāng）声母不同：h 与 g，意思是荒地。"}, "sentence_index": null, "correct_answer": "光"}, "level_3": {"options": [{"text": "光", "is_correct": true, "explanation": "光：手电筒发出的光才能照路，“手电筒的光”是正确搭配。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池本身不发光，不能用来照路。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水不会发光，不能用来照路。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：手电筒没有“墙壁”，墙壁也不会发光照路。"}], "explanations": {"光": "光：手电筒发出的光才能照路，“手电筒的光”是正确搭配。", "电池": "语义：电池本身不发光，不能用来照路。", "雨水": "语义：雨水不会发光，不能用来照路。", "墙壁": "语义：手电筒没有“墙壁”，墙壁也不会发光照路。"}, "sentence_index": 6, "correct_answer": "光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "黑暗里突然出现了一张光。", "explanation": "量词错误：“张”用于平面的东西，光应用〈道〉或〈束〉。"}, {"text": "黑暗里突然出现了一棵光。", "explanation": "量词错误：“棵”用于树木，光应用〈道〉或〈束〉。"}, {"text": "黑暗里突然出现了一把光。", "explanation": "量词错误：“把”用于有柄的东西，光应用〈道〉或〈束〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只光照进了屋子。", "corrected_sentence": "一束光照进了屋子。", "error_description": "量词错误：“光”应搭配“束”或“道”，不能用“只”（“只”用于动物、成对的东西等）。正确说法是“一束光照进了屋子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "太阳会光，地球上才有白天。", "corrected_sentence": "太阳会发光，地球上才有白天。", "error_description": "语法错误：“会”后面应接动词，不能直接接名词“光”，应说“会发光”。正确说法是“太阳会发光，地球上才有白天。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'caef7f98-f1fc-4e1a-89f9-2a0f13ea5637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
