INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89549, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可数是可以一个一个数出来的。", "primary_collocate": null, "pronunciation": "kě shǔ", "ipa": "kʰɤ˨˩˦ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "苹果是可数的，我们可以一个一个地数。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子和椅子都是可数的东西。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里的饺子是可数的，一共十个。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水不是可数的，不能一个一个地数。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的学生是可数的，一共二十个。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英语里，书是可数的，米饭不是。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的灯是可数的，我可以一盏一盏地数。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，人和书都是可数的。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家养的猫是可数的，一共两只。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问我，空气是不是可数的东西？", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词：事物能一个一个数出来（可计数）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89549, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可数", "is_correct": true, "explanation": "正确：可数，可以一个一个数出来。"}, {"text": "可补", "is_correct": false, "explanation": "第一个音节相同，第二个音节只有声母不同（bǔ 与 shǔ），意思是“可以补充、弥补”。"}, {"text": "可恕", "is_correct": false, "explanation": "第一个音节相同，第二个音节只有声调不同（shù 与 shǔ），意思是“可以饶恕”。"}, {"text": "客属", "is_correct": false, "explanation": "第二个音节相同，第一个音节只有声调不同（kè 与 kě），意思是“客家人的同乡或宗族”。"}, {"text": "科属", "is_correct": false, "explanation": "第二个音节相同，第一个音节的声调不同（kē 第一声与 kě 第三声），意思是生物分类中的“科”和“属”。"}], "explanations": {"可数": "正确：可数，可以一个一个数出来。", "可补": "第一个音节相同，第二个音节只有声母不同（bǔ 与 shǔ），意思是“可以补充、弥补”。", "可恕": "第一个音节相同，第二个音节只有声调不同（shù 与 shǔ），意思是“可以饶恕”。", "客属": "第二个音节相同，第一个音节只有声调不同（kè 与 kě），意思是“客家人的同乡或宗族”。", "科属": "第二个音节相同，第一个音节的声调不同（kē 第一声与 kě 第三声），意思是生物分类中的“科”和“属”。"}, "sentence_index": null, "correct_answer": "可数"}, "level_3": {"options": [{"text": "可数", "is_correct": true, "explanation": "正确：“可数”表示能一个一个数出来，与“一个一个地数”相合。"}, {"text": "无限", "is_correct": false, "explanation": "语义：“无限”表示没有尽头，无法一个一个数，与“一个一个地数”矛盾。"}, {"text": "液态", "is_correct": false, "explanation": "搭配：“液态”只用于形容液体，不能用来描述苹果。"}, {"text": "无数", "is_correct": false, "explanation": "语义：“无数”表示多得数不清，与“一个一个地数”矛盾。"}], "explanations": {"可数": "正确：“可数”表示能一个一个数出来，与“一个一个地数”相合。", "无限": "语义：“无限”表示没有尽头，无法一个一个数，与“一个一个地数”矛盾。", "液态": "搭配：“液态”只用于形容液体，不能用来描述苹果。", "无数": "语义：“无数”表示多得数不清，与“一个一个地数”矛盾。"}, "sentence_index": 0, "correct_answer": "可数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的幸福是可数的，我一个一个地数过。", "explanation": "这里“可数”被误用为〈有限〉的意思：“幸福”是抽象感受，没有一个个的单位，不能说可以一个一个数出来。"}, {"text": "快乐是可数的，我数也数不清。", "explanation": "这里“可数”与“数也数不清”相矛盾：“快乐”是抽象感受，说它能一个一个数出来，又说数不清，前后矛盾。"}, {"text": "这片海是可数的，它一望无际。", "explanation": "这里“可数”与“一望无际”相矛盾：能一个一个数出来的事物不可能无边无际；海是连成一片的整体，不能这样计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89549, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可数", "is_correct": true, "explanation": "正确：“可数”表示能一个一个数出来，与“一盏一盏地数”相合。"}, {"text": "连绵", "is_correct": false, "explanation": "语义：“连绵”表示接连不断，与“一盏一盏地数”矛盾。"}, {"text": "抽象", "is_correct": false, "explanation": "搭配：“抽象”多用于概念，不能用来描述具体的灯。"}, {"text": "无形", "is_correct": false, "explanation": "语义：“无形”表示看不见，与“一盏一盏地数”矛盾。"}], "explanations": {"可数": "正确：“可数”表示能一个一个数出来，与“一盏一盏地数”相合。", "连绵": "语义：“连绵”表示接连不断，与“一盏一盏地数”矛盾。", "抽象": "搭配：“抽象”多用于概念，不能用来描述具体的灯。", "无形": "语义：“无形”表示看不见，与“一盏一盏地数”矛盾。"}, "sentence_index": 6, "correct_answer": "可数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯牛奶是可数的，我一个一个地数了。", "explanation": "这里“可数”与〈不可数〉相混：牛奶是液体，没有一个个的单位，不能一个一个地数。"}, {"text": "这桶油是可数的，它是连在一起的一大片。", "explanation": "这里“可数”与〈不可数〉相混：油是连在一起的整体，没有一个个的单位，说它可以一个一个数出来，前后矛盾。"}, {"text": "空气是可数的，它无处不在，连成一片。", "explanation": "这里“可数”与〈不可数〉相混：空气是连成一片的气体，没有一个个的单位，说它可以一个一个数出来，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些气球是可数地，一共十个。", "corrected_sentence": "这些气球是可数的，一共十个。", "error_description": "“可数”是形容词，作谓语后面要用“的”，不用“地”；“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上的鸡蛋是可数，一共六个。", "corrected_sentence": "桌上的鸡蛋是可数的，一共六个。", "error_description": "“可数”作谓语时后面要用“的”，应写成“是可数的”；这里漏掉了“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
