INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89550, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以数得出来的。", "primary_collocate": null, "pronunciation": "kě shǔ", "ipa": "kʰɤ˨˩˦ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "来参加的人不多，是可数的。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的高楼是可数的，一只手就能数完。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的书是可数的，一共才二十本。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱是可数的，我们要省着用。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里的鱼是可数的，没有几条。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年里下雪的日子是可数的。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的好机会是可数的，一年也遇不到几次，别错过。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会的字很少，是可数的。", "target_word": "可数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的老人已经是可数的了，只剩五个。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班会游泳的人是可数的，只有三个。", "target_word": "可数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词：数量不多，数得过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89550, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可数", "is_correct": true, "explanation": "正确：可数，数量不多，数得过来。"}, {"text": "可补", "is_correct": false, "explanation": "第一个音节相同，第二个音节只有声母不同（bǔ 与 shǔ），意思是“可以补充、弥补”。"}, {"text": "可恕", "is_correct": false, "explanation": "第一个音节相同，第二个音节只有声调不同（shù 与 shǔ），意思是“可以饶恕”。"}, {"text": "客属", "is_correct": false, "explanation": "第二个音节相同，第一个音节只有声调不同（kè 与 kě），意思是“客家人的同乡或宗族”。"}, {"text": "科属", "is_correct": false, "explanation": "第二个音节相同，第一个音节的声调不同（kē 第一声与 kě 第三声），意思是生物分类中的“科”和“属”。"}], "explanations": {"可数": "正确：可数，数量不多，数得过来。", "可补": "第一个音节相同，第二个音节只有声母不同（bǔ 与 shǔ），意思是“可以补充、弥补”。", "可恕": "第一个音节相同，第二个音节只有声调不同（shù 与 shǔ），意思是“可以饶恕”。", "客属": "第二个音节相同，第一个音节只有声调不同（kè 与 kě），意思是“客家人的同乡或宗族”。", "科属": "第二个音节相同，第一个音节的声调不同（kē 第一声与 kě 第三声），意思是生物分类中的“科”和“属”。"}, "sentence_index": null, "correct_answer": "可数"}, "level_3": {"options": [{"text": "可数", "is_correct": true, "explanation": "正确：“可数”表示数量不多、数得过来，与“来参加的人不多”相合。"}, {"text": "无数", "is_correct": false, "explanation": "语义：“无数”表示很多，与“来参加的人不多”矛盾。"}, {"text": "繁多", "is_correct": false, "explanation": "语义：“繁多”表示数量很多，与“来参加的人不多”矛盾。"}, {"text": "茂盛", "is_correct": false, "explanation": "搭配：“茂盛”多形容草木，不能用来形容人。"}], "explanations": {"可数": "正确：“可数”表示数量不多、数得过来，与“来参加的人不多”相合。", "无数": "语义：“无数”表示很多，与“来参加的人不多”矛盾。", "繁多": "语义：“繁多”表示数量很多，与“来参加的人不多”矛盾。", "茂盛": "搭配：“茂盛”多形容草木，不能用来形容人。"}, "sentence_index": 0, "correct_answer": "可数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的沙子是可数的，一望无际。", "explanation": "这里“可数”表示数量少，与“一望无际”所描写的大规模矛盾，应改用〈无边无际〉或〈数不清〉。"}, {"text": "这里的人很多，是可数的，一共十万人。", "explanation": "这里“可数”表示数量少，与“一共十万人”矛盾，数量多应说〈数不清〉。"}, {"text": "湖里的水是可数的，一眼望不到边。", "explanation": "这里“可数”表示数量少，与“一眼望不到边”的大规模矛盾，应改用〈无边无际〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可数", "is_correct": true, "explanation": "正确：“可数”表示数量少、数得过来，与“别错过”所说的难得相合。"}, {"text": "常见", "is_correct": false, "explanation": "语义：“常见”表示经常出现，与“别错过”所说的难得相矛盾。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”多形容刀刃等物，不能用来形容机会。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”多形容分量，不能用来形容机会。"}], "explanations": {"可数": "正确：“可数”表示数量少、数得过来，与“别错过”所说的难得相合。", "常见": "语义：“常见”表示经常出现，与“别错过”所说的难得相矛盾。", "锋利": "搭配：“锋利”多形容刀刃等物，不能用来形容机会。", "沉重": "搭配：“沉重”多形容分量，不能用来形容机会。"}, "sentence_index": 6, "correct_answer": "可数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班会游泳的人是可数的，几乎人人都会。", "explanation": "这里“可数”表示数量少，与“几乎人人都会”矛盾，应改用〈很多〉。"}, {"text": "这片树林里的树是可数的，一望无际。", "explanation": "这里“可数”表示数量少，与“一望无际”的大规模矛盾，应改用〈数不清〉。"}, {"text": "他的烦恼是可数的，一共有五十件。", "explanation": "这里“可数”表示数量少，与“一共有五十件”矛盾，应改用〈很多〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个季节的台风是可数地，只来了两次。", "corrected_sentence": "这个季节的台风是可数的，只来了两次。", "error_description": "“可数”是形容词，作谓语后面要用“的”，不用“地”；“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年来，我收到的礼物是可数，只有三件。", "corrected_sentence": "这些年来，我收到的礼物是可数的，只有三件。", "error_description": "“可数”作谓语时后面要用“的”，应写成“是可数的”；这里漏掉了“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89551, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "撤离", "is_correct": true, "explanation": "反义：“撤离”是撤走并离开某地，与“进驻”的进入并住下来相反。"}, {"text": "研究", "is_correct": false, "explanation": "不是反义词：“研究”是探讨问题，与“进驻”没有对立关系。"}, {"text": "休息", "is_correct": false, "explanation": "不是反义词：“休息”是停止工作，与“住下来工作”不构成对立。"}, {"text": "讨论", "is_correct": false, "explanation": "不是反义词：“讨论”是交换意见，与“进驻”没有对立关系。"}], "correct_answer": "撤离", "explanations": {"撤离": "反义：“撤离”是撤走并离开某地，与“进驻”的进入并住下来相反。", "研究": "不是反义词：“研究”是探讨问题，与“进驻”没有对立关系。", "休息": "不是反义词：“休息”是停止工作，与“住下来工作”不构成对立。", "讨论": "不是反义词：“讨论”是交换意见，与“进驻”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89551, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "撤出", "is_correct": true, "explanation": "反义：“撤出”是离开某地并撤走，与“进驻”的进入并住下来相反。"}, {"text": "散步", "is_correct": false, "explanation": "不是反义词：“散步”是悠闲地走路，与“进驻”无关。"}, {"text": "建设", "is_correct": false, "explanation": "不是反义词：“建设”是修建发展，与“进驻”没有对立关系。"}, {"text": "参加", "is_correct": false, "explanation": "不是反义词：“参加”是加入活动，与“进驻”没有对立关系。"}], "correct_answer": "撤出", "explanations": {"撤出": "反义：“撤出”是离开某地并撤走，与“进驻”的进入并住下来相反。", "散步": "不是反义词：“散步”是悠闲地走路，与“进驻”无关。", "建设": "不是反义词：“建设”是修建发展，与“进驻”没有对立关系。", "参加": "不是反义词：“参加”是加入活动，与“进驻”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89551, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进驻是一队人来到一个地方，在那里住下来工作。", "primary_collocate": null, "pronunciation": "jìn zhù", "ipa": "tɕin⁵¹ ʈʂu⁵¹", "syllable_count": 2, "sentences": [{"text": "工作队进驻村子，帮农民修路。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们进驻山区学校，一住就是一年。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗队进驻了小镇。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们进驻这里的时候，天已经黑了。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查组进驻工厂，开始检查工作。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的工程队进驻了这片工地。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台的人进驻了小村子。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一队医生进驻山里，给大家看病。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们进驻这个地方以后，每天都很忙。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程队明天就进驻河边。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进驻了", "label": "体标"}, {"form": "进驻过", "label": "体标"}], "register": "书面", "sense_fingerprint": "一队人来到某地住下来工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89551, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进驻", "is_correct": true, "explanation": "正确答案：进驻（jìn zhù），指一队人来到某地住下来工作。"}, {"text": "进出", "is_correct": false, "explanation": "jìn chū 与 jìn zhù 的第二个音节声母不同（ch 与 zh），意思是进去和出来。"}, {"text": "近视", "is_correct": false, "explanation": "第二个音节 shì（第四声）与 zhù 的声母不同（sh 与 zh），意思是视力不好。"}, {"text": "禁止", "is_correct": false, "explanation": "第二个音节 zhǐ（第三声）与 zhù（第四声）声调不同，意思是不许做。"}, {"text": "近处", "is_correct": false, "explanation": "第二个音节 chù（第四声）与 zhù 的声母不同（ch 与 zh），意思是靠近的地方。"}], "explanations": {"进驻": "正确答案：进驻（jìn zhù），指一队人来到某地住下来工作。", "进出": "jìn chū 与 jìn zhù 的第二个音节声母不同（ch 与 zh），意思是进去和出来。", "近视": "第二个音节 shì（第四声）与 zhù 的声母不同（sh 与 zh），意思是视力不好。", "禁止": "第二个音节 zhǐ（第三声）与 zhù（第四声）声调不同，意思是不许做。", "近处": "第二个音节 chù（第四声）与 zhù 的声母不同（ch 与 zh），意思是靠近的地方。"}, "sentence_index": null, "correct_answer": "进驻"}, "level_3": {"options": [{"text": "种植", "is_correct": false, "explanation": "语义：“种植”是栽培植物，工作队不会去种一个村子。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：“观看”的对象是表演、比赛等，不能说观看村子。"}, {"text": "进驻", "is_correct": true, "explanation": "正确。进驻与“工作队”搭配，表示一队人来到村子住下来工作。"}, {"text": "拜访", "is_correct": false, "explanation": "搭配：“拜访”的对象是人，不能说拜访一个村子。"}], "explanations": {"种植": "语义：“种植”是栽培植物，工作队不会去种一个村子。", "观看": "搭配：“观看”的对象是表演、比赛等，不能说观看村子。", "进驻": "正确。进驻与“工作队”搭配，表示一队人来到村子住下来工作。", "拜访": "搭配：“拜访”的对象是人，不能说拜访一个村子。"}, "sentence_index": 0, "correct_answer": "进驻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天进驻了那个村子。", "explanation": "这里应该用〈路过〉。进驻指一队人来到某地住下来工作，我一个人昨天经过村子只是路过，要用路过。"}, {"text": "我们每个周末都进驻那家餐厅。", "explanation": "这里应该用〈光顾〉。进驻指一队人住下来工作，每周末去餐厅吃饭要用光顾。"}, {"text": "这些树木进驻了山坡。", "explanation": "进驻的主语应是人，树木不能进驻。这里应该用〈生长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89551, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "进驻", "is_correct": true, "explanation": "正确答案：进驻（jìn zhù），指一队人来到某地住下来工作。"}, {"text": "尽数", "is_correct": false, "explanation": "第二个音节 shù 与 zhù 的声母不同（sh 与 zh），意思是全部数过。"}, {"text": "金主", "is_correct": false, "explanation": "jīn（第一声）与 jìn 声调不同，zhǔ（第三声）与 zhù 声调不同，意思是出钱的人。"}, {"text": "金珠", "is_correct": false, "explanation": "jīn 与 jìn、zhū 与 zhù 声调都不同，意思是金色的珠子。"}], "explanations": {"进驻": "正确答案：进驻（jìn zhù），指一队人来到某地住下来工作。", "尽数": "第二个音节 shù 与 zhù 的声母不同（sh 与 zh），意思是全部数过。", "金主": "jīn（第一声）与 jìn 声调不同，zhǔ（第三声）与 zhù 声调不同，意思是出钱的人。", "金珠": "jīn 与 jìn、zhū 与 zhù 声调都不同，意思是金色的珠子。"}, "sentence_index": null, "correct_answer": "进驻"}, "level_3": {"options": [{"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”是喂养动物，与电视台的人和村子不相配。"}, {"text": "进驻", "is_correct": true, "explanation": "正确。进驻与“电视台的人”搭配，表示一队人来到村子住下来工作。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”的对象是申请、计划等，不能说批准一个村子。"}, {"text": "缴纳", "is_correct": false, "explanation": "搭配：“缴纳”的对象是税款、费用，不能说缴纳一个村子。"}], "explanations": {"饲养": "语义：“饲养”是喂养动物，与电视台的人和村子不相配。", "进驻": "正确。进驻与“电视台的人”搭配，表示一队人来到村子住下来工作。", "批准": "搭配：“批准”的对象是申请、计划等，不能说批准一个村子。", "缴纳": "搭配：“缴纳”的对象是税款、费用，不能说缴纳一个村子。"}, "sentence_index": 6, "correct_answer": "进驻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游客进驻了那座古城。", "explanation": "这里应该用〈游览〉。进驻指一队人住下来工作，游客只是观光，不能用进驻。"}, {"text": "他们每年春节都进驻老家。", "explanation": "这里应该用〈回〉。进驻指一队人来到某地住下来工作，每年春节回老家探亲要用回。"}, {"text": "孩子们进驻了游乐场。", "explanation": "这里应该用〈玩耍〉。进驻指一队人住下来工作，孩子在游乐场玩耍不能用进驻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医疗队进驻过过那个小镇。", "corrected_sentence": "医疗队进驻过那个小镇。", "error_description": "错误：“进驻过过”。“过”只能出现一次，紧跟动词，应为“医疗队进驻过那个小镇。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师们把进驻过那所学校一年。", "corrected_sentence": "老师们进驻过那所学校一年。", "error_description": "错误：“进驻”前多了“把”。正确：“老师们进驻过那所学校一年。”“把”字句须表示对宾语的处置，“进驻”不能用于“把”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
