INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89552, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "军队、机构或人员进入某地并驻扎下来。", "primary_collocate": null, "pronunciation": "jìn zhù", "ipa": "tɕin⁵¹ ʈʂu⁵¹", "syllable_count": 2, "sentences": [{"text": "军队昨天进驻了这座小城。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司下个月就要进驻新大楼。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员已经进驻现场。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们进驻了山里的小村子。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察进驻学校，保护学生。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行去年进驻了我们的城市。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队进驻边境后，那里安静了。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多商店进驻了新的商场。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者们已经进驻比赛的地方。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支部队以前进驻过这座城市。", "target_word": "进驻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进驻了", "label": "体标"}, {"form": "进驻过", "label": "体标"}], "register": "书面", "sense_fingerprint": "军队、机构或人员进入某地并驻扎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89552, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进驻", "is_correct": true, "explanation": "正确答案：进驻（jìn zhù），指军队、机构或人员进入某地并驻扎下来。"}, {"text": "进出", "is_correct": false, "explanation": "jìn chū 与 jìn zhù 的第二个音节声母不同（ch 与 zh），意思是进去和出来。"}, {"text": "近视", "is_correct": false, "explanation": "第二个音节 shì（第四声）与 zhù 的声母不同（sh 与 zh），意思是视力不好。"}, {"text": "禁止", "is_correct": false, "explanation": "第二个音节 zhǐ（第三声）与 zhù（第四声）声调不同，意思是不许做。"}, {"text": "近处", "is_correct": false, "explanation": "第二个音节 chù（第四声）与 zhù 的声母不同（ch 与 zh），意思是靠近的地方。"}], "explanations": {"进驻": "正确答案：进驻（jìn zhù），指军队、机构或人员进入某地并驻扎下来。", "进出": "jìn chū 与 jìn zhù 的第二个音节声母不同（ch 与 zh），意思是进去和出来。", "近视": "第二个音节 shì（第四声）与 zhù 的声母不同（sh 与 zh），意思是视力不好。", "禁止": "第二个音节 zhǐ（第三声）与 zhù（第四声）声调不同，意思是不许做。", "近处": "第二个音节 chù（第四声）与 zhù 的声母不同（ch 与 zh），意思是靠近的地方。"}, "sentence_index": null, "correct_answer": "进驻"}, "level_3": {"options": [{"text": "游览", "is_correct": false, "explanation": "语义：军队是来驻扎的，不是来观光的，“游览”的主体一般是游客。"}, {"text": "进驻", "is_correct": true, "explanation": "正确。进驻与“军队”搭配，表示部队进入并驻扎下来。"}, {"text": "拜访", "is_correct": false, "explanation": "搭配：“拜访”的对象是人，不能说拜访一座城市。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于衣物、身体等，不能说洗一座小城。"}], "explanations": {"游览": "语义：军队是来驻扎的，不是来观光的，“游览”的主体一般是游客。", "进驻": "正确。进驻与“军队”搭配，表示部队进入并驻扎下来。", "拜访": "搭配：“拜访”的对象是人，不能说拜访一座城市。", "洗": "搭配：“洗”用于衣物、身体等，不能说洗一座小城。"}, "sentence_index": 0, "correct_answer": "进驻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上进驻书房看书。", "explanation": "这里应该用〈待在〉。进驻指团体或机构进到某地驻扎工作，一个人在书房看书只是待在，不能用进驻。"}, {"text": "客人进驻了我们的店。", "explanation": "这里应该用〈光临〉。进驻含有驻扎、长期留下工作的意思，客人偶尔来店要用光临。"}, {"text": "这批货物进驻了仓库。", "explanation": "进驻的主语应是军队、机构或人员，货物不能进驻。这里应该用〈存放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89552, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "进驻", "is_correct": true, "explanation": "正确答案：进驻（jìn zhù），指军队、机构或人员进入某地并驻扎下来。"}, {"text": "尽数", "is_correct": false, "explanation": "第二个音节 shù 与 zhù 的声母不同（sh 与 zh），意思是全部数过。"}, {"text": "金主", "is_correct": false, "explanation": "jīn（第一声）与 jìn 声调不同，zhǔ（第三声）与 zhù 声调不同，意思是出钱的人。"}, {"text": "金珠", "is_correct": false, "explanation": "jīn 与 jìn、zhū 与 zhù 声调都不同，意思是金色的珠子。"}], "explanations": {"进驻": "正确答案：进驻（jìn zhù），指军队、机构或人员进入某地并驻扎下来。", "尽数": "第二个音节 shù 与 zhù 的声母不同（sh 与 zh），意思是全部数过。", "金主": "jīn（第一声）与 jìn 声调不同，zhǔ（第三声）与 zhù 声调不同，意思是出钱的人。", "金珠": "jīn 与 jìn、zhū 与 zhù 声调都不同，意思是金色的珠子。"}, "sentence_index": null, "correct_answer": "进驻"}, "level_3": {"options": [{"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于植物、庄稼，不能说种植边境。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：“繁殖”指生物增加后代，与部队和边境不相配。"}, {"text": "进驻", "is_correct": true, "explanation": "正确。进驻与“部队”搭配，表示部队进入边境并驻扎。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房屋，不能说装修边境。"}], "explanations": {"种植": "搭配：“种植”用于植物、庄稼，不能说种植边境。", "繁殖": "语义：“繁殖”指生物增加后代，与部队和边境不相配。", "进驻": "正确。进驻与“部队”搭配，表示部队进入边境并驻扎。", "装修": "搭配：“装修”用于房屋，不能说装修边境。"}, "sentence_index": 6, "correct_answer": "进驻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我只进驻博物馆半个小时。", "explanation": "这里应该用〈参观〉。进驻指团体或机构住下来驻扎工作，只待半小时的短暂参观要用参观。"}, {"text": "我们假期进驻了古城。", "explanation": "这里应该用〈游览〉。进驻指团体或机构住下来驻扎工作，假期去古城观光要用游览。"}, {"text": "我一个人进驻那个商场转了一下午。", "explanation": "这里应该用〈逛〉。进驻指团体或机构驻扎工作，一个人在商场转一下午只是随便看看，要用逛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们进驻过过那个山村。", "corrected_sentence": "工人们进驻过那个山村。", "error_description": "错误：“进驻过过”。“过”只能出现一次，紧跟动词，应为“工人们进驻过那个山村。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部队把进驻过那个小镇。", "corrected_sentence": "部队进驻过那个小镇。", "error_description": "错误：“进驻”前多了“把”。正确：“部队进驻过那个小镇。”“把”字句须表示对宾语的处置，“进驻”不能用于“把”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
