INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89553, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "兼是一个人同时做两件事。", "primary_collocate": null, "pronunciation": "jiān", "ipa": "tɕjɛn˥", "syllable_count": 1, "sentences": [{"text": "他白天上班,晚上兼做家教。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老师教数学,还兼着班主任。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在店里卖衣服,也兼管收钱。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王读书的时候兼做过服务员。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是司机，下班后也兼做快递员。", "target_word": "兼", "complexity_tier": "T3", "furigana": "tā shì sījī, xiàbān hòu yě jiān zuò kuàidìyuán.", "sentence_source": "generated"}, {"text": "我白天上班,周末兼做翻译。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在家工作，还兼管家务。", "target_word": "兼", "complexity_tier": "T3", "furigana": "māma zài jiā gōngzuò, hái jiān guǎn jiāwù.", "sentence_source": "generated"}, {"text": "校长忙的时候,也兼教一节课。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理太忙,秘书兼管会议的事。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在医院工作,休息日兼做志愿者。", "target_word": "兼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兼着", "label": "体标"}, {"form": "兼了", "label": "体标"}, {"form": "兼职", "label": "复合"}, {"form": "兼任", "label": "复合"}], "register": "书面", "sense_fingerprint": "兼:同时做另一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb4c8f47-f9b5-4427-b6c0-3ded0add6b63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89553, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兼", "is_correct": true, "explanation": "兼（jiān）：同时做另一件事，是正确答案。"}, {"text": "减", "is_correct": false, "explanation": "减（jiǎn，第三声）与 jiān（第一声）声调不同，意思是减少。"}, {"text": "建", "is_correct": false, "explanation": "建（jiàn，第四声）与 jiān（第一声）声调不同，意思是建立。"}, {"text": "江", "is_correct": false, "explanation": "江（jiāng）与 jiān 的韵母 an/ang 不同，意思是江河。"}, {"text": "千", "is_correct": false, "explanation": "千（qiān）与 jiān 的声母 j/q 不同，意思是一千。"}], "explanations": {"兼": "兼（jiān）：同时做另一件事，是正确答案。", "减": "减（jiǎn，第三声）与 jiān（第一声）声调不同，意思是减少。", "建": "建（jiàn，第四声）与 jiān（第一声）声调不同，意思是建立。", "江": "江（jiāng）与 jiān 的韵母 an/ang 不同，意思是江河。", "千": "千（qiān）与 jiān 的声母 j/q 不同，意思是一千。"}, "sentence_index": null, "correct_answer": "兼"}, "level_3": {"options": [{"text": "兼", "is_correct": true, "explanation": "正确：「兼做」表示同时做另一件事，与白天上班、晚上做家教的语境相符。"}, {"text": "辞", "is_correct": false, "explanation": "搭配：「辞」多用于辞职、辞去职务，「辞做家教」不成词，也与白天上班的语境冲突。"}, {"text": "拒", "is_correct": false, "explanation": "语义：「拒做」表示拒绝去做，「晚上拒做家教」与句中做家教的意思相反。"}, {"text": "停", "is_correct": false, "explanation": "语义：「停做」表示停止，与「白天上班，晚上兼做」的并行意思相反。"}], "explanations": {"兼": "正确：「兼做」表示同时做另一件事，与白天上班、晚上做家教的语境相符。", "辞": "搭配：「辞」多用于辞职、辞去职务，「辞做家教」不成词，也与白天上班的语境冲突。", "拒": "语义：「拒做」表示拒绝去做，「晚上拒做家教」与句中做家教的意思相反。", "停": "语义：「停做」表示停止，与「白天上班，晚上兼做」的并行意思相反。"}, "sentence_index": 0, "correct_answer": "兼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我兼了一个苹果。", "explanation": "这里应该用〈吃〉。「兼」不能接具体食物作宾语，吃苹果要说〈吃〉。"}, {"text": "这家公司兼了那家小厂。", "explanation": "这里应该用〈兼并〉。「兼」单用不表示「吞并、收购」，要说「兼并」。"}, {"text": "他兼了一件新衣服。", "explanation": "这里应该用〈穿〉。「兼」不表示穿着，穿新衣服要说〈穿〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89553, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "兼", "is_correct": true, "explanation": "兼（jiān）：同时做另一件事，是正确答案。"}, {"text": "剑", "is_correct": false, "explanation": "剑（jiàn，第四声）与 jiān（第一声）声调不同，意思是剑。"}, {"text": "将", "is_correct": false, "explanation": "将（jiāng）与 jiān 的韵母 an/ang 不同，意思是将要。"}, {"text": "迁", "is_correct": false, "explanation": "迁（qiān）与 jiān 的声母 j/q 不同，意思是迁移。"}, {"text": "检", "is_correct": false, "explanation": "检（jiǎn，第三声）与 jiān（第一声）声调不同，意思是检查。"}], "explanations": {"兼": "兼（jiān）：同时做另一件事，是正确答案。", "剑": "剑（jiàn，第四声）与 jiān（第一声）声调不同，意思是剑。", "将": "将（jiāng）与 jiān 的韵母 an/ang 不同，意思是将要。", "迁": "迁（qiān）与 jiān 的声母 j/q 不同，意思是迁移。", "检": "检（jiǎn，第三声）与 jiān（第一声）声调不同，意思是检查。"}, "sentence_index": null, "correct_answer": "兼"}, "level_3": {"options": [{"text": "兼", "is_correct": true, "explanation": "正确：「还兼管家务」表示在做妈妈工作的同时还管家务，与「还」表示增加的语义相符。"}, {"text": "请", "is_correct": false, "explanation": "搭配：「请」用于请人做事，「还请管家务」表示另找人管，与妈妈自己在家工作的语境不符。"}, {"text": "忘", "is_correct": false, "explanation": "语义：「忘」表示忘记，与「还」所表示的增加承担语义矛盾。"}, {"text": "躲", "is_correct": false, "explanation": "语义：「躲」表示躲避，与「还管家务」的承担语义相反。"}], "explanations": {"兼": "正确：「还兼管家务」表示在做妈妈工作的同时还管家务，与「还」表示增加的语义相符。", "请": "搭配：「请」用于请人做事，「还请管家务」表示另找人管，与妈妈自己在家工作的语境不符。", "忘": "语义：「忘」表示忘记，与「还」所表示的增加承担语义矛盾。", "躲": "语义：「躲」表示躲避，与「还管家务」的承担语义相反。"}, "sentence_index": 6, "correct_answer": "兼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去超市兼了一本书。", "explanation": "这里应该用〈买〉。「兼」不能直接接具体物品作宾语，去超市买书要说〈买〉。"}, {"text": "他下班时兼了超市。", "explanation": "这里应该用〈去〉。「兼」不能带处所作宾语，下班后去超市要说〈去〉。"}, {"text": "他家里兼了一只猫。", "explanation": "这里应该用〈养〉。「兼」不表示饲养，养猫要说〈养〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33a71714-3837-48e5-bbad-9537eeb8ec4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content,