INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89555, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "呢子是一种又厚又暖的布，用来做冬天的衣服。", "primary_collocate": null, "pronunciation": "ní zi", "ipa": "ni˧˥ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "这块呢子又厚又暖。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用呢子给我做了一件大衣。", "target_word": "呢子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我喜欢穿呢子外套。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种呢子摸起来很软。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里有各种颜色的呢子。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶买了两米呢子做裤子。", "target_word": "呢子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "呢子比一般的布贵一些。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雪了，他穿上呢子大衣出门。", "target_word": "呢子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条呢子裙子穿着很暖和。", "target_word": "呢子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一块灰色的呢子。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "呢子大衣", "label": "复合"}, {"form": "呢子外套", "label": "复合"}], "register": "口语", "sense_fingerprint": "做冬衣的厚暖布料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89555, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "呢子", "is_correct": true, "explanation": "呢子（ní zi）：一种又厚又暖的布，用来做冬天的衣服。"}, {"text": "梨子", "is_correct": false, "explanation": "lí 与 ní 声母不同（l／n），意思是梨子（水果）。"}, {"text": "离子", "is_correct": false, "explanation": "lí 与 ní 声母不同（l／n），意思是离子（化学概念）。"}, {"text": "腻子", "is_correct": false, "explanation": "nì（第四声）与 ní（第二声）声调不同，意思是腻子（一种刮墙用的材料）。"}], "explanations": {"呢子": "呢子（ní zi）：一种又厚又暖的布，用来做冬天的衣服。", "梨子": "lí 与 ní 声母不同（l／n），意思是梨子（水果）。", "离子": "lí 与 ní 声母不同（l／n），意思是离子（化学概念）。", "腻子": "nì（第四声）与 ní（第二声）声调不同，意思是腻子（一种刮墙用的材料）。"}, "sentence_index": null, "correct_answer": "呢子"}, "level_3": {"options": [{"text": "呢子", "is_correct": true, "explanation": "正确。“块”用于成块的布料，呢子又厚又暖，符合句意。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块不能用“又厚又暖”来形容，与句中的描述冲突。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是透明的硬质材料，不能用“又厚又暖”来形容，与句意冲突。"}, {"text": "毛衣", "is_correct": false, "explanation": "搭配：量词“块”不用于衣服，应说“件”，“这块毛衣”不成立。"}], "explanations": {"呢子": "正确。“块”用于成块的布料，呢子又厚又暖，符合句意。", "冰块": "语义：冰块不能用“又厚又暖”来形容，与句中的描述冲突。", "玻璃": "语义：玻璃是透明的硬质材料，不能用“又厚又暖”来形容，与句意冲突。", "毛衣": "搭配：量词“块”不用于衣服，应说“件”，“这块毛衣”不成立。"}, "sentence_index": 0, "correct_answer": "呢子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用呢子织了一件毛衣。", "explanation": "这里应该用〈毛线〉。呢子已经是织好的布料，不能再用来“织”；“织”的对象是毛线、绒线等纱线。"}, {"text": "她用呢子写了一封信。", "explanation": "这里应该用〈信纸〉。呢子是布料，不能用来写字，写信要用信纸。"}, {"text": "我买了一根呢子。", "explanation": "这里应该用〈块〉或〈米〉。呢子是成块的布料，量词不用“根”，“根”用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呢子", "is_correct": true, "explanation": "正确。呢子是较贵的布料，与“比一般的布贵一些”相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气没有价格可以比较，与句中的“贵”冲突。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子不是商品，无法比较价格。"}, {"text": "皮肤", "is_correct": false, "explanation": "搭配：“贵”用于商品价格，“皮肤”不能拿来比价钱。"}], "explanations": {"呢子": "正确。呢子是较贵的布料，与“比一般的布贵一些”相符。", "空气": "语义：空气没有价格可以比较，与句中的“贵”冲突。", "蚊子": "语义：蚊子不是商品，无法比较价格。", "皮肤": "搭配：“贵”用于商品价格，“皮肤”不能拿来比价钱。"}, "sentence_index": 6, "correct_answer": "呢子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用呢子煮了一锅汤。", "explanation": "这里应该用〈水〉。呢子是布料，不能用来煮汤。"}, {"text": "我戴上呢子去散步。", "explanation": "这里应该用〈手套〉。呢子是布料，不能戴在手上。"}, {"text": "他骑着呢子去上班。", "explanation": "这里应该用〈自行车〉。呢子是布料，不能骑，“骑”的对象是自行车、摩托车等交通工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她买了一只呢子做外套。", "corrected_sentence": "她买了一块呢子做外套。", "error_description": "“呢子”是成块的布料，量词应用“块”，不能用“只”（“只”多用于动物或成对物品中的一个）。正确：一块呢子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了三本呢子做裤子。", "corrected_sentence": "他买了三米呢子做裤子。", "error_description": "“呢子”是布料，按长度买时用“米”，不能用“本”（“本”用于书、本子）。正确：三米呢子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
