INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种较厚的毛织品，多用来做外衣。", "primary_collocate": null, "pronunciation": "ní zi", "ipa": "ni˧˥ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "这件外衣是呢子做的。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种呢子是用羊毛织的。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸有一件黑色的呢子大衣。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "呢子不太好洗，要送到店里。", "target_word": "呢子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把呢子外套挂在门后。", "target_word": "呢子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门做呢子。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "呢子做的外衣冬天穿最好。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块蓝呢子很结实。", "target_word": "呢子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师穿着一件旧呢子上衣。", "target_word": "呢子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把呢子大衣放进了柜子。", "target_word": "呢子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "呢子大衣", "label": "复合"}, {"form": "呢子外套", "label": "复合"}], "register": "口语", "sense_fingerprint": "较厚的毛织品、多做外衣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89556, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "呢子", "is_correct": true, "explanation": "呢子（ní zi）：较厚的毛织品，多用来做外衣。"}, {"text": "梨子", "is_correct": false, "explanation": "lí 与 ní 声母不同（l／n），意思是梨子（水果）。"}, {"text": "离子", "is_correct": false, "explanation": "lí 与 ní 声母不同（l／n），意思是离子（化学概念）。"}, {"text": "腻子", "is_correct": false, "explanation": "nì（第四声）与 ní（第二声）声调不同，意思是腻子（一种刮墙用的材料）。"}], "explanations": {"呢子": "呢子（ní zi）：较厚的毛织品，多用来做外衣。", "梨子": "lí 与 ní 声母不同（l／n），意思是梨子（水果）。", "离子": "lí 与 ní 声母不同（l／n），意思是离子（化学概念）。", "腻子": "nì（第四声）与 ní（第二声）声调不同，意思是腻子（一种刮墙用的材料）。"}, "sentence_index": null, "correct_answer": "呢子"}, "level_3": {"options": [{"text": "呢子", "is_correct": true, "explanation": "正确。呢子是较厚的毛织品，多用来做外衣，符合句意。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能用来做外衣。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：泥土不能用来做外衣，与句意冲突。"}, {"text": "纸板", "is_correct": false, "explanation": "语义：纸板硬而脆，不能用来做外衣。"}], "explanations": {"呢子": "正确。呢子是较厚的毛织品，多用来做外衣，符合句意。", "玻璃": "语义：玻璃不能用来做外衣。", "泥土": "语义：泥土不能用来做外衣，与句意冲突。", "纸板": "语义：纸板硬而脆，不能用来做外衣。"}, "sentence_index": 0, "correct_answer": "呢子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我织了一件呢子。", "explanation": "这里应该用〈毛衣〉。呢子是已经织好的布料，不能再用“织”做成衣服。"}, {"text": "他用呢子给汽车加油。", "explanation": "这里应该用〈汽油〉。呢子是布料，不能用来给汽车加油。"}, {"text": "他背着呢子去上学。", "explanation": "这里应该用〈书包〉。呢子是布料，不能用来背。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呢子", "is_correct": true, "explanation": "正确。呢子保暖，冬天穿最好，符合句意。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰做的外衣冬天穿会很冷，与“冬天穿最好”矛盾。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸做的外衣不保暖，与“冬天穿最好”矛盾。"}, {"text": "海绵", "is_correct": false, "explanation": "搭配：“做外衣”要用能裁剪、能织造的布料，“海绵”不能作衣料。"}], "explanations": {"呢子": "正确。呢子保暖，冬天穿最好，符合句意。", "冰": "语义：冰做的外衣冬天穿会很冷，与“冬天穿最好”矛盾。", "纸": "语义：纸做的外衣不保暖，与“冬天穿最好”矛盾。", "海绵": "搭配：“做外衣”要用能裁剪、能织造的布料，“海绵”不能作衣料。"}, "sentence_index": 6, "correct_answer": "呢子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用呢子熬了一碗粥。", "explanation": "这里应该用〈米〉。呢子是布料，不能用来熬粥。"}, {"text": "她用呢子擦脸。", "explanation": "这里应该用〈毛巾〉。呢子是厚重的毛织布料，不用来擦脸。"}, {"text": "妈妈用呢子包饺子。", "explanation": "这里应该用〈面皮〉。呢子是布料，不能用来包饺子，包饺子要用面皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈买了一只呢子做外套。", "corrected_sentence": "妈妈买了一匹呢子做外套。", "error_description": "整卷布料计量时用“匹”，“只”用于动物或成对物品中的一个，不能用于布料。正确：一匹呢子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一本呢子做大衣。", "corrected_sentence": "我买了一块呢子做大衣。", "error_description": "“呢子”是布料，量词用“块”或“匹”，不能用“本”（“本”用于书、本子）。正确：一块呢子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
