INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89558, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "办理信件、包裹等传递及相关业务的事业。", "primary_collocate": null, "pronunciation": "yóu zhèng", "ipa": "joʊ˧˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "国家的邮政事业发展很快。", "target_word": "邮政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国邮政在很多小城市都有营业厅。", "target_word": "邮政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮政不但送信，还办理银行业务。", "target_word": "邮政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮政系统让全国的信件都能送到。", "target_word": "邮政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家邮政公司的服务很不错。", "target_word": "邮政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮政部门通知我们，明天不送包裹。", "target_word": "邮政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一辈子都在为邮政事业工作。", "target_word": "邮政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮政改革以后，寄信更方便了。", "target_word": "邮政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李在邮政系统工作，对各地地址很熟。", "target_word": "邮政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮政部门每年要处理几十亿件包裹。", "target_word": "邮政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "邮政局", "label": "复合"}, {"form": "邮政编码", "label": "复合"}], "register": "中性", "sense_fingerprint": "办理信件包裹传递及相关业务的事业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01aef012-b953-4027-8c37-cd1db6afc7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "邮政", "is_correct": true, "explanation": "正确：「国家的邮政事业」指递送信件等业务的事业，句子通顺。"}, {"text": "邮票", "is_correct": false, "explanation": "语义：邮票是物品，不是可以发展的事业，「国家的邮票事业」不成立。"}, {"text": "信箱", "is_correct": false, "explanation": "语义：信箱是存放信件的器具，不是事业领域，句子不通。"}, {"text": "包裹", "is_correct": false, "explanation": "搭配：「……事业」前的修饰语应是领域名称，「包裹」是物件，不能构成「包裹事业」。"}], "explanations": {"邮政": "正确：「国家的邮政事业」指递送信件等业务的事业，句子通顺。", "邮票": "语义：邮票是物品，不是可以发展的事业，「国家的邮票事业」不成立。", "信箱": "语义：信箱是存放信件的器具，不是事业领域，句子不通。", "包裹": "搭配：「……事业」前的修饰语应是领域名称，「包裹」是物件，不能构成「包裹事业」。"}, "sentence_index": 0, "correct_answer": "邮政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试，他的邮政很高。", "explanation": "这里应该用〈成绩〉。考试的分数才能说高；邮政是事业，不能用来表示分数。"}, {"text": "他每次都用邮政写字。", "explanation": "这里应该用〈钢笔〉。写字要用书写工具；邮政是事业，不能当作书写工具。"}, {"text": "我妹妹是个邮政，每天都很忙。", "explanation": "这里应该用〈邮递员〉。邮递员是送信的人，可以说「个邮递员」；邮政是事业，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "邮政", "is_correct": true, "explanation": "正确：「为邮政事业工作」指为递送信件等业务的事业工作，句子通顺。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是事业领域，「为钥匙事业工作」不成立。"}, {"text": "饭碗", "is_correct": false, "explanation": "语域：「饭碗」是口语词，与书面的「事业」不搭配，「为饭碗事业工作」不通。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：电灯是照明的器具，不能作为事业领域，句子不成立。"}], "explanations": {"邮政": "正确：「为邮政事业工作」指为递送信件等业务的事业工作，句子通顺。", "钥匙": "语义：钥匙不是事业领域，「为钥匙事业工作」不成立。", "饭碗": "语域：「饭碗」是口语词，与书面的「事业」不搭配，「为饭碗事业工作」不通。", "电灯": "语义：电灯是照明的器具，不能作为事业领域，句子不成立。"}, "sentence_index": 6, "correct_answer": "邮政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这封信的邮政写错了。", "explanation": "这里应该用〈邮编〉。邮编是邮政编码，写错的是编码；邮政指业务或事业，不能指编码。"}, {"text": "我把包裹放进邮政。", "explanation": "这里应该用〈包裹柜〉。包裹要放进包裹柜；邮政是事业，不是存放包裹的地方。"}, {"text": "我喜欢收藏邮政。", "explanation": "这里应该用〈邮票〉。收藏的对象是邮票；邮政是事业，不能被收藏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的很邮政事业发展得很快。", "corrected_sentence": "这座城市的邮政事业发展得很快。", "error_description": "程度副词错误：「很」不能修饰名词「邮政」，「邮政」在此作定语，应删去「很」。应说：这座城市的邮政事业发展得很快。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家的邮政了事业发展得很快。", "corrected_sentence": "这个国家的邮政事业发展得很快。", "error_description": "助词错误：「邮政」修饰「事业」时，中间不能加「了」，「了」不能用在定语位置。应说：这个国家的邮政事业发展得很快。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
