INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89559, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89559, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国字是我们国家的字，就是汉字。", "primary_collocate": null, "pronunciation": "guó zì", "ipa": "kwɔ˧˥ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "在台湾，人们常把汉字叫作国字。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国字我不认识，你能教我吗？", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子已经能认很多国字了。", "target_word": "国字", "complexity_tier": "T3", "furigana": "zhè ge hái zi yǐ jīng néng rèn hěn duō guó zì le.", "sentence_source": "generated"}, {"text": "小明正在练习写国字。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上的国字不多，孩子也能看懂。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个国字写在黑板上。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我学过很多国字，但还不会写这个。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天在家用毛笔写国字。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡片上有五个国字。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教弟弟认国字。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "我们国家的字，即汉字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89559, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国字", "is_correct": true, "explanation": "正确：国字（guó zì）指汉字。"}, {"text": "果子", "is_correct": false, "explanation": "guǒ（第三声）与 guó（第二声）声调不同，果子指水果。"}, {"text": "锅子", "is_correct": false, "explanation": "guō（第一声）与 guó（第二声）声调不同，锅子指锅。"}, {"text": "国资", "is_correct": false, "explanation": "zī（第一声）与 zì（第四声）声调不同，国资指国有资产。"}], "explanations": {"国字": "正确：国字（guó zì）指汉字。", "果子": "guǒ（第三声）与 guó（第二声）声调不同，果子指水果。", "锅子": "guō（第一声）与 guó（第二声）声调不同，锅子指锅。", "国资": "zī（第一声）与 zì（第四声）声调不同，国资指国有资产。"}, "sentence_index": null, "correct_answer": "国字"}, "level_3": {"options": [{"text": "国字", "is_correct": true, "explanation": "正确：“把汉字叫作国字”，国字指汉字，与句意相符。"}, {"text": "笔画", "is_correct": false, "explanation": "语义：笔画是汉字的组成部分，不能作为汉字的名称。"}, {"text": "部首", "is_correct": false, "explanation": "语义：部首是汉字的偏旁类别，不能作为汉字的名称。"}, {"text": "词语", "is_correct": false, "explanation": "搭配：“叫作”后要接事物的名称，“词语”是词的总称，不能指汉字。"}], "explanations": {"国字": "正确：“把汉字叫作国字”，国字指汉字，与句意相符。", "笔画": "语义：笔画是汉字的组成部分，不能作为汉字的名称。", "部首": "语义：部首是汉字的偏旁类别，不能作为汉字的名称。", "词语": "搭配：“叫作”后要接事物的名称，“词语”是词的总称，不能指汉字。"}, "sentence_index": 0, "correct_answer": "国字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外婆喜欢听国字广播。", "explanation": "这里应该用〈国语〉。国字指汉字这种文字，不能用来指广播的语言。"}, {"text": "我们国字很大。", "explanation": "这里应该用〈国家〉。国字指文字，不能指国家。"}, {"text": "我写了一把国字。", "explanation": "量词〈把〉用于有柄的东西，〈个〉用于字。这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89559, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "国字", "is_correct": true, "explanation": "正确：国字（guó zì）指汉字。"}, {"text": "活字", "is_correct": false, "explanation": "h 与 g 声母不同，活字（huó zì）指印刷用的字模。"}, {"text": "果汁", "is_correct": false, "explanation": "guǒ（第三声）与 guó（第二声）声调不同，果汁指水果榨出的汁。"}, {"text": "锅子", "is_correct": false, "explanation": "guō（第一声）与 guó（第二声）声调不同，锅子指锅。"}], "explanations": {"国字": "正确：国字（guó zì）指汉字。", "活字": "h 与 g 声母不同，活字（huó zì）指印刷用的字模。", "果汁": "guǒ（第三声）与 guó（第二声）声调不同，果汁指水果榨出的汁。", "锅子": "guō（第一声）与 guó（第二声）声调不同，锅子指锅。"}, "sentence_index": null, "correct_answer": "国字"}, "level_3": {"options": [{"text": "国字", "is_correct": true, "explanation": "正确：“学过很多国字，但还不会写这个”，国字指汉字，可以学、可以写。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“学过很多”不能修饰阳光，“学阳光”也不成立。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的物质，不能学，也不能说“学过很多空气”。"}, {"text": "清风", "is_correct": false, "explanation": "搭配：“清风”不能用“学过很多”来修饰，搭配不成立。"}], "explanations": {"国字": "正确：“学过很多国字，但还不会写这个”，国字指汉字，可以学、可以写。", "阳光": "搭配：“学过很多”不能修饰阳光，“学阳光”也不成立。", "空气": "语义：空气是无形的物质，不能学，也不能说“学过很多空气”。", "清风": "搭配：“清风”不能用“学过很多”来修饰，搭配不成立。"}, "sentence_index": 6, "correct_answer": "国字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件文物是我们的国字，要好好保护。", "explanation": "这里应该用〈国宝〉。国字指汉字，不能指珍贵的文物。"}, {"text": "学校每天都升国字。", "explanation": "这里应该用〈国旗〉。升的是旗帜，国字是文字。"}, {"text": "我们和国字朋友交流经验。", "explanation": "这里应该用〈国际〉。国字指文字，不能用来修饰“朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我这个月学会了三十只国字。", "corrected_sentence": "我这个月学会了三十个国字。", "error_description": "错误：量词“只”。正确：“个”。“只”用于动物等，“国字”是字，应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把这张国字写在纸上。", "corrected_sentence": "请把这个国字写在纸上。", "error_description": "错误：量词“张”。正确：“个”。“张”用于纸张等平面物，“国字”是字，应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
