INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89560, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "本国的文字，指汉字。", "primary_collocate": null, "pronunciation": "guó zì", "ipa": "kwɔ˧˥ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "国字是中国人用了几千年的文字。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的国字方方正正，很好看。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱学国字。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们每天抄十个国字。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是用国字写的。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国字的笔画很多，我写得很慢。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国朋友说，国字很难学。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把国字写得更漂亮。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个店名是用国字写的。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们跟着老师读国字。", "target_word": "国字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "本国的文字，指汉字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89560, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国字", "is_correct": true, "explanation": "正确：国字（guó zì）指汉字。"}, {"text": "果子", "is_correct": false, "explanation": "guǒ（第三声）与 guó（第二声）声调不同，果子指水果。"}, {"text": "锅子", "is_correct": false, "explanation": "guō（第一声）与 guó（第二声）声调不同，锅子指锅。"}, {"text": "国资", "is_correct": false, "explanation": "zī（第一声）与 zì（第四声）声调不同，国资指国有资产。"}], "explanations": {"国字": "正确：国字（guó zì）指汉字。", "果子": "guǒ（第三声）与 guó（第二声）声调不同，果子指水果。", "锅子": "guō（第一声）与 guó（第二声）声调不同，锅子指锅。", "国资": "zī（第一声）与 zì（第四声）声调不同，国资指国有资产。"}, "sentence_index": null, "correct_answer": "国字"}, "level_3": {"options": [{"text": "国字", "is_correct": true, "explanation": "正确：“国字是中国人用了几千年的文字”，国字指汉字，与句意相符。"}, {"text": "笔画", "is_correct": false, "explanation": "语义：笔画是汉字的组成部分，不是一种文字。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言是口语的地方变体，不是书面文字。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“用了几千年的文字”说的是文字，乐器不搭配这一描述。"}], "explanations": {"国字": "正确：“国字是中国人用了几千年的文字”，国字指汉字，与句意相符。", "笔画": "语义：笔画是汉字的组成部分，不是一种文字。", "方言": "语义：方言是口语的地方变体，不是书面文字。", "乐器": "搭配：“用了几千年的文字”说的是文字，乐器不搭配这一描述。"}, "sentence_index": 0, "correct_answer": "国字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他会说一口流利的国字。", "explanation": "这里应该用〈国语〉。国字指汉字，是书面文字，不能用来指说话用的语言。"}, {"text": "我们和国字朋友交流经验。", "explanation": "这里应该用〈国际〉。国字指文字，不能用来修饰“朋友”。"}, {"text": "他写了一只国字。", "explanation": "量词〈只〉用于动物，〈个〉用于字。这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89560, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "国字", "is_correct": true, "explanation": "正确：国字（guó zì）指汉字。"}, {"text": "活字", "is_correct": false, "explanation": "h 与 g 声母不同，活字（huó zì）指印刷用的字模。"}, {"text": "果汁", "is_correct": false, "explanation": "guǒ（第三声）与 guó（第二声）声调不同，果汁指水果榨出的汁。"}, {"text": "锅子", "is_correct": false, "explanation": "guō（第一声）与 guó（第二声）声调不同，锅子指锅。"}], "explanations": {"国字": "正确：国字（guó zì）指汉字。", "活字": "h 与 g 声母不同，活字（huó zì）指印刷用的字模。", "果汁": "guǒ（第三声）与 guó（第二声）声调不同，果汁指水果榨出的汁。", "锅子": "guō（第一声）与 guó（第二声）声调不同，锅子指锅。"}, "sentence_index": null, "correct_answer": "国字"}, "level_3": {"options": [{"text": "国字", "is_correct": true, "explanation": "正确：“外国朋友说，国字很难学”，国字指汉字，可以学。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗影，不是可以学习的内容。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“很难学”说的是知识或技能，“脚印”不搭配。"}, {"text": "梦境", "is_correct": false, "explanation": "语义：梦境是睡眠中的幻象，不是可以学习的东西。"}], "explanations": {"国字": "正确：“外国朋友说，国字很难学”，国字指汉字，可以学。", "影子": "语义：影子是光线形成的暗影，不是可以学习的内容。", "脚印": "搭配：“很难学”说的是知识或技能，“脚印”不搭配。", "梦境": "语义：梦境是睡眠中的幻象，不是可以学习的东西。"}, "sentence_index": 6, "correct_answer": "国字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师用国字讲课。", "explanation": "这里应该用〈国语〉。国字指文字，不能用来讲课。"}, {"text": "学校每天升国字。", "explanation": "这里应该用〈国旗〉。升的是旗帜，国字是文字。"}, {"text": "这家国字工厂很大。", "explanation": "这里应该用〈国营〉。国字指文字，不能修饰工厂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他能写很多条国字。", "corrected_sentence": "他能写很多国字。", "error_description": "错误：量词“条”。“条”用于长条形事物，不能修饰国字；这里直接用“很多”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这张国字写得很工整。", "corrected_sentence": "他把这个国字写得很工整。", "error_description": "错误：量词“张”。正确：“个”。“张”用于纸张等平面物，“国字”是字，应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
