INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89565, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国情是一个国家自己的情况。", "primary_collocate": null, "pronunciation": "guó qíng", "ipa": "kwo˧˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "每个国家的国情都不一样。", "target_word": "国情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要了解中国的国情。", "target_word": "国情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法不适合我们的国情。", "target_word": "国情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在书里介绍了很多国家的国情。", "target_word": "国情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习外国经验，也要看自己的国情。", "target_word": "国情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的国情有不同的发展路子。", "target_word": "国情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来中国以前，她看过很多关于国情的书。", "target_word": "国情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们说说自己国家的国情。", "target_word": "国情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很关心国情，每天看新闻。", "target_word": "国情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "了解国情，才能做好工作。", "target_word": "国情", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "中国国情", "label": "复合"}, {"form": "国情教育", "label": "复合"}], "register": "书面", "sense_fingerprint": "一国自身的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89565, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国情", "is_correct": true, "explanation": "正确。国情指一个国家的基本状况，各国不同，符合句意。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛属于人体，国家没有眼睛，不能用来比较各国的不同。"}, {"text": "体重", "is_correct": false, "explanation": "语义：国家没有体重，这里的比较对象不成立。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情属于个人，不能说“每个国家的心情”，与句意冲突。"}], "explanations": {"国情": "正确。国情指一个国家的基本状况，各国不同，符合句意。", "眼睛": "语义：眼睛属于人体，国家没有眼睛，不能用来比较各国的不同。", "体重": "语义：国家没有体重，这里的比较对象不成立。", "心情": "语义：心情属于个人，不能说“每个国家的心情”，与句意冲突。"}, "sentence_index": 0, "correct_answer": "国情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国的国情比日本大得多。", "explanation": "这里应该用〈国土〉。“国情”指国家的基本状况，不能说“大”；说面积要用“国土”。"}, {"text": "政府制定了新的国情。", "explanation": "这里应该用〈国策〉。国情是客观状况，不能说“制定”；制定的是国策。"}, {"text": "这个国家的国情有十三亿。", "explanation": "这里应该用〈人口〉。“有十三亿”说的是人数，国情不能计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国情", "is_correct": true, "explanation": "正确。“关于国情的书”指介绍国家基本状况的书，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "语法：“关于”后要接名词作书的主题，“很”是副词，不能作主题。"}, {"text": "下个星期", "is_correct": false, "explanation": "搭配：“关于”后要接书的主题，“下个星期”是时间词，不能作书的主题。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“关于”后要接名词作书的主题，“非常”是副词，不能作主题。"}], "explanations": {"国情": "正确。“关于国情的书”指介绍国家基本状况的书，符合句意。", "很": "语法：“关于”后要接名词作书的主题，“很”是副词，不能作主题。", "下个星期": "搭配：“关于”后要接书的主题，“下个星期”是时间词，不能作书的主题。", "非常": "语法：“关于”后要接名词作书的主题，“非常”是副词，不能作主题。"}, "sentence_index": 6, "correct_answer": "国情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上挂着一幅国情。", "explanation": "这里应该用〈地图〉。国情是抽象的状况，不能挂在墙上，也不能用“幅”来数。"}, {"text": "他一口气喝了一杯国情。", "explanation": "这里应该用〈咖啡〉。国情是抽象的状况，不能用来喝。"}, {"text": "他的国情比我的工资高。", "explanation": "这里应该用〈收入〉。国情不能与工资比较高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要认真制定国情。", "corrected_sentence": "我们要认真了解国情。", "error_description": "国情是一个国家本来的情况，不能“制定”（制定的是政策、计划）；应说“了解国情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了各国的国情。", "corrected_sentence": "他研究了各国的国情。", "error_description": "“买”的对象是商品等物品，不能说“买国情”；应说“研究各国的国情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
