INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89566, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家的基本状况，如历史、文化、经济等。", "primary_collocate": null, "pronunciation": "guó qíng", "ipa": "kwo˧˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这本书讲了中国的历史、文化和国情。", "target_word": "国情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开了一门国情课。", "target_word": "国情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国情包括历史、文化和经济。", "target_word": "国情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "留学生要先学习中国的国情。", "target_word": "国情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的国情很特别。", "target_word": "国情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从经济看国情，可以知道它的发展水平。", "target_word": "国情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是研究国情的专家。", "target_word": "国情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者用一年时间调查了国情。", "target_word": "国情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国情不同，办法也不同。", "target_word": "国情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次活动让孩子们认识了国情。", "target_word": "国情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中国国情", "label": "复合"}, {"form": "国情教育", "label": "复合"}], "register": "书面", "sense_fingerprint": "一国历史文化经济等基本状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75989926-2000-4579-bc3e-ef612459992c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国情", "is_correct": true, "explanation": "正确。国情与历史、文化并列，指国家的基本状况，符合句意。"}, {"text": "牙齿", "is_correct": false, "explanation": "语义：牙齿是人体的一部分，不能与“历史、文化”并列作为讲一个国家的书的内容。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是个人的感受，不能与历史、文化并列作为一本书的内容。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：心跳是生理现象，不能与“历史、文化”并列作书的讲述内容。"}], "explanations": {"国情": "正确。国情与历史、文化并列，指国家的基本状况，符合句意。", "牙齿": "语义：牙齿是人体的一部分，不能与“历史、文化”并列作为讲一个国家的书的内容。", "心情": "语义：心情是个人的感受，不能与历史、文化并列作为一本书的内容。", "心跳": "语义：心跳是生理现象，不能与“历史、文化”并列作书的讲述内容。"}, "sentence_index": 0, "correct_answer": "国情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国的国情有九百六十万平方公里。", "explanation": "这里应该用〈国土〉。国情指国家的基本状况，不能用来说面积。"}, {"text": "中国的国情越来越强。", "explanation": "这里应该用〈国力〉。国情不能说“强”，“强”用于国力。"}, {"text": "这个国家的国情很发达。", "explanation": "这里应该用〈经济〉。“发达”形容经济，国情不能说“发达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国情", "is_correct": true, "explanation": "正确。“研究国情的专家”指研究国家基本状况的专家，符合句意。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”是某一天，不能作研究的对象。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”是时间，不能作研究的对象。"}, {"text": "中午", "is_correct": false, "explanation": "搭配：“研究”后面要接事物或学问，“中午”是时间，不搭配。"}], "explanations": {"国情": "正确。“研究国情的专家”指研究国家基本状况的专家，符合句意。", "昨天": "语义：“昨天”是某一天，不能作研究的对象。", "下午": "语义：“下午”是时间，不能作研究的对象。", "中午": "搭配：“研究”后面要接事物或学问，“中午”是时间，不搭配。"}, "sentence_index": 6, "correct_answer": "国情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位作家的国情很大。", "explanation": "这里应该用〈名声〉。国情不能说“大”，形容名声才用“大”。"}, {"text": "这首民歌的国情很好听。", "explanation": "这里应该用〈旋律〉。“好听”形容声音、旋律，国情是国家的基本状况，不能说好听。"}, {"text": "这只小狗的国情很可爱。", "explanation": "这里应该用〈样子〉。“可爱”形容外表或神态，国情指国家的基本状况，不能说可爱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她吃了国情。", "corrected_sentence": "她了解了国情。", "error_description": "“吃”的对象是食物，不能说“吃国情”；应说“了解国情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把国情煮得很透。", "corrected_sentence": "他把国情研究得很透。", "error_description": "“煮”的对象是食物，不能用来处理“国情”；应说“研究国情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae49c009-f4b3-4164-b8c0-cdcef9d0a099') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
