INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89567, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "半是一个东西分成相同的两块,其中的一块。", "primary_collocate": null, "pronunciation": "bàn", "ipa": "pan˥˩", "syllable_count": 1, "sentences": [{"text": "把蛋糕切成两半。", "target_word": "半", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一半给你，那一半给我。", "target_word": "半", "complexity_tier": "T3", "furigana": "zhè yí bàn gěi nǐ, nà yí bàn gěi wǒ。", "sentence_source": "generated"}, {"text": "这本书我只看了一半。", "target_word": "半", "complexity_tier": "T3", "furigana": "zhè běn shū wǒ zhǐ kàn le yí bàn。", "sentence_source": "generated"}, {"text": "苹果烂了一半。", "target_word": "一半", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把纸撕成了两半。", "target_word": "半", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个圆的一半是红色，另一半是蓝色。", "target_word": "半", "complexity_tier": "T3", "furigana": "zhè ge yuán de yí bàn shì hóngsè, lìng yí bàn shì lánsè。", "sentence_source": "generated"}, {"text": "你吃一半，我吃一半。", "target_word": "一半", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "钱已经花了一半。", "target_word": "一半", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盘子掉在地上，碎成两半。", "target_word": "半", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把西瓜分成两半。", "target_word": "半", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一半", "label": "复合"}, {"form": "两半", "label": "数量搭配"}], "register": "中性", "sense_fingerprint": "半：一个整体平分后的其中一块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4412296-5735-4d77-9af9-beeaa2149034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89567, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "半", "is_correct": true, "explanation": "bàn（第四声）意思是一个整体平分后的一块，正是目标词。"}, {"text": "盘", "is_correct": false, "explanation": "pán（第二声）与 bàn 声母不同（p／b），意思是盘子。"}, {"text": "帮", "is_correct": false, "explanation": "bāng（第一声）与 bàn 韵母不同（ang／an），声调也不同，意思是帮助。"}, {"text": "满", "is_correct": false, "explanation": "mǎn（第三声）与 bàn 声母不同（m／b），声调也不同，意思是装满的。"}, {"text": "爸", "is_correct": false, "explanation": "bà（第四声）韵母只有 a，与 bàn 的 an 不同，意思是爸爸。"}], "explanations": {"半": "bàn（第四声）意思是一个整体平分后的一块，正是目标词。", "盘": "pán（第二声）与 bàn 声母不同（p／b），意思是盘子。", "帮": "bāng（第一声）与 bàn 韵母不同（ang／an），声调也不同，意思是帮助。", "满": "mǎn（第三声）与 bàn 声母不同（m／b），声调也不同，意思是装满的。", "爸": "bà（第四声）韵母只有 a，与 bàn 的 an 不同，意思是爸爸。"}, "sentence_index": null, "correct_answer": "半"}, "level_3": {"options": [{"text": "半", "is_correct": true, "explanation": "“两半”是固定说法，表示切成的两部分，符合句子语境。"}, {"text": "滴", "is_correct": false, "explanation": "搭配：“滴”指液体的一小点，不能用来计量切开的蛋糕。"}, {"text": "粒", "is_correct": false, "explanation": "语义：“粒”指颗粒状的小东西，与切成两大块蛋糕的语境不符。"}, {"text": "颗", "is_correct": false, "explanation": "搭配：“颗”用于圆形的颗粒，不能说“切成两颗蛋糕”。"}], "explanations": {"半": "“两半”是固定说法，表示切成的两部分，符合句子语境。", "滴": "搭配：“滴”指液体的一小点，不能用来计量切开的蛋糕。", "粒": "语义：“粒”指颗粒状的小东西，与切成两大块蛋糕的语境不符。", "颗": "搭配：“颗”用于圆形的颗粒，不能说“切成两颗蛋糕”。"}, "sentence_index": 0, "correct_answer": "半"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "把蛋糕切成三半。", "explanation": "这里应该用〈三份〉。“半”只表示二分之一，把东西平均分成三份不能说“三半”。"}, {"text": "把绳子剪成三半。", "explanation": "这里应该用〈三段〉。“半”指两份中的一份，分成三段不能用“半”来说明。"}, {"text": "他把蛋糕分成了三半。", "explanation": "这里应该用〈三份〉。“一半”和“两半”只涉及二分，分成三份要用“三份”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89567, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "半", "is_correct": true, "explanation": "bàn（第四声）意思是一个整体平分后的一块，正是目标词。"}, {"text": "饭", "is_correct": false, "explanation": "fàn（第四声）与 bàn 声母不同（f／b），意思是米饭。"}, {"text": "笨", "is_correct": false, "explanation": "bèn（第四声）与 bàn 韵母不同（en／an），意思是笨拙。"}, {"text": "班", "is_correct": false, "explanation": "bān（第一声）与 bàn 声调不同，意思是班级。"}, {"text": "本", "is_correct": false, "explanation": "běn（第三声）与 bàn 的韵母和声调都不同，意思是本子。"}, {"text": "版", "is_correct": false, "explanation": "bǎn（第三声）与 bàn 声调不同，意思是版本。"}], "explanations": {"半": "bàn（第四声）意思是一个整体平分后的一块，正是目标词。", "饭": "fàn（第四声）与 bàn 声母不同（f／b），意思是米饭。", "笨": "bèn（第四声）与 bàn 韵母不同（en／an），意思是笨拙。", "班": "bān（第一声）与 bàn 声调不同，意思是班级。", "本": "běn（第三声）与 bàn 的韵母和声调都不同，意思是本子。", "版": "bǎn（第三声）与 bàn 声调不同，意思是版本。"}, "sentence_index": null, "correct_answer": "半"}, "level_3": {"options": [{"text": "一半", "is_correct": true, "explanation": "“你吃一半，我吃一半”中“一半”表示平分的一份，符合句子语境。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”指全都吃掉，与“我吃一半”合起来超出整体，逻辑矛盾。"}, {"text": "大半", "is_correct": false, "explanation": "语义：“大半”超过一半，与“我吃一半”合起来超出整体，逻辑矛盾。"}, {"text": "整个", "is_correct": false, "explanation": "搭配：“吃整个”指全部吃完，与“我吃一半”的平分说法不搭配。"}], "explanations": {"一半": "“你吃一半，我吃一半”中“一半”表示平分的一份，符合句子语境。", "全部": "语义：“全部”指全都吃掉，与“我吃一半”合起来超出整体，逻辑矛盾。", "大半": "语义：“大半”超过一半，与“我吃一半”合起来超出整体，逻辑矛盾。", "整个": "搭配：“吃整个”指全部吃完，与“我吃一半”的平分说法不搭配。"}, "sentence_index": 6, "correct_answer": "一半"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请把西瓜分成一半。", "explanation": "这里应该用〈两半〉。“分成”后要说明分出几份，“一半”只表示一份，不能说明切分的结果。"}, {"text": "请把西瓜分成半块。", "explanation": "这里应该用〈两半〉。“半块”指一块的一半，不能表示把西瓜切成的两部分。"}, {"text": "请把西瓜分成三半。", "explanation": "这里应该用〈三份〉。“半”只表示二分之一，分成三份不能说“三半”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把面包切成两的半。", "corrected_sentence": "把面包切成两半。", "error_description": "错误：“两半”中间不能插入“的”。“两的半”不成词，正确说法是“两半”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他吃了饼干的半。", "corrected_sentence": "他吃了饼干的一半。", "error_description": "错误：漏掉了数词“一”。“的半”不成立，正确说法是“的一半”，表示二分之一。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
