INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89568, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "二分之一。", "primary_collocate": null, "pronunciation": "bàn", "ipa": "pan˥˩", "syllable_count": 1, "sentences": [{"text": "我买了半个西瓜。", "target_word": "半", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝了半杯水。", "target_word": "半", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请等我半小时。", "target_word": "半", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在北京住了半年。", "target_word": "半", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌上有半块面包。", "target_word": "半", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在是三点半。", "target_word": "半", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他只吃了半碗饭。", "target_word": "半", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路有半公里长。", "target_word": "半", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给我切了半个梨。", "target_word": "半", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想要半瓶牛奶。", "target_word": "半", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "半个", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "半：二分之一，放在量词前表示一半的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4412296-5735-4d77-9af9-beeaa2149034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89568, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "半", "is_correct": true, "explanation": "bàn（第四声）意思是二分之一，正是目标词。"}, {"text": "饭", "is_correct": false, "explanation": "fàn（第四声）与 bàn 声母不同（f／b），意思是米饭。"}, {"text": "笨", "is_correct": false, "explanation": "bèn（第四声）与 bàn 韵母不同（en／an），意思是笨拙。"}, {"text": "班", "is_correct": false, "explanation": "bān（第一声）与 bàn 声调不同，意思是班级。"}, {"text": "本", "is_correct": false, "explanation": "běn（第三声）与 bàn 的韵母和声调都不同，意思是本子。"}, {"text": "版", "is_correct": false, "explanation": "bǎn（第三声）与 bàn 声调不同，意思是版本。"}], "explanations": {"半": "bàn（第四声）意思是二分之一，正是目标词。", "饭": "fàn（第四声）与 bàn 声母不同（f／b），意思是米饭。", "笨": "bèn（第四声）与 bàn 韵母不同（en／an），意思是笨拙。", "班": "bān（第一声）与 bàn 声调不同，意思是班级。", "本": "běn（第三声）与 bàn 的韵母和声调都不同，意思是本子。", "版": "bǎn（第三声）与 bàn 声调不同，意思是版本。"}, "sentence_index": null, "correct_answer": "半"}, "level_3": {"options": [{"text": "半", "is_correct": true, "explanation": "「半个西瓜」中“半”表示二分之一，后接量词“个”，符合句子语境。"}, {"text": "零", "is_correct": false, "explanation": "语义：“买了”表示已经买到，“零”表示一个也没有，二者矛盾。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是副词，不能直接修饰量词“个”，“很个西瓜”不成立。"}, {"text": "全", "is_correct": false, "explanation": "语法：“全”不能直接修饰量词“个”，应说“全部”，“全个西瓜”不成立。"}], "explanations": {"半": "「半个西瓜」中“半”表示二分之一，后接量词“个”，符合句子语境。", "零": "语义：“买了”表示已经买到，“零”表示一个也没有，二者矛盾。", "很": "语法：“很”是副词，不能直接修饰量词“个”，“很个西瓜”不成立。", "全": "语法：“全”不能直接修饰量词“个”，应说“全部”，“全个西瓜”不成立。"}, "sentence_index": 0, "correct_answer": "半"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了半只西瓜。", "explanation": "这里应该用〈个〉。西瓜不用“只”计量，应说“半个西瓜”。"}, {"text": "桌上有半只面包。", "explanation": "这里应该用〈块〉。面包是块状食物，“只”多用于动物，不用于面包。"}, {"text": "我想喝半条牛奶。", "explanation": "这里应该用〈杯〉或〈瓶〉。牛奶是液体，不用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89568, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "半", "is_correct": true, "explanation": "bàn（第四声）意思是二分之一，正是目标词。"}, {"text": "盘", "is_correct": false, "explanation": "pán（第二声）与 bàn 声母不同（p／b），意思是盘子。"}, {"text": "帮", "is_correct": false, "explanation": "bāng（第一声）与 bàn 韵母不同（ang／an），声调也不同，意思是帮助。"}, {"text": "满", "is_correct": false, "explanation": "mǎn（第三声）与 bàn 声母不同（m／b），声调也不同，意思是装满的。"}, {"text": "爸", "is_correct": false, "explanation": "bà（第四声）韵母只有 a，与 bàn 的 an 不同，意思是爸爸。"}], "explanations": {"半": "bàn（第四声）意思是二分之一，正是目标词。", "盘": "pán（第二声）与 bàn 声母不同（p／b），意思是盘子。", "帮": "bāng（第一声）与 bàn 韵母不同（ang／an），声调也不同，意思是帮助。", "满": "mǎn（第三声）与 bàn 声母不同（m／b），声调也不同，意思是装满的。", "爸": "bà（第四声）韵母只有 a，与 bàn 的 an 不同，意思是爸爸。"}, "sentence_index": null, "correct_answer": "半"}, "level_3": {"options": [{"text": "半", "is_correct": true, "explanation": "「半碗饭」中“半”表示二分之一，与量词“碗”组合，符合句子语境。"}, {"text": "整", "is_correct": false, "explanation": "语义：“整碗”指全部吃完，与“只”表示不完全的限定相矛盾。"}, {"text": "满", "is_correct": false, "explanation": "搭配：“满碗饭”指盛得满满的一碗，与“只吃了”的饭量不搭配。"}, {"text": "多", "is_correct": false, "explanation": "语义：“多碗”表示数量很多，与“只”表示少量的限定相矛盾。"}], "explanations": {"半": "「半碗饭」中“半”表示二分之一，与量词“碗”组合，符合句子语境。", "整": "语义：“整碗”指全部吃完，与“只”表示不完全的限定相矛盾。", "满": "搭配：“满碗饭”指盛得满满的一碗，与“只吃了”的饭量不搭配。", "多": "语义：“多碗”表示数量很多，与“只”表示少量的限定相矛盾。"}, "sentence_index": 6, "correct_answer": "半"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想要半成品牛奶。", "explanation": "这里的“半”表示不完整、未完成，“半成品”指加工未完成的产品，不表示二分之一。"}, {"text": "我想要半次牛奶。", "explanation": "这里应该用〈瓶〉。“次”用于动作或次数，牛奶是液体，不能用“次”计量。"}, {"text": "我想要半天牛奶。", "explanation": "这里的“半天”是一段时间，不表示牛奶的一半，用在“要牛奶”的句子里不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了半苹果。", "corrected_sentence": "我买了半个苹果。", "error_description": "错误：“半”后面漏掉了量词“个”。正确说法是“半个苹果”，“半”要和量词组合后才能修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她喝了杯半茶。", "corrected_sentence": "她喝了半杯茶。", "error_description": "错误：“半”和量词“杯”的顺序颠倒。正确说法是“半杯茶”，“半”要放在量词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d6a37-67b8-414b-a374-05b45063ddd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
