INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89569, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89569, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "酱是用豆子或果子做成的一种软软的、拿来调味的东西。", "primary_collocate": null, "pronunciation": "jiàng", "ipa": "tɕjɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "吃饺子的时候，我喜欢蘸一点酱。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗面太淡了，再加一勺酱吧。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用黄豆做了一瓶酱。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个酱放久了，有点太咸。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶家的酱是自己做的，很香。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烤肉的时候，别忘了准备酱。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用酱炒了一盘肉，很下饭。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶酱用豆子做成，味道有点辣。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在碗里放了酱，又放了葱。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的酱有两种，一种甜，一种辣。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶", "label": "量词"}, {"form": "勺", "label": "量词"}], "register": "中性", "sense_fingerprint": "用豆子或果子做的软调味品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '898186d7-746b-41f1-9872-48aa0b237dc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89569, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "酱", "is_correct": true, "explanation": "酱（第四声）是用豆子或果子做成的软软的调味品。"}, {"text": "姜", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是生姜。"}, {"text": "江", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是江河。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是讲述。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是奖励。"}, {"text": "呛", "is_correct": false, "explanation": "qiàng 与 jiàng 声母不同（q 与 j），意思是呛住。"}], "explanations": {"酱": "酱（第四声）是用豆子或果子做成的软软的调味品。", "姜": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是生姜。", "江": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是江河。", "讲": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是讲述。", "奖": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是奖励。", "呛": "qiàng 与 jiàng 声母不同（q 与 j），意思是呛住。"}, "sentence_index": null, "correct_answer": "酱"}, "level_3": {"options": [{"text": "酱", "is_correct": true, "explanation": "蘸酱是吃饺子的常见吃法，“酱”符合语境。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是食物，不能拿来蘸着吃，与“吃饺子”的语境不符。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不能蘸着吃，与“吃饺子”的语境不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能蘸着吃，与饺子的吃法不符。"}], "explanations": {"酱": "蘸酱是吃饺子的常见吃法，“酱”符合语境。", "手机": "语义：手机不是食物，不能拿来蘸着吃，与“吃饺子”的语境不符。", "纸": "语义：纸不能蘸着吃，与“吃饺子”的语境不符。", "桌子": "语义：桌子是家具，不能蘸着吃，与饺子的吃法不符。"}, "sentence_index": 0, "correct_answer": "酱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我盛了一碗酱，我慢慢喝。", "explanation": "这里应该用〈汤〉。酱是糊状的调味品，不能像汤一样“喝”；喝的是汤、粥等液体。"}, {"text": "我每天早上用酱刷牙。", "explanation": "这里应该用〈牙膏〉。酱是调味品，刷牙要用牙膏，不能用酱。"}, {"text": "妈妈用酱给我洗了头发。", "explanation": "这里应该用〈洗发水〉。酱是食用的调味品，洗头发要用洗发水，不能用酱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89569, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "酱", "is_correct": true, "explanation": "酱（第四声）是用豆子或果子做成的软软的调味品。"}, {"text": "像", "is_correct": false, "explanation": "xiàng 与 jiàng 声母不同（x 与 j），意思是“像”。"}, {"text": "向", "is_correct": false, "explanation": "xiàng 与 jiàng 声母不同（x 与 j），意思是“向”。"}, {"text": "桨", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是船桨。"}], "explanations": {"酱": "酱（第四声）是用豆子或果子做成的软软的调味品。", "像": "xiàng 与 jiàng 声母不同（x 与 j），意思是“像”。", "向": "xiàng 与 jiàng 声母不同（x 与 j），意思是“向”。", "桨": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是船桨。"}, "sentence_index": null, "correct_answer": "酱"}, "level_3": {"options": [{"text": "酱", "is_correct": true, "explanation": "用酱炒肉是常见做法，“很下饭”也与酱相合。"}, {"text": "笔", "is_correct": false, "explanation": "语义：笔不能用来炒菜，与“炒了一盘肉”的语境冲突。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不能下锅炒，与“很下饭”也对不上。"}, {"text": "水", "is_correct": false, "explanation": "搭配：炒菜一般用油，说“用水炒”不自然，也不能“很下饭”。"}], "explanations": {"酱": "用酱炒肉是常见做法，“很下饭”也与酱相合。", "笔": "语义：笔不能用来炒菜，与“炒了一盘肉”的语境冲突。", "木头": "语义：木头不能下锅炒，与“很下饭”也对不上。", "水": "搭配：炒菜一般用油，说“用水炒”不自然，也不能“很下饭”。"}, "sentence_index": 6, "correct_answer": "酱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆自行车的链条生锈了，要加一点酱。", "explanation": "这里应该用〈润滑油〉。酱是食用的调味品，给链条上油要用润滑油，不能用酱。"}, {"text": "他的钢笔写不出字了，要换一瓶酱。", "explanation": "这里应该用〈墨水〉。酱是食用的调味品，钢笔要加墨水，不能用酱。"}, {"text": "这张纸破了，我要用酱粘好。", "explanation": "这里应该用〈胶水〉。酱是食用的调味品，粘纸要用胶水，不能用酱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89569, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在饺子旁边放了一只酱。", "corrected_sentence": "妈妈在饺子旁边放了一勺酱。", "error_description": "量词错误：“只”；正确：“勺”。酱是糊状、没有固定形状的东西，不用“只”计量，应说“放了一勺酱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89569, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶一下子买了三只酱。", "corrected_sentence": "奶奶一下子买了三瓶酱。", "error_description": "量词错误：“只”；正确：“瓶”。酱是糊状、没有固定形状的东西，不用“只”计量，应说“三瓶酱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
