INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89570, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用豆、麦、果品等发酵或捣制而成的糊状调味品。", "primary_collocate": null, "pronunciation": "jiàng", "ipa": "tɕjɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "北方人爱吃面，常常配着酱一起吃。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种酱用豆子和麦子发酵做成。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师把酱倒进锅里，炒了几下。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有一碗酱，你自己蘸着吃。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里卖的酱很多，我不知道买哪种。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用筷子挑了一点酱放在饭上。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶酱已经过了期，不能吃了。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸最爱吃的菜是用酱做的。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一小碗酱，我想配着烤鸭吃。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家的酱发酵了三个月，特别香。", "target_word": "酱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "碗", "label": "量词"}, {"form": "瓶", "label": "量词"}], "register": "中性", "sense_fingerprint": "豆麦果品发酵或捣制的糊状调味品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '898186d7-746b-41f1-9872-48aa0b237dc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89570, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "酱", "is_correct": true, "explanation": "酱（第四声）是用豆、麦等发酵做成的糊状调味品。"}, {"text": "江", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是江河。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是讲述。"}, {"text": "呛", "is_correct": false, "explanation": "qiàng 与 jiàng 声母不同（q 与 j），意思是呛住。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是奖励。"}], "explanations": {"酱": "酱（第四声）是用豆、麦等发酵做成的糊状调味品。", "江": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是江河。", "讲": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是讲述。", "呛": "qiàng 与 jiàng 声母不同（q 与 j），意思是呛住。", "奖": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是奖励。"}, "sentence_index": null, "correct_answer": "酱"}, "level_3": {"options": [{"text": "酱", "is_correct": true, "explanation": "北方人吃面常配酱，“酱”符合语境。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能用来配面一起吃，与“吃”的语境不符。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是食物，不能配着面一起吃。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：“配着……一起吃”要求食物做宾语，“黑板”不能与“吃”搭配。"}], "explanations": {"酱": "北方人吃面常配酱，“酱”符合语境。", "书": "语义：书不能用来配面一起吃，与“吃”的语境不符。", "椅子": "语义：椅子不是食物，不能配着面一起吃。", "黑板": "搭配：“配着……一起吃”要求食物做宾语，“黑板”不能与“吃”搭配。"}, "sentence_index": 0, "correct_answer": "酱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我渴了，喝了一口酱。", "explanation": "这里应该用〈水〉。酱是糊状的，不能像水一样“喝”，“喝”只用于液体。"}, {"text": "这件衣服用酱洗干净了。", "explanation": "这里应该用〈洗衣粉〉。酱是食用调味品，不能用来洗衣服。"}, {"text": "夏天出门前，我要擦酱。", "explanation": "这里应该用〈防晒霜〉。酱是食用的糊状调味品，出门前擦在皮肤上的是防晒霜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89570, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "酱", "is_correct": true, "explanation": "酱（第四声）是用豆、麦等发酵做成的糊状调味品。"}, {"text": "像", "is_correct": false, "explanation": "xiàng 与 jiàng 声母不同（x 与 j），意思是“像”。"}, {"text": "向", "is_correct": false, "explanation": "xiàng 与 jiàng 声母不同（x 与 j），意思是“向”。"}, {"text": "姜", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是生姜。"}], "explanations": {"酱": "酱（第四声）是用豆、麦等发酵做成的糊状调味品。", "像": "xiàng 与 jiàng 声母不同（x 与 j），意思是“像”。", "向": "xiàng 与 jiàng 声母不同（x 与 j），意思是“向”。", "姜": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是生姜。"}, "sentence_index": null, "correct_answer": "酱"}, "level_3": {"options": [{"text": "酱", "is_correct": true, "explanation": "“这瓶酱已经过了期”语境中，“酱”是食品，符合“不能吃了”。"}, {"text": "瓶子", "is_correct": false, "explanation": "语义：瓶子是容器，不是食品，不会“过了期”，也不能吃。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不是食品，不会“过了期”，也不能吃。"}, {"text": "蜡", "is_correct": false, "explanation": "搭配：“过期”通常说食品、药品，说“蜡过了期”不自然。"}], "explanations": {"酱": "“这瓶酱已经过了期”语境中，“酱”是食品，符合“不能吃了”。", "瓶子": "语义：瓶子是容器，不是食品，不会“过了期”，也不能吃。", "花": "语义：花不是食品，不会“过了期”，也不能吃。", "蜡": "搭配：“过期”通常说食品、药品，说“蜡过了期”不自然。"}, "sentence_index": 6, "correct_answer": "酱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在画布上涂了蓝色的酱。", "explanation": "这里应该用〈颜料〉。酱是食用的糊状调味品，画布上涂的是颜料。"}, {"text": "我的手机没电了，要去买酱。", "explanation": "这里应该用〈电池〉。酱是调味品，手机没电要买的是电池。"}, {"text": "机器坏了，要换新的酱。", "explanation": "这里应该用〈零件〉。酱不是机器零件，机器坏了要换的是零件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他往碗里倒了一只酱。", "corrected_sentence": "他往碗里倒了一勺酱。", "error_description": "量词错误：“只”；正确：“勺”。酱是糊状、没有固定形状的东西，不用“只”计量，应说“倒了一勺酱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前过吃这种酱。", "corrected_sentence": "我以前吃过这种酱。", "error_description": "错误：“过吃”；正确：“吃过”。“过”要紧跟动词“吃”放在后面，应说“吃过这种酱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb88a41c-84a7-4499-9b5f-99dce7d0aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89571, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一", "is_correct": true, "explanation": "反义：单一指只有一种，与“多元”（种类多）相对。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：“迅速”说速度快，与“多元”没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "无关：“温暖”说温度或感受，与“多元”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”说明白、分明，与“多元”没有反义关系。"}], "correct_answer": "单一", "explanations": {"单一": "反义：单一指只有一种，与“多元”（种类多）相对。", "迅速": "无关：“迅速”说速度快，与“多元”没有反义关系。", "温暖": "无关：“温暖”说温度或感受，与“多元”没有反义关系。", "清楚": "无关：“清楚”说明白、分明，与“多元”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
