INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89571, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有很多种不一样的。", "primary_collocate": null, "pronunciation": "duō yuán", "ipa": "twɔ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个城市的文化很多元。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的生活方式越来越多元。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里有多元的社团活动。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢多元的音乐风格。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的朋友圈很多元，什么人都有。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的看法很多元，没有统一答案。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的人口越来越多元了。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班的学生来自多元的家庭。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在人们的选择很多元。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校提供多元的课程，学生可以自己选。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多元化", "label": "复合"}], "register": "中性", "sense_fingerprint": "多元：文化、生活、选择等种类多、各不相同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b48a4e59-1e2a-4b1f-9e51-871774232826') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89571, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多元", "is_correct": true, "explanation": "正确：多元指种类多、各不相同，正好描述这个城市的文化。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，文化不说甜。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，与文化的种类无关。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说温度，不能用来形容文化。"}], "explanations": {"多元": "正确：多元指种类多、各不相同，正好描述这个城市的文化。", "甜": "语义：“甜”说味道，文化不说甜。", "快": "语义：“快”说速度，与文化的种类无关。", "冷": "语义：“冷”说温度，不能用来形容文化。"}, "sentence_index": 0, "correct_answer": "多元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一场多元的暴雨下了一整天。", "explanation": "这里应该表达〈猛烈〉的意思。多元说事物种类多、各不相同，不能用来形容雨势的强弱。"}, {"text": "一座多元的高山矗立在眼前。", "explanation": "这里应该表达〈高〉的意思。多元说种类多，不能用来形容山的高矮。"}, {"text": "一条多元的河流在山谷里流淌。", "explanation": "这里应该表达〈宽阔〉的意思。多元说种类多，不能用来形容河面的宽窄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89571, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多元", "is_correct": true, "explanation": "正确：多元表示种类多，符合“人口越来越多元”的意思。"}, {"text": "热", "is_correct": false, "explanation": "语义：“热”说温度，人口不能说热。"}, {"text": "结实", "is_correct": false, "explanation": "体貌：“结实”形容人的身体，不用来说人口。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”说光线或颜色，人口不能说亮。"}], "explanations": {"多元": "正确：多元表示种类多，符合“人口越来越多元”的意思。", "热": "语义：“热”说温度，人口不能说热。", "结实": "体貌：“结实”形容人的身体，不用来说人口。", "亮": "搭配：“亮”说光线或颜色，人口不能说亮。"}, "sentence_index": 6, "correct_answer": "多元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一头多元的大象站在河边。", "explanation": "这里应该表达〈庞大〉的意思。多元说种类多，不能用来形容体型的大小。"}, {"text": "一只多元的蚂蚁爬过地板。", "explanation": "这里应该表达〈微小〉的意思。多元说种类多，不能用来形容体型的小。"}, {"text": "一颗多元的星星在夜空中闪烁。", "explanation": "这里应该表达〈明亮〉的意思。多元说种类多，不能用来形容星光的亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店的书很多多元，什么类型都有。", "corrected_sentence": "这家书店的书很多元，什么类型都有。", "error_description": "错误形式：“很多多元”；“很”后面多写了一个“多”。正确形式：“很多元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店提供多元地商品，顾客可以随便挑。", "corrected_sentence": "这家店提供多元的商品，顾客可以随便挑。", "error_description": "错误形式：“多元地商品”；“多元”修饰名词“商品”时要用“的”，不能用“地”。正确形式：“多元的商品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89572, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一", "is_correct": true, "explanation": "反义：单一指只有一种成分，与“多元”（由多种成分构成）相对。"}, {"text": "沉重", "is_correct": false, "explanation": "无关：“沉重”说分量大或心情压抑，与“多元”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”说光线充足，与“多元”没有反义关系。"}, {"text": "简便", "is_correct": false, "explanation": "无关：“简便”说方法容易，与“多元”没有反义关系。"}], "correct_answer": "单一", "explanations": {"单一": "反义：单一指只有一种成分，与“多元”（由多种成分构成）相对。", "沉重": "无关：“沉重”说分量大或心情压抑，与“多元”没有反义关系。", "明亮": "无关：“明亮”说光线充足，与“多元”没有反义关系。", "简便": "无关：“简便”说方法容易，与“多元”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89572, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一", "is_correct": true, "explanation": "反义：单一指只有一种成分，与“多元”（由多种成分构成）相对。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：“柔软”说质地，与“多元”没有反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "无关：“辽阔”说面积大，与“多元”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”说没有声音，与“多元”没有反义关系。"}], "correct_answer": "单一", "explanations": {"单一": "反义：单一指只有一种成分，与“多元”（由多种成分构成）相对。", "柔软": "无关：“柔软”说质地，与“多元”没有反义关系。", "辽阔": "无关：“辽阔”说面积大，与“多元”没有反义关系。", "安静": "无关：“安静”说没有声音，与“多元”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89572, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由多种成分、方面或类型构成的。", "primary_collocate": null, "pronunciation": "duō yuán", "ipa": "twɔ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这家公司的收入来源是多元的。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用多元的方法评价学生，不只看考试。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家是多元社会，有很多民族。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的股东结构很多元，有个人也有公司。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用多元标准选学生，不只看成绩。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团队的成员背景多元，来自不同行业。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的收入多元，除了工资还有稿费。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个多元的社区里有老人，也有孩子和外国人。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的产品结构很多元，吃的穿的都卖。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要多元的评价方式。", "target_word": "多元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多元化", "label": "复合"}], "register": "中性", "sense_fingerprint": "多元：结构、标准、来源等由多种成分构成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b48a4e59-1e2a-4b1f-9e51-871774232826') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89572, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多元", "is_correct": true, "explanation": "正确：多元表示由多种成分构成，符合“收入来源是多元的”的意思。"}, {"text": "红", "is_correct": false, "explanation": "体貌：“红”指颜色，收入来源没有颜色。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，来源不说快慢。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”说味道，与收入来源无关。"}], "explanations": {"多元": "正确：多元表示由多种成分构成，符合“收入来源是多元的”的意思。", "红": "体貌：“红”指颜色，收入来源没有颜色。", "快": "语义：“快”说速度，来源不说快慢。", "辣": "语义：“辣”说味道，与收入来源无关。"}, "sentence_index": 0, "correct_answer": "多元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一条多元的小溪在山间流淌。", "explanation": "这里应该表达〈细小〉的意思。多元说构成多样，不能用来形容溪流的粗细。"}, {"text": "一只多元的蝴蝶飞过花丛。", "explanation": "这里应该表达〈鲜艳〉的意思。多元说构成多样，不能用来形容蝴蝶的颜色。"}, {"text": "她的身高很多元。", "explanation": "这里应该表达〈高〉的意思。多元说构成多样，不能用来形容身高的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多元", "is_correct": true, "explanation": "正确：多元表示收入由多种成分构成，符合“除了工资还有稿费”的说明。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”说分量，收入不说重。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“湿”说水分，与收入无关。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人的体形，收入不说瘦。"}], "explanations": {"多元": "正确：多元表示收入由多种成分构成，符合“除了工资还有稿费”的说明。", "重": "语义：“重”说分量，收入不说重。", "湿": "语义：“湿”说水分，与收入无关。", "瘦": "体貌：“瘦”形容人的体形，收入不说瘦。"}, "sentence_index": 6, "correct_answer": "多元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块多元的石头很重。", "explanation": "这里应该表达〈沉重〉的意思。多元说构成多样，不能用来形容重量。"}, {"text": "一座多元的火山喷发了。", "explanation": "这里应该表达〈猛烈〉的意思。多元说构成多样，不能用来形容喷发的强烈程度。"}, {"text": "这把椅子很多元。", "explanation": "这里应该表达〈结实〉的意思。多元说构成多样，不能用来形容椅子是否坚固。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
