INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司有多元地收入来源，不只靠一种产品。", "corrected_sentence": "这家公司有多元的收入来源，不只靠一种产品。", "error_description": "错误形式：“多元地收入来源”；“多元”修饰名词时要用“的”，不能用“地”。正确形式：“多元的收入来源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
