INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89573, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "土地资源是可以种地、盖房子的地。", "primary_collocate": null, "pronunciation": "tǔ dì zī yuán", "ipa": "tʰu˨˩˦ ti˥˩ tsz̩˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "我们国家的土地资源不算少。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地资源可以用来种地，也可以盖房子。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的土地资源很丰富，大家都种粮食。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市越来越大，土地资源越来越少。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要节约土地资源，不能乱盖房子。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的土地资源少，种地很不容易。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想好好用土地资源，多盖新学校。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了土地资源，农民才能种出粮食。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，土地资源是我们生活的基础。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的土地资源所剩无几，不能再盖楼了。", "target_word": "土地资源", "complexity_tier": "T3", "furigana": "zhè lǐ de tǔ dì zī yuán suǒ shèng wú jǐ, bù néng zài gài lóu le.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词：能种地、盖房的土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89573, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土地资源", "is_correct": true, "explanation": "正确：“土地资源”指可供种地、盖房的土地，与“不算少”搭配。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”是行走时的动作或声音，不能说“国家的脚步不算少”。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是人的体液，不能归国家所有，也不能用“不算少”来计量。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”是抽象的心理状态，不能用“不算少”来计量。"}], "explanations": {"土地资源": "正确：“土地资源”指可供种地、盖房的土地，与“不算少”搭配。", "脚步": "搭配：“脚步”是行走时的动作或声音，不能说“国家的脚步不算少”。", "眼泪": "语义：眼泪是人的体液，不能归国家所有，也不能用“不算少”来计量。", "心情": "搭配：“心情”是抽象的心理状态，不能用“不算少”来计量。"}, "sentence_index": 0, "correct_answer": "土地资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在政府里有很多土地资源，办事很方便。", "explanation": "这里应该用〈关系〉。土地资源指可用于农业与建设的土地，不指人际关系，不能用来说有门路。"}, {"text": "他手里有很多土地资源，随时能拿去花。", "explanation": "这里应该用〈现金〉。土地资源指可用于农业与建设的土地，不能像钱一样随时花掉。"}, {"text": "这个村子有一棵土地资源。", "explanation": "量词〈棵〉用于树木，不能修饰土地资源。这里应该用〈片〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土地资源", "is_correct": true, "explanation": "正确：“用土地资源”指利用可用的土地，与“盖新学校”相符。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“用”不能支配“笑声”，“好好用笑声”不成立。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗影，政府不能“用”它来盖学校。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“脚印”是足迹，不能说“好好用脚印”。"}], "explanations": {"土地资源": "正确：“用土地资源”指利用可用的土地，与“盖新学校”相符。", "笑声": "搭配：“用”不能支配“笑声”，“好好用笑声”不成立。", "影子": "语义：影子是光线形成的暗影，政府不能“用”它来盖学校。", "脚印": "搭配：“脚印”是足迹，不能说“好好用脚印”。"}, "sentence_index": 6, "correct_answer": "土地资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的土地资源很多，每天都能学习。", "explanation": "这里应该用〈精力〉。土地资源指可用于农业与建设的土地，不能用来指人的体力或精神。"}, {"text": "他做土地资源生意，主要卖房子。", "explanation": "这里应该用〈地产〉。土地资源是可利用的土地总量，不是可以买卖的房地产。"}, {"text": "这块土地资源今年考试得了满分。", "explanation": "这里应该用〈学生〉。土地资源指可用于农业与建设的土地，不能参加考试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条土地资源很肥沃，适合种粮食。", "corrected_sentence": "这片土地资源很肥沃，适合种粮食。", "error_description": "错误：量词“条”。正确：“片”。“条”用于长条形事物，土地应用“片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只土地资源很大。", "corrected_sentence": "这片土地资源很大。", "error_description": "错误：量词“只”。正确：“片”。“只”用于动物等，土地是一大片，应用“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
