INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可供农业、建设等利用的土地。", "primary_collocate": null, "pronunciation": "tǔ dì zī yuán", "ipa": "tʰu˨˩˦ ti˥˩ tsz̩˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "这个地区的土地资源主要用于农业。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，要保护好土地资源。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地资源既能发展农业，也能用于建设。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府计划开发这片土地资源，用于农业和建设。", "target_word": "土地资源", "complexity_tier": "T3", "furigana": "zhèng fǔ jì huà kāi fā zhè piàn tǔ dì zī yuán, yòng yú nóng yè hé jiàn shè.", "sentence_source": "generated"}, {"text": "工厂越建越多，占用了大量土地资源。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的土地资源很紧张。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该合理利用土地资源。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的土地资源适合发展农业。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发新区需要大量土地资源。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，土地资源正在减少。", "target_word": "土地资源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词：可供农业、建设利用的土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土地资源", "is_correct": true, "explanation": "正确：“土地资源”可以“主要用于农业”，与句意相符。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪不是可用于农业的资源，不能“主要用于农业”。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“笑声”不能“用于农业”，搭配不成立。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是心理状态，不能用于农业。"}], "explanations": {"土地资源": "正确：“土地资源”可以“主要用于农业”，与句意相符。", "眼泪": "语义：眼泪不是可用于农业的资源，不能“主要用于农业”。", "笑声": "搭配：“笑声”不能“用于农业”，搭配不成立。", "心情": "语义：心情是心理状态，不能用于农业。"}, "sentence_index": 0, "correct_answer": "土地资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在单位里有很多土地资源，办事很方便。", "explanation": "这里应该用〈关系〉。土地资源指可用于农业与建设的土地，不指人际关系，不能用来说有门路。"}, {"text": "他靠做土地资源生意赚了钱。", "explanation": "这里应该用〈地产〉。土地资源是资源总称，不是可以买卖的房地产。"}, {"text": "那个村子有一座土地资源。", "explanation": "量词〈座〉用于山、楼等大型固定物，不能修饰土地资源。这里应该用〈片〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土地资源", "is_correct": true, "explanation": "正确：“合理利用土地资源”是常见搭配，与句意相符。"}, {"text": "梦境", "is_correct": false, "explanation": "语义：梦境是睡眠中的幻象，不能被“合理利用”。"}, {"text": "眼神", "is_correct": false, "explanation": "搭配：“合理利用”不能支配“眼神”。"}, {"text": "心跳", "is_correct": false, "explanation": "搭配：“心跳”是生理现象，不能说“合理利用心跳”。"}], "explanations": {"土地资源": "正确：“合理利用土地资源”是常见搭配，与句意相符。", "梦境": "语义：梦境是睡眠中的幻象，不能被“合理利用”。", "眼神": "搭配：“合理利用”不能支配“眼神”。", "心跳": "搭配：“心跳”是生理现象，不能说“合理利用心跳”。"}, "sentence_index": 6, "correct_answer": "土地资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他手里有不少土地资源，随时能拿去花。", "explanation": "这里应该用〈现金〉。土地资源指可用于农业与建设的土地，不能像钱一样随时花掉。"}, {"text": "他有很多土地资源，每天都能学习。", "explanation": "这里应该用〈精力〉。土地资源指可用于农业与建设的土地，不能用来指人的体力或精神。"}, {"text": "他每天把土地资源当早饭吃。", "explanation": "这里应该用〈面包〉。土地资源指可用于农业与建设的土地，不能当食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这头土地资源很肥沃，适合种粮食。", "corrected_sentence": "这片土地资源很肥沃，适合种粮食。", "error_description": "错误：量词“头”。正确：“片”。“头”用于牛、猪等大牲畜，土地应用“片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵土地资源已经规划好了。", "corrected_sentence": "这片土地资源已经规划好了。", "error_description": "错误：量词“棵”。正确：“片”。“棵”用于树木，土地应用“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
