INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "博士是读完大学以后继续学习研究、得到最高学位的人。", "primary_collocate": null, "pronunciation": "bó shì", "ipa": "pɔ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "那位博士读过的书，比图书馆里的还多。", "target_word": "博士", "complexity_tier": "T3", "furigana": "bó shì", "sentence_source": "generated"}, {"text": "大家都很尊敬那位博士，因为他懂得很多。", "target_word": "博士", "complexity_tier": "T3", "furigana": "bó shì", "sentence_source": "generated"}, {"text": "那位博士每天都在实验室里做研究。", "target_word": "博士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位博士的书写得又清楚又有用。", "target_word": "博士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位博士年纪很大了，还每天读书学习。", "target_word": "博士", "complexity_tier": "T3", "furigana": "bó shì", "sentence_source": "generated"}, {"text": "小王的爸爸是一位有名的博士。", "target_word": "博士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校请来一位博士给我们上课。", "target_word": "博士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是我们学校的第一位女博士。", "target_word": "博士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题，博士也想了很久。", "target_word": "博士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说那位博士会说五种语言。", "target_word": "博士", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "博士生", "label": "复合"}, {"form": "博士后", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：获得最高学位的人；位/名 博士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b85a5fef-cf91-4887-8a4f-1d7906f0a58f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "博士", "is_correct": true, "explanation": "“博士”指读书最多、学问很深的人，与“读过的书”和“那位”的人称相合。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔不会读书，“读过的书”要求施事是能阅读的人。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是场所，不能读书；“那位”也只用于指人。"}, {"text": "文盲", "is_correct": false, "explanation": "语义：“文盲”指不识字的人，与“读过的书比图书馆里的还多”矛盾。"}], "explanations": {"博士": "“博士”指读书最多、学问很深的人，与“读过的书”和“那位”的人称相合。", "钢笔": "语义：钢笔不会读书，“读过的书”要求施事是能阅读的人。", "工厂": "语义：工厂是场所，不能读书；“那位”也只用于指人。", "文盲": "语义：“文盲”指不识字的人，与“读过的书比图书馆里的还多”矛盾。"}, "sentence_index": 0, "correct_answer": "博士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那头博士每天在田里耕地，很辛苦。", "explanation": "这里应该用〈牛〉。“博士”指学问深的人，不能指耕地的牲畜。"}, {"text": "我的电脑坏了，请楼下的博士来修一下。", "explanation": "这里应该用〈师傅〉。“博士”指获得最高学位的人，修电脑的人要说“师傅”。"}, {"text": "那棵博士每天在院子里长大，很漂亮。", "explanation": "这里应该用〈树〉。“博士”指学问深的人，不能指植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "博士", "is_correct": true, "explanation": "“博士”指读书多、学问深的人，可以给学生上课，与“学校请来”和“上课”相合。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不说“一位电脑”；电脑也不能给学生上课。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来参观的人，不会给学生上课，与“上课”矛盾。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷是偷东西的人，学校请他来上课不合情理，与“给我们上课”不相合。"}], "explanations": {"博士": "“博士”指读书多、学问深的人，可以给学生上课，与“学校请来”和“上课”相合。", "电脑": "搭配：量词“位”只用于人，不说“一位电脑”；电脑也不能给学生上课。", "游客": "语义：游客是来参观的人，不会给学生上课，与“上课”矛盾。", "小偷": "语义：小偷是偷东西的人，学校请他来上课不合情理，与“给我们上课”不相合。"}, "sentence_index": 6, "correct_answer": "博士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那匹博士每天在草原上奔跑，很快。", "explanation": "这里应该用〈马〉。“博士”指学问深的人，不能指奔跑的动物。"}, {"text": "他每天早上开博士去上班。", "explanation": "这里应该用〈车〉。“博士”指人，不能开着去上班。"}, {"text": "那棵博士每天在院子里开花，很漂亮。", "explanation": "这里应该用〈树〉。“博士”指学问深的人，不能指植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只博士的讲座很受欢迎。", "corrected_sentence": "那位博士的讲座很受欢迎。", "error_description": "量词用错：指人的“博士”应用量词“位”（或“个”）。“只”只用于动物，这里把指人的“博士”当成动物来计量，应改为“那位博士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位的博士很受学生欢迎。", "corrected_sentence": "那位博士很受学生欢迎。", "error_description": "助词“的”用错：指示代词加量词修饰名词时不加“的”，应说“那位博士”，“的”不能插在量词与名词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
