INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89577, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重返是又回到以前去过的地方。", "primary_collocate": null, "pronunciation": "chóng fǎn", "ipa": "tʂʰʊŋ³⁵ fan²¹⁴", "syllable_count": 2, "sentences": [{"text": "十年后，他重返了自己的家乡。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很想重返小时候住过的小城。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人重返故地，心里很激动。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们重返了去年玩过的海边。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业二十年后，他重返校园看老师。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开北京三年，今年重返这座城市。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客重返山顶，又看了一次日出。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她重返那个小村子，一切都变了。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束了，人们重返家园。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直希望重返以前留学的国家。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重返了", "label": "体标"}, {"form": "重返过", "label": "体标"}], "register": "书面", "sense_fingerprint": "又回到以前去过的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a716b1e6-c5ce-40f3-a6a3-7a805e3ea816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89577, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重返", "is_correct": true, "explanation": "重返 chóng fǎn：再次回到以前去过的地方，是本题的正确答案。"}, {"text": "重翻", "is_correct": false, "explanation": "fān（第一声）与 fǎn（第三声）声调不同，意思是再次翻译。"}, {"text": "重犯", "is_correct": false, "explanation": "fàn（第四声）与 fǎn（第三声）声调不同，意思是再次犯罪。"}, {"text": "重版", "is_correct": false, "explanation": "bǎn（第三声）与 fǎn（第三声）声母不同：b 与 f，意思是再次出版。"}], "explanations": {"重返": "重返 chóng fǎn：再次回到以前去过的地方，是本题的正确答案。", "重翻": "fān（第一声）与 fǎn（第三声）声调不同，意思是再次翻译。", "重犯": "fàn（第四声）与 fǎn（第三声）声调不同，意思是再次犯罪。", "重版": "bǎn（第三声）与 fǎn（第三声）声母不同：b 与 f，意思是再次出版。"}, "sentence_index": null, "correct_answer": "重返"}, "level_3": {"options": [{"text": "重返", "is_correct": true, "explanation": "重返：再次回到以前去过的地方，符合“十年后”重新回到家乡的语境。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：毕业是不及物动词，后面接学校或学业，不能直接带“家乡”作宾语。"}, {"text": "出生", "is_correct": false, "explanation": "配价：出生是不及物动词，应说“出生在某地”，不能直接带“家乡”作宾语。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：拆除的对象是建筑或设施，“家乡”不能被拆除，句意说不通。"}], "explanations": {"重返": "重返：再次回到以前去过的地方，符合“十年后”重新回到家乡的语境。", "毕业": "配价：毕业是不及物动词，后面接学校或学业，不能直接带“家乡”作宾语。", "出生": "配价：出生是不及物动词，应说“出生在某地”，不能直接带“家乡”作宾语。", "拆除": "语义：拆除的对象是建筑或设施，“家乡”不能被拆除，句意说不通。"}, "sentence_index": 0, "correct_answer": "重返"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们第一次来这里，终于重返了山顶。", "explanation": "这里应该用〈到达〉。重返指再次回到去过的地方，第一次到山顶应说到达。"}, {"text": "周末我去医院重返了生病的奶奶。", "explanation": "这里应该用〈探望〉。重返只能用于地点或岗位，指人要用探望。"}, {"text": "他一生都没离开过这个城市，却重返了这里。", "explanation": "这里应该用〈留在〉。重返指离开后再次回到原处，他从未离开过，应说留在这里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89577, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "重返", "is_correct": true, "explanation": "重返 chóng fǎn：再次回到以前去过的地方，是本题的正确答案。"}, {"text": "冲犯", "is_correct": false, "explanation": "chōng（第一声）与 chóng（第二声）、fàn（第四声）与 fǎn（第三声）声调都不同，意思是冒犯。"}, {"text": "重演", "is_correct": false, "explanation": "yǎn（第三声）与 fǎn（第三声）声母不同（零声母与 f），意思是再次表演。"}, {"text": "重展", "is_correct": false, "explanation": "zhǎn（第三声）与 fǎn（第三声）声母不同：zh 与 f，意思是再次展出。"}, {"text": "重染", "is_correct": false, "explanation": "rǎn（第三声）与 fǎn（第三声）声母不同：r 与 f，意思是再次染色。"}], "explanations": {"重返": "重返 chóng fǎn：再次回到以前去过的地方，是本题的正确答案。", "冲犯": "chōng（第一声）与 chóng（第二声）、fàn（第四声）与 fǎn（第三声）声调都不同，意思是冒犯。", "重演": "yǎn（第三声）与 fǎn（第三声）声母不同（零声母与 f），意思是再次表演。", "重展": "zhǎn（第三声）与 fǎn（第三声）声母不同：zh 与 f，意思是再次展出。", "重染": "rǎn（第三声）与 fǎn（第三声）声母不同：r 与 f，意思是再次染色。"}, "sentence_index": null, "correct_answer": "重返"}, "level_3": {"options": [{"text": "重返", "is_correct": true, "explanation": "重返：再次回到以前去过的山顶，符合“又看了一次日出”的语境。"}, {"text": "诞生", "is_correct": false, "explanation": "配价：诞生是不及物动词，且“游客诞生”本身不通，不能带“山顶”作宾语。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶的对象是车辆等交通工具，“山顶”不能被驾驶。"}, {"text": "作曲", "is_correct": false, "explanation": "搭配：作曲的对象是曲子，不能说“作曲山顶”。"}], "explanations": {"重返": "重返：再次回到以前去过的山顶，符合“又看了一次日出”的语境。", "诞生": "配价：诞生是不及物动词，且“游客诞生”本身不通，不能带“山顶”作宾语。", "驾驶": "语义：驾驶的对象是车辆等交通工具，“山顶”不能被驾驶。", "作曲": "搭配：作曲的对象是曲子，不能说“作曲山顶”。"}, "sentence_index": 6, "correct_answer": "重返"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他决定重返学习。", "explanation": "这里应该用〈重新开始〉。重返只能接地点或岗位，“学习”是动作，不能作重返的宾语。"}, {"text": "他在海边重返了三天。", "explanation": "这里应该用〈停留〉。重返是回到某地，不能带“三天”这样的时段，应说停留了三天。"}, {"text": "他又重返了那次争吵，真让人头疼。", "explanation": "这里应该用〈重新爆发〉。重返只能指回到地点或岗位，不能用于争吵；争吵再次出现应说重新爆发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她十年后终于重返回了那座小城。", "corrected_sentence": "她十年后终于重返了那座小城。", "error_description": "补语多余：“重返”本身已含“再次回到”的意思，后面不能再加“回”。正确说法是“重返了那座小城”，不说“重返回了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老兵离开部队多年后，终于重返在那片战场。", "corrected_sentence": "老兵离开部队多年后，终于重返了那片战场。", "error_description": "助词错误：“重返”后接地点宾语时不能用“在”。“在”用于“住在”“放在”等，不能直接接在“重返”后。删去“在”即可，“了”可有可无，正确说法是“重返了那片战场”或“重返那片战场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
