INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89578, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "再次回到原来的地方或岗位。", "primary_collocate": null, "pronunciation": "chóng fǎn", "ipa": "tʂʰʊŋ³⁵ fan²¹⁴", "syllable_count": 2, "sentences": [{"text": "受伤的球员终于重返赛场。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她休完产假，重返工作岗位。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他病好了，重返公司上班。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师病好后重返讲台。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他决定重返原来的单位。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他很快就可以重返球队。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手想重返舞台。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李重返了原来的岗位。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长伤好后重返球场训练。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过休息，她重返了工作的地方。", "target_word": "重返", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重返了", "label": "体标"}, {"form": "重返过", "label": "体标"}], "register": "书面", "sense_fingerprint": "再次回到原来的地方或工作岗位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a716b1e6-c5ce-40f3-a6a3-7a805e3ea816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89578, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重返", "is_correct": true, "explanation": "重返 chóng fǎn：再次回到原来的地方或岗位，是本题的正确答案。"}, {"text": "重翻", "is_correct": false, "explanation": "fān（第一声）与 fǎn（第三声）声调不同，意思是再次翻译。"}, {"text": "重犯", "is_correct": false, "explanation": "fàn（第四声）与 fǎn（第三声）声调不同，意思是再次犯罪。"}, {"text": "重版", "is_correct": false, "explanation": "bǎn（第三声）与 fǎn（第三声）声母不同：b 与 f，意思是再次出版。"}, {"text": "冲犯", "is_correct": false, "explanation": "chōng（第一声）与 chóng（第二声）、fàn（第四声）与 fǎn（第三声）声调都不同，意思是冒犯。"}], "explanations": {"重返": "重返 chóng fǎn：再次回到原来的地方或岗位，是本题的正确答案。", "重翻": "fān（第一声）与 fǎn（第三声）声调不同，意思是再次翻译。", "重犯": "fàn（第四声）与 fǎn（第三声）声调不同，意思是再次犯罪。", "重版": "bǎn（第三声）与 fǎn（第三声）声母不同：b 与 f，意思是再次出版。", "冲犯": "chōng（第一声）与 chóng（第二声）、fàn（第四声）与 fǎn（第三声）声调都不同，意思是冒犯。"}, "sentence_index": null, "correct_answer": "重返"}, "level_3": {"options": [{"text": "重返", "is_correct": true, "explanation": "重返：再次回到原来的赛场，符合受伤球员伤愈后回归的语境。"}, {"text": "退役", "is_correct": false, "explanation": "配价：退役是不及物动词，后面不能直接带“赛场”作宾语。"}, {"text": "演唱", "is_correct": false, "explanation": "搭配：演唱的对象是歌曲，不能说“演唱赛场”。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶的对象是车辆，球员不能驾驶赛场。"}], "explanations": {"重返": "重返：再次回到原来的赛场，符合受伤球员伤愈后回归的语境。", "退役": "配价：退役是不及物动词，后面不能直接带“赛场”作宾语。", "演唱": "搭配：演唱的对象是歌曲，不能说“演唱赛场”。", "驾驶": "语义：驾驶的对象是车辆，球员不能驾驶赛场。"}, "sentence_index": 0, "correct_answer": "重返"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他第一次当老师，就重返了讲台。", "explanation": "这里应该用〈登上〉。重返指再次回到原来的岗位，第一次站上讲台应说登上。"}, {"text": "他去医院重返了生病的同事。", "explanation": "这里应该用〈探望〉。重返只能用于地点或岗位，指人要用探望。"}, {"text": "他从没离开过家乡，却说想重返那里。", "explanation": "这里应该用〈留在〉。重返指离开后再次回到原处，他从未离开过，应说想留在那里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89578, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "重返", "is_correct": true, "explanation": "重返 chóng fǎn：再次回到原来的地方或岗位，是本题的正确答案。"}, {"text": "重放", "is_correct": false, "explanation": "fàng（第四声，韵母 ang）与 fǎn（第三声，韵母 an）声调和韵母都不同，意思是再次播放。"}, {"text": "重演", "is_correct": false, "explanation": "yǎn（第三声）与 fǎn（第三声）声母不同（零声母与 f），意思是再次表演。"}, {"text": "重发", "is_correct": false, "explanation": "fā（第一声，无鼻音韵尾）与 fǎn（第三声）声调和韵母都不同，意思是再次发送。"}], "explanations": {"重返": "重返 chóng fǎn：再次回到原来的地方或岗位，是本题的正确答案。", "重放": "fàng（第四声，韵母 ang）与 fǎn（第三声，韵母 an）声调和韵母都不同，意思是再次播放。", "重演": "yǎn（第三声）与 fǎn（第三声）声母不同（零声母与 f），意思是再次表演。", "重发": "fā（第一声，无鼻音韵尾）与 fǎn（第三声）声调和韵母都不同，意思是再次发送。"}, "sentence_index": null, "correct_answer": "重返"}, "level_3": {"options": [{"text": "重返", "is_correct": true, "explanation": "重返：再次回到原来的舞台，符合歌手想回去的语境。"}, {"text": "出生", "is_correct": false, "explanation": "配价：出生是不及物动词，不能带“舞台”作宾语。"}, {"text": "作曲", "is_correct": false, "explanation": "搭配：作曲的对象是曲子，“想作曲舞台”搭配不当。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳需要水域，“舞台”不能用来游泳，句意说不通。"}], "explanations": {"重返": "重返：再次回到原来的舞台，符合歌手想回去的语境。", "出生": "配价：出生是不及物动词，不能带“舞台”作宾语。", "作曲": "搭配：作曲的对象是曲子，“想作曲舞台”搭配不当。", "游泳": "语义：游泳需要水域，“舞台”不能用来游泳，句意说不通。"}, "sentence_index": 6, "correct_answer": "重返"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他又重返了那个错误，真让人失望。", "explanation": "这里应该用〈再犯〉。重返只能指回到地点或岗位，不能用于错误；又犯同样的错误应说再犯。"}, {"text": "他在那里重返了两年。", "explanation": "这里应该用〈停留〉。重返是回到某地，不能带“两年”这样的时段，应说停留了两年。"}, {"text": "他每天早上都重返学校上课。", "explanation": "这里应该用〈去〉。重返指离开一段时间后再次回到原处，每天照常上学只能说去学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生说他病好后就能重返回球场。", "corrected_sentence": "医生说他病好后就能重返球场。", "error_description": "补语多余：“重返”本身已含“回到”的意思，后面不能再加“回”。正确说法是“重返球场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教练说他伤好后就能重返在赛场。", "corrected_sentence": "教练说他伤好后就能重返赛场。", "error_description": "助词多余：“重返”后直接接地点宾语，不用“在”。“在”用于“住在”“放在”等，不能接在“重返”后。正确说法是“重返赛场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
