INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89579, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家里很多人一起投票，选出最重要的领导人。", "primary_collocate": null, "pronunciation": "dà xuǎn", "ipa": "ta˥˩ ɕɥɛn˨˩", "syllable_count": 2, "sentences": [{"text": "今年国家举行大选。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大选那天，很多人排队投票。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次大选有三位候选人。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大选的结果明天公布。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大选中得了最多的票。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大选前，候选人到处演讲。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次参加大选，心情很激动。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家每四年举行一次大选。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大选结束后，新总统发表了讲话。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸每天都在报道大选。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次大选", "label": "量词"}, {"form": "一场大选", "label": "量词"}, {"form": "大選", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "全国很多人一起投票选出最重要领导人的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb360e55-9684-4dc5-bf88-9814d0ac9a26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89579, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大选", "is_correct": true, "explanation": "大选：全国性的选民投票选出领导人，与“国家举行”的语境相符。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是个人的仪式，国家不会举行婚礼，与句中的“国家”不相配。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“举行”一般不与“生日”搭配，不能说“国家举行生日”。"}, {"text": "相亲", "is_correct": false, "explanation": "语义：相亲是两个人之间的见面，国家不会举行相亲，句意不通。"}], "explanations": {"大选": "大选：全国性的选民投票选出领导人，与“国家举行”的语境相符。", "婚礼": "语义：婚礼是个人的仪式，国家不会举行婚礼，与句中的“国家”不相配。", "生日": "搭配：“举行”一般不与“生日”搭配，不能说“国家举行生日”。", "相亲": "语义：相亲是两个人之间的见面，国家不会举行相亲，句意不通。"}, "sentence_index": 0, "correct_answer": "大选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次大选的菜很好吃。", "explanation": "这里应该用〈饭菜〉。大选专指国家选民投票选举领导人，不能指饭菜。"}, {"text": "妈妈去市场大选了一个西瓜。", "explanation": "这里应该用〈挑选〉。大选专指国家选民投票选举领导人，买东西挑选不能用大选。"}, {"text": "工人大选了一台电脑。", "explanation": "这里应该用〈组装〉。大选专指国家选民投票选举领导人，组装机器不能用大选。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89579, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大选", "is_correct": true, "explanation": "大选：全国性的选民投票选出领导人，与“第一次参加”和“心情很激动”的语境相符。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“参加”的宾语应是活动、考试之类，不能说“参加感冒”，句子不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“参加”不与“作业”搭配，应说“做作业”。"}, {"text": "事故", "is_correct": false, "explanation": "语义：事故是意外的不幸，不能说“第一次参加事故”，心情激动也不符。"}], "explanations": {"大选": "大选：全国性的选民投票选出领导人，与“第一次参加”和“心情很激动”的语境相符。", "感冒": "搭配：“参加”的宾语应是活动、考试之类，不能说“参加感冒”，句子不通。", "作业": "搭配：“参加”不与“作业”搭配，应说“做作业”。", "事故": "语义：事故是意外的不幸，不能说“第一次参加事故”，心情激动也不符。"}, "sentence_index": 6, "correct_answer": "大选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我参加了一块大选。", "explanation": "这里量词用错。大选是一次选举活动，量词应用“次”或“场”，不用“块”。"}, {"text": "他看了一条大选。", "explanation": "这里量词用错。大选应配“次”或“场”，“条”不用于这类选举活动。"}, {"text": "她记录了一座大选。", "explanation": "这里量词用错。大选应配“次”或“场”，“座”不用于这类选举活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89579, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只大选吸引了很多年轻人。", "corrected_sentence": "这次大选吸引了很多年轻人。", "error_description": "错误：大选的量词“只”用错，写成“这只大选”。大选计次应用“次”，正确形式是“这次大选”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他参加了一部大选。", "corrected_sentence": "他参加了一次大选。", "error_description": "错误：大选的量词“部”用错，写成“一部大选”。大选应用“次”或“场”，正确形式是“一次大选”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
