INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89580, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家或地区的选民投票选举国家元首、议会等的活动。", "primary_collocate": null, "pronunciation": "dà xuǎn", "ipa": "ta˥˩ ɕɥɛn˨˩", "syllable_count": 2, "sentences": [{"text": "选民今天去投票站参加大选。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大选决定谁当新总统。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会大选将在十月举行。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次大选的投票率很高。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大选期间，各党忙着拉票。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统大选吸引了全世界的目光。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家分析了这次大选的结果。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个政党在大选中竞争激烈。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大选后，政府换了新领导。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们讨论着大选的消息。", "target_word": "大选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次大选", "label": "量词"}, {"form": "一场大选", "label": "量词"}, {"form": "大選", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "国家或地区选民投票选举国家元首、议会等的政治活动（正式说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb360e55-9684-4dc5-bf88-9814d0ac9a26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大选", "is_correct": true, "explanation": "大选：选民去投票站投票选举领导人，与“选民”和“投票站”的语境相符。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：投票站是投票的场所，不能说“去投票站参加考试”，两者不搭配。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是悼念逝者的仪式，选民不会去投票站参加葬礼，句意不通。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：比赛是竞技活动，与投票站和选民的身份不相符，句意不通。"}], "explanations": {"大选": "大选：选民去投票站投票选举领导人，与“选民”和“投票站”的语境相符。", "考试": "搭配：投票站是投票的场所，不能说“去投票站参加考试”，两者不搭配。", "葬礼": "语义：葬礼是悼念逝者的仪式，选民不会去投票站参加葬礼，句意不通。", "比赛": "语义：比赛是竞技活动，与投票站和选民的身份不相符，句意不通。"}, "sentence_index": 0, "correct_answer": "大选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在饭馆大选了一道菜。", "explanation": "这里应该用〈点〉。大选专指国家或地区的选民投票选举领导人，点菜不能用大选。"}, {"text": "我大选了一只小猫。", "explanation": "这里应该用〈收养〉。大选专指国家或地区的选民投票选举领导人，收养小猫不能用大选。"}, {"text": "他们大选了教室的墙壁。", "explanation": "这里应该用〈装饰〉。大选专指国家或地区的选民投票选举领导人，装饰墙壁不能用大选。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大选", "is_correct": true, "explanation": "大选：选民投票选举领导人的政治活动，与“专家分析了这次…的结果”的语境相符。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子是穿戴用品，没有可以分析的“结果”，句意不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“结果”不与“饭菜”搭配，不能说“分析饭菜的结果”。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐只是一顿饭，不是需要专家分析结果的事件，句意不通。"}], "explanations": {"大选": "大选：选民投票选举领导人的政治活动，与“专家分析了这次…的结果”的语境相符。", "帽子": "语义：帽子是穿戴用品，没有可以分析的“结果”，句意不通。", "饭菜": "搭配：“结果”不与“饭菜”搭配，不能说“分析饭菜的结果”。", "早餐": "语义：早餐只是一顿饭，不是需要专家分析结果的事件，句意不通。"}, "sentence_index": 6, "correct_answer": "大选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们观看了一座大选。", "explanation": "这里量词用错。大选是一次选举活动，量词应用“次”或“场”，不用“座”。"}, {"text": "他们讨论了一条大选。", "explanation": "这里量词用错。大选应配“次”或“场”，“条”不用于这类选举活动。"}, {"text": "他们组织了一块大选。", "explanation": "这里量词用错。大选应配“次”或“场”，“块”不用于这类选举活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她曾经参加一只大选。", "corrected_sentence": "她曾经参加一次大选。", "error_description": "错误：大选的量词“只”用错，写成“一只大选”。大选应用“次”或“场”，正确形式是“一次大选”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多人在大选去投票站排队。", "corrected_sentence": "很多人在大选前去投票站排队。", "error_description": "错误：时间方位词“前”漏掉了，写成“在大选去”。正确形式是“在大选前”，表示时间的“前”应紧跟在名词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
