INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89581, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89581, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地形是地面高高低低的样子，有山，有平地。", "primary_collocate": null, "pronunciation": "dì xíng", "ipa": "ti˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这里的地形有山，也有平地。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看看地图上的地形。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方地形很复杂。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的地形高高低低，走路很累。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云南的地形有很多山。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机不熟悉这里的地形，开得很慢。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地形不一样，天气也不一样。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家那边地形很平，没有山。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了中国的地形。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片拍出了山村的地形。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地形图", "label": "复合"}, {"form": "一种地形", "label": "量词"}], "register": "中性", "sense_fingerprint": "地面高高低低的样子，有山有平地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地形", "is_correct": true, "explanation": "正确。地形指地面高低起伏的样子，与“有山，也有平地”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气说的是冷热晴雨，不能说这里的天气有山、有平地。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指人的数量，不描述地面有没有山和平地。"}, {"text": "物价", "is_correct": false, "explanation": "搭配：“有山，也有平地”描述地面的样子，“物价”没有这样的搭配。"}], "explanations": {"地形": "正确。地形指地面高低起伏的样子，与“有山，也有平地”相符。", "天气": "语义：天气说的是冷热晴雨，不能说这里的天气有山、有平地。", "人口": "语义：人口指人的数量，不描述地面有没有山和平地。", "物价": "搭配：“有山，也有平地”描述地面的样子，“物价”没有这样的搭配。"}, "sentence_index": 0, "correct_answer": "地形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他累得直接躺在地形上睡着了。", "explanation": "这里应该用〈地面〉。地形指地面高低起伏的样子，人躺在上面要说地面。"}, {"text": "我们拿出地形研究路线。", "explanation": "这里应该用〈地图〉。地形是地面的样子，不是可以拿在手里研究的纸，要说地图。"}, {"text": "夏天中午地形温度很高，别光脚走路。", "explanation": "这里应该用〈地表〉。地形指地面的形态，描述温度要说地表温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地形", "is_correct": true, "explanation": "正确。“地形不一样”指各地地面高低起伏的样子不同，与“天气也不一样”相对应。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌指人或动物的样子，不用来说地面或天气的样子。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资指劳动所得的钱，与“天气”不是同一类事物，不能这样并列。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费指上学要交的钱，不能和“天气”一样用“也不一样”来比较。"}], "explanations": {"地形": "正确。“地形不一样”指各地地面高低起伏的样子不同，与“天气也不一样”相对应。", "外貌": "体貌：外貌指人或动物的样子，不用来说地面或天气的样子。", "工资": "语义：工资指劳动所得的钱，与“天气”不是同一类事物，不能这样并列。", "学费": "语义：学费指上学要交的钱，不能和“天气”一样用“也不一样”来比较。"}, "sentence_index": 6, "correct_answer": "地形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把地形放进书包，带着去爬山。", "explanation": "这里应该用〈地图〉。地形是地面高高低低的样子，不能放进书包；能带着走的是地图。"}, {"text": "妈妈在地形上铺了一块新地毯。", "explanation": "这里应该用〈地板〉。地毯铺在屋里的地板上，地形是外面山和平地的样子。"}, {"text": "这只小狗的地形很可爱。", "explanation": "这里应该用〈样子〉。地形只说地面的样子，不说动物长得怎么样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地方得地形很复杂。", "corrected_sentence": "这个地方的地形很复杂。", "error_description": "错误：“得”。正确：“的”。“地形”前的修饰语要用结构助词“的”，“得”用在动词后面引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在书店买了一个地形图，回家慢慢看。", "corrected_sentence": "我们在书店买了一张地形图，回家慢慢看。", "error_description": "“地形图”是一张图，量词应用“张”，不用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
