INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89582, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89582, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地表高低起伏的形态，如山地、平原、盆地。", "primary_collocate": null, "pronunciation": "dì xíng", "ipa": "ti˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "四川的地形是盆地，四周都是山。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "华北的地形主要是平原。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图用不同颜色表示地形。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的地形让修路很困难。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的地形，人们的生活也不同。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青藏高原的地形以高原为主。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们根据地形来决定在哪里盖房子。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里地形低，雨季容易积水。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说说你家乡的地形。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平原地形开阔，适合种粮食。", "target_word": "地形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地形图", "label": "复合"}, {"form": "一种地形", "label": "量词"}], "register": "中性", "sense_fingerprint": "地表高低起伏的形态，如山地、平原、盆地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地形", "is_correct": true, "explanation": "正确。地形指地表高低起伏的形态，盆地和四周的山正是地形的特点。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指冷热晴雨，不说某地是盆地或四周都是山。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指人的数量，不能说“是盆地”。"}, {"text": "方言", "is_correct": false, "explanation": "搭配：“是盆地，四周都是山”描述的是自然地理，“方言”不能这样描述。"}], "explanations": {"地形": "正确。地形指地表高低起伏的形态，盆地和四周的山正是地形的特点。", "天气": "语义：天气指冷热晴雨，不说某地是盆地或四周都是山。", "人口": "语义：人口指人的数量，不能说“是盆地”。", "方言": "搭配：“是盆地，四周都是山”描述的是自然地理，“方言”不能这样描述。"}, "sentence_index": 0, "correct_answer": "地形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把地形写在信封上。", "explanation": "这里应该用〈地址〉。地形指地表高低起伏的形态，不能像地址那样写在信封上。"}, {"text": "这座城的地形很好听。", "explanation": "这里应该用〈地名〉。地形说的是地面的形态，好听的是地名，不说地形好听。"}, {"text": "我每天坐地形上班。", "explanation": "这里应该用〈地铁〉。地形不是交通工具，上班坐的应是地铁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地形", "is_correct": true, "explanation": "正确。根据地形决定盖房子的地方，地形指地表的高低起伏，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与盖房子选在哪里没有关系，不能作为选址的依据。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人的感受，不能作为决定盖房子位置的依据。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌，不能用来决定房子盖在哪里。"}], "explanations": {"地形": "正确。根据地形决定盖房子的地方，地形指地表的高低起伏，符合语境。", "颜色": "语义：颜色与盖房子选在哪里没有关系，不能作为选址的依据。", "心情": "语义：心情是人的感受，不能作为决定盖房子位置的依据。", "身高": "体貌：身高是人的体貌，不能用来决定房子盖在哪里。"}, "sentence_index": 6, "correct_answer": "地形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把地形折好，放进了口袋。", "explanation": "这里应该用〈地图〉。地形是地表的起伏形态，不能折起来放进口袋；能折的是地图。"}, {"text": "我们在地形上铺了木头，屋里很干净。", "explanation": "这里应该用〈地板〉。屋里铺木头的是地板，地形指山地、平原等自然形态。"}, {"text": "这只小猫的地形很可爱。", "explanation": "这里应该用〈样子〉。地形只说地表的形态，不说动物的长相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校附近得地形很平。", "corrected_sentence": "我们学校附近的地形很平。", "error_description": "错误：“得”。正确：“的”。“地形”前的修饰语要用结构助词“的”，“得”用在动词后面引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师给我们看了一个地形图，山和平原都很清楚。", "corrected_sentence": "老师给我们看了一张地形图，山和平原都很清楚。", "error_description": "“地形图”是一张图，量词应用“张”，不用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "害怕是心里觉得不安全,想躲开。", "primary_collocate": null, "pronunciation": "hài pà", "ipa": "xaɪ˥˩ pʰa˥˩", "syllable_count": 2, "sentences": [{"text": "我害怕蛇，看到就想躲开。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小猫害怕洗澡，一听水声就跑。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他害怕见医生，所以一直不去医院。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟害怕黑，晚上不敢关灯睡觉。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人害怕坐飞机。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她害怕老鼠，看到就大叫。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子害怕打针，一看到医生就哭了。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从小就害怕高的地方。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗害怕大声音，一直躲在桌子下面。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人害怕一个人在家，晚上总睡不好。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "害怕了", "label": "体标"}, {"form": "害怕过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：觉得不安全而想躲开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b85a5fef-cf91-4887-8a4f-1d7906f0a58f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "害怕", "is_correct": true, "explanation": "“害怕”表示觉得不安全而想躲开，与“想躲开”相合。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”与后文“想躲开”矛盾，喜欢蛇的人不会想躲开。"}, {"text": "迎接", "is_correct": false, "explanation": "搭配：“迎接”多用于客人、来宾，不说“迎接蛇”。"}, {"text": "观察", "is_correct": false, "explanation": "语义：“观察”是仔细看，与“看到就想躲开”不合。"}], "explanations": {"害怕": "“害怕”表示觉得不安全而想躲开，与“想躲开”相合。", "喜欢": "语义：“喜欢”与后文“想躲开”矛盾，喜欢蛇的人不会想躲开。", "迎接": "搭配：“迎接”多用于客人、来宾，不说“迎接蛇”。", "观察": "语义：“观察”是仔细看，与“看到就想躲开”不合。"}, "sentence_index": 0, "correct_answer": "害怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我害怕中午的阳光，所以每天都去晒太阳。", "explanation": "这里应该用〈喜欢〉。“害怕”表示觉得不安全、想躲开，“每天去晒太阳”是主动靠近，应表示喜爱，不能用“害怕”。"}, {"text": "我很害怕过生日，因为能收到很多礼物。", "explanation": "这里应该用〈盼望〉。“害怕”表示觉得不安全、想躲开，收到礼物让人期待，应用“盼望”。"}, {"text": "她害怕见到好朋友，因为和好朋友在一起很开心。", "explanation": "这里应该用〈喜欢〉。“害怕”表示想躲开，和朋友在一起开心，应用“喜欢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "害怕", "is_correct": true, "explanation": "“害怕”表示觉得打针不安全而想躲开，与“一看到医生就哭了”相合。"}, {"text": "盼望", "is_correct": false, "explanation": "语义：“盼望”是期待，与“一看到医生就哭了”矛盾。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：孩子讨论打针与“一看到医生就哭了”的反应不协调，不符合这里的情境。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不与“打针”搭配，打针是注射的动作，不能喝。"}], "explanations": {"害怕": "“害怕”表示觉得打针不安全而想躲开，与“一看到医生就哭了”相合。", "盼望": "语义：“盼望”是期待，与“一看到医生就哭了”矛盾。", "讨论": "语义：孩子讨论打针与“一看到医生就哭了”的反应不协调，不符合这里的情境。", "喝": "搭配：“喝”不与“打针”搭配，打针是注射的动作，不能喝。"}, "sentence_index": 6, "correct_answer": "害怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈害怕看到孩子的笑脸。", "explanation": "这里应该用〈喜欢〉。“害怕”表示觉得不安全、想躲开，“看到孩子的笑脸”应表示喜爱，不能用“害怕”。"}, {"text": "我害怕这个周末的假期，因为可以好好休息。", "explanation": "这里应该用〈期待〉。“害怕”表示想躲开，能休息的假期令人期待。"}, {"text": "她很害怕天气好，因为天气好就可以出去玩。", "explanation": "这里应该用〈喜欢〉。“害怕”表示想躲开，能出去玩的好天气让人喜欢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我害怕的不敢靠近狗。", "corrected_sentence": "我害怕得不敢靠近狗。", "error_description": "“得”与“的”混用：“害怕”后接表示程度结果的“得”，不能用“的”，应改为“害怕得不敢靠近狗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从来别害怕狗。", "corrected_sentence": "她从来不害怕狗。", "error_description": "否定词用错：叙述习惯要用“不”，“别”只用于劝阻或祈使，应说“从来不害怕狗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇到困难或危险时心中不安、胆怯。", "primary_collocate": null, "pronunciation": "hài pà", "ipa": "xaɪ˥˩ pʰa˥˩", "syllable_count": 2, "sentences": [{"text": "看到大狗跑过来，小孩很害怕。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里一个人走路，她有点害怕。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到危险时，不要害怕，要冷静。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他害怕地躲在门后面。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山路很陡，我害怕会摔下去。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她第一次上台，害怕得手都在抖。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打雷的时候，弟弟害怕极了。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别害怕，医生会帮你的。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来不害怕困难。", "target_word": "害怕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过桥的时候，我害怕得不敢往下看。", "target_word": "害怕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "害怕了", "label": "体标"}, {"form": "害怕过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：遇到危险或困难时心里不安、胆怯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b85a5fef-cf91-4887-8a4f-1d7906f0a58f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "害怕", "is_correct": true, "explanation": "“害怕”表示看到大狗跑过来而心中胆怯，与“小孩很”相合。"}, {"text": "打针", "is_correct": false, "explanation": "语义：“打针”是医疗动作，不表示心理状态，与“看到大狗跑过来”不相合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳是动作，不是心理状态，“小孩很游泳”不成立。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”必须带宾语（原谅某人），“小孩很原谅”缺少宾语，不成立。"}], "explanations": {"害怕": "“害怕”表示看到大狗跑过来而心中胆怯，与“小孩很”相合。", "打针": "语义：“打针”是医疗动作，不表示心理状态，与“看到大狗跑过来”不相合。", "游泳": "语义：游泳是动作，不是心理状态，“小孩很游泳”不成立。", "原谅": "配价：“原谅”必须带宾语（原谅某人），“小孩很原谅”缺少宾语，不成立。"}, "sentence_index": 0, "correct_answer": "害怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很害怕你送的生日礼物。", "explanation": "这里应该用〈喜欢〉。“害怕”指遇到危险或困难时心中不安、胆怯，不能用来表示对生日礼物的喜爱。"}, {"text": "她害怕地兴奋地拆开了礼物。", "explanation": "“害怕”表示心中胆怯，与“兴奋”的情绪相互矛盾，句子不成立。"}, {"text": "她害怕每天都有好消息。", "explanation": "这里应该用〈盼望〉。“害怕”指心中不安、胆怯，“好消息”令人高兴，应用〈盼望〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "害怕", "is_correct": true, "explanation": "“害怕”表示打雷时心中胆怯，与“弟弟……极了”相合。"}, {"text": "收拾", "is_correct": false, "explanation": "语义：“收拾”是整理的动作，不是心理状态，与“打雷的时候”不相合。"}, {"text": "表扬", "is_correct": false, "explanation": "配价：“表扬”必须带宾语（表扬某人），“弟弟……极了”缺少宾语，不成立。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是洗身体的动作，不表示心理状态，与“打雷的时候”不相合。"}], "explanations": {"害怕": "“害怕”表示打雷时心中胆怯，与“弟弟……极了”相合。", "收拾": "语义：“收拾”是整理的动作，不是心理状态，与“打雷的时候”不相合。", "表扬": "配价：“表扬”必须带宾语（表扬某人），“弟弟……极了”缺少宾语，不成立。", "洗澡": "语义：“洗澡”是洗身体的动作，不表示心理状态，与“打雷的时候”不相合。"}, "sentence_index": 6, "correct_answer": "害怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她害怕这只小猫的可爱模样。", "explanation": "这里应该用〈喜欢〉。“害怕”指心中不安、胆怯，“可爱的模样”令人喜爱，应用〈喜欢〉。"}, {"text": "他害怕地开心地笑着。", "explanation": "“害怕”表示心中胆怯，与“开心”的情绪相互矛盾，句子不成立。"}, {"text": "我害怕地津津有味地吃着妈妈做的饭。", "explanation": "“害怕”表示心中胆怯，与“津津有味”的情绪相互矛盾，句子不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他害怕的不敢出门。", "corrected_sentence": "他害怕得不敢出门。", "error_description": "“得”与“的”混用：表示程度结果的补语要用“得”，“害怕的”不能修饰后面的动词短语，应改为“害怕得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看到那条大蛇，妹妹很害怕极了。", "corrected_sentence": "看到那条大蛇，妹妹害怕极了。", "error_description": "程度表达重复：“害怕极了”已表示程度很高，前面不能再加“很”，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
