INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89589, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对象是你做事时面对的人或东西。", "primary_collocate": null, "pronunciation": "duì xiàng", "ipa": "tweɪ̯˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们的服务对象是老人。", "target_word": "对象", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的聊天对象是谁？", "target_word": "对象", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个节目的对象是孩子。", "target_word": "对象", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这门课的教学对象是刚来的新同学。", "target_word": "对象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "练习口语时，我找了一个对话对象。", "target_word": "对象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察的调查对象是那家公司。", "target_word": "对象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家医院的服务对象主要是附近的老人和孩子。", "target_word": "对象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写文章以前，要先想好你的阅读对象。", "target_word": "对象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动的参加对象是十岁以下的小朋友。", "target_word": "对象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买礼物时，要先想好送礼的对象。", "target_word": "对象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "服务对象", "label": "复合"}, {"form": "教学对象", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：做事、服务、交流时面对的人，如“服务对象”“教学对象”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a37e-859d-480a-acef-93c3977707a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89589, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对象", "is_correct": true, "explanation": "“服务对象”指服务所面向的人，符合“是老人”的语境。"}, {"text": "工具", "is_correct": false, "explanation": "语义：“工具”是用来做事的物件，不能指被服务的人。"}, {"text": "对手", "is_correct": false, "explanation": "搭配：“对手”指竞争的一方，不能与“服务”搭配。"}, {"text": "设备", "is_correct": false, "explanation": "语义：“设备”是物品，不能指被服务的老人。"}], "explanations": {"对象": "“服务对象”指服务所面向的人，符合“是老人”的语境。", "工具": "语义：“工具”是用来做事的物件，不能指被服务的人。", "对手": "搭配：“对手”指竞争的一方，不能与“服务”搭配。", "设备": "语义：“设备”是物品，不能指被服务的老人。"}, "sentence_index": 0, "correct_answer": "对象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动的对象是提高成绩。", "explanation": "这里应该用〈目标〉。“对象”指做事时面对的人或东西，不能指要达到的结果。"}, {"text": "他对这个问题的对象很清楚。", "explanation": "这里应该用〈情况〉。“对象”指做事时面对的人或东西，不能指问题的具体情况。"}, {"text": "我们用一个新对象解决了这个问题。", "explanation": "这里应该用〈方法〉。“对象”指做事时面对的人或东西，不能指做事的手段，“新方法”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89589, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对象", "is_correct": true, "explanation": "“服务对象”指服务所面向的人群，符合“主要是附近的老人和孩子”的语境。"}, {"text": "产品", "is_correct": false, "explanation": "语义：“产品”是商品，不能指被服务的人群。"}, {"text": "药品", "is_correct": false, "explanation": "搭配：“服务药品”搭配不当，药品不是服务所面向的人。"}, {"text": "仪器", "is_correct": false, "explanation": "语义：“仪器”是器械，与被服务的老人和孩子不符。"}], "explanations": {"对象": "“服务对象”指服务所面向的人群，符合“主要是附近的老人和孩子”的语境。", "产品": "语义：“产品”是商品，不能指被服务的人群。", "药品": "搭配：“服务药品”搭配不当，药品不是服务所面向的人。", "仪器": "语义：“仪器”是器械，与被服务的老人和孩子不符。"}, "sentence_index": 6, "correct_answer": "对象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的对象是三百页。", "explanation": "这里应该用〈篇幅〉。“对象”指做事时面对的人或东西，不能指书的页数或篇幅。"}, {"text": "这场比赛的对象是一张桌子。", "explanation": "这里应该用〈器材〉。“对象”指做事时面对的人或东西，比赛中的器材不是比赛所面对的对象。"}, {"text": "这次比赛的对象是一个体育馆。", "explanation": "这里应该用〈场地〉。“对象”指做事时面对的人或东西，不能指比赛所在的场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了一只合适的谈话对象。", "corrected_sentence": "我找到了一个合适的谈话对象。", "error_description": "错误在于量词。“对象”指人，应该用量词“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个项目的很服务对象主要是农民。", "corrected_sentence": "这个项目的服务对象主要是农民。", "error_description": "错误在于在名词复合词“服务对象”前误加了程度副词“很”。名词前不能用“很”修饰，应直接说“服务对象”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
