INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89590, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行动或思考时所针对的人或事物。", "primary_collocate": null, "pronunciation": "duì xiàng", "ipa": "tweɪ̯˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "狗是他的研究对象。", "target_word": "对象", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是大家的讨论对象。", "target_word": "对象", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好人是我们学习的对象。", "target_word": "对象", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位科学家的研究对象是海里的鱼。", "target_word": "对象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的作品成了很多人批评的对象。", "target_word": "对象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生的检查对象是所有新来的工人。", "target_word": "对象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位明星很受欢迎，是很多年轻人关注的对象。", "target_word": "对象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书把中国的家庭关系当作研究对象。", "target_word": "对象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直是大家羡慕的对象，可他自己并不开心。", "target_word": "对象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种动物很少见，所以成了科学家观察的对象。", "target_word": "对象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "研究对象", "label": "复合"}, {"form": "批评对象", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：研究、批评、关注、观察等行动或思考所针对的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a37e-859d-480a-acef-93c3977707a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对象", "is_correct": true, "explanation": "正确答案。“研究对象”指研究所针对的事物，狗是他研究的对象。"}, {"text": "方法", "is_correct": false, "explanation": "语义：“方法”是做事的途径，狗是动物，不能作研究方法。"}, {"text": "报告", "is_correct": false, "explanation": "语义：“报告”是书面或口头的陈述材料，狗不是报告。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是时段，狗是动物，“狗是他的研究时间”不通。"}], "explanations": {"对象": "正确答案。“研究对象”指研究所针对的事物，狗是他研究的对象。", "方法": "语义：“方法”是做事的途径，狗是动物，不能作研究方法。", "报告": "语义：“报告”是书面或口头的陈述材料，狗不是报告。", "时间": "语义：“时间”是时段，狗是动物，“狗是他的研究时间”不通。"}, "sentence_index": 0, "correct_answer": "对象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这学期的对象是考上大学。", "explanation": "这里应该用〈目标〉。对象指行动所针对的人或事物，不指要达到的结果，“学期目标”才对。"}, {"text": "我们用新对象解决了这个问题。", "explanation": "这里应该用〈方法〉。对象指行动所针对的人或事物，不指用来做事的手段，“新方法”才对。"}, {"text": "我来这里的对象是学习汉语。", "explanation": "这里应该用〈目的〉。对象指行动所针对的人或事物，不指要达到的意图，“来这里的目的”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对象", "is_correct": true, "explanation": "正确答案。“关注的对象”指人们注意、关心的人，明星正是这样的人。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，不能指被关注的人。"}, {"text": "理论", "is_correct": false, "explanation": "语义：“理论”是抽象的知识体系，明星是人，不能是“很多年轻人关注的理论”。"}, {"text": "工具", "is_correct": false, "explanation": "语义：“工具”是用来做事的器具，明星是人，不能作工具。"}], "explanations": {"对象": "正确答案。“关注的对象”指人们注意、关心的人，明星正是这样的人。", "厨房": "语义：“厨房”是做饭的地方，不能指被关注的人。", "理论": "语义：“理论”是抽象的知识体系，明星是人，不能是“很多年轻人关注的理论”。", "工具": "语义：“工具”是用来做事的器具，明星是人，不能作工具。"}, "sentence_index": 6, "correct_answer": "对象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这周我的对象是把报告写完。", "explanation": "这里应该用〈任务〉。对象指行动所针对的人或事物，不指要完成的工作，“这周的任务”才对。"}, {"text": "面对这个问题，他们提出的对象很有效。", "explanation": "这里应该用〈对策〉。对象指行动所针对的人或事物，不指解决问题的办法，“对策”才对。"}, {"text": "这本书的对象很丰富，每一章都有趣。", "explanation": "这里应该用〈内容〉。对象指人或事物，不指书中的内容，“内容”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位教授地研究对象是海洋生物。", "corrected_sentence": "这位教授的研究对象是海洋生物。", "error_description": "助词错误：“的”连接定语与中心语，“地”用来修饰动词或形容词。“研究对象”是定语结构，应说“这位教授的研究对象”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他成了很多记者采访的一只对象。", "corrected_sentence": "他成了很多记者采访的一个对象。", "error_description": "量词错误：“对象”指人或事物，量词应用“个”，“只”多用于动物，不能修饰“对象”。应说“一个对象”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
