INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89591, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "锦标赛是很多人来比谁最棒的大比赛。", "primary_collocate": null, "pronunciation": "jǐn biāo sài", "ipa": "tɕin˨˩˦ pjau˥ sai˥˩", "syllable_count": 3, "sentences": [{"text": "这个周末有一场游泳锦标赛。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国的小朋友都来参加锦标赛。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在锦标赛上拿了第一名。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锦标赛每四年举行一次。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校要办乒乓球锦标赛。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了锦标赛，他每天练习三小时。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场锦标赛有一百多个人参加。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喜欢看足球锦标赛。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的锦标赛，我们队没赢。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锦标赛的奖杯又大又亮。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "届", "label": "量词"}, {"form": "世界锦标赛", "label": "复合词"}, {"form": "錦標賽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多人参加、比谁最棒的大型比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94079a68-bf10-4746-bd88-8d31e031ef14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89591, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "锦标赛", "is_correct": true, "explanation": "正确。锦标赛是为争夺冠军而举行的大型比赛，能与“游泳”组成“游泳锦标赛”，并用“场”计数。"}, {"text": "音乐会", "is_correct": false, "explanation": "语义：音乐会是演奏音乐的活动，不是游泳比赛，与“游泳”不搭配。"}, {"text": "游泳馆", "is_correct": false, "explanation": "搭配：“场”用于比赛、活动，不用于场馆，游泳馆应用“座”计数。"}, {"text": "舞会", "is_correct": false, "explanation": "语义：舞会是跳舞的聚会，与“游泳”不搭配，也不是比赛。"}], "explanations": {"锦标赛": "正确。锦标赛是为争夺冠军而举行的大型比赛，能与“游泳”组成“游泳锦标赛”，并用“场”计数。", "音乐会": "语义：音乐会是演奏音乐的活动，不是游泳比赛，与“游泳”不搭配。", "游泳馆": "搭配：“场”用于比赛、活动，不用于场馆，游泳馆应用“座”计数。", "舞会": "语义：舞会是跳舞的聚会，与“游泳”不搭配，也不是比赛。"}, "sentence_index": 0, "correct_answer": "锦标赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把锦标赛擦得干干净净，摆在书架上。", "explanation": "这里应该用〈奖杯〉。锦标赛是比赛，不是奖品实物，擦拭、摆放的是奖杯。"}, {"text": "我们下午去锦标赛买点菜吧。", "explanation": "这里应该用〈菜市场〉。锦标赛是比赛，不是地点，买菜要去菜市场。"}, {"text": "他是班里的锦标赛。", "explanation": "这里应该用〈冠军〉。锦标赛指比赛，不能指人；指人应说〈冠军〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89591, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "锦标赛", "is_correct": true, "explanation": "正确。“这场”后接大型活动，“有一百多个人参加”说明规模，锦标赛符合。"}, {"text": "奖杯", "is_correct": false, "explanation": "语义：奖杯是奖品，不是活动，不能有一百多个人参加。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：冠军是名次或获胜者，不是活动，不能说有人参加。"}, {"text": "球场", "is_correct": false, "explanation": "搭配：“场”可计数比赛，但“球场”是场地，不能说“这场球场有一百多个人参加”。"}], "explanations": {"锦标赛": "正确。“这场”后接大型活动，“有一百多个人参加”说明规模，锦标赛符合。", "奖杯": "语义：奖杯是奖品，不是活动，不能有一百多个人参加。", "冠军": "语义：冠军是名次或获胜者，不是活动，不能说有人参加。", "球场": "搭配：“场”可计数比赛，但“球场”是场地，不能说“这场球场有一百多个人参加”。"}, "sentence_index": 6, "correct_answer": "锦标赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次锦标赛的作业特别多，我们写到半夜。", "explanation": "这里应该用〈课〉。锦标赛是比赛，不会留作业；留作业的是课。"}, {"text": "我们这学期学的锦标赛是数学。", "explanation": "这里应该用〈科目〉。锦标赛是比赛，不是课程；学的数学是科目。"}, {"text": "她是我们学校最厉害的锦标赛。", "explanation": "这里应该用〈运动员〉。锦标赛是比赛，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89591, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年夏天有一张国际锦标赛。", "corrected_sentence": "今年夏天有一场国际锦标赛。", "error_description": "“锦标赛”的量词用“场”或“届”，不能用“张”，应说“一场国际锦标赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89591, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈常常和朋友一起看篮球锦标赛们。", "corrected_sentence": "妈妈常常和朋友一起看篮球锦标赛。", "error_description": "“们”只用于指人，“锦标赛”不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
