INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89592, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为争夺冠军而举行的较大规模的体育比赛。", "primary_collocate": null, "pronunciation": "jǐn biāo sài", "ipa": "tɕin˨˩˦ pjau˥ sai˥˩", "syllable_count": 3, "sentences": [{"text": "世界锦标赛下个月在北京举行。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在这次锦标赛中夺得冠军。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一场规模很大的体育锦标赛。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家队已经出发去参加锦标赛。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在亚洲锦标赛上打破了纪录。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锦标赛的冠军可以拿到奖金。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这届锦标赛有二十个国家的队。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视正在直播篮球锦标赛。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锦标赛的第一天，天气特别好。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为受伤，他不能参加这次锦标赛。", "target_word": "锦标赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "届", "label": "量词"}, {"form": "世界锦标赛", "label": "复合词"}, {"form": "錦標賽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为争夺冠军而举行的较大规模体育比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94079a68-bf10-4746-bd88-8d31e031ef14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "锦标赛", "is_correct": true, "explanation": "正确。锦标赛是为争夺冠军而举行的大型体育比赛，可以“在北京举行”。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：冠军是名次或获胜者，不是活动，不能在北京举行。"}, {"text": "运动员", "is_correct": false, "explanation": "搭配：“举行”用于活动，运动员是人，不说“运动员在北京举行”。"}, {"text": "奖杯", "is_correct": false, "explanation": "语义：奖杯是奖品，不是活动，不能在北京举行。"}], "explanations": {"锦标赛": "正确。锦标赛是为争夺冠军而举行的大型体育比赛，可以“在北京举行”。", "冠军": "语义：冠军是名次或获胜者，不是活动，不能在北京举行。", "运动员": "搭配：“举行”用于活动，运动员是人，不说“运动员在北京举行”。", "奖杯": "语义：奖杯是奖品，不是活动，不能在北京举行。"}, "sentence_index": 0, "correct_answer": "锦标赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国家队把锦标赛存进了银行。", "explanation": "这里应该用〈奖金〉。锦标赛是比赛，不是钱；存进银行的应该是奖金。"}, {"text": "国家队已经出发去锦标赛吃午饭。", "explanation": "这里应该用〈食堂〉。锦标赛是比赛，不是地点，吃午饭要去食堂或餐厅。"}, {"text": "我们这学期选修的锦标赛是音乐。", "explanation": "这里应该用〈科目〉。锦标赛是比赛，不是课程；选修的音乐是科目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "锦标赛", "is_correct": true, "explanation": "正确。“这届”后接大型比赛，“有二十个国家的队”说明规模，锦标赛符合。"}, {"text": "教练", "is_correct": false, "explanation": "搭配：“这届”后接活动，教练是人，不能说“教练有二十个国家的队”。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：裁判是执裁比赛的人，不是参赛的队伍，不能说有二十个国家的队。"}, {"text": "球场", "is_correct": false, "explanation": "搭配：“这届”后接活动，球场是场地，不能说“球场有二十个国家的队”。"}], "explanations": {"锦标赛": "正确。“这届”后接大型比赛，“有二十个国家的队”说明规模，锦标赛符合。", "教练": "搭配：“这届”后接活动，教练是人，不能说“教练有二十个国家的队”。", "裁判": "语义：裁判是执裁比赛的人，不是参赛的队伍，不能说有二十个国家的队。", "球场": "搭配：“这届”后接活动，球场是场地，不能说“球场有二十个国家的队”。"}, "sentence_index": 6, "correct_answer": "锦标赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们坐锦标赛去北京，路上很舒服。", "explanation": "这里应该用〈火车〉。锦标赛是比赛，不是交通工具；去北京要坐〈火车〉。"}, {"text": "他是一名优秀的锦标赛。", "explanation": "这里应该用〈运动员〉。锦标赛是比赛，不能指人。"}, {"text": "两个人在操场上比谁跑得快，这是一场锦标赛。", "explanation": "这里应该用〈比赛〉。锦标赛指较大规模的体育比赛，两个人的比试不用这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个届亚洲锦标赛明年在上海举行。", "corrected_sentence": "这届亚洲锦标赛明年在上海举行。", "error_description": "“届”本身是量词，前面直接用“这”，说“这届亚洲锦标赛”，不能再加“个”说成“这个届”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电视正在转播游泳锦标赛们。", "corrected_sentence": "电视正在转播游泳锦标赛。", "error_description": "“们”只用于指人，“锦标赛”不能加“们”表示复数，应说“游泳锦标赛”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a134650a-f904-4db3-ae3e-6660b2d5be45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89594, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公用", "is_correct": true, "explanation": "正确：“公用”指供大家共同使用，与“为病人准备了专用的饭菜”中只给病人的意思相反。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：指光线充足或颜色鲜亮，与“专用”没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "宽阔：指面积大、空间广，与“专用”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软：指质地松软，与“专用”没有反义关系。"}], "correct_answer": "公用", "explanations": {"公用": "正确：“公用”指供大家共同使用，与“为病人准备了专用的饭菜”中只给病人的意思相反。", "明亮": "明亮：指光线充足或颜色鲜亮，与“专用”没有反义关系。", "宽阔": "宽阔：指面积大、空间广，与“专用”没有反义关系。", "柔软": "柔软：指质地松软，与“专用”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89594, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公用", "is_correct": true, "explanation": "正确：“公用”指供大家共同使用，与“只能用在这台机器上”的专用意思相反。"}, {"text": "结实", "is_correct": false, "explanation": "结实：指坚固、不易损坏，与“专用”没有反义关系。"}, {"text": "清淡", "is_correct": false, "explanation": "清淡：指味道或颜色淡，与“专用”没有反义关系。"}, {"text": "轻便", "is_correct": false, "explanation": "轻便：指轻巧方便，与“专用”没有反义关系。"}], "correct_answer": "公用", "explanations": {"公用": "正确：“公用”指供大家共同使用，与“只能用在这台机器上”的专用意思相反。", "结实": "结实：指坚固、不易损坏，与“专用”没有反义关系。", "清淡": "清淡：指味道或颜色淡，与“专用”没有反义关系。", "轻便": "轻便：指轻巧方便，与“专用”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89594, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "专门供某人或某种用途使用的。", "primary_collocate": null, "pronunciation": "zhuān yòng", "ipa": "ʈʂwan˥ joŋ˥˩", "syllable_count": 2, "sentences": [{"text": "实验室里有这种实验的专用设备。", "target_word": "专用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一间自己的专用办公室。", "target_word": "专用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种专用工具是为修手机做的。", "target_word": "专用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院为病人准备了专用的饭菜。", "target_word": "专用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专用软件能帮你算工资。", "target_word": "专用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是工作人员的专用入口。", "target_word": "专用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理有专用电梯，上下很快。", "target_word": "专用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员有专用的更衣室。", "target_word": "专用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给客人准备了专用的会议室。", "target_word": "专用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种专用纸只能用在这台机器上。", "target_word": "专用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "專用", "label": "繁体"}, {"form": "专用设备", "label": "复合"}, {"form": "专用工具", "label": "复合"}], "register": "中性", "sense_fingerprint": "专用：专门为某人或某种用途准备的（设备、工具、场所）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b48a4e59-1e2a-4b1f-9e51-871774232826') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89594, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专用", "is_correct": true, "explanation": "正确：“专用”指专门为某种用途准备，与“实验室里有这种实验的设备”相符。"}, {"text": "家用", "is_correct": false, "explanation": "语义：“家用”指供家庭使用，与“实验室里”的场所不符。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，设备不说甜。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”形容人的性情，不能修饰“设备”。"}], "explanations": {"专用": "正确：“专用”指专门为某种用途准备，与“实验室里有这种实验的设备”相符。", "家用": "语义：“家用”指供家庭使用，与“实验室里”的场所不符。", "甜": "语义：“甜”说味道，设备不说甜。", "温柔": "搭配：“温柔”形容人的性情，不能修饰“设备”。"}, "sentence_index": 0, "correct_answer": "专用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种专用工具修什么都能用。", "explanation": "这里应该用〈通用〉。专用指专为某种用途准备，“修什么都能用”应说通用。"}, {"text": "学校的专用厕所，谁都能用。", "explanation": "这里应该用〈公共〉。专用指专为某些人准备的场所，“谁都能用”应说公共。"}, {"text": "这间专用实验室是大家共用的，学生都可以来做实验。", "explanation": "这里应该用〈公用〉。专用指只供特定对象使用，句中说实验室大家都能用，应说公用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专用", "is_correct": true, "explanation": "正确：“专用”指专门给总经理使用的，与“总经理有……电梯”相符。"}, {"text": "公共", "is_correct": false, "explanation": "语义：“公共”指人人可用，与“总经理有”的专属含义矛盾。"}, {"text": "慢吞吞", "is_correct": false, "explanation": "语义：“慢吞吞”形容速度慢，与“上下很快”相矛盾。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”形容声音或笑容，不能修饰“电梯”。"}], "explanations": {"专用": "正确：“专用”指专门给总经理使用的，与“总经理有……电梯”相符。", "公共": "语义：“公共”指人人可用，与“总经理有”的专属含义矛盾。", "慢吞吞": "语义：“慢吞吞”形容速度慢，与“上下很快”相矛盾。", "甜美": "搭配：“甜美”形容声音或笑容，不能修饰“电梯”。"}, "sentence_index": 6, "correct_answer": "专用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种专用纸可以用在任何机器上。", "explanation": "这里应该用〈通用〉。专用纸只能用在特定机器上，“可以用在任何机器上”应说通用。"}, {"text": "这台专用打印机谁都能用。", "explanation": "这里应该用〈共享〉。专用指只为某人或某用途准备，“谁都能用”应说共享。"}, {"text": "图书馆的专用电脑，谁都能用。", "explanation": "这里应该用〈公用〉。专用指只供特定对象使用，“谁都能用”应说公用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个柜子是专用，只放药品。", "corrected_sentence": "这个柜子是专用的，只放药品。", "error_description": "错误：作谓语时“专用”后漏了“的”。正确应为“这个柜子是专用的”，补上“的”。区别词“专用”作谓语须带“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的专用过停车场只给领导停车。", "corrected_sentence": "这里的专用停车场只给领导停车。", "error_description": "错误：“专用”后面加了动态助词“过”。正确应为“这里的专用停车场”，去掉“过”。形容词“专用”不能带“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
