INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89595, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就地是就在那个地方,不到别处去。", "primary_collocate": null, "pronunciation": "jiù dì", "ipa": "tɕjoʊ̯˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "他们累了,就地坐在路边。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要乱跑,请大家就地等我。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上没有房子,我们就地过夜。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修路用的石头都是工人们就地挖的。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一听见响声,就地蹲下了。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏了,司机就地修了起来。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题要就地解决,不用送到别处。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天雪太大,大家就地住下了。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的菜叶,工人们就地埋了。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在公园里就地铺开了一块布。", "target_word": "就地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "就在当地不去别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b6d23d-90ac-4dc8-9c4e-4b812c474339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89595, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "极力", "is_correct": false, "explanation": "搭配：“极力”表示竭力，不能修饰“坐”，与“累了坐下歇息”的语境不符。"}, {"text": "连夜", "is_correct": false, "explanation": "语义：“连夜”指整夜，与“累了坐在路边”的即时情境矛盾。"}, {"text": "就地", "is_correct": true, "explanation": "就地：就在当地，不挪动，与“累了坐在路边”的语境相符。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久，与“累了歇一歇”的暂时性矛盾。"}], "explanations": {"极力": "搭配：“极力”表示竭力，不能修饰“坐”，与“累了坐下歇息”的语境不符。", "连夜": "语义：“连夜”指整夜，与“累了坐在路边”的即时情境矛盾。", "就地": "就地：就在当地，不挪动，与“累了坐在路边”的语境相符。", "永远": "语义：“永远”表示长久，与“累了歇一歇”的暂时性矛盾。"}, "sentence_index": 0, "correct_answer": "就地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车坏了，我们就地把车送到修理厂。", "explanation": "这里应该用〈就近〉。就地表示不挪地方，送车去修理厂要离开原地；就近指离得近，与语境相符。"}, {"text": "收到消息，他就地坐飞机去了北京。", "explanation": "这里应该用〈当即〉。就地表示不换地方，“坐飞机去北京”需要换地方；当即表示立刻，符合语境。"}, {"text": "听到警报，他就地起身离开了房间。", "explanation": "这里应该用〈即刻〉。就地表示不换地方，“离开房间”需要换地方；即刻表示马上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远远", "is_correct": false, "explanation": "搭配：“远远”修饰距离或差距，不能修饰“解决”。"}, {"text": "乱", "is_correct": false, "explanation": "语义：「乱」表示随便、没有条理，「问题要乱解决」不合情理，也与「不用送到别处」无关。"}, {"text": "就地", "is_correct": true, "explanation": "就地：就在当地处理，与“不用送到别处”相符。"}, {"text": "一味", "is_correct": false, "explanation": "搭配：“一味”表示只管、一直，不能修饰“解决”，与语境不符。"}], "explanations": {"远远": "搭配：“远远”修饰距离或差距，不能修饰“解决”。", "乱": "语义：「乱」表示随便、没有条理，「问题要乱解决」不合情理，也与「不用送到别处」无关。", "就地": "就地：就在当地处理，与“不用送到别处”相符。", "一味": "搭配：“一味”表示只管、一直，不能修饰“解决”，与语境不符。"}, "sentence_index": 6, "correct_answer": "就地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到敲门声，她就地跑了出去。", "explanation": "这里应该用〈随即〉。就地表示不离开原地，“跑了出去”需要离开；随即表示紧接着。"}, {"text": "发现车祸，他就地跑去救人。", "explanation": "这里应该用〈立即〉。就地表示不挪地方，“跑去救人”需要移动；立即表示马上。"}, {"text": "比赛结束，她就地离开了球场。", "explanation": "这里应该用〈就此〉。就地表示不换地方，“离开球场”需要换地方；就此表示于是、从此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们走累了，在就地歇了一会儿。", "corrected_sentence": "我们走累了，就地歇了一会儿。", "error_description": "错误：“就地”前多加了“在”。“就地”是副词，直接修饰动词“歇”，前面不能加“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89595, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们玩累了，就地的睡着了。", "corrected_sentence": "孩子们玩累了，就地睡着了。", "error_description": "错误：副词“就地”后面多加了“的”。“就地”是副词，应直接修饰动词“睡着”，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89599, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大型", "is_correct": true, "explanation": "正确：“大型”指个头或体积大，与“小型”相反。"}, {"text": "温和", "is_correct": false, "explanation": "温和：指性情或气候平和，与“小型”没有反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "清脆：指声音清亮爽脆，与“小型”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软：指质地松软，与“小型”没有反义关系。"}], "correct_answer": "大型", "explanations": {"大型": "正确：“大型”指个头或体积大，与“小型”相反。", "温和": "温和：指性情或气候平和，与“小型”没有反义关系。", "清脆": "清脆：指声音清亮爽脆，与“小型”没有反义关系。", "柔软": "柔软：指质地松软，与“小型”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89599, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大型", "is_correct": true, "explanation": "正确：“大型”指个头或体积大，与“小型”相反。"}, {"text": "轻便", "is_correct": false, "explanation": "轻便：指轻巧方便，与“小型”没有反义关系。"}, {"text": "灵活", "is_correct": false, "explanation": "灵活：指动作敏捷、变通自如，与“小型”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：指没有声音或不吵闹，与“小型”没有反义关系。"}], "correct_answer": "大型", "explanations": {"大型": "正确：“大型”指个头或体积大，与“小型”相反。", "轻便": "轻便：指轻巧方便，与“小型”没有反义关系。", "灵活": "灵活：指动作敏捷、变通自如，与“小型”没有反义关系。", "安静": "安静：指没有声音或不吵闹，与“小型”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89599, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "个子不大，样子小小的。", "primary_collocate": null, "pronunciation": "xiǎo xíng", "ipa": "ɕiɑʊ˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这只小型犬很爱叫。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的猫是小型品种，体重只有三公斤。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开着一辆小型车，在窄路上很方便。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小型鸟只有拇指那么大。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小型冰箱可以放在桌子下面。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小型飞机只能坐四个人。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有很多小型狗，个子都不高。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台小型电脑可以放进书包里。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小型汽车比大卡车更好停。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小型马比一般的马矮很多。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小型犬", "label": "复合"}, {"form": "小型车", "label": "复合"}], "register": "中性", "sense_fingerprint": "小型：形容动物、车辆等个头小、样子小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b48a4e59-1e2a-4b1f-9e51-871774232826') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89599, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小型", "is_correct": true, "explanation": "正确：“小型”指个头或体积小，多用于动物、车辆等。"}, {"text": "小星", "is_correct": false, "explanation": "声调：xīng（第一声）与 xíng（第二声）声调不同，“小星”意思是小星星。"}, {"text": "笑星", "is_correct": false, "explanation": "声调：xiào（第四声）与 xiǎo（第三声）、xīng（第一声）与 xíng（第二声）声调都不同，“笑星”意思是喜剧明星。"}, {"text": "脚型", "is_correct": false, "explanation": "声母：jiǎo 与 xiǎo 声母不同（j 与 x），“脚型”意思是脚的形状。"}], "explanations": {"小型": "正确：“小型”指个头或体积小，多用于动物、车辆等。", "小星": "声调：xīng（第一声）与 xíng（第二声）声调不同，“小星”意思是小星星。", "笑星": "声调：xiào（第四声）与 xiǎo（第三声）、xīng（第一声）与 xíng（第二声）声调都不同，“笑星”意思是喜剧明星。", "脚型": "声母：jiǎo 与 xiǎo 声母不同（j 与 x），“脚型”意思是脚的形状。"}, "sentence_index": null, "correct_answer": "小型"}, "level_3": {"options": [{"text": "小型", "is_correct": true, "explanation": "正确：“小型”指个头小，与“这只小型犬很爱叫”的描述相符。"}, {"text": "木制", "is_correct": false, "explanation": "语义：“木制”说材料，木头做的犬不会叫，与“很爱叫”矛盾。"}, {"text": "无声", "is_correct": false, "explanation": "语义：“无声”指没有声音，与“很爱叫”相矛盾。"}, {"text": "精美", "is_correct": false, "explanation": "搭配：“精美”多修饰物品或工艺，不说“精美犬”。"}], "explanations": {"小型": "正确：“小型”指个头小，与“这只小型犬很爱叫”的描述相符。", "木制": "语义：“木制”说材料，木头做的犬不会叫，与“很爱叫”矛盾。", "无声": "语义：“无声”指没有声音，与“很爱叫”相矛盾。", "精美": "搭配：“精美”多修饰物品或工艺，不说“精美犬”。"}, "sentence_index": 0, "correct_answer": "小型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他个子小型，跑得很快。", "explanation": "这里应该用〈矮小〉。小型用于动物、车辆、机器等的个头，形容人的个子要说矮小。"}, {"text": "这种小型误差很难察觉。", "explanation": "这里应该用〈微小〉。小型说的是实体的个头或体积，“误差”这类细微的差别要说微小。"}, {"text": "这个小型的孩子需要照顾。", "explanation": "这里应该用〈幼小〉。小型不用来形容人，年纪小的孩子要说幼小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89599, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小型", "is_correct": true, "explanation": "正确：“小型”指个头小，与“个子都不高”相符。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”指个子高，与“个子都不高”矛盾。"}, {"text": "巨型", "is_correct": false, "explanation": "语义：“巨型”指体型极大，与“个子都不高”矛盾。"}, {"text": "高耸", "is_correct": false, "explanation": "搭配：“高耸”形容建筑或山峰很高，不能用来形容狗。"}], "explanations": {"小型": "正确：“小型”指个头小，与“个子都不高”相符。", "高大": "语义：“高大”指个子高，与“个子都不高”矛盾。", "巨型": "语义：“巨型”指体型极大，与“个子都不高”矛盾。", "高耸": "搭配：“高耸”形容建筑或山峰很高，不能用来形容狗。"}, "sentence_index": 6, "correct_answer": "小型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他手上有一道小型的伤口。", "explanation": "这里应该用〈细小〉。小型指个头或体积小，伤口之类细微的小要说细小。"}, {"text": "在大海面前，人类显得十分小型。", "explanation": "这里应该用〈渺小〉。小型不用来形容人在自然面前的微不足道，要说渺小。"}, {"text": "那个孩子身材小型，动作很灵活。", "explanation": "这里应该用〈瘦小〉。小型不用来形容人的身材，要说瘦小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只猫是小型，很安静。", "corrected_sentence": "这只猫是小型的，很安静。", "error_description": "错误：作谓语时“小型”后漏了“的”。正确应为“这只猫是小型的”，补上“的”。区别词“小型”作谓语须带“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间小型过厨房很干净。", "corrected_sentence": "这间小型厨房很干净。", "error_description": "错误：“小型”后面加了动态助词“过”。正确应为“这间小型厨房”，去掉“过”。区别词“小型”不能带“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
