INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89600, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "规模或体积较小的。", "primary_collocate": null, "pronunciation": "xiǎo xíng", "ipa": "ɕiɑʊ˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他在城里开了一家小型公司。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天开一个小型会议。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小型超市晚上十点关门。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办了一场小型音乐会。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小型工厂只有二十个工人。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的小型书店每天都有客人。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们在家里开了小型聚会。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小型水电站只给山村用电。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小型企业需要更多的帮助。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次小型展览一共有三十件作品。", "target_word": "小型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小型企业", "label": "复合"}], "register": "中性", "sense_fingerprint": "小型：形容公司、活动、场所等规模小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b48a4e59-1e2a-4b1f-9e51-871774232826') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89600, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小型", "is_correct": true, "explanation": "正确：“小型”指规模或体积小，用于公司、活动、场所等。"}, {"text": "小星", "is_correct": false, "explanation": "声调：xīng（第一声）与 xíng（第二声）声调不同，“小星”意思是小星星。"}, {"text": "笑星", "is_correct": false, "explanation": "声调：xiào（第四声）与 xiǎo（第三声）、xīng（第一声）与 xíng（第二声）声调都不同，“笑星”意思是喜剧明星。"}, {"text": "脚型", "is_correct": false, "explanation": "声母：jiǎo 与 xiǎo 声母不同（j 与 x），“脚型”意思是脚的形状。"}], "explanations": {"小型": "正确：“小型”指规模或体积小，用于公司、活动、场所等。", "小星": "声调：xīng（第一声）与 xíng（第二声）声调不同，“小星”意思是小星星。", "笑星": "声调：xiào（第四声）与 xiǎo（第三声）、xīng（第一声）与 xíng（第二声）声调都不同，“笑星”意思是喜剧明星。", "脚型": "声母：jiǎo 与 xiǎo 声母不同（j 与 x），“脚型”意思是脚的形状。"}, "sentence_index": null, "correct_answer": "小型"}, "level_3": {"options": [{"text": "小型", "is_correct": true, "explanation": "正确：“小型”指规模小，与“他在城里开了一家公司”相符。"}, {"text": "偏远", "is_correct": false, "explanation": "语义：“偏远”指地方很远、人烟稀少，与“在城里”相矛盾。"}, {"text": "无形", "is_correct": false, "explanation": "搭配：“无形”指看不见，不能修饰“公司”。"}, {"text": "英俊", "is_correct": false, "explanation": "体貌：“英俊”形容人的相貌，不用来形容公司。"}], "explanations": {"小型": "正确：“小型”指规模小，与“他在城里开了一家公司”相符。", "偏远": "语义：“偏远”指地方很远、人烟稀少，与“在城里”相矛盾。", "无形": "搭配：“无形”指看不见，不能修饰“公司”。", "英俊": "体貌：“英俊”形容人的相貌，不用来形容公司。"}, "sentence_index": 0, "correct_answer": "小型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他休息了一个小型的时间，就又开始工作了。", "explanation": "这里应该用〈短暂〉。小型说的是体积或规模，时间不长要说短暂。"}, {"text": "这次调整只带来了小型的变化。", "explanation": "这里应该用〈微小〉。小型说的是规模或体积小，细微的变化要说微小。"}, {"text": "这只是一个小型的问题，不用担心。", "explanation": "这里应该用〈细小〉。小型用于规模或体积，问题的细小要说细小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小型", "is_correct": true, "explanation": "正确：“小型”指规模小，与“周末在家里开的聚会”相符。"}, {"text": "露天", "is_correct": false, "explanation": "语义：“露天”指在室外，与“在家里”相矛盾。"}, {"text": "户外", "is_correct": false, "explanation": "语义：“户外”指在室外，与“在家里”相矛盾。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容物体表面不光滑，不能修饰“聚会”。"}], "explanations": {"小型": "正确：“小型”指规模小，与“周末在家里开的聚会”相符。", "露天": "语义：“露天”指在室外，与“在家里”相矛盾。", "户外": "语义：“户外”指在室外，与“在家里”相矛盾。", "粗糙": "搭配：“粗糙”形容物体表面不光滑，不能修饰“聚会”。"}, "sentence_index": 6, "correct_answer": "小型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她身材小型，动作很利落。", "explanation": "这里应该用〈瘦小〉。小型不用来形容人的身材，要说瘦小。"}, {"text": "他面对困难时显得很小型。", "explanation": "这里应该用〈渺小〉。小型不用来形容人在困难面前的微不足道，要说渺小。"}, {"text": "他只有小型的收入。", "explanation": "这里应该用〈微薄〉。小型说的是体积或规模，收入少要说微薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个展览是小型，很有意思。", "corrected_sentence": "这个展览是小型的，很有意思。", "error_description": "错误：作谓语时“小型”后漏了“的”。正确应为“这个展览是小型的”，补上“的”。区别词“小型”作谓语须带“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家小型过商店每天只开六小时。", "corrected_sentence": "这家小型商店每天只开六小时。", "error_description": "错误：“小型”后面加了动态助词“过”。正确应为“这家小型商店”，去掉“过”。区别词“小型”不能带“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a041ebbe-87b0-4669-af1b-ae099177a203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
