INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89601, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "就里是一件事里面没有说出的原因。", "primary_collocate": null, "pronunciation": "jiù lǐ", "ipa": "tɕjoʊ˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "她突然辞职，大家都想知道其中的就里。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两家为什么不来往，谁也说不清就里。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "其中的就里，他不愿意对别人多说。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛为什么突然取消，其中的就里没有人知道。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不知就里的邻居，还以为他们吵架了。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问了好几次，他都不肯说出就里。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看出了就里，却没有当面说破。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他好像知道一些就里，可是一直不开口。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他始终没提就里，大家只能瞎猜。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人知道就里，所以大家只能乱猜。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "就里|名词|事情里面没有说出的原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3ab9ed-a0b5-40d9-895a-567767ad38c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89601, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就里", "is_correct": true, "explanation": "正确：“其中的就里”指事情背后没有说出的原因，与“大家都想知道”相符。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：“想知道”一般搭配原因、内情，不说“想知道其中的字体”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与辞职的原因无关，句子说不通。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状与事情的原因无关，“大家都想知道其中的形状”不合逻辑。"}], "explanations": {"就里": "正确：“其中的就里”指事情背后没有说出的原因，与“大家都想知道”相符。", "字体": "搭配：“想知道”一般搭配原因、内情，不说“想知道其中的字体”。", "颜色": "语义：颜色与辞职的原因无关，句子说不通。", "形状": "语义：形状与事情的原因无关，“大家都想知道其中的形状”不合逻辑。"}, "sentence_index": 0, "correct_answer": "就里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的就里很快。", "explanation": "这里应该用〈速度〉。就里指一件事里面没有说出的原因，不能用来形容电脑的运行速度。"}, {"text": "他的就里很结实。", "explanation": "这里应该用〈体格〉。就里不能用来形容人的身体强壮。"}, {"text": "这块石头的就里很大。", "explanation": "这里应该用〈体积〉。就里指没有说出的原因，不能用来描述石头的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89601, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就里", "is_correct": true, "explanation": "正确：“看出了就里”指看出了没有说出的内情，与“却没有当面说破”相呼应。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“看出”不搭配“气味”，气味应该说“闻出”。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音应该说“听出”，“看出了声音”搭配不当。"}, {"text": "光线", "is_correct": false, "explanation": "语义：光线是可见的物理现象，与“却没有当面说破”的内情无关。"}], "explanations": {"就里": "正确：“看出了就里”指看出了没有说出的内情，与“却没有当面说破”相呼应。", "气味": "搭配：“看出”不搭配“气味”，气味应该说“闻出”。", "声音": "搭配：声音应该说“听出”，“看出了声音”搭配不当。", "光线": "语义：光线是可见的物理现象，与“却没有当面说破”的内情无关。"}, "sentence_index": 6, "correct_answer": "就里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说话的就里很响。", "explanation": "这里应该用〈音量〉。就里指没有说出的原因，不能用来形容说话的音量。"}, {"text": "这份作业的就里很难。", "explanation": "这里应该用〈难度〉。就里指没有说出的原因，不指作业的难易程度。"}, {"text": "这把椅子的就里很高。", "explanation": "这里应该用〈高度〉。就里不能用来描述椅子的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我隐约猜到一个就里。", "corrected_sentence": "我隐约猜到一些就里。", "error_description": "量词错误：“就里”指内情，不可数，表示不定量时多说“一些”，不说“一个”。应改为“我隐约猜到一些就里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有说出这件事就里。", "corrected_sentence": "他没有说出这件事的就里。", "error_description": "漏掉“的”：“这件事”修饰“就里”时通常要加“的”，漏掉后表达不自然，应改为“这件事的就里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
