INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89602, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "内情;内部的情况。", "primary_collocate": null, "pronunciation": "jiù lǐ", "ipa": "tɕjoʊ˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "他刚来公司，不知就里，就说了很多话。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没把就里告诉客人，客人还以为出了大事。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的就里，只有经理一个人清楚。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者到处打听，想弄清这件事的就里。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外人不了解就里，难免会误会他们。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张一直瞒着我，我至今不知道其中的就里。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着摇摇头，没有说出其中的就里。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先别问，等我告诉你这里面的就里。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不知就里的人，看到他哭都很吃惊。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把事情的就里都告诉了警察。", "target_word": "就里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "就里|名词|内情，内部的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3ab9ed-a0b5-40d9-895a-567767ad38c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就里", "is_correct": true, "explanation": "正确：“就里”指内情，与“不知内情就说了很多话”的意思一致。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与“不知……就说话”的情况无关，句子说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不是需要了解的情况，“不知味道，就说了很多话”不合逻辑。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是可以测量的数值，与“不知……就说了很多话”的情况无关。"}], "explanations": {"就里": "正确：“就里”指内情，与“不知内情就说了很多话”的意思一致。", "颜色": "语义：颜色与“不知……就说话”的情况无关，句子说不通。", "味道": "语义：味道不是需要了解的情况，“不知味道，就说了很多话”不合逻辑。", "温度": "语义：温度是可以测量的数值，与“不知……就说了很多话”的情况无关。"}, "sentence_index": 0, "correct_answer": "就里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告列出了所有就里。", "explanation": "这里应该用〈细节〉。就里指事情背后没有说出的内情，不指报告中列出的具体细节。"}, {"text": "这种饮料的就里有很多糖。", "explanation": "这里应该用〈成分〉。就里指内情，不能用来说饮料里含有什么。"}, {"text": "他们制定了一个详细的就里。", "explanation": "这里应该用〈计划〉。就里是没有说出的内情，不指可以制定的计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就里", "is_correct": true, "explanation": "正确：“其中的就里”指没有说出的内情，与句意一致。"}, {"text": "包装", "is_correct": false, "explanation": "语义：包装是事物的外在部分，不是可以说出的内情。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料与“没有说出”的情况无关，句子说不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”是测量得出的数值，“说出其中的体温”搭配不当。"}], "explanations": {"就里": "正确：“其中的就里”指没有说出的内情，与句意一致。", "包装": "语义：包装是事物的外在部分，不是可以说出的内情。", "颜料": "语义：颜料与“没有说出”的情况无关，句子说不通。", "体温": "搭配：“体温”是测量得出的数值，“说出其中的体温”搭配不当。"}, "sentence_index": 6, "correct_answer": "就里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的就里很精彩。", "explanation": "这里应该用〈内容〉。就里指没有说出的内情，不用来评价书的精彩程度。"}, {"text": "他说话的就里很温和。", "explanation": "这里应该用〈语气〉。就里是内情，不用来描述说话的语气。"}, {"text": "这座城市的就里很悠久。", "explanation": "这里应该用〈历史〉。就里指内情，不指城市历史的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我大概知道一个就里。", "corrected_sentence": "我大概知道一些就里。", "error_description": "量词错误：“就里”指内情，不可数，表示不定量时多说“一些”，不说“一个”。应改为“我大概知道一些就里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想弄清楚这件事就里。", "corrected_sentence": "我想弄清楚这件事的就里。", "error_description": "漏掉“的”：“这件事”修饰“就里”时通常要加“的”，漏掉后表达不自然，应改为“这件事的就里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e244b311-aaae-495b-909d-d9b2ebc1db12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "带来", "is_correct": true, "explanation": "正确答案。“带来”与“带去”方向相反，指带着东西或领着人到说话人所在的地方。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”是发声表演，与“带去”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指用笔记录文字，与“带去”没有反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "“洗”指用水清除污垢，与“带去”没有反义关系。"}], "correct_answer": "带来", "explanations": {"带来": "正确答案。“带来”与“带去”方向相反，指带着东西或领着人到说话人所在的地方。", "唱": "“唱”是发声表演，与“带去”没有反义关系。", "写": "“写”指用笔记录文字，与“带去”没有反义关系。", "洗": "“洗”指用水清除污垢，与“带去”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "带来", "is_correct": true, "explanation": "正确答案。“带来”与“带去”方向相反，指带着东西或领着人到说话人所在的地方。"}, {"text": "画", "is_correct": false, "explanation": "“画”指用笔描绘图形，与“带去”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "“读”指看着文字发出声音或理解文字，与“带去”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”指快速移动双腿，与“带去”没有反义关系。"}], "correct_answer": "带来", "explanations": {"带来": "正确答案。“带来”与“带去”方向相反，指带着东西或领着人到说话人所在的地方。", "画": "“画”指用笔描绘图形，与“带去”没有反义关系。", "读": "“读”指看着文字发出声音或理解文字，与“带去”没有反义关系。", "跑": "“跑”指快速移动双腿，与“带去”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿着东西，或者领着人，一起走到别的地方。", "primary_collocate": null, "pronunciation": "dài qù", "ipa": "taɪ̯˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "明天我会把这本书带去学校。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把孩子带去了医院。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一些水果带去朋友家。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把弟弟带去公园玩。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把学生带去了图书馆。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把雨伞带去办公室。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末爸爸要把我带去海边。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己做的蛋糕带去了公司。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们别忘了把礼物带去他家。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把小狗带去了医院看病。", "target_word": "带去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带去了", "label": "体标"}, {"form": "带去过", "label": "体标"}], "register": "中性", "sense_fingerprint": "拿着东西或领着人一起去别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc3263d-b0b9-4fc5-b37b-119d6a479c93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带去", "is_correct": true, "explanation": "正确答案。“把这本书带去学校”表示拿着书前往别的地方，与句意相符。"}, {"text": "吃去", "is_correct": false, "explanation": "语义：书不能吃，“吃去学校”与“这本书”的动作不符。"}, {"text": "扔去", "is_correct": false, "explanation": "语义：“扔”是抛出或丢弃，不是拿着东西一起去；“把这本书扔去学校”与“明天我会……”的句意不符。"}, {"text": "唱去", "is_correct": false, "explanation": "语义：“唱”是发声表演，不能把书“唱去”学校，与句意不符。"}], "explanations": {"带去": "正确答案。“把这本书带去学校”表示拿着书前往别的地方，与句意相符。", "吃去": "语义：书不能吃，“吃去学校”与“这本书”的动作不符。", "扔去": "语义：“扔”是抛出或丢弃，不是拿着东西一起去；“把这本书扔去学校”与“明天我会……”的句意不符。", "唱去": "语义：“唱”是发声表演，不能把书“唱去”学校，与句意不符。"}, "sentence_index": 0, "correct_answer": "带去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你快把作业带去我这儿。", "explanation": "这里应该用〈带来〉。“我这儿”是说话人所在的地方，朝说话人方向移动应说“带来”，“带去”指离开说话人去别处。"}, {"text": "同事给我带去了一份文件。", "explanation": "这里应该用〈送来〉。“给我”表示朝说话人方向，应说“送来”，“带去”指离开说话人去别处。"}, {"text": "你把这本书带去我这里吧。", "explanation": "这里应该用〈带来〉。“我这里”是说话人所在的地方，朝说话人方向移动应说“带来”，“带去”指离开说话人去别处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带去", "is_correct": true, "explanation": "正确答案。“把我带去海边”表示领着人前往别的地方，与句意相符。"}, {"text": "拿去", "is_correct": false, "explanation": "语义：“拿”只用于东西，不能把人“拿去”海边。"}, {"text": "哭去", "is_correct": false, "explanation": "语义：“哭”是不及物动词，不能以“把”字引出的人作宾语，“周末爸爸要把我哭去海边”不成立。"}, {"text": "笑去", "is_correct": false, "explanation": "语义：“笑”是不及物动词，不能把人“笑去”海边，与句意不符。"}], "explanations": {"带去": "正确答案。“把我带去海边”表示领着人前往别的地方，与句意相符。", "拿去": "语义：“拿”只用于东西，不能把人“拿去”海边。", "哭去": "语义：“哭”是不及物动词，不能以“把”字引出的人作宾语，“周末爸爸要把我哭去海边”不成立。", "笑去": "语义：“笑”是不及物动词，不能把人“笑去”海边，与句意不符。"}, "sentence_index": 6, "correct_answer": "带去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸出差回来，给我带去了一份礼物。", "explanation": "这里应该用〈带回〉。“给我”表示朝说话人方向，应说“带回”，“带去”指离开说话人去别处。"}, {"text": "妈妈在老家给我带去了一箱苹果。", "explanation": "这里应该用〈寄来〉。“给我”表示朝说话人方向，应说“寄来”，“带去”指离开说话人去别处。"}, {"text": "朋友从北京给我带去了一封信。", "explanation": "这里应该用〈捎来〉。“给我”表示朝说话人方向，应说“捎来”，“带去”指离开说话人去别处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天把这本书带去图书馆了。", "corrected_sentence": "我明天把这本书带去图书馆。", "error_description": "时态错误：“明天”指将来，句末不能加“了”表示已完成。应说“我明天把这本书带去图书馆”，不能说“带去图书馆了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈带去地钥匙找到了。", "corrected_sentence": "妈妈带去的钥匙找到了。", "error_description": "结构助词错误：“带去”修饰名词“钥匙”，应用“的”，说“带去的钥匙”；“地”用于修饰动词、形容词，不能说“带去地钥匙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89606, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "带来", "is_correct": true, "explanation": "正确答案。“带来”与“带去”方向相反，指带着东西或领着人到说话人所在的地方。"}, {"text": "打扫", "is_correct": false, "explanation": "“打扫”指清除垃圾和灰尘，与“带去”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "“读”指看着文字发出声音或理解文字，与“带去”没有反义关系。"}, {"text": "画", "is_correct": false, "explanation": "“画”指用笔描绘图形，与“带去”没有反义关系。"}], "correct_answer": "带来", "explanations": {"带来": "正确答案。“带来”与“带去”方向相反，指带着东西或领着人到说话人所在的地方。", "打扫": "“打扫”指清除垃圾和灰尘，与“带去”没有反义关系。", "读": "“读”指看着文字发出声音或理解文字，与“带去”没有反义关系。", "画": "“画”指用笔描绘图形，与“带去”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
