INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89609, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "门票是进公园、电影院等地方要买的一张小票。", "primary_collocate": null, "pronunciation": "mén piào", "ipa": "mən˧˥ pʰjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我买了两张公园门票。", "target_word": "门票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的门票一张五十块。", "target_word": "门票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把门票给检票员看一下。", "target_word": "门票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子进动物园不用买门票。", "target_word": "门票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在门口丢了门票，进不去。", "target_word": "门票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我拿着两张门票在门口等朋友。", "target_word": "门票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的博物馆门票已经卖完了。", "target_word": "门票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场音乐会的门票很难买。", "target_word": "门票", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生买门票可以打八折。", "target_word": "门票", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他送我一张游乐园的门票。", "target_word": "门票", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张门票", "label": "量词"}, {"form": "免费门票", "label": "复合"}, {"form": "門票", "label": "繁体"}], "register": "中性", "sense_fingerprint": "进公园、电影院等地方要买的小票", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a0ab2c6-267b-46f6-963b-75f6b1d7240e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89609, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "门票", "is_correct": true, "explanation": "门票：进公园要买的票，与“我买了两张公园”的语境相合。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票是乘车用的票，公园里不卖这种票，句意不通。"}, {"text": "发票", "is_correct": false, "explanation": "语义：发票是购物凭证，不是进园用的票，句意不通。"}, {"text": "请柬", "is_correct": false, "explanation": "搭配：请柬是发出去的邀请函，不说“买”，与“买了两张”不搭。"}], "explanations": {"门票": "门票：进公园要买的票，与“我买了两张公园”的语境相合。", "车票": "语义：车票是乘车用的票，公园里不卖这种票，句意不通。", "发票": "语义：发票是购物凭证，不是进园用的票，句意不通。", "请柬": "搭配：请柬是发出去的邀请函，不说“买”，与“买了两张”不搭。"}, "sentence_index": 0, "correct_answer": "门票"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在网上买了一张飞上海的门票。", "explanation": "这里应该用〈机票〉。门票用于进入公园、剧场等场所，坐飞机要买机票。"}, {"text": "我买了一张去北京的门票。", "explanation": "这里应该用〈车票〉。门票用于进入公园、剧场等场所，去北京要买的是车票。"}, {"text": "我在超市买完东西，店员给了我一张门票。", "explanation": "这里应该用〈发票〉。门票是进入场所的凭证，购物凭证要说发票。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "门票", "is_correct": true, "explanation": "门票：博物馆周末售完的入场票，与语境相合。"}, {"text": "船票", "is_correct": false, "explanation": "语义：船票用于乘船，与博物馆无关，句意不通。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：账单是付款后的凭据，不说“卖完”，与“已经卖完了”不搭。"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票是证券，不在博物馆里出售，句意不通。"}], "explanations": {"门票": "门票：博物馆周末售完的入场票，与语境相合。", "船票": "语义：船票用于乘船，与博物馆无关，句意不通。", "账单": "搭配：账单是付款后的凭据，不说“卖完”，与“已经卖完了”不搭。", "股票": "语义：股票是证券，不在博物馆里出售，句意不通。"}, "sentence_index": 6, "correct_answer": "门票"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他忘了带门票，回不了宿舍。", "explanation": "这里应该用〈门禁卡〉。门票是买来进入公园、剧场等场所的票，宿舍门要靠门禁卡刷开。"}, {"text": "我在码头买了一张去大连的门票。", "explanation": "这里应该用〈船票〉。门票用于进入场所，乘船去大连要买船票。"}, {"text": "我买了一张门票，希望能中大奖。", "explanation": "这里应该用〈彩票〉。门票用于进入场所，希望中大奖要买彩票。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了两张门票们。", "corrected_sentence": "我买了两张门票。", "error_description": "“们”只加在指人的名词后，不能加在“门票”后，应删去，改为“两张门票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我门票忘在家里了。", "corrected_sentence": "我的门票忘在家里了。", "error_description": "漏掉“的”：“我”修饰“门票”时要加“的”，应为“我的门票”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
