INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89611, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事很快，不拖拉。", "primary_collocate": null, "pronunciation": "kuài dang", "ipa": "kʰuaɪ̯˥˩ taŋ", "syllable_count": 2, "sentences": [{"text": "他办事一向快当，从不拖拉。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板喜欢做事快当的员工。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他接到任务就动手，快当得很。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事处理得快当，大家都满意。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做决定很快当，不会想很久。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办手续这么快当，我真没想到。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃饭、洗澡都很快当。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理回信回得真快当。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事快当的人，别人都愿意找他。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修车师傅检查得很快当，十分钟就好了。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "快快当当", "label": "重叠"}], "register": "口语", "sense_fingerprint": "做事很快、不拖拉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc3263d-b0b9-4fc5-b37b-119d6a479c93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89611, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "快当", "is_correct": true, "explanation": "快当：做事敏捷，不拖拉，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来说办事的快慢。"}, {"text": "甜美", "is_correct": false, "explanation": "体貌：“甜美”形容声音或容貌，与办事无关。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：“冰凉”形容温度，与办事的快慢无关。"}], "explanations": {"快当": "快当：做事敏捷，不拖拉，符合句意。", "高大": "体貌：“高大”形容身材，不能用来说办事的快慢。", "甜美": "体貌：“甜美”形容声音或容貌，与办事无关。", "冰凉": "语义：“冰凉”形容温度，与办事的快慢无关。"}, "sentence_index": 0, "correct_answer": "快当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个学期过得很快当。", "explanation": "这里应该用〈快〉。快当形容人做事利落，不用来说学期流逝的快慢。"}, {"text": "他的个子很快当。", "explanation": "这里应该用〈高〉。快当形容做事利落，不用来形容身材。"}, {"text": "她对老人很快当。", "explanation": "这里应该用〈耐心〉。快当形容做事利落，不用来说对待别人的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89611, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "快当", "is_correct": true, "explanation": "快当：做事敏捷利落，符合句意。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”形容外貌，不能用来说吃饭洗澡的快慢。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”说空间，不说吃饭洗澡。"}, {"text": "圆润", "is_correct": false, "explanation": "语义：“圆润”形容声音或形状，与吃饭洗澡无关。"}], "explanations": {"快当": "快当：做事敏捷利落，符合句意。", "美丽": "语义：“美丽”形容外貌，不能用来说吃饭洗澡的快慢。", "宽敞": "搭配：“宽敞”说空间，不说吃饭洗澡。", "圆润": "语义：“圆润”形容声音或形状，与吃饭洗澡无关。"}, "sentence_index": 6, "correct_answer": "快当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影很快当。", "explanation": "这里应该用〈精彩〉。快当形容人做事利落，不用来评价电影。"}, {"text": "这座房子很快当。", "explanation": "这里应该用〈漂亮〉。快当只形容人的动作，不用来形容房屋。"}, {"text": "房间很快当。", "explanation": "这里应该用〈干净〉。快当说的是动作利落，不用来形容房间整洁与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学生做事了快当。", "corrected_sentence": "这个学生做事很快当。", "error_description": "形容词“快当”前不能加“了”；“了”不能放在“做事”和“快当”之间，应改为程度副词“很”，说“做事很快当”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
