INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89612, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "敏捷利落；迅速。", "primary_collocate": null, "pronunciation": "kuài dang", "ipa": "kʰuaɪ̯˥˩ taŋ", "syllable_count": 2, "sentences": [{"text": "他干活很快当。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手脚真快当。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位师傅做事又快当又仔细。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王把房间打扫得很快当。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三下两下就收拾好了，真快当。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师切菜的动作很快当。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李处理事情很快当。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮递员送信一向很快当。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她洗衣服洗得又快当又干净。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子穿衣服很快当。", "target_word": "快当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "快快当当", "label": "重叠"}], "register": "口语", "sense_fingerprint": "动作敏捷利落、迅速", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc3263d-b0b9-4fc5-b37b-119d6a479c93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "快当", "is_correct": true, "explanation": "快当：敏捷利落，形容干活的动作麻利，符合句意。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”形容外貌或景色，不能用来评价干活的快慢。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”说空间，不说干活的样子。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：“冰凉”形容温度或触感，与干活的快慢无关。"}], "explanations": {"快当": "快当：敏捷利落，形容干活的动作麻利，符合句意。", "美丽": "语义：“美丽”形容外貌或景色，不能用来评价干活的快慢。", "宽敞": "搭配：“宽敞”说空间，不说干活的样子。", "冰凉": "语义：“冰凉”形容温度或触感，与干活的快慢无关。"}, "sentence_index": 0, "correct_answer": "快当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个假期时间过得很快当。", "explanation": "这里应该用〈快〉。快当形容人做事敏捷利落，不用来说时间流逝的快慢。"}, {"text": "这座山很快当。", "explanation": "这里应该用〈高〉。快当形容动作利落或迅速，不用来形容山的高低。"}, {"text": "这块石头很快当。", "explanation": "这里应该用〈重〉。快当形容动作利落或迅速，不用来形容物体的轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "快当", "is_correct": true, "explanation": "快当：敏捷利落，形容处理事情干脆麻利，符合句意。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，不能用来说处理事情的快慢。"}, {"text": "甜美", "is_correct": false, "explanation": "体貌：“甜美”形容声音或容貌，与处理事情无关。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来评价做事的快慢。"}], "explanations": {"快当": "快当：敏捷利落，形容处理事情干脆麻利，符合句意。", "寒冷": "语义：“寒冷”形容温度，不能用来说处理事情的快慢。", "甜美": "体貌：“甜美”形容声音或容貌，与处理事情无关。", "高大": "体貌：“高大”形容身材，不能用来评价做事的快慢。"}, "sentence_index": 6, "correct_answer": "快当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌很快当。", "explanation": "这里应该用〈好听〉。快当形容人做事利落，不用来评价歌曲。"}, {"text": "这幅画很快当。", "explanation": "这里应该用〈好看〉。快当只形容人的动作，不用来评价画作。"}, {"text": "他对孩子很快当。", "explanation": "这里应该用〈耐心〉。快当形容动作利落，不用来说对待别人的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是个很快当地人。", "corrected_sentence": "她是个很快当的人。", "error_description": "结构助词错误：“快当”修饰名词“人”，应用“的”，说“很快当的人”；“地”用于修饰动词，不能说“很快当地人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈做家务做很快当。", "corrected_sentence": "妈妈做家务做得很快当。", "error_description": "补语前应有“得”：说“做得很快当”；漏掉“得”，说“做很快当”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07af9851-8207-4882-aef2-aee5d4796571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
