INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "家庭的社会地位和声望。", "primary_collocate": null, "pronunciation": "mén dì", "ipa": "mən˧˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这个家族门第显赫，在城里很有名。", "target_word": "门第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代很看重门第，穷人很难做官。", "target_word": "门第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠自己努力，不靠家里的门第。", "target_word": "门第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里写了两个门第不同的年轻人。", "target_word": "门第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧社会讲究门第，儿女的婚事由父母决定。", "target_word": "门第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门第再高，也不能看不起别人。", "target_word": "门第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的门第很高，可是为人很谦虚。", "target_word": "门第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在那个年代，门第决定了一个人的前途。", "target_word": "门第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老宅说明，这家人的门第曾经很显赫。", "target_word": "门第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家人门第不高，但是很受人敬重。", "target_word": "门第", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "门第：家庭的社会地位和声望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e48683c-72c5-47cf-8ca9-695253ccc13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89614, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "门第", "is_correct": true, "explanation": "门第 mén dì：正确答案，指家庭的社会地位和名望。"}, {"text": "盆地", "is_correct": false, "explanation": "pén 与 mén 声母不同（p／m），声调相同，意思是四周高中间低的地形。"}, {"text": "满地", "is_correct": false, "explanation": "mǎn（第三声）与 mén（第二声）韵母与声调不同，意思是遍地、到处都是。"}, {"text": "猛地", "is_correct": false, "explanation": "měng（第三声）与 mén（第二声）韵母与声调不同，意思是突然。"}, {"text": "本地", "is_correct": false, "explanation": "běn（第三声）与 mén（第二声）声母与声调不同，意思是当地、本地。"}], "explanations": {"门第": "门第 mén dì：正确答案，指家庭的社会地位和名望。", "盆地": "pén 与 mén 声母不同（p／m），声调相同，意思是四周高中间低的地形。", "满地": "mǎn（第三声）与 mén（第二声）韵母与声调不同，意思是遍地、到处都是。", "猛地": "měng（第三声）与 mén（第二声）韵母与声调不同，意思是突然。", "本地": "běn（第三声）与 mén（第二声）声母与声调不同，意思是当地、本地。"}, "sentence_index": null, "correct_answer": "门第"}, "level_3": {"options": [{"text": "门第", "is_correct": true, "explanation": "正确：门第指家庭的社会地位和名望，“门第显赫”搭配自然。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”指人数，不能用“显赫”来形容。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指冷热阴晴，与家族的名望无关。"}, {"text": "步伐", "is_correct": false, "explanation": "语义：步伐指走路的脚步，不能说家族“步伐显赫”。"}], "explanations": {"门第": "正确：门第指家庭的社会地位和名望，“门第显赫”搭配自然。", "人口": "搭配：“人口”指人数，不能用“显赫”来形容。", "天气": "语义：天气指冷热阴晴，与家族的名望无关。", "步伐": "语义：步伐指走路的脚步，不能说家族“步伐显赫”。"}, "sentence_index": 0, "correct_answer": "门第"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试她的门第很高，全班第一。", "explanation": "这里应该用〈成绩〉。门第指家庭地位，考试的好坏要用“成绩”。"}, {"text": "她研究生毕业，门第很高，找工作很容易。", "explanation": "这里应该用〈学历〉。门第不指个人受教育的程度，应说“学历很高”。"}, {"text": "这个月他的门第很高，还清了贷款。", "explanation": "这里应该用〈收入〉。门第指家庭地位，个人一个月赚的钱要用“收入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "门第", "is_correct": true, "explanation": "正确：门第指家庭的社会地位，“门第很高”与后句“为人很谦虚”形成转折。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔指地面高出海平面的高度，不能用来形容一个人的门第。"}, {"text": "视力", "is_correct": false, "explanation": "语义：视力是眼睛看东西的能力，不能用来形容“门第”。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数指文字的数量，不能形容家庭的地位。"}], "explanations": {"门第": "正确：门第指家庭的社会地位，“门第很高”与后句“为人很谦虚”形成转折。", "海拔": "语义：海拔指地面高出海平面的高度，不能用来形容一个人的门第。", "视力": "语义：视力是眼睛看东西的能力，不能用来形容“门第”。", "字数": "语义：字数指文字的数量，不能形容家庭的地位。"}, "sentence_index": 6, "correct_answer": "门第"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的门第很高，适合当模特。", "explanation": "这里应该用〈个子〉。门第指家庭地位，说人的高矮要用“个子”。"}, {"text": "他的英语门第很高，能用英语写文章。", "explanation": "这里应该用〈水平〉。门第不用于能力的高低，英语的高低要用“水平”。"}, {"text": "孩子的门第很高，要马上去医院。", "explanation": "这里应该用〈体温〉。门第不指身体的温度，孩子发烧时要说“体温很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个家族的门第矮，亲戚都很敬重他们。", "corrected_sentence": "这个家族的门第低，亲戚都很敬重他们。", "error_description": "“矮”错误，应为“低”。门第指家庭的社会地位，地位高低用“低”，不用“矮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他出身普通，门第矮，只能靠自己奋斗。", "corrected_sentence": "他出身普通，门第低，只能靠自己奋斗。", "error_description": "“矮”错误，应为“低”。门第指家庭的社会地位，地位高低用“低”，不用“矮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff614021-6adc-43dd-b962-1474bfb99a80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
