INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89615, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "感受是心里觉得到的样子。", "primary_collocate": null, "pronunciation": "gǎn shòu", "ipa": "kan˨˩ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "来到新城市，我的第一个感受是安静。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你说说看完这部电影后的感受。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在农村的感受和住在城市很不一样。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们写下旅行的真实感受。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一次坐飞机，他有一种很特别的感受。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把自己的感受告诉了妈妈。", "target_word": "感受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人对这件事的感受都不同。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听完他的故事，我的感受很复杂。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们不太会说出自己的感受。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "读这篇文章的感受，我到现在还记得。", "target_word": "感受", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词：心里对事物产生的感觉和体会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b85a5fef-cf91-4887-8a4f-1d7906f0a58f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89615, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感受", "is_correct": true, "explanation": "正确：“第一个感受”指心里的体会，与“是安静”搭配。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不能用来描述心里的感觉是安静。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能直接用“是安静”来描述人的感觉。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或口味，与新城市给人的心理感觉不符。"}], "explanations": {"感受": "正确：“第一个感受”指心里的体会，与“是安静”搭配。", "感冒": "语义：“感冒”是疾病，不能用来描述心里的感觉是安静。", "颜色": "搭配：“颜色”不能直接用“是安静”来描述人的感觉。", "味道": "语义：“味道”指气味或口味，与新城市给人的心理感觉不符。"}, "sentence_index": 0, "correct_answer": "感受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的感受高两米，只能弯着腰走路。", "explanation": "这里应该用〈个子〉。感受指心里觉得到的样子，人的高矮要说“个子”，不能用“感受”。"}, {"text": "这件衣服的感受是红色的。", "explanation": "这里应该用〈颜色〉。感受指心里的体会，衣服是什么颜色要说“颜色”，不能用“感受”。"}, {"text": "这块石头的感受很粗糙。", "explanation": "这里应该用〈手感〉。感受指心里觉得到的样子，摸到物体的质地要说“手感”，不能用“感受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89615, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感受", "is_correct": true, "explanation": "正确：每个人对这件事的心里感觉不同，符合“感受”的意思。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”指钱的数目，不能说“对这件事的价格”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人的岁数，与对这件事的心理反应无关。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，与对事情的感觉无关。"}], "explanations": {"感受": "正确：每个人对这件事的心里感觉不同，符合“感受”的意思。", "价格": "搭配：“价格”指钱的数目，不能说“对这件事的价格”。", "年龄": "语义：“年龄”指人的岁数，与对这件事的心理反应无关。", "体重": "语义：“体重”指身体的重量，与对事情的感觉无关。"}, "sentence_index": 6, "correct_answer": "感受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的感受是五十块钱。", "explanation": "这里应该用〈价格〉。感受指心里的体会，书卖多少钱要说“价格”，不能用“感受”。"}, {"text": "这道菜的感受很咸。", "explanation": "这里应该用〈味道〉。感受指心里觉得到的样子，菜的咸淡要说“味道”，不能用“感受”。"}, {"text": "我的感受很重，有五十公斤。", "explanation": "这里应该用〈体重〉。感受指心里觉得到的样子，人的重量要说“体重”，不能用“感受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89615, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一条很深的感受。", "corrected_sentence": "我有一种很深的感受。", "error_description": "量词错误：“感受”应用“种”（或“个”），用“条”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89615, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "读完这封信，她有一只温暖的感受。", "corrected_sentence": "读完这封信，她有一种温暖的感受。", "error_description": "量词错误：“感受”应用“种”（或“个”），“只”用于动物或成对事物中的一个，不能用于感受。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199f2240-b881-461a-bdb0-22d1d29b7975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
