INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89619, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "关说是请有地位的人帮忙对别人说好话。", "primary_collocate": null, "pronunciation": "guān shuō", "ipa": "kuan˥ ʂuo˥", "syllable_count": 2, "sentences": [{"text": "他想请市长帮他关说一下。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让儿子进好学校，她去找校长的朋友关说。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要找人关说，自己好好准备考试。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请一位老朋友向经理关说，想得到那份工作。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生认识局长，常有人来请他关说。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去替你关说，他一定会帮忙。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给老板打电话关说，希望他多照顾弟弟。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找人关说不一定有用，还要靠自己。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他关说了两次，老师才答应再看看。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友替我关说，我才拿到了面试的机会。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "关说了", "label": "体标"}, {"form": "关说过", "label": "体标"}], "register": "书面", "sense_fingerprint": "请有地位的人替自己向别人说好话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89619, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关说", "is_correct": true, "explanation": "关说：请有地位的人替人说好话，符合「请市长帮他」的语境。"}, {"text": "举报", "is_correct": false, "explanation": "语义：举报是向有关部门揭发他人违法行为，与「帮他」的好意相反。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评是指出缺点和错误，与「帮他」的意图不符。"}, {"text": "提高", "is_correct": false, "explanation": "语义：提高是使水平或数量变高，与请市长替人说好话的意思不符。"}], "explanations": {"关说": "关说：请有地位的人替人说好话，符合「请市长帮他」的语境。", "举报": "语义：举报是向有关部门揭发他人违法行为，与「帮他」的好意相反。", "批评": "语义：批评是指出缺点和错误，与「帮他」的意图不符。", "提高": "语义：提高是使水平或数量变高，与请市长替人说好话的意思不符。"}, "sentence_index": 0, "correct_answer": "关说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天都关说我早点睡觉。", "explanation": "这里应该用〈劝说〉。关说是请有地位的第三人替人说情，不能用来直接劝别人做事。"}, {"text": "他在会上关说了几句，大家都很认真地听。", "explanation": "这里应该用〈发言〉。关说是请有地位的人替人说好话，不能指在会上讲话。"}, {"text": "他向老师关说迟到的原因。", "explanation": "这里应该用〈解释〉。关说指替人说好话求照顾，不是说明事情的原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89619, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关说", "is_correct": true, "explanation": "关说：请人替自己向有关方面说情，符合「给老板打电话」的请托语境。"}, {"text": "骂", "is_correct": false, "explanation": "语义：骂是斥责他人，与「希望他多照顾弟弟」的请托意思相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：拒绝是回绝对方，与「希望他多照顾弟弟」的意思相冲突。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡是清洁身体，与打电话请老板照顾弟弟无关，句子说不通。"}], "explanations": {"关说": "关说：请人替自己向有关方面说情，符合「给老板打电话」的请托语境。", "骂": "语义：骂是斥责他人，与「希望他多照顾弟弟」的请托意思相反。", "拒绝": "语义：拒绝是回绝对方，与「希望他多照顾弟弟」的意思相冲突。", "洗澡": "语义：洗澡是清洁身体，与打电话请老板照顾弟弟无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "关说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板关说了他一顿，他很委屈。", "explanation": "这里应该用〈训斥〉。关说是请有地位的人替人说好话，不能表示责备他人。"}, {"text": "老师关说他的作文写得很好，所以给了高分。", "explanation": "这里应该用〈称赞〉。关说是请人替自己求情，不是对别人的优点加以赞扬。"}, {"text": "他和朋友关说了一下午。", "explanation": "这里应该用〈聊天〉。关说是替人向有地位的人说好话，不指一般的闲谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他请亲戚替他局长关说，希望能调到好部门。", "corrected_sentence": "他请亲戚替他向局长关说，希望能调到好部门。", "error_description": "介词漏用：关说的对象（局长）前应加介词「向」，应写作「替他向局长关说」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你帮我关说一个，好吗？", "corrected_sentence": "请你帮我关说一下，好吗？", "error_description": "补语错误：表示动作稍作尝试的动量补语应用“一下”，不能用“一个”，应写作“关说一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
