INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "私下向有关人员说情、疏通。", "primary_collocate": null, "pronunciation": "guān shuō", "ipa": "kuan˥ ʂuo˥", "syllable_count": 2, "sentences": [{"text": "有人私下向法官关说，想让朋友少坐牢。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司规定，不能找官员关说。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他私下找负责人关说，想拿到工程。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请议员出面关说，事情才办成。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者发现有人向警察关说，想把案子放一放。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不合规定，谁来关说都没用。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她托人关说，希望能少交一点钱。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司说，所有关说的电话都要记下来。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不关说，也不收别人的礼物。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请朋友向官员关说，所以事情很快办好了。", "target_word": "关说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "关说了", "label": "体标"}, {"form": "关说过", "label": "体标"}], "register": "书面", "sense_fingerprint": "私下向有关人员说情、疏通以求照顾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03a58b85-513c-435a-bb24-117a71c919f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关说", "is_correct": true, "explanation": "关说：私下向有关人员说情疏通，符合「私下向法官」的语境。"}, {"text": "举报", "is_correct": false, "explanation": "语义：举报是揭发他人的违法行为，与「想让朋友少坐牢」的目的相反。"}, {"text": "上诉", "is_correct": false, "explanation": "搭配：上诉是向上级法院提出，不能私下向法官本人提出，搭配不当。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评是指出错误，与「想让朋友少坐牢」的目的相反。"}], "explanations": {"关说": "关说：私下向有关人员说情疏通，符合「私下向法官」的语境。", "举报": "语义：举报是揭发他人的违法行为，与「想让朋友少坐牢」的目的相反。", "上诉": "搭配：上诉是向上级法院提出，不能私下向法官本人提出，搭配不当。", "批评": "语义：批评是指出错误，与「想让朋友少坐牢」的目的相反。"}, "sentence_index": 0, "correct_answer": "关说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下班后向经理关说了工作进展。", "explanation": "这里应该用〈汇报〉。关说是私下替人说情疏通，不是报告工作情况。"}, {"text": "他和同事关说了很久，还是没定下方案。", "explanation": "这里应该用〈讨论〉。关说指私下向有关人员说情、疏通，不指同事之间商量。"}, {"text": "老师向学生关说了这道题的解法。", "explanation": "这里应该用〈讲解〉。关说是替人向有关人员说好话，不用来讲解知识。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关说", "is_correct": true, "explanation": "关说：私下托人向有关方面说情，符合「托人」和「少交钱」的语境。"}, {"text": "缴纳", "is_correct": false, "explanation": "语义：缴纳是交钱，与「希望能少交一点钱」的意思相反。"}, {"text": "增加", "is_correct": false, "explanation": "配价：增加要带宾语（增加什么），「托人增加」缺少宾语，不成句。"}, {"text": "支付", "is_correct": false, "explanation": "语义：支付是付钱，与「希望能少交一点钱」的意思相反。"}], "explanations": {"关说": "关说：私下托人向有关方面说情，符合「托人」和「少交钱」的语境。", "缴纳": "语义：缴纳是交钱，与「希望能少交一点钱」的意思相反。", "增加": "配价：增加要带宾语（增加什么），「托人增加」缺少宾语，不成句。", "支付": "语义：支付是付钱，与「希望能少交一点钱」的意思相反。"}, "sentence_index": 6, "correct_answer": "关说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经理关说大家明天开会。", "explanation": "这里应该用〈通知〉。关说是替人向有权人士说情，不用来传达信息。"}, {"text": "他向客户关说产品。", "explanation": "这里应该用〈推销〉。关说不表示向人推销商品。"}, {"text": "我们去北京关说了故宫。", "explanation": "这里应该用〈参观〉。关说是替人向有地位的人说好话，不指游览景点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他私下局长关说，希望能把罚款减一些。", "corrected_sentence": "他私下向局长关说，希望能把罚款减一些。", "error_description": "介词漏用：关说的对象（局长）前应加介词「向」，应写作「他私下向局长关说」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她托同学主任关说，希望能换个班。", "corrected_sentence": "她托同学向主任关说，希望能换个班。", "error_description": "介词漏用：关说的对象（主任）前应加介词「向」，应写作「她托同学向主任关说」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a345e6f1-434d-4163-8ee1-2464e2e577e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
