INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89621, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最好、最合适的（多指时间、位置、办法等）。", "primary_collocate": null, "pronunciation": "zuì jiā", "ipa": "tsweɪ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "春天是去北京玩的最佳时间。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是你现在最佳的选择。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上读书效果最佳。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在前面是看电影的最佳位置。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认为这个办法是最佳的。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡前不吃东西是最佳做法。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的位置最佳，客人很多。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气很好，是拍照的最佳机会。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁是去机场的最佳方式。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对写作来说，安静的环境是最佳的条件。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "时间、位置、办法等最合适最好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89621, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "最佳", "is_correct": true, "explanation": "正确。最佳 zuì jiā 指最好、最合适的。"}, {"text": "作家", "is_correct": false, "explanation": "zuò（第四声）与 zuì（第四声）韵母不同（o 与 i），意思是写作的人。"}, {"text": "醉驾", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是醉酒后开车。"}, {"text": "自家", "is_correct": false, "explanation": "zì 比 zuì 少了 u 介音，发音不同，意思是自己家或自己人。"}], "explanations": {"最佳": "正确。最佳 zuì jiā 指最好、最合适的。", "作家": "zuò（第四声）与 zuì（第四声）韵母不同（o 与 i），意思是写作的人。", "醉驾": "jià（第四声）与 jiā（第一声）声调不同，意思是醉酒后开车。", "自家": "zì 比 zuì 少了 u 介音，发音不同，意思是自己家或自己人。"}, "sentence_index": null, "correct_answer": "最佳"}, "level_3": {"options": [{"text": "最佳", "is_correct": true, "explanation": "正确。最佳修饰“时间”，表示最合适的时间。"}, {"text": "严重", "is_correct": false, "explanation": "语义：“严重”指情况危险或程度深，不能用来形容时间。"}, {"text": "高级", "is_correct": false, "explanation": "搭配：“高级”说等级或质量，不能修饰“时间”。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容表面，不能说粗糙的时间。"}], "explanations": {"最佳": "正确。最佳修饰“时间”，表示最合适的时间。", "严重": "语义：“严重”指情况危险或程度深，不能用来形容时间。", "高级": "搭配：“高级”说等级或质量，不能修饰“时间”。", "粗糙": "搭配：“粗糙”形容表面，不能说粗糙的时间。"}, "sentence_index": 0, "correct_answer": "最佳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我最佳的朋友。", "explanation": "这里应该用〈最好〉。最佳多指时间、位置、办法等最合适的选择，不用来形容人际关系中的朋友。"}, {"text": "这是我最佳的回忆。", "explanation": "这里应该用〈最美好〉。最佳侧重合适或优越，回忆这类感受要说最美好。"}, {"text": "这次事故的伤亡最佳。", "explanation": "这里应该用〈最少〉。最佳表示优越、合适，伤亡这类负面结果要说伤亡最少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89621, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最佳", "is_correct": true, "explanation": "正确。最佳说位置最合适，与“客人很多”相符。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”形容重量或心情，不能修饰店铺的位置。"}, {"text": "僵硬", "is_correct": false, "explanation": "搭配：“僵硬”形容身体或物体的状态，不能修饰店铺的位置。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容地势，不用来描述店铺的位置。"}], "explanations": {"最佳": "正确。最佳说位置最合适，与“客人很多”相符。", "沉重": "搭配：“沉重”形容重量或心情，不能修饰店铺的位置。", "僵硬": "搭配：“僵硬”形容身体或物体的状态，不能修饰店铺的位置。", "陡峭": "搭配：“陡峭”形容地势，不用来描述店铺的位置。"}, "sentence_index": 6, "correct_answer": "最佳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的难度最佳。", "explanation": "这里应该用〈最难〉。最佳表示优越、合适，说题目的难度要用最难。"}, {"text": "这次地震的破坏程度最佳。", "explanation": "这里应该用〈最严重〉。最佳表示优越、合适，破坏程度要说最严重。"}, {"text": "这种药的副作用最佳。", "explanation": "这里应该用〈最轻〉。最佳表示优越、合适，副作用要说最轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个办法很最佳。", "corrected_sentence": "这个办法最佳。", "error_description": "错误：“很最佳”。正确：“最佳”。“最佳”本身已表示最好，前面不能再加“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
