INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89622, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（比赛、评选中）最优秀的。", "primary_collocate": null, "pronunciation": "zuì jiā", "ipa": "tsweɪ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "他得到了本届比赛的最佳球员奖。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影得了最佳影片奖。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是今年的最佳女演员。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师得了最佳教师奖。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队今天取得了最佳成绩。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凭借这场比赛的表现，被评为最佳选手。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片是比赛中的最佳作品。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李被评为这次唱歌比赛的最佳歌手。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，他拿到了最佳进步奖。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位设计师的作品获得了最佳设计奖。", "target_word": "最佳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "比赛评选中最优秀的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a670e97f-7768-4085-8ced-22657cd44e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89622, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "最佳", "is_correct": true, "explanation": "正确。最佳 zuì jiā 指比赛评选中最优秀的。"}, {"text": "作家", "is_correct": false, "explanation": "zuò（第四声）与 zuì（第四声）韵母不同（o 与 i），意思是写作的人。"}, {"text": "醉驾", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是醉酒后开车。"}, {"text": "自家", "is_correct": false, "explanation": "zì 比 zuì 少了 u 介音，发音不同，意思是自己家或自己人。"}], "explanations": {"最佳": "正确。最佳 zuì jiā 指比赛评选中最优秀的。", "作家": "zuò（第四声）与 zuì（第四声）韵母不同（o 与 i），意思是写作的人。", "醉驾": "jià（第四声）与 jiā（第一声）声调不同，意思是醉酒后开车。", "自家": "zì 比 zuì 少了 u 介音，发音不同，意思是自己家或自己人。"}, "sentence_index": null, "correct_answer": "最佳"}, "level_3": {"options": [{"text": "最佳", "is_correct": true, "explanation": "正确。最佳修饰“球员奖”，表示评选中最优秀的球员。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”形容速度，与评选奖项的含义无关。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”形容身高，不能说矮球员奖。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”形容温度，不能修饰奖项。"}], "explanations": {"最佳": "正确。最佳修饰“球员奖”，表示评选中最优秀的球员。", "慢": "语义：“慢”形容速度，与评选奖项的含义无关。", "矮": "搭配：“矮”形容身高，不能说矮球员奖。", "冷": "搭配：“冷”形容温度，不能修饰奖项。"}, "sentence_index": 0, "correct_answer": "最佳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个字在书里出现的次数最佳。", "explanation": "这里应该用〈最多〉。最佳表示优越、合适，次数多少要说最多。"}, {"text": "王老师是我最佳的老师。", "explanation": "这里应该用〈最好〉。最佳用于评选中的优秀者或最合适的选择，不用来说个人心中的好老师。"}, {"text": "这次考试他犯的错误最佳。", "explanation": "这里应该用〈最少〉。最佳表示优越、合适，犯的错误要说最少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最佳", "is_correct": true, "explanation": "正确。最佳修饰“作品”，表示优秀的作品。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”形容质地，与评价作品的优劣无关。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：“轻”形容重量，不能说轻作品来表示评价。"}, {"text": "胖", "is_correct": false, "explanation": "搭配：“胖”形容人或动物的体型，不能修饰作品。"}], "explanations": {"最佳": "正确。最佳修饰“作品”，表示优秀的作品。", "硬": "语义：“硬”形容质地，与评价作品的优劣无关。", "轻": "搭配：“轻”形容重量，不能说轻作品来表示评价。", "胖": "搭配：“胖”形容人或动物的体型，不能修饰作品。"}, "sentence_index": 6, "correct_answer": "最佳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场火灾的损失最佳。", "explanation": "这里应该用〈最大〉。最佳表示优越、合适，火灾损失的多少要说最大。"}, {"text": "这次手术的并发症最佳。", "explanation": "这里应该用〈最少〉。最佳表示优越、合适，并发症要说最少。"}, {"text": "这是一段最佳的时光。", "explanation": "这里应该用〈美好〉。最佳侧重合适或优秀，时光这类感受要说美好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位画家今年拿到了很最佳作品奖。", "corrected_sentence": "这位画家今年拿到了最佳作品奖。", "error_description": "错误：“很最佳作品奖”。正确：“最佳作品奖”。“最佳”本身已表示最优秀，前面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛中，他的表现比别人最佳。", "corrected_sentence": "这次比赛中，他的表现最佳。", "error_description": "错误：“比别人最佳”。正确：“最佳”。“最佳”本身已表示最高程度，不能与“比别人”的比较结构同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4884df8-fbe4-4327-baeb-3d18cf822b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89623, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聪明", "is_correct": true, "explanation": "“聪明”与“愚蠢”是反义词，指头脑灵活、善于动脑筋。"}, {"text": "善良", "is_correct": false, "explanation": "“善良”指心地好、待人厚道，与“愚蠢”的头脑之义不构成反义。"}, {"text": "勤奋", "is_correct": false, "explanation": "“勤奋”说学习或工作刻苦，与“愚蠢”不构成反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”表示心情愉快，与“愚蠢”的头脑之义无关，不是它的反义词。"}], "correct_answer": "聪明", "explanations": {"聪明": "“聪明”与“愚蠢”是反义词，指头脑灵活、善于动脑筋。", "善良": "“善良”指心地好、待人厚道，与“愚蠢”的头脑之义不构成反义。", "勤奋": "“勤奋”说学习或工作刻苦，与“愚蠢”不构成反义关系。", "高兴": "“高兴”表示心情愉快，与“愚蠢”的头脑之义无关，不是它的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89623, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聪明", "is_correct": true, "explanation": "“聪明”与“愚蠢”是反义词，指头脑灵活、会动脑筋。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”指不怕困难和危险，与“愚蠢”不构成反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”构成反义，与“愚蠢”的意义无关。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”指待人真诚、积极，不是“愚蠢”的反义词。"}], "correct_answer": "聪明", "explanations": {"聪明": "“聪明”与“愚蠢”是反义词，指头脑灵活、会动脑筋。", "勇敢": "“勇敢”指不怕困难和危险，与“愚蠢”不构成反义关系。", "安静": "“安静”与“吵闹”构成反义，与“愚蠢”的意义无关。", "热情": "“热情”指待人真诚、积极，不是“愚蠢”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89623, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不会动脑筋，做出很傻的事。", "primary_collocate": null, "pronunciation": "yú chǔn", "ipa": "y˧˥ ʈʂʰwən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他做了一件很愚蠢的事。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不看地图就上路，这个办法太愚蠢了。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得借钱去赌博非常愚蠢。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说：“我真愚蠢，又把钥匙忘在家里了。”", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不问问题才是最愚蠢的。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他后来才发现自己的想法很愚蠢。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大热天穿着厚棉袄出门，真愚蠢。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愚蠢的人总是不愿意动脑筋。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没做作业就去玩，你为什么这么愚蠢？", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个愚蠢的错误让我们丢了比赛。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不动脑筋而做傻事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f31afe75-cf81-4a37-a9d7-9dd37dc90485') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "愚蠢", "is_correct": true, "explanation": "“愚蠢”指不会动脑筋、做出很傻的事，可以修饰“事”，符合句意。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容物体或环境含水多，不能用来形容一件事。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写人或物的高度，事情没有高矮之分。"}, {"text": "圆", "is_correct": false, "explanation": "体貌：“圆”描写物体的形状，不能用来形容事情。"}], "explanations": {"愚蠢": "“愚蠢”指不会动脑筋、做出很傻的事，可以修饰“事”，符合句意。", "潮湿": "语义：“潮湿”形容物体或环境含水多，不能用来形容一件事。", "矮": "体貌：“矮”描写人或物的高度，事情没有高矮之分。", "圆": "体貌：“圆”描写物体的形状，不能用来形容事情。"}, "sentence_index": 0, "correct_answer": "愚蠢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他手脚很愚蠢，总是把碗打翻。", "explanation": "这里应该用〈笨〉。“愚蠢”形容头脑不会动脑筋，手脚不灵活要说“笨”，不能说“愚蠢”。"}, {"text": "这间屋子的装修很愚蠢，连一点装饰都没有。", "explanation": "这里应该用〈简陋〉。“愚蠢”形容人的头脑和行为，装修朴素、不加装饰不能说“愚蠢”，要说“简陋”。"}, {"text": "这些字太愚蠢了，我实在看不清。", "explanation": "这里应该用〈模糊〉。“模糊”可以说字迹模糊、看不清；“愚蠢”只形容人的头脑，不能用来形容字迹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愚蠢", "is_correct": true, "explanation": "“愚蠢”符合句意，说明在大热天穿厚棉袄出门的做法很傻。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：“坚硬”形容物体质地硬，不能用来评价穿厚棉袄出门的做法，句子不通。"}, {"text": "透明", "is_correct": false, "explanation": "体貌：“透明”形容物体能透光，棉袄不透明，句子语义不通。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”与“大热天”的语境相反，句子无法成立。"}], "explanations": {"愚蠢": "“愚蠢”符合句意，说明在大热天穿厚棉袄出门的做法很傻。", "坚硬": "语义：“坚硬”形容物体质地硬，不能用来评价穿厚棉袄出门的做法，句子不通。", "透明": "体貌：“透明”形容物体能透光，棉袄不透明，句子语义不通。", "冰冷": "语义：“冰冷”与“大热天”的语境相反，句子无法成立。"}, "sentence_index": 6, "correct_answer": "愚蠢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这个行业很愚蠢，连基本常识都不清楚。", "explanation": "这里应该用〈无知〉。“无知”指缺乏知识，“愚蠢”指不会动脑筋、做出傻事，只说缺少知识时要用“无知”。"}, {"text": "这台机器太愚蠢了，搬起来很费劲。", "explanation": "这里应该用〈笨重〉。“愚蠢”只形容人的头脑和行为，形容机器的体积和重量要用“笨重”。"}, {"text": "这台老电脑的反应太愚蠢了，打开一个文件要等很久。", "explanation": "这里应该用〈迟钝〉。“迟钝”说反应慢，“愚蠢”形容人的头脑，不能用来形容电脑的反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他愚蠢的把钱全借给了朋友。", "corrected_sentence": "他愚蠢地把钱全借给了朋友。", "error_description": "“愚蠢”修饰动词“借”时，状语要用“地”，写成“的”是错误的，应为“愚蠢地把钱全借给了朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说了一句愚蠢地话，大家都笑了。", "corrected_sentence": "他说了一句愚蠢的话，大家都笑了。", "error_description": "错误：“愚蠢”修饰名词“话”时要用“的”，写成“地”是错误的，应为“愚蠢的话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89624, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聪明", "is_correct": true, "explanation": "“聪明”与“愚蠢”是反义词，指头脑灵活、理解力强。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”指待人亲切、积极主动，与“愚蠢”的头脑之义无关。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容外貌或事物好看，不是“愚蠢”的反义词。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”构成反义，与“愚蠢”不构成反义关系。"}], "correct_answer": "聪明", "explanations": {"聪明": "“聪明”与“愚蠢”是反义词，指头脑灵活、理解力强。", "热情": "“热情”指待人亲切、积极主动，与“愚蠢”的头脑之义无关。", "美丽": "“美丽”形容外貌或事物好看，不是“愚蠢”的反义词。", "安静": "“安静”与“吵闹”构成反义，与“愚蠢”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
