INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89624, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "愚笨；缺乏智慧而做事糊涂。", "primary_collocate": null, "pronunciation": "yú chǔn", "ipa": "y˧˥ ʈʂʰwən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他不是愚蠢，只是学得比别人慢。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事讲了一个愚蠢的国王。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愚蠢的人常常相信骗子的话。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不觉得自己愚蠢。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人看上去愚蠢，其实很聪明。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他愚蠢得连简单的道理都不懂。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聪明人学习，愚蠢的人只会抱怨。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的人物既愚蠢又可笑。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人都笑他愚蠢，他却不生气。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愚蠢不可怕，可怕的是不愿学习。", "target_word": "愚蠢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "愚笨缺乏智慧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f31afe75-cf81-4a37-a9d7-9dd37dc90485') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "愚蠢", "is_correct": true, "explanation": "“愚蠢”与“只是学得慢”形成对照，指缺乏智慧、做事糊涂，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌好看，与学习速度无关，句子不通。"}, {"text": "善良", "is_correct": false, "explanation": "语义：“善良”指品德好，与“学得慢”不构成对照，句子语义不通。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容天气或温度，不能用来形容一个人的智力。"}], "explanations": {"愚蠢": "“愚蠢”与“只是学得慢”形成对照，指缺乏智慧、做事糊涂，符合句意。", "漂亮": "体貌：“漂亮”形容外貌好看，与学习速度无关，句子不通。", "善良": "语义：“善良”指品德好，与“学得慢”不构成对照，句子语义不通。", "寒冷": "语义：“寒冷”形容天气或温度，不能用来形容一个人的智力。"}, "sentence_index": 0, "correct_answer": "愚蠢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台老电梯反应很愚蠢，每次都要等很久。", "explanation": "这里应该用〈迟钝〉。“迟钝”说反应慢，“愚蠢”形容人的头脑，不能用来形容电梯。"}, {"text": "这辆卡车很愚蠢，开起来特别费力。", "explanation": "这里应该用〈笨重〉。“笨重”形容体积大、不灵便，“愚蠢”不能用来形容车的重量和体积。"}, {"text": "这幅画的构图太愚蠢，缺少变化。", "explanation": "这里应该用〈呆板〉。“呆板”形容构图或表情死板、缺少变化，“愚蠢”只说人的头脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愚蠢", "is_correct": true, "explanation": "“愚蠢”与“聪明人”对照，指不会动脑筋的人，符合句意。"}, {"text": "细长", "is_correct": false, "explanation": "体貌：“细长”描写外形，与学习和抱怨的品性无关，句子不通。"}, {"text": "湿润", "is_correct": false, "explanation": "语义：“湿润”形容空气或土壤含水适中，不能用来形容一类人。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”说物体的质地，不能用来形容人的学习和抱怨行为。"}], "explanations": {"愚蠢": "“愚蠢”与“聪明人”对照，指不会动脑筋的人，符合句意。", "细长": "体貌：“细长”描写外形，与学习和抱怨的品性无关，句子不通。", "湿润": "语义：“湿润”形容空气或土壤含水适中，不能用来形容一类人。", "柔软": "语义：“柔软”说物体的质地，不能用来形容人的学习和抱怨行为。"}, "sentence_index": 6, "correct_answer": "愚蠢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份菜单的排版太愚蠢，东一行西一行，很乱。", "explanation": "这里应该用〈凌乱〉。“愚蠢”形容人的头脑和行为，不能用来说排版混乱，排版乱要说“凌乱”。"}, {"text": "这份译文太愚蠢，读起来很别扭。", "explanation": "这里应该用〈生硬〉。“生硬”形容文字不自然、不流畅，“愚蠢”只形容人的头脑和行为。"}, {"text": "这张照片太愚蠢了，看不清人的脸。", "explanation": "这里应该用〈模糊〉。“模糊”说影像看不清，“愚蠢”只形容人，不能用来形容照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个人愚蠢地连路都不会找。", "corrected_sentence": "这个人愚蠢得连路都不会找。", "error_description": "“愚蠢”后面接表示程度的补语，要用“得”引出，写成“地”是错误的，应为“愚蠢得连路都不会找”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划太愚蠢的了，我不同意。", "corrected_sentence": "这个计划太愚蠢了，我不同意。", "error_description": "错误：“愚蠢”后多出“的”。“太愚蠢了”中“愚蠢”后直接接“了”，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
