INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89625, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "阻挡是把路拦住，不让人或东西过去。", "primary_collocate": null, "pronunciation": "zǔ dǎng", "ipa": "tsu˨˩˦ tɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "一辆大车阻挡了前面的路。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察在路口阻挡行人过去。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大树倒在路上，阻挡了汽车。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手阻挡前面的人。", "target_word": "阻挡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大门前的石头阻挡着汽车进去。", "target_word": "阻挡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安站在门口阻挡陌生人进去。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雪阻挡了回家的路。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几只羊阻挡了车子过去。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他伸开手臂，阻挡球飞过来。", "target_word": "阻挡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把大石头放在路中间阻挡车辆。", "target_word": "阻挡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阻挡了", "label": "体标"}, {"form": "阻挡着", "label": "体标"}, {"form": "阻挡过", "label": "体标"}], "register": "中性", "sense_fingerprint": "阻挡：拦住道路，不让人或物通过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '464d8e31-3b58-4903-948d-c22c693dcaf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
